  ["21:6514"] = "¡Nuevo Hall Fama!",
  ["21:66db"] = "¡Maestro HdF!",
  ["21:66eb"] = "    vez/veces HdF",
  ["24:4244"] = "¿Eh? Perdona,\nn° equivocado.{DONE}",
  ["24:462a"] = "Ese número no es\nde esta zona.{DONE}",
  ["24:4633"] = "¡Habla con esa\npersona!{DONE}",
  ["40:4615"] = "¡Bienvenido a\nnuestro CENTRO\011POKéMON!{DONE}",
  ["40:4640"] = "¡Hola! ¡Bienvenido\na nuestro CENTRO\011POKéMON!{DONE}",
  ["40:4664"] = "¡Buenas noches!\nBienvenido a\012nuestro CENTRO\nPOKéMON.{DONE}",
  ["40:469f"] = "Nosotros curamos\na tus POKéMON.\012¿Quieres curar a\ntus POKéMON?{DONE}",
  ["40:46e2"] = "Muy bien, déjame\ntus POKéMON.{DONE}",
  ["40:46fc"] = "¡Gracias por\nesperar!\012Tus POKéMON están\nen plena forma.{DONE}",
  ["40:4730"] = "¡Vuelve siempre\nque quieras!{DONE}",
  ["40:4766"] = "Tus POKéMON\ntienen minúsculas\012formas de vida\nunidas a ellos.\012Tus POKéMON están\nsanos y parecen\011contentos.\012Pero no podemos\ndarte más\012información en un\nCENTRO POKéMON.{DONE}",
  ["40:4801"] = "Está llena de\nlibros complejos.{DONE}",
  ["40:481f"] = "¡Una colección de\nlibros ilustrados\011de POKéMON!{DONE}",
  ["40:484a"] = "Revistas POKéMON…\nTELEVISOR POKéMON,\012MANUAL POKéMON,\nGRÁFICA POKéMON…{DONE}",
  ["40:4880"] = "VOTOS TEAM ROCKET\012Robar POKéMON para\nenriquecernos.\012Explotarlos para\nenriquecernos.\012¡Todo POKéMON\nexiste para gloria\011del TEAM ROCKET!{DONE}",
  ["40:48ef"] = "¿Qué es esto?\012¡Oh! ¡Es un\npebetero!{DONE}",
  ["40:4919"] = "¡Cantidad de\nartículos POKéMON!{DONE}",
  ["40:4934"] = "MAPA del PUEBLO.{DONE}",
  ["40:4947"] = "¡Mi reflejo!\n¡Qué guapo!{DONE}",
  ["40:4965"] = "Es una TV.{DONE}",
  ["40:4970"] = "PÁGINA DE INICIO\nREVISTA POKéMON.\012No ha sido\nactualizada…{DONE}",
  ["40:49cd"] = "Aquí dentro no\nhay nada…{DONE}",
  ["40:4a26"] = "Cura a tus POKéMON\nCENTRO POKéMON{DONE}",
  ["40:4a43"] = "Todo lo necesario\npara tus POKéMON\012TIENDA POKéMON{DONE}",
  ["40:4a66"] = "Vamos a evaluar\na tus POKéMON.\012……\n……\012¡Hemos elegido a\nlos ganadores!\012¿Estás preparado?{DONE}",
  ["40:4ac8"] = "¡Uauu! ¡Eres\nbastante fuerte!\012¿Me das tu número\nde teléfono?\012Te llamaré para\nvolver a pelear.{DONE}",
  ["40:4b1d"] = "¿Grabar el número\nde teléfono?{DONE}",
  ["40:4b39"] = "{PLAYER} grabó el\nN° de {STRBUF}.{DONE}",
  ["40:4b56"] = "Te llamaré si\nsurge algo.{DONE}",
  ["40:4b7a"] = "¡Ah! ¡Vale…!\nPues habla conmigo\012cuando quieras\nmi número.{DONE}",
  ["40:4bb7"] = "En tu teléfono\nno tienes espacio\011para más números.{DONE}",
  ["40:4bef"] = "Te esperaba.\n¡Luchemos!{DONE}",
  ["40:4c14"] = "¡Uauu! Peleas\nmuy bien.\012¿Me das tu número\nde teléfono?\012Te llamaré para\nvolver a pelear.{DONE}",
  ["40:4c77"] = "¿Grabar el número\nde teléfono?{DONE}",
  ["40:4c93"] = "{PLAYER} grabó el\nN° de {STRBUF}.{DONE}",
  ["40:4cb0"] = "Te llamaré si\nsurge algo.{DONE}",
  ["40:4cd0"] = "De acuerdo.\nCuando quieras\012mi número de\nteléfono, dímelo.{DONE}",
  ["40:4d12"] = "En tu teléfono\nno tienes espacio\011para más números.{DONE}",
  ["40:4d4a"] = "Te esperaba.\n¡Luchemos!{DONE}",
  ["40:4d6a"] = "{PLAYER} gana el\npremio N°{STRBUF}:\011¡una {STRBUF}!{DONE}",
  ["40:4d90"] = "{PLAYER} recibió\n{STRBUF}.{DONE}",
  ["40:4da3"] = "¡Participa en el\npróximo concurso!{DONE}",
  ["40:4dc9"] = "¡Todos los demás\nreciben una BAYA\011como consolación!{DONE}",
  ["40:4dff"] = "A ver si mejoras\nla próxima vez.{DONE}",
  ["40:4e21"] = "Aquí tienes los\nPOKéMON que\012te estábamos\ncuidando.{DONE}",
  ["40:4e55"] = "¡Equipo completo!\nEl POKéMON fue\012enviado a tu CAJA\nen el PC de BILL.{DONE}",
  ["40:4e96"] = "GIMNASIO POKéMON\nDE {STRBUF}{DONE}",
  ["40:4ea4"] = "LÍDER: {STRBUF}\012GANADORES:\n{PLAYER}{DONE}",
  ["40:4ec7"] = "Bienvenido al\nCASINO.{DONE}",
  ["40:4ee4"] = "¿Necesitas fichas\nde juego?\012¡Oh! No tienes\nun MONEDERO\011para tus fichas.{DONE}",
  ["40:4f2b"] = "¿Necesitas fichas\nde juego?\01250 fichas por\n1000¥. ¿Quieres\011comprar?{DONE}",
  ["40:4f78"] = "¡Gracias! Aquí\ntienes 50 fichas.{DONE}",
  ["40:4f97"] = "¡Gracias! Aquí\ntienes 500 fichas.{DONE}",
  ["40:4fb7"] = "No tienes\nbastante dinero.{DONE}",
  ["40:4fd4"] = "¡Uups! Tu MONEDERO\nestá lleno.{DONE}",
  ["40:4ff5"] = "¿No quieres\nfichas?\012Vuelve cuando\nquieras.{DONE}",
  ["40:5014"] = "¡Oh! Tu MOCHILA\nestá llena.\012Te guardaremos\nesto. Vuelve\012cuando tengas\nsitio.{DONE}",
  ["40:5072"] = "¡Uauu! ¡Tú y tus\nPOKéMON estáis\011muy unidos!{DONE}",
  ["40:509c"] = "Cuanto más tiempo\npases con los\012POKéMON, más\nte querrán.{DONE}",
  ["40:50d1"] = "No has domesticado\na tu POKéMON.\012Si no eres amable,\néste se enfadará.{DONE}",
  ["41:4a8a"] = "Buenos días.{DONE}",
  ["41:4a99"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿Trabajando duro?{DONE}",
  ["41:4aba"] = "Así que estás en\n{STRBUF}.\012¿No está ahí\n{STRBUF}?\012¿Has ido a echar\nun vistazo?{DONE}",
  ["41:4b04"] = "¿Sí? ¿Estás en\n{STRBUF}?\012Nunca he estado\nallí. ¡Genial,\011{PLAYER}!{DONE}",
  ["41:4b4a"] = "¿Qué? ¿Estás en\n{STRBUF}?\012¡Ven a verme\ncuando quieras!{DONE}",
  ["41:4b7d"] = "¿Estás visitando a\n{STRBUF}?\012¿Por qué no vienes\nun rato a casa?{DONE}",
  ["41:4bb5"] = "¡Uau! ¿Estás en\n{STRBUF}?\012¡Suerte en tu\naventura POKéMON!{DONE}",
  ["41:4be9"] = "Eso parece\nbastante duro.\012Pero, {PLAYER}, sé\nque estás decidido\012y que te irá bien,\n¿de acuerdo?{DONE}",
  ["41:4c40"] = "Por cierto, has\nahorrado {STRBUF}¥.\012¿Quieres seguir\nahorrando dinero?{DONE}",
  ["41:4c83"] = "Es importante que\nahorres dinero.{DONE}",
  ["41:4ca6"] = "¡Oh, {PLAYER}!\nNo estás ahorrando\012dinero. ¿Quieres\nahorrar?{DONE}",
  ["41:4ce2"] = "Por cierto, has\nahorrado {STRBUF}¥.\012¿Quieres seguir\nahorrando?{DONE}",
  ["41:4d22"] = "Vale. Te guardaré\nel dinero.{DONE}",
  ["41:4d3c"] = "Vale. Dejaré de\nguardarte dinero.{DONE}",
  ["41:4d5d"] = "¡Sigue así,\n{PLAYER}!\011¡Estoy contigo!{DONE}",
  ["41:4d87"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿No te esperaba\011el PROF. ELM?{DONE}",
  ["41:4dba"] = "¿Dígame?\012¡Hola, {PLAYER}!\n¿Tienes una misión\012importante del\nPROF. ELM? ¡Bien!{DONE}",
  ["41:4dfc"] = "¿Dígame?\012¡Hola, {PLAYER}!\nCuando termines\012tu misión, vuelve\na casa.{DONE}",
  ["41:4e3e"] = "¿Dígame?\012¿{PLAYER}…?\nMe dijo el PROF.\012ELM que saliste\nde viaje.\012Ojalá me lo\nhubieras dicho…\012¿Y el dinero? ¿Te\nlo guardo?{DONE}",
  ["41:4ec4"] = "¡Buenos días!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.{DONE}",
  ["41:4f0d"] = "¡Buenos días!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.{DONE}",
  ["41:4f52"] = "¡Buenas noches!\012SERVICIO de\nADMÓN. del SISTEMA\012de ALMACENAMIENTO\nde los POKéMON.{DONE}",
  ["41:4f9b"] = "¿Quién llama?\012{PLAYER}, ¿eres tú?\nEspera un segundo.\012……\n……{DONE}",
  ["41:4fc7"] = "¡Gracias por\nesperar!\012{PLAYER}, en tu\nCAJA cabe/n {STRBUF}\011POKéMON más.\012¡Adelante!\n¡Llénala!{DONE}",
  ["41:5024"] = "¡Gracias por\nesperar!\012{PLAYER}, en tu\nCAJA sólo cabe/n\011{STRBUF} POKéMON más.\012Quizá deberías\ncambiar de CAJA.{DONE}",
  ["41:508a"] = "¡Gracias por\nesperar!\012¡{PLAYER}, tu\nCAJA está llena!\012Si quieres atrapar\nmás POKéMON,\012tendrás que\ncambiar de CAJA.{DONE}",
  ["41:50ef"] = "Hola, ¿{PLAYER}?\n¡Soy yo, BILL!\012Gracias por usar\nmi SISTEMA de\011ALMACENAMIENTO.\012Tu CAJA se llenó\ncon el último\012POKéMON que\nenviaste.\012Si quieres atrapar\nmás POKéMON,\012tendrás que\ncambiar de CAJA.\012¡Hasta luego!{DONE}",
  ["41:5199"] = "Hola, ¿{PLAYER}?\012No te\nexcedas.\012No olvides curar\na tus POKéMON\011si están heridos.\n{DONE}",
  ["41:51e6"] = "Hola, ¿{PLAYER}?\012¿Viste al SR.\nPOKéMON? ¡Genial!\011¡Vuelve ileso!{DONE}",
  ["41:5221"] = "¿{PLAYER}? Ahora\nestoy muy triste.\012Nos han robado un\nPOKéMON. ¿Cómo\012han podido\nhacerlo?{DONE}",
  ["41:5272"] = "Hola, ¿{PLAYER}?\012Estamos analizando\nel HUEVO. Parece\012ser un HUEVO de\nPOKéMON.{DONE}",
  ["41:52b9"] = "Hola, ¿{PLAYER}?\012¿Has visto a mi\nayudante? Está en\012el CENTRO POKéMON\nde CIUDAD MALVA.{DONE}",
  ["41:5305"] = "Hola, ¿{PLAYER}?\012¿Qué tal el HUEVO?\n¿Ha cambiado algo?\012Si pasa algo, por\nfavor llámame.{DONE}",
  ["41:5358"] = "Hola, ¿{PLAYER}?\n¿Qué tal el HUEVO?\012¿Qué? ¿Se ha\nabierto? ¡Uau!\011¿Qué POKéMON es?\012¡Por favor, ven\na enseñármelo!{DONE}",
  ["41:53bc"] = "Hola, ¿{PLAYER}?\012Acabo de hacer un\ndescubrimiento.\012El tiempo que\ntarda un HUEVO en\012abrirse depende\ndel POKéMON.{DONE}",
  ["41:541f"] = "Hola, ¿{PLAYER}?\012Los movimientos de\nun POKéMON recién\012nacido son\nun misterio.\012Ahora estamos\ninvestigando eso.{DONE}",
  ["41:5484"] = "Hola, ¿{PLAYER}?\012He descubierto\nalgo extraño.\012Parece haber algo\nllamado POKéRUS\012que infecta\na los POKéMON.\012¡Sí! Es como un\nvirus, por eso se\011llama POKéRUS.\012Se multiplica\nrápido e infecta\012a otros POKéMON.\nPero eso es todo.\012Parece que no\nhace nada y que\012desaparece con\nel tiempo.\012Creo que no hay\nde qué preocuparse\011¡Adiós!{DONE}",
  ["41:55b4"] = "¿Hola? ¿{PLAYER}?\n¡Qué desastre!\012¡Ee…, ee…, es\nterrible!\012¿Qué hacer?\n¡Oh, no…!\012¡Vuelve aquí\nahora mismo!{DONE}",
  ["41:5624"] = "Hola, ¿{PLAYER}?\n¡Hemos descubierto\012algo sobre el\nHUEVO!\012Mi ayudante está\nen el CENTRO\012POKéMON de CIUDAD\nMALVA. ¿Podrías\011hablar con él?{DONE}",
  ["41:56a3"] = "{PLAYER}, ¿qué tal\nvan las cosas?\012Te llamo porque\npasó algo raro\012con las emisiones\nde radio.\012Hablaban del\nTEAM ROCKET.\012{PLAYER}, ¿sabes\nalgo sobre\011esto?\012Quizá ha vuelto\nel TEAM ROCKET.\012No, no puede\nser cierto.\012Siento molestarte.\n¡Cuídate!{DONE}",
  ["41:57a6"] = "Hola, ¿{PLAYER}?\012Tengo algo para\nti aquí.\012¿Puedes venir\nal LABORATORIO?\012¡Hasta luego!{DONE}",
  ["41:5862"] = "Hola. Soy\n{STRBUF}…\012¡Buenos días,\n{PLAYER}!{DONE}",
  ["41:588a"] = "Hola. Soy\n{STRBUF}…\012¿Qué tal,\n{PLAYER}?{DONE}",
  ["41:58b3"] = "Hola. Soy\n{STRBUF}…\012¡Buenas noches,\n{PLAYER}!{DONE}",
  ["41:58db"] = "Hola. Soy\n{STRBUF}.\012¡Hola, {PLAYER}!\nBuenos días.{DONE}",
  ["41:5904"] = "Hola. Soy\n{STRBUF}.\012¡Hola, {PLAYER}!\n¿Cómo estás?{DONE}",
  ["41:592c"] = "Hola. Soy\n{STRBUF}.\012¡Hola, {PLAYER}!\nBuenas noches.{DONE}",
  ["41:5955"] = "¡Buenos días,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Qué tal estás?{DONE}",
  ["41:5989"] = "Hola, {PLAYER}.\012Soy yo, {STRBUF}.\n¿Qué tal va todo?{DONE}",
  ["41:59b5"] = "¡Buenas noches,\n{PLAYER}!\012Soy yo, {STRBUF}.\n¿Tienes un minuto?{DONE}",
  ["41:59e4"] = "Buenos días,\n{PLAYER}.\012Soy {STRBUF}.\n¿Te he despertado?{DONE}",
  ["41:5a15"] = "Hola, {PLAYER}.\012Soy {STRBUF}.\n¿Qué tal todo?{DONE}",
  ["41:5a3f"] = "Buenas noches,\n{PLAYER}.\012Soy {STRBUF}.\n¿Estabas dormido?{DONE}",
  ["41:5a70"] = "¿Qué tal están\ntus POKéMON?\012Mi {STRBUF}\ntiene mucha\011energía. ¡Genial!{DONE}",
  ["41:5ab5"] = "¿Qué tal están\ntus POKéMON?\012Mi {STRBUF}\nestá en forma\012porque lo llevo al\nCENTRO POKéMON.{DONE}",
  ["41:5b0d"] = "Mi {STRBUF}\ntiene un aspecto\012increíble. Ojalá\npudieras verlo.{DONE}",
  ["41:5b42"] = "He vestido a mi\n{STRBUF}.\012Tiene mucho mejor\naspecto que antes.{DONE}",
  ["41:5b7b"] = "¡Sí! He ganado\na un fuerte\011{STRBUF}.\012Debo fortalecer\na mi equipo.{DONE}",
  ["41:5bcb"] = "¡Tienes que oír\nesto! El otro día\012derroté a\n{STRBUF}.\012¡Fue sencillo!\nTuve ventaja.{DONE}",
  ["41:5c27"] = "¡Eh, escucha!\nCasi atrapo a\012{STRBUF} el\notro día.\012¡Oh, estuve\nmuy cerca!{DONE}",
  ["41:5c76"] = "¿Sabes lo que me\npasó el otro día?\012Se me volvió\na escapar\012{STRBUF}.\nQuizá no sea tan\011guay en esto…{DONE}",
  ["41:5cdb"] = "¿Quieres luchar?\nNo volverá a\012ocurrir lo de la\núltima vez.\012Estaré por\n{STRBUF}.{DONE}",
  ["41:5d37"] = "¿Quieres luchar?\n¡Esta vez ganaré!\012Te estaré\nesperando por\012{STRBUF}.\nBúscame, ¿vale?{DONE}",
  ["41:5da0"] = "¿Hola? Soy\n{STRBUF}…\012¡Oh, oh…! ¡Tú no\neres MATEO! ¡Vaya,\011me he equivocado!{DONE}",
  ["41:5de2"] = "Hola, soy\n{STRBUF}. ¿Cómo\011estás, ARIADNA?\012¿Eh? ¿{PLAYER}?\n¡Me he equivocado!{DONE}",
  ["41:5e2e"] = "¡Hasta luego!{DONE}",
  ["41:5e3e"] = "¡Adiós!{DONE}",
  ["41:5e48"] = "¡Tienes que ver\nesto! ¡Es salvaje!\012¡Ha aparecido\nun grupo de\012{STRBUF}\nalrededor de\011{STRBUF}!{DONE}",
  ["41:5e9c"] = "¡Es increíble!\012En {STRBUF},\nestán picando\012{STRBUF} como si\nno hubiera mañana.\012¡{PLAYER}, trae\ntu CAÑA, tío!{DONE}",
  ["41:5efa"] = "Un amigo me lo\nacaba de decir.\012Ha visto muchos\n{STRBUF} en\011{STRBUF}.\012{PLAYER}, deberías\nir a verlo.{DONE}",
  ["41:5f50"] = "Hoy se celebra el\nConcurso de\012Captura de Bichos\nen el PARQUE.\012¿Vas a ir,\n{PLAYER}?{DONE}",
  ["41:5fa4"] = "¿Sabes qué,\n{PLAYER}?\012Dicen que el TEAM\nROCKET ha asaltado\012la TORRE de RADIO\nde CIUDAD TRIGAL.\012¿Pero qué es el\nTEAM ROCKET?{DONE}",
  ["41:6014"] = "¿{PLAYER}, has\noído las noticias?\012El TEAM ROCKET ha\nasaltado la TORRE\012de RADIO de\nCIUDAD TRIGAL.\012¿Estarán bien\nlos trabajadores?{DONE}",
  ["41:608d"] = "¡Hola, {PLAYER}!\n¡Las ventas de\012BICIS han subido\nespectacularmente!\012Y todo gracias a\nla publicidad\012que has hecho\ncon nuestra BICI.\012Quédate con esa\nBICI como\012agradecimiento.\n¡Gracias de nuevo!{DONE}",
  ["42:4027"] = "Montamos guardia\nen esta torre.\012Así expresamos\nnuestra gratitud a\011todos los POKéMON.{DONE}",
  ["42:4078"] = "¡Gra-Gracias!{DONE}",
  ["42:4087"] = "Todos los seres\nvivos coexisten\011en cooperación.\012Deberíamos\nestar agradecidos.{DONE}",
  ["42:40dc"] = "Sólo obtendrás\nuna MO si llegas\011arriba.{DONE}",
  ["42:410e"] = "La TORRE\nBELLSPROUT fue\012construida para\nentrenar POKéMON.{DONE}",
  ["42:414d"] = "Un BELLSPROUT de\n30 m de altura.\012Dice la gente que\nse convirtió en la\011columna central.{DONE}",
  ["42:41a1"] = "¿Ves cómo se\nmueve la columna?\012Arriba hay gente\nentrenando.{DONE}",
  ["42:41da"] = "Estatua POKéMON…\012Parece muy\nilustre.{DONE}",
  ["42:42ad"] = "Por mucho que\nluchemos, la TORRE\011seguirá en pie.{DONE}",
  ["42:42e3"] = "Luché con fuerza\npero estoy débil.{DONE}",
  ["42:4303"] = "La columna\nflexible protege\012la TORRE hasta\nde los terremotos.{DONE}",
  ["42:4345"] = "Se mueve como las\nhojas al viento…{DONE}",
  ["42:4365"] = "¡Oh, estoy débil!{DONE}",
  ["42:4373"] = "Quería imitar los\nsuaves movimientos\012de BELLSPROUT\npara pelear…\012Pero no me\nentrené bastante.{DONE}",
  ["42:43cc"] = "Estatua POKéMON…\012Parece muy\nilustre.{DONE}",
  ["42:452b"] = "ANCIANO: Eres\nun entrenador\011muy hábil.\012Como te prometí,\naquí tienes tu MO.\012Pero déjame que te\ndiga que deberías\012tratar mejor a\ntus POKéMON.\012Luchas de forma\nmuy violenta.\012Los POKéMON no son\narmas de guerra.{DONE}",
  ["42:45f0"] = "…\n¡Bah!\012Afirma ser el\nANCIANO, pero\011es muy débil.\012Es evidente.\012Jamás perdería\nante quienes dicen\012que hay que ser\nbuenos con\011los POKéMON.\012Sólo me interesan\nlos POKéMON\011ganadores.\012Paso de los\nPOKéMON\011débiles.{DONE}",
  ["42:46cc"] = "¡{RIVAL}\nusó\011CUERDA HUIDA!{DONE}",
  ["42:46e4"] = "¡Encantado de\nverte por aquí!\012TORRE BELLSPROUT\nes un lugar de\011entrenamiento.\012La gente y los\nPOKéMON evalúan\012sus vínculos para\nconstruir juntos\011un futuro mejor.\012Yo soy la prueba\nfinal.\012¡Déjame evaluar\ntus vínculos con\011los POKéMON!{DONE}",
  ["42:47b6"] = "¡Ah, excelente!{DONE}",
  ["42:47c6"] = "Tú y tus POKéMON\nno deberíais tener\012problemas con\neste movimiento.\012Toma esta MO.\nEs DESTELLO.{DONE}",
  ["42:4817"] = "DESTELLO ilumina\nhasta el lugar\011más oscuro.\012Y con la MEDALLA\nde CIUDAD MALVA,\012podrás usarlo\nfuera del combate.{DONE}",
  ["42:488c"] = "¡Ojalá aprendas y\nmadures con\011tu viaje!{DONE}",
  ["42:48ba"] = "¡Entreno para\nsaberlo todo\011sobre los POKéMON!{DONE}",
  ["42:48e2"] = "¡Derrotado por\nun mocoso!{DONE}",
  ["42:48fb"] = "Cuanto más fuerte\nsea el POKéMON,\012más fuerte será\nsu entrenador.\012No, espera. Cuanto\nmás fuerte sea el\012entrenador, más\nfuerte el POKéMON.{DONE}",
  ["42:4961"] = "A ver cuánto\nconfías en tus\011POKéMON.{DONE}",
  ["42:498b"] = "¡Sí, tu confianza\nes auténtica!{DONE}",
  ["42:49a5"] = "No estás lejos\ndel ANCIANO.{DONE}",
  ["42:49c2"] = "La MO del ANCIANO\nalumbra hasta\011lo más oscuro.{DONE}",
  ["42:49f4"] = "¡Mi cerebro sí\nque es brillante!{DONE}",
  ["42:4a13"] = "¡Que haya luz\nen tus viajes!{DONE}",
  ["42:4a38"] = "Es un bonito\ncuadro de un\011BELLSPROUT.{DONE}",
  ["42:4a62"] = "Estatua POKéMON…\012Parece muy\nilustre.{DONE}",
  ["42:4b20"] = "Intento desvelar\nel secreto del\012POKéMON legendario\nque, en teoría,\011descansa aquí.\012Dicen que este\nPOKéMON no ha\012dejado de volar\ndesde que se quemó\011la TORRE Oeste.\012Por eso pensé que\nsi tuviera algo\012de ese POKéMON,\néste se sentiría\011atraído por mí.\012Creo que ese\nobjeto es…\012¡Un ALA ARCOIRIS!\012Pero, ¿dónde\nencontrar una?{DONE}",
  ["42:4f24"] = "…… …… ……\012¡Ah, eres tú!\012Querías ser más\nfuerte y por eso\012has venido a por\nel POKéMON\012legendario que\nvive aquí. Ésa es\011tu historia, ¿no?\012Pues ya te puedes\nir olvidando.\012¡Porque ese\nPOKéMON será mío!\012Quiero ser el\nmejor entrenador\012del mundo y ese\nPOKéMON legendario\012sería perfecto\npara mí.\012De todos modos,\nya estoy harto de\012ver a un mocoso\ncomo tú siempre\011por aquí.{DONE}",
  ["42:5093"] = "¡Bah!\012¡Por eso no me\ngusta luchar\012contra memos!\n¡Son tan malos!{DONE}",
  ["42:50da"] = "¡Que más da!\012Jamás podrías\natrapar un\012POKéMON\nlegendario.{DONE}",
  ["42:5124"] = "¡Bah!\012¡Por eso no me\ngusta luchar\012contra memos! ¡Qué\npérdida de tiempo!{DONE}",
  ["42:516d"] = "Estoy entrenándome\nen secreto.\012¡Me da vergüenza\nque mires!{DONE}",
  ["42:51ac"] = "¡Terminé\nhecho cenizas…!{DONE}",
  ["42:51cb"] = "Estaba tan ocupado\nentrenándome que\012caí por este\nagujero.{DONE}",
  ["42:5202"] = "¡Mi alma está\nardiendo! ¡Déjame\012que te enseñe\ncómo quema!{DONE}",
  ["42:5236"] = "Aún no hace\nbastante calor…{DONE}",
  ["42:524d"] = "En el pasado\nexistían POKéMON\012que corrían\npor la hierba a\011gran velocidad.\012Dicen que corren\ncomo el viento.\012Si te encuentras\ncon uno de ellos,\011puede que escape.{DONE}",
  ["42:552a"] = "Del suelo salieron\nun montón de\012DIGLETT.\n¡Qué susto!{DONE}",
  ["42:562d"] = "…… …… ……\012¡Cuánto tiempo,\n{PLAYER}!\012Tras haber sido\nderrotado por\012ti, estuve\npensando en mis\011POKéMON…\012Y llegué a una\nconclusión.\012¡Ahora verás,\n{PLAYER}!{DONE}",
  ["42:56c5"] = "…… …… ……\012Creía haber\nentrenado muy\012bien a mis\nPOKéMON…\012Pero estaba\nequivocado…{DONE}",
  ["42:5722"] = "…… …… ……\012Has ganado\njustamente.\012Lo admito. Pero\nesto no termina\011aquí.\012Voy a ser el mejor\nentrenador POKéMON\011del mundo.\012Ya que estos\nchicos me apoyan.\012Mira, {PLAYER}.\012Uno de estos días\nte demostraré lo\012bueno que soy,\nderrotándote.{DONE}",
  ["42:5808"] = "…… …… ……\012Ya te he pagado\nmi deuda.\012Con mis POKéMON\nganaré al CAMPEÓN\012y seré el mejor\nentrenador\011del mundo.{DONE}",
  ["42:5a87"] = "Espera.\012¿Vas a\nparticipar en la\011LIGA POKéMON?\012No me hagas reír.\nEres mucho más\012débil que yo,\nporque ya no\012soy el mismo\nde antes.\012¡Ahora tengo los\nPOKéMON mejores\012y más fuertes!\n¡Soy invencible!\012¡{PLAYER}!\n¡Yo te desafío!{DONE}",
  ["42:5b65"] = "He perdido…\012Hice todo lo\nque pude…\012Lo que tú tienes\ny yo no tengo…\012Empiezo a entender\nlo que me dijo\012aquel maestro\nde dragones…{DONE}",
  ["42:5bf6"] = "Sigo queriendo\nser el mejor\011entrenador…\012Descubriré por qué\nno puedo ganar\012y ser más\nfuerte…\012Te desafiaré en\ncuanto lo sepa.\012Y te aplastaré\ncon todo\011mi poder.\012Hasta entonces,\n¡sigue entrenando!{DONE}",
  ["42:5cd2"] = "¡Bah!\012Después de todo,\nnada mejor que\011el poder.\012No necesito\nnada más.{DONE}",
  ["43:4196"] = "¡Eh! ¡Mira mi\nmochila!\012Imprimí de la\nPOKéDEX mis\012POKéMON favoritos\ny los pegué\011en ella.{DONE}",
  ["43:41f1"] = "Es una CARTA\nde mi hija.\011¡Me da ánimos!{DONE}",
  ["43:4228"] = "¡Presta atención,\npor favor!\012¡Ups! A ver si\ndejo de hablar\012como si fuera\nuna maestra.\012Eres un entrenador\nPOKéMON.\012Como estás\ntrabajando tan\012duro, te voy\na dar esto.{DONE}",
  ["43:42d0"] = "Dale a un POKéMON\nesa GARRA RÁPIDA.\012Y a veces atacará\nel primero\011en combate.{DONE}",
  ["43:4320"] = "Estoy jugando con\nlas pegatinas de\011mi POKéDEX.{DONE}",
  ["43:4352"] = "La pegatina de la\nPOKéDEX del otro\012chico será mía,\nsi gano.{DONE}",
  ["43:437f"] = "Doy paseos por\nel PARQUE, pero\012nunca entro en\nla hierba.\012Los entrenadores\nsiempre luchan…{DONE}",
  ["43:43d9"] = "PERSIAN: ¡Persiia!{DONE}",
  ["43:43ed"] = "Estoy imprimiendo\nmi POKéDEX.\012También puedes\nimprimir las\012CARTAS y\nCAJAS de tu PC.{DONE}",
  ["43:4441"] = "El mundo POKéMON\nes muy amplio.\012Y sigue habiendo\nmuchas cosas que\011ignoramos.\012¡Pero yo sé\nmás que tú!{DONE}",
  ["43:44a7"] = "¿Qué, qué, qué?{DONE}",
  ["43:44b6"] = "Hay muchas cosas\nque aprender.\012Por ejemplo…\012Hay 50 tipos de\nMT.\012Los POKéMON\nintercambiados\012suben antes\nde nivel.{DONE}",
  ["43:4514"] = "Mis POKéMON son\nmuy monos. Te los\011voy a enseñar.{DONE}",
  ["43:4547"] = "Quizá no pueda\nvencerte…\012Pero los míos son\nmucho más bonitos.{DONE}",
  ["43:4584"] = "Un amigo mío tiene\nun MARILL. ¡Es\012precioso! ¡Ojalá\ntuviera un MARILL!{DONE}",
  ["43:45c1"] = "Queremos a\nnuestros POKéMON,\012aunque ellos\nno nos quieran.\012Eso significa ser\nun FAN POKéMON.{DONE}",
  ["43:4611"] = "¡M-mi POKéMON!{DONE}",
  ["43:461d"] = "Perdí el combate,\npero mis POKéMON\012son más adorables\nque los tuyos.{DONE}",
  ["43:4662"] = "¿Hola?\n¿Y tú que miras?\012¿Quieres luchar?{DONE}",
  ["43:4693"] = "¡Mmmm…!{DONE}",
  ["43:469b"] = "Por como me\nmirabas, pensé\011que te gustaba.\012Al fin y al cabo,\nsoy tan guapa…{DONE}",
  ["43:46e4"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL{DONE}",
  ["43:4705"] = "¿Qué dice\neste cartel?\012Por favor, lucha\nsólo en la hierba.\012PUESTO DEL GUARDA\nPARQUE NACIONAL{DONE}",
  ["43:475a"] = "PISTAS ENTRENADOR\012Imprime una CARTA\nabriéndola y\011pulsando START.{DONE}",
  ["43:48e0"] = "RAFA: ¡Voy a\nganar! No me\011molestes.{DONE}",
  ["43:4907"] = "SAM: Mi PARASECT\nduerme a los\012POKéMON con\nESPORA.{DONE}",
  ["43:4937"] = "NANO: Entreno a\nPOKéMON rápidos\011para luchar.{DONE}",
  ["43:4960"] = "GUILLE: No me\nimporta ganar.\012Sólo busco\nPOKéMON raros.{DONE}",
  ["43:49a9"] = "TINO: ¡Ssh! Vas a\nasustar a SCYTHER.\012Hablaré contigo\ndespués.{DONE}",
  ["43:49e6"] = "BENITO: Debilita a\nlos POKéMON\012bicho y lánzales\nuna PARQUE BALL.{DONE}",
  ["43:4a25"] = "CINDY: ¿Qué pasa?\012¿Te parece\ngracioso que\012una chica atrape\nPOKéMON bicho?{DONE}",
  ["43:4a70"] = "KAI: Colecciono\nPOKéMON bicho\012desde que era\nsólo un niño.\012¡Es imposible\nque pueda perder!{DONE}",
  ["43:4acd"] = "SAMUEL: Si tienes\ntiempo para\012conversar, busca\nPOKéMON bicho.{DONE}",
  ["43:4b0c"] = "KOLDO: Soy un gran\nestudioso de los\011POKéMON bicho.\012Seguro que\ngano.{DONE}",
  ["43:4b4f"] = "PLAZA DEL DESCANSO\nPARQUE NACIONAL{DONE}",
  ["43:4b70"] = "¿Qué dice\neste cartel?\012Por favor, lucha\nsólo en la hierba.\012PARQUE NACIONAL\nPUESTO DEL GUARDA{DONE}",
  ["43:4bc5"] = "PISTAS ENTRENADOR\012Imprime una CARTA\nabriéndola y\011pulsando START.{DONE}",
  ["43:4e1f"] = "¡Bienvenido!{DONE}",
  ["43:4e29"] = "Hola. Lo siento\npero hoy no\012se admiten\nvisitas.{DONE}",
  ["43:4e62"] = "¿Quieres probar\nen el NÚMERO DE\011LA SUERTE?\012¿Compruebo los\nnúmeros ID de\011tus POKéMON?\012Si tienes suerte,\nganarás un premio.{DONE}",
  ["43:4ee2"] = "El número de esta\nsemana es {STRBUF}.{DONE}",
  ["43:4f02"] = "A ver si coincide\ncon tu número.{DONE}",
  ["43:4f21"] = "……\n……{DONE}",
  ["43:4f26"] = "Vuelve la próxima\nsemana y participa\012otra vez en el\nN° DE LA SUERTE.{DONE}",
  ["43:4f5d"] = "¡Uauu! ¡Tus cinco\nnúmeros coinciden!\012¡Ya tenemos un\nganador!\012¡Has ganado una\nMASTER BALL!{DONE}",
  ["43:4fcb"] = "¡Oye! ¡Tus tres\núltimos números\011coinciden!\012¡Ganaste el\nsegundo premio:\011REPARTIR EXP!{DONE}",
  ["43:501e"] = "¡Ooh! ¡Tus dos\núltimos números\011coinciden!\012Ganaste el tercer\npremio: MÁS PP.{DONE}",
  ["43:5068"] = "¡No! Tus números\nID no coinciden.{DONE}",
  ["43:508e"] = "No tienes sitio\npara tu premio.\012Hazle sitio y\nvuelve enseguida.{DONE}",
  ["43:50d5"] = "Ahora tenemos\nuna promoción\011especial.\012Acierta estas 5\npreguntas y gana\011una TARJETA RADIO.\012Introdúcela en tu\nPOKéGEAR para oír\012la radio siempre\nque quieras.\012¿Quieres\nparticipar?{DONE}",
  ["43:519a"] = "Pregunta 1:\012¿Se puede ver el\nMAPA del PUEBLO\011en el POKéGEAR?{DONE}",
  ["43:51d1"] = "¡Correcto!\nPregunta 2:\012¿NIDORINA es\nsiempre hembra?{DONE}",
  ["43:5204"] = "¡Perfecto!\nPregunta 3:\012¿Utiliza BONTURI\nCÉSAR, el artesano\011de las POKé BALL?{DONE}",
  ["43:524d"] = "¡Por ahora bien!\nPregunta 4:\012¿Es cierto que\nMAGIKARP no puede\012aprender ningún\nmovimiento de MT?{DONE}",
  ["43:528b"] = "¡Otro acierto!\nY ahora la última\011pregunta:\012La HORA POKéMON\ndel PROF. OAK es\011muy popular.\012¿Es ROSI la\nco-presentadora?{DONE}",
  ["43:530b"] = "¡Bingo!\n¡Enhorabuena!\012Éste es tu premio:\n¡la TARJETA RADIO!{DONE}",
  ["43:5350"] = "¡El POKéGEAR de\n{PLAYER} se puede\011usar como radio!{DONE}",
  ["43:5375"] = "Sintoniza nuestros\nprogramas.{DONE}",
  ["43:5399"] = "Lo siento mucho,\npero te has\012equivocado.\n¡Vuelve a probar!{DONE}",
  ["43:53d3"] = "¡Ah! Entiendo.\nVuelve a probar si\011cambias de idea.{DONE}",
  ["43:5403"] = "NARDO es un DJ\nfabuloso.\012¡Su dulce voz\nme derrite!{DONE}",
  ["43:5439"] = "Me gusta ROSA, de\nla HORA POKéMON.\012Aunque sólo\nconozca su voz.{DONE}",
  ["43:5481"] = "¡Por fin nos hemos\napoderado de la\011TORRE de RADIO!\012¡Ahora todos\nexperimentarán el\012verdadero terror\ndel TEAM ROCKET!\012¡Ya veréis qué\nhorribles somos!{DONE}",
  ["43:550f"] = "¡Demasiado fuerte!\nTe vigilaremos…{DONE}",
  ["43:552f"] = "Eres muy fuerte.\012Arruinarías\nnuestros planes.\012Mejor alertar a\nlos otros…{DONE}",
  ["43:5574"] = "PB RECEPCIÓN\nP1 VENTAS\012P2 PERSONAL\nP3 PRODUCCIÓN\012P4 OFICINA DEL\n   DIRECTOR{DONE}",
  ["43:55be"] = "¡CANAL SUERTE!\012¡Gana con los ID\nde los POKéMON!\012¡Cambia POKéMON\ny reúne diferentes\011números ID!{DONE}",
  ["43:570e"] = "Puedes escuchar la\nradio en cualquier\011lugar. ¡Sintoniza!{DONE}",
  ["43:5740"] = "Las nanas de la\nradio duermen\011a los POKéMON.{DONE}",
  ["43:576d"] = "¿Por qué querrían\napoderarse de la\011TORRE de RADIO?{DONE}",
  ["43:57a0"] = "JIGGLYPUFF:\nJiggly…{DONE}",
  ["43:57b5"] = "¡Aviso!\nProhibido entrar\011sin autorización.\012Antes no\nera así.\012Debe de haber\nalgún problema con\011el DIRECTOR…{DONE}",
  ["43:582e"] = "Puedes mirar por\ntodas partes.\012El DIRECTOR ya\nno está enfadado.{DONE}",
  ["43:5885"] = "Hace tres años, el\nTEAM ROCKET tuvo\011que separarse.\012¡Pero nos estamos\nvolviendo a\011reunir aquí!{DONE}",
  ["43:58db"] = "¡Bah! ¡No te\nhagas el chulo!{DONE}",
  ["43:58f1"] = "¡No permitiremos\nque arruines\011nuestros planes!{DONE}",
  ["43:5923"] = "¡Somos el\nTEAM ROCKET,\012explotadores de\nlos POKéMON!\012¡Nos gusta ser\nmalos! ¿Asustado?{DONE}",
  ["43:596a"] = "¿Te crees\nun héroe?{DONE}",
  ["43:5983"] = "No siempre somos\nmalos. Hacemos\011lo que queremos.{DONE}",
  ["43:59b7"] = "¡Oye! ¡Fuera de\nnuestro camino!{DONE}",
  ["43:59d7"] = "¡Argg! Me rindo.{DONE}",
  ["43:59ea"] = "Nuestros\nEJECUTIVOS\012quieren hacerse\ncon este lugar.\012Tienen grandes\nplanes. ¿Cuáles\011serán?{DONE}",
  ["43:5a4e"] = "¡Jajaja!\012¡Qué aburrimiento!\n¡Fue tan sencillo\012apoderarse de\neste lugar!\012¡Venga,\nentretenme!{DONE}",
  ["43:5aa9"] = "¿Quién eres tú?{DONE}",
  ["43:5aba"] = "¡Me venciste y no\npienso olvidarlo!{DONE}",
  ["43:5ade"] = "P1 VENTAS{DONE}",
  ["43:5ae8"] = "La HORA POKéMON\ndel PROF. OAK.\012¡El mejor programa\nde la radio!{DONE}",
  ["43:5b1b"] = "Radio POKéMON.\nA cualquier hora\011y en todas partes.{DONE}",
  ["43:5cbf"] = "Hemos grabado los\ngritos de todos\012los POKéMON\ndescubiertos.\012Debemos de tener\nunos 200 tipos.{DONE}",
  ["43:5d20"] = "Los POKéMON son\nmuy queridos por\011sus entrenadores.\012Es horrible ver\ncómo trata el\012TEAM ROCKET\na los POKéMON.{DONE}",
  ["43:5d89"] = "Emitimos programas\nde entretenimiento\012las 24 horas\ndel día.\012¡Intentaremos\nhacerlo lo mejor\011posible!{DONE}",
  ["43:5df2"] = "El jefe del TEAM\nROCKET se ha\011encerrado.\012Pero el DIRECTOR\npuede abrirle.\012Está en el\ncuarto piso.\012¡Sálvale!{DONE}",
  ["43:5e69"] = "¿Está a salvo\nel DIRECTOR?{DONE}",
  ["43:5e80"] = "¡Gracias!\n¡Eres mi héroe!\012Toma esto como\nagradecimiento.{DONE}",
  ["43:5ebf"] = "¡Es DÍA SOLEADO!\nMejora movimientos\012del tipo fuego\ndurante un tiempo.{DONE}",
  ["43:5efa"] = "¡Estuviste\ngenial!{DONE}",
  ["43:5f16"] = "He recibido\nórdenes.\012¡Aplastaré a todo\naquél que desafíe\011al TEAM ROCKET!{DONE}",
  ["43:5f66"] = "¿¡Qué!?{DONE}",
  ["43:5f6e"] = "No he cumplido\ncon mi deber…\012Y me van a\nbajar el sueldo…{DONE}",
  ["43:5fa2"] = "Me encanta ordenar\na los POKéMON que\011cometan delitos.{DONE}",
  ["43:5fd2"] = "¿Bromeas?{DONE}",
  ["43:5fe2"] = "¡No me gusta\nperder!\012¡Odio a los\nPOKéMON inútiles!{DONE}",
  ["43:601b"] = "¿Por qué se\nabrió la puerta?\012¿Acaso eres tú\nel responsable?{DONE}",
  ["43:6060"] = "¡Es mi fin!{DONE}",
  ["43:606e"] = "¿Qué? ¿Esquivaste\na nuestros hombres\011del SUBTERRÁNEO?\012¿Cómo lo hiciste?{DONE}",
  ["43:60b2"] = "¿Un niño que\nmerodea por aquí?\012¿Quién eres?{DONE}",
  ["43:60e1"] = "¡Vaya! ¡No te tomé\nmuy en serio!{DONE}",
  ["43:60ff"] = "¡Jajajajaja…!\012Desde aquí puedo\ntransmitir todo\011tipo de señales.{DONE}",
  ["43:6142"] = "Es la ranura de la\nLLAVE MAGNÉTICA.{DONE}",
  ["43:615a"] = "{PLAYER}\nusó la\011LLAVE MAGNÉTICA.{DONE}",
  ["43:6174"] = "P2 PERSONAL{DONE}",
  ["43:6182"] = "MÚSICA POKéMON\ncon el DJ NARDO{DONE}",
  ["43:62b0"] = "Mientras estaba\nen las RUINAS\011oía la radio.\012Y escuché una\nextraña emisión.{DONE}",
  ["43:6306"] = "ROSA: ¿Por qué?\n¿Por qué debo\011sufrir?\012¡MEOWTH, ayúdame!{DONE}",
  ["43:6349"] = "ROSA: ¡Oh! ¡Eres\nmi salvador!\012¿Aceptas esto como\nagradecimiento?{DONE}",
  ["43:638d"] = "ROSA: Es para los\nPOKéMON que\012saben movimientos\nnormales.{DONE}",
  ["43:63ca"] = "ROSA: Sintoniza\nconmigo en la\012HORA POKéMON\ndel PROF. OAK.{DONE}",
  ["43:6404"] = "MEOWTH: Meowth…{DONE}",
  ["43:6415"] = "¿Quieres rescatar\nal DIRECTOR?\012¡Pues ya te puedes\nir olvidando de\012eso, porque te\nvoy a ganar!{DONE}",
  ["43:646d"] = "¡No! ¡Increíble!{DONE}",
  ["43:6480"] = "¡Increíble!\n¡He perdido!{DONE}",
  ["43:64a2"] = "¡Alto ahí!\n¡Me llaman la\012fortaleza del\nTEAM ROCKET!\012¡No des un\npaso más!{DONE}",
  ["43:64ee"] = "¡La fortaleza\nse derrumbó!{DONE}",
  ["43:6507"] = "Te has ganado mi\nrespeto. ¡Te daré\011un consejo!\012Aún estás a\ntiempo de darte\011la vuelta.{DONE}",
  ["43:6562"] = "¿Son buenos mis\nPOKéMON?\012¡Creeré que mis\nPOKéMON son buenos\012cuando derroten\na los tuyos!{DONE}",
  ["43:65b3"] = "¡Oh, no! ¡Son\ntan inútiles!{DONE}",
  ["43:65cf"] = "¡Me gusta mi\npersonalidad!\012¿Qué importan\nlos POKéMON?{DONE}",
  ["43:6600"] = "¡Extraordinario!\012Esta TORRE de\nRADIO completará\011nuestro gran plan.{DONE}",
  ["43:6641"] = "¡Mmmm…!\012Todo gran plan\ntiene sus pegas.{DONE}",
  ["43:6669"] = "¿De verdad crees\nque puedes detener\011al TEAM ROCKET?{DONE}",
  ["43:669c"] = "P3 PRODUCCIÓN{DONE}",
  ["43:66ab"] = "P3 ESTUDIO 2{DONE}",
  ["43:686a"] = "¡Tú! ¿Has venido\na rescatarme?{DONE}",
  ["43:6889"] = "¿Es eso lo que\nestabas esperando?\012¡Pues no!\n¡Soy un impostor!\012Me hice pasar por\nel director para\012preparar nuestra\ninvasión.\012¿Quieres saber\ndónde escondimos\011al DIRECTOR?\012Te lo diré,\n¡pero sólo si eres\011capaz de vencerme!{DONE}",
  ["43:6965"] = "Muy bien. Te diré\ndónde está.{DONE}",
  ["43:6988"] = "Escondimos al\nauténtico DIRECTOR\012en el ALMACÉN\nSUBTERRÁNEO.\012Está al otro\nextremo del\011SUBTERRÁNEO.\012Pero dudo que\nllegues tan lejos.{DONE}",
  ["43:6a0d"] = "Hola, jovencito.\n¿Me recuerdas de\012la GUARIDA de\nPUEBLO CAOBA?\012Entonces perdí,\npero ahora no.{DONE}",
  ["43:6a70"] = "¡Esto no me puede\nestar pasando!\012He luchado y\nhe perdido…{DONE}",
  ["43:6aaa"] = "{PLAYER}, ¿verdad?\012Un mocoso como tú\nno puede apreciar\012la grandeza del\nTEAM ROCKET.\012¡Qué lástima!\nTendrías futuro\011con nosotros.{DONE}",
  ["43:6b23"] = "¿Cómo has logrado\nllegar tan lejos?\012Debes de ser un\nbuen entrenador.\012Queremos hacernos\ncon esta EMISORA\012de RADIO para\nanunciar nuestra\011vuelta.\012Eso debería\nhacer regresar a\012GIOVANNI de su\nentrenamiento.\012Vamos a recuperar\nla gloria\011perdida.\012Y no voy a\npermitir que\012interfieras en\nnuestros planes.{DONE}",
  ["43:6c45"] = "¡No! ¡Perdóname,\nGIOVANNI!{DONE}",
  ["43:6c60"] = "¿Qué ha pasado?\012Nuestros sueños\nhechos añicos.\012No estaba listo\npara la tarea.\012Como ya hiciera\nGIOVANNI, hoy\012abandonaré yo el\nTEAM ROCKET.\012¡Adiós!{DONE}",
  ["43:6d04"] = "DIRECTOR: Gracias,\n{PLAYER}.\012Tu valiente\nacción ha salvado\012a los POKéMON\nde todo el país.\012Sé que no es\nmucho, pero\011acepta esto.{DONE}",
  ["43:6d7e"] = "En CIUDAD TRIGAL\nhabía una\011torre.\012Pero era vieja\ne inestable.\012Y la sustituimos\npor nuestra\011TORRE de RADIO.\012Al demolerla,\nencontramos eso en\011la parte superior.\012Dicen que antes\nvolaban enormes\012POKéMON sobre\nCIUDAD TRIGAL.\012Podría ser de\nun POKéMON.\012Como el que\naparece en la\012TORRE HOJALATA\nde CIUDAD IRIS.\012Mejor que vuelva\na mi OFICINA.{DONE}",
  ["43:6ee3"] = "En CIUDAD TRIGAL\nhabía una\011torre.\012Pero era vieja\ne inestable.\012Y la sustituimos\npor nuestra\011TORRE de RADIO.\012Al demolerla,\nencontramos eso en\011la parte superior.\012Dicen que antes\nvolaban enormes\012POKéMON sobre\nCIUDAD TRIGAL.\012Podría ser de\nun POKéMON.\012Como el que\naparece en ISLAS\012REMOLINO, cerca de\nCIUDAD ORQUÍDEA.\012Mejor que vuelva\na mi OFICINA.{DONE}",
  ["43:7049"] = "DIRECTOR: ¡Hola,\n{PLAYER}!\012Ya sabes que amo\na los POKéMON.\012Construí la TORRE\nde RADIO para\012expresar mi amor\npor los POKéMON.\012¡Ojalá difrute la\ngente con nuestros\011programas!{DONE}",
  ["43:70e3"] = "NARDO: ¿Escuchas\nnuestra música?{DONE}",
  ["43:7105"] = "P4 OFICINA\n   DEL DIRECTOR{DONE}",
  ["43:711e"] = "P4 ESTUDIO 1{DONE}",
  ["44:409f"] = "¿Eh? Es una\nPOKéDEX, ¿verdad?\011¿Puedo verla?\012Hay muchos tipos\nde POKéMON.\012¿Y esto qué es?\012¿Cuál es este\nPOKéMON?\012Se parece a las\nraras escrituras\012de las paredes\nde las RUINAS.\012Si esos dibujos\nson POKéMON,\012debería haber\nmuchos más.\012¡Ya sé! Voy a\nactualizar tu\011POKéDEX. Sígueme.{DONE}",
  ["44:42c3"] = "¡Mmm…! ¡Qué\nlugar tan extraño!{DONE}",
  ["44:42e3"] = "…{DONE}",
  ["44:42e6"] = "Me gusta pensar\naquí.{DONE}",
  ["44:42fd"] = "SALA DEL PANEL DE\nPIEDRA MISTERIOSO{DONE}",
  ["44:431a"] = "RUINAS ALFA\n¡Bienvenidos!{DONE}",
  ["44:433a"] = "C. INVESTIGACIÓN\nDE LAS RUINAS ALFA\012La Autoridad en\nlas RUINAS ALFA{DONE}",
  ["44:443c"] = "Es una réplica\nde un antiguo\011POKéMON.{DONE}",
  ["44:4461"] = "Un POKéMON que\nvuela elegante,\012con alas de color\narcoiris.{DONE}",
  ["44:4516"] = "¡Bienvenido a\nesta cámara!\012Hay unos paneles\ncon el dibujo de\012un POKéMON, hecho\npor los antiguos.\012Mueve los paneles\ny completa el\011dibujo.\012A la derecha verás\nuna descripción\011del POKéMON.{DONE}",
  ["44:45cb"] = "Es una réplica\nde un POKéMON\011antiguo.{DONE}",
  ["44:45f0"] = "Un POKéMON que se\noculta en el mar.\012Con sus ojos\nexplora la zona.{DONE}",
  ["44:46bb"] = "Es una réplica de\nun POKéMON\011antiguo.{DONE}",
  ["44:46e0"] = "Este POKéMON\nflota a la deriva\012moviendo sus\ndiez tentáculos.{DONE}",
  ["44:4795"] = "Es una réplica de\nun POKéMON\011antiguo.{DONE}",
  ["44:47ba"] = "Este POKéMON\nvolador ataca a\012su presa con sus\nfuertes colmillos.{DONE}",
  ["44:484a"] = "Siento una\nrara presencia…{DONE}",
  ["44:486d"] = "Esta habitación es\nmuy grande, pero\011aquí no hay nada.{DONE}",
  ["44:489b"] = "Este lugar está\nimpregnado de\011misticismo.\012Parece hasta\netéreo.{DONE}",
  ["44:48e5"] = "Los edificios\nantiguos suelen\012ser tumbas\nde reyes.\012Como por ejemplo,\nlas pirámides.{DONE}",
  ["44:4933"] = "Es una réplica de\nun POKéMON\011antiguo.{DONE}",
  ["44:4b1e"] = "¡Ya está!\012He modificado\ntu POKéDEX.\012Añadí una\nPOKéDEX opcional\012para guardar los\ndatos de UNOWN.\012Los registra en\nel orden en que\011son atrapados.{DONE}",
  ["44:4ba0"] = "Mejorada POKéDEX\nde {PLAYER}.{DONE}",
  ["44:4bb7"] = "Todos los UNOWN\nque atrapes serán\011registrados aquí.\012A ver cuántos\ntipos existen.{DONE}",
  ["44:4c05"] = "¿Atrapaste a todos\nlos UNOWN?\012¡Es un gran\nlogro!\012He ajustado la\nimpresora para\011UNOWN.\012Puedes usarla\ncuando quieras.{DONE}",
  ["44:4c93"] = "Las RUINAS datan\nde hace unos\0111.500 años.\012Pero ignoramos\npor qué o por\012quién fueron\nconstruidas.{DONE}",
  ["44:4ceb"] = "¿Cuántos tipos de\nPOKéMON habrá\011en las RUINAS?{DONE}",
  ["44:4d1e"] = "¿Hay POKéMON\nen las RUINAS?\012¡Qué noticia\ntan increíble!\012Tendremos que\ninvestigarlo.{DONE}",
  ["44:4d71"] = "En las paredes de\nlas RUINAS hay\012unos dibujos\nmuy raros.\012Son la clave\npara resolver\012el misterio\nde las RUINAS.{DONE}",
  ["44:4ded"] = "¿Los POKéMON\nraros que viste\011en las RUINAS?\012Son muy parecidos\na los dibujos de\012esas paredes\nde ahí.\012¡Mmm…!\012Debe de significar\nque hay muchos\011tipos diferentes…{DONE}",
  ["44:4e8b"] = "RUINAS ALFA\01210 Años\nde Exploración{DONE}",
  ["44:4eae"] = "Nombre de POKéMON\nmisterioso: UNOWN\012Encontrados un\ntotal de 26 tipos.{DONE}",
  ["44:4ee3"] = "Parece que esto\naún no funciona.{DONE}",
  ["44:4f02"] = "Se puede imprimir\nUNOWN.{DONE}",
  ["44:4f5b"] = "Hay muchos libros\nacadémicos.\012Ruinas Antiguas…\nLos Misterios de\011los Antiguos…{DONE}",
  ["44:505c"] = "¿Te diriges a\nPUEBLO AZALEA?\012Demuestra a\nmis POKéMON que\011vales para luchar.{DONE}",
  ["44:50b0"] = "¡Oh, oh, oh!{DONE}",
  ["44:50bd"] = "¡Muy bien!\nYa lo he decidido.\012¡No me iré hasta\nque mis POKéMON\011se fortalezcan!{DONE}",
  ["44:5106"] = "Merodeo por todas\npartes en busca\011de POKéMON.\012¿También tú vas en\nbusca de POKéMON?\012¡Pues entonces\neres mi rival\011coleccionista!{DONE}",
  ["44:516c"] = "¡Ugh! Mis pobres\nPOKéMON…{DONE}",
  ["44:5182"] = "Todos los viernes\nse escucha a un\012POKéMON que ruge\nen la cueva.{DONE}",
  ["44:51c4"] = "¡Uauu!\n¡Qué sorpresa!\012¡No esperaba\nver a nadie!{DONE}",
  ["44:51ff"] = "¡Uauu! ¡Me\nhan machacado!{DONE}",
  ["44:521a"] = "Me obligaron a\ncomprar una COLA\011de SLOWPOKE.\012Lo siento por\nel pobre POKéMON.{DONE}",
  ["44:5266"] = "El SUPERSÓNICO de\nZUBAT confunde a\011mis POKéMON.\012¡Y eso me\npreocupa!{DONE}",
  ["44:52b1"] = "¡Me inflamé!{DONE}",
  ["44:52c0"] = "Los fines de\nsemana se oyen\012extraños rugidos\nen la cueva.{DONE}",
  ["44:5300"] = "Si hay luz, no me\nasusta la cueva.\012Si eres fuerte,\nlos POKéMON no\011se asustarán.{DONE}",
  ["44:5345"] = "¡DESTELLO!{DONE}",
  ["44:534d"] = "El fuego de mi\nPOKéMON\011ilumina la cueva.{DONE}",
  ["44:546e"] = "Hace mucho\ntiempo que no\011veo a nadie.\012No seas tímido.\n¡Luchemos!{DONE}",
  ["44:54bb"] = "¡Uurggh…!{DONE}",
  ["44:54c4"] = "Llevo perdido\nmucho tiempo…\012No es que me\nimporte, ¡pero\011estoy hambriento!{DONE}",
  ["44:5510"] = "¡Qué sabes tú!\n¡Un visitante!{DONE}",
  ["44:552e"] = "¡Jajaja! ¡Eres\nmuy susceptible!{DONE}",
  ["44:554c"] = "Vivo aquí abajo.\012Y tú también\npodrías si\011quisieras.\012Como ves, hay\nmucho sitio.{DONE}",
  ["44:559b"] = "¿Quién anda ahí?\012¡Déjame en paz,\na mí y a mis\011POKéMON!{DONE}",
  ["44:55c4"] = "¡Fuera…!\n¡Lárgate!{DONE}",
  ["44:55d2"] = "Sólo yo y mis\nPOKéMON. ¡Me\011muero de alegría!{DONE}",
  ["44:5601"] = "He venido hasta\naquí para estudiar\011a los POKéMON.\012¡Te demostraré\nmis hallazgos en\011un combate real!{DONE}",
  ["44:5668"] = "¡Lo has demostrado\nconmigo!{DONE}",
  ["44:5681"] = "Debería reunir\ny publicar mis\011hallazgos.\012Podría hacerme\ntan famoso como\011el PROF. ELM.{DONE}",
  ["44:57bf"] = "Hay dos tipos\nde personas.\012Los que tienen\nestilo y los que\011no lo tienen.\012¿A qué tipo\nperteneces tú?{DONE}",
  ["44:5826"] = "¡Tu estilo es\ndeslumbrante!{DONE}",
  ["44:5841"] = "El estilo de tus\nPOKéMON es\011sorprendente.\012¡Seguirás\nmejorando!{DONE}",
  ["44:5895"] = "Estoy entrenando.\n¿Quieres luchar?{DONE}",
  ["44:58b8"] = "No, eres demasiado\nbueno para mí.{DONE}",
  ["44:58d9"] = "Seguiré\nentrenándome\011hasta que mejore.{DONE}",
  ["44:5907"] = "Si los POKéMON\nque me gustan\012estuvieran ahí,\niría sin pensarlo.\012Eso haría un\nbuen entrenador.{DONE}",
  ["44:5958"] = "¡Preferiría cuidar\nde mis niños!{DONE}",
  ["44:597c"] = "Cada semana viene\nun POKéMON hasta\011la orilla.\012Quería ver a ese\nPOKéMON…{DONE}",
  ["44:5b06"] = "CÉSAR: ¡Hola,\n{PLAYER}!\012Los guardias de\narriba huyeron en\011cuanto les grité.\012Pero entonces\nme caí por el\011POZO.\012Me golpeé en la\nespalda y ahora\011no puedo moverme.\012Si estuviera bien,\nmis POKéMON\012los habrían\nmachacado…\012¡Bah! Pero no\npuedo hacer nada.\012¡{PLAYER},\ndemuéstrales lo\011que vales!{DONE}",
  ["44:5c1d"] = "CÉSAR: ¡Muy bien,\n{PLAYER}!\012El TEAM ROCKET\nha huido.\012Y yo estoy mejor\nde mi espalda.\011¡Salgamos de aquí!{DONE}",
  ["44:5c78"] = "¡Maldición! Estaba\nde guardia arriba\012cuando un viejo\nmemo me gritó.\012Me asusté tanto\nque me he caído\011aquí abajo.\012¡Creo que voy\na desahogar mi\012ira luchando\ncontra ti!{DONE}",
  ["44:5d1f"] = "¡Arrg! ¡Hoy NO\nes mi día!{DONE}",
  ["44:5d3b"] = "Sí, hemos estado\ncortando las colas\012de los SLOWPOKE\ny vendiéndolas.\012Lo hacemos sólo\npor dinero.\012¡Así es! Somos\nel TEAM ROCKET,\012¡y haríamos lo que\nfuera por dinero!{DONE}",
  ["44:5dde"] = "¿Qué quieres?\012¡Si nos molestas,\nno esperes\011misericordia!{DONE}",
  ["44:5e23"] = "Lo hiciste bien,\nmocoso, pero ya\011verás la próxima.{DONE}",
  ["44:5e54"] = "Sí, el TEAM ROCKET\nse separó hace\011tres años.\012Pero seguimos\nclandestinamente\012con nuestras\nactividades.\012¡Diviértete ahora\ncon nuestras\011fechorías!{DONE}",
  ["44:5ee5"] = "¿Dejar de cortar\nlas COLAS de\011los SLOWPOKE?\012¡Obedecerte\narruinaría la\012reputación del\nTEAM ROCKET!{DONE}",
  ["44:5f37"] = "Simplemente…\nMuy fuerte…{DONE}",
  ["44:5f4a"] = "Necesitamos pasta,\n¿pero vendiendo\011COLAS de SLOWPOKE?\012¡Es muy duro ser\nun SOLDADO ROCKET!{DONE}",
  ["44:5f9b"] = "¿No más COLAS?\012¡Claro! ¡Intenta\nvencernos a todos!{DONE}",
  ["44:5fd3"] = "¡Maldito lambrijo!{DONE}",
  ["44:5fe5"] = "¡Las COLAS de los\nSLOWPOKE se\011regeneran rápido!\012¿Qué hay de malo\nen venderlas?{DONE}",
  ["44:6023"] = "Un SLOWPOKE\nsin COLA…\012¿Qué? Tiene una\nCARTA. ¿Leerla?{DONE}",
  ["44:6061"] = "{PLAYER} lee\nla CARTA.\012Sé bueno y cuida\nla casa donde\012está el abuelo y\nSLOWPOKE.\012Te quiere, papá.{DONE}",
  ["44:60b9"] = "Un SLOWPOKE\nsin COLA…{DONE}",
  ["44:6182"] = "Me gustaría ver\ncómo evoluciona\011SLOWPOKE.\012Observándolos\nhe hecho un nuevo\011descubrimiento.\012Un SLOWPOKE con\nuna ROCA DEL REY\012suele ser mordido\npor un SHELLDER.\012Toma, compartiré\nuna ROCA DEL REY\011contigo.{DONE}",
  ["44:624a"] = "Voy a ser como\nSLOWPOKE.\012Tendré paciencia\ny a ver si\011evoluciona alguno.{DONE}",
  ["44:62c5"] = "En este FARO se\nentrena la gente.\012No es fácil subir\nporque hay muchos\011entrenadores.{DONE}",
  ["44:631a"] = "Antes había unos\nPOKéMON que\012iluminaban el mar\nque rodea OLIVO.\012El FARO se\nconstruyó en honor\011a esos POKéMON.{DONE}",
  ["44:646b"] = "¡Los hombres de\nmar siempre\011quieren luchar!{DONE}",
  ["44:64a1"] = "¡Urf!\n¡He perdido!{DONE}",
  ["44:64af"] = "¡Qué poder!\n¿Te gustaría\012navegar conmigo\npor estos mares?{DONE}",
  ["44:64e9"] = "¿Qué? Aquí\nno se juega.{DONE}",
  ["44:650c"] = "¡Ah! Ya veo que\nvas en serio.{DONE}",
  ["44:652f"] = "Arriba hay un\nPOKéMON que\011ilumina el FARO.\012Pero dicen que\nestá enfermo y que\012la medicina normal\nno puede curarle.{DONE}",
  ["44:6625"] = "¿Qué haces aquí?\n¿Sólo mirando?\012¡Pues mejor\nque te vayas!{DONE}",
  ["44:666e"] = "Estás realmente\npreocupado…{DONE}",
  ["44:6689"] = "¿Cómo diablos\nse sube?\012Quiero visitar\nal POKéMON\012enfermo, pero no\npuedo subir…{DONE}",
  ["44:66dd"] = "Los marineros\nsomos fuertes y\011simpáticos. ¿Y tú?{DONE}",
  ["44:670f"] = "Eres fuerte y\nsimpático…{DONE}",
  ["44:672e"] = "Siempre que vuelvo\na CIUDAD OLIVO\011voy al GIMNASIO.\012El tipo de POKéMON\nde su LÍDER ha\012cambiado sin\ndarme cuenta.{DONE}",
  ["44:679e"] = "Viajo por el mundo\npara entrenar a\012mis POKéMON.\n¿Quieres luchar?{DONE}",
  ["44:67e1"] = "(Suspiro…)\nDebo entrenar más.{DONE}",
  ["44:6801"] = "YASMINA solía\nutilizar POKéMON\011roca como ONIX.{DONE}",
  ["44:68bc"] = "YASMINA debe de\nestar preocupada\011por este POKéMON.\012Ni siquiera\nsonríe.{DONE}",
  ["44:690f"] = "Yo tampoco puedo\nsonreír…{DONE}",
  ["44:692e"] = "Hablando de\nenfermedades, hay\012una FARMACIA en\nCIUDAD ORQUÍDEA.{DONE}",
  ["44:696f"] = "YASMINA es LÍDER\nde este GIMNASIO.\012Quería que viniera\nconmigo.\012¡No he encontrado\na nadie mejor!{DONE}",
  ["44:69d5"] = "¡Ay! ¡Mi POKéMON!{DONE}",
  ["44:69e6"] = "Cualquiera estaría\npreocupado si sus\012POKéMON estuvieran\nenfermos.\012Rezaré por este\nPOKéMON, para que\012YASMINA regrese\nal GIMNASIO.{DONE}",
  ["44:6aef"] = "Quería luchar con\nYASMINA, pero no\012está disponible.\n¿Y tú, qué…?{DONE}",
  ["44:6b3a"] = "¡Uauu! ¡Eres\nincreíble!{DONE}",
  ["44:6b5b"] = "Ser LÍDER de un\nGIMNASIO no es\012sólo una cuestión\nde fuerza. Todo\012LÍDER también debe\nser compasivo.{DONE}",
  ["44:6bb0"] = "Estamos bastante\naltos aquí. Mis\012POKéMON pájaro\nestán en forma.{DONE}",
  ["44:6beb"] = "¡Uups…!\n¡Se estrellaron!{DONE}",
  ["44:6bff"] = "Mi POKéMON\naprendió VUELO en\011CIUDAD ORQUÍDEA.\012Y como soy un\nperdedor, cruzaré\011el mar VOLANDO…{DONE}",
  ["44:6dbd"] = "YASMINA: Este\nPOKéMON siempre\012iluminaba el mar\npor la noche.\012Pero de pronto\nenfermó… Le\011cuesta respirar…\012Dicen que hay\nuna FARMACIA\012estupenda en\nCIUDAD ORQUÍDEA…\012Pero está al otro\nlado del mar…\012Y no puedo dejar\nsolo a AMPHY…{DONE}",
  ["44:6ea0"] = "¿Podrías traerme\nsu medicina?\011¿Por favor?{DONE}",
  ["44:6ed5"] = "YASMINA: ¡Ah…!\n¿Le das a AMPHY\011esa medicina?{DONE}",
  ["44:6eff"] = "{PLAYER} entregó\nla POCIÓN SECRETA\011a YASMINA.{DONE}",
  ["44:6f26"] = "YASMINA: ¡Mmm!\nPor favor, no te\011ofendas…\012AMPHY no aceptaría\nnada de nadie,\011sólo confía en mí.{DONE}",
  ["44:6f80"] = "YASMINA: …\012AMPHY, ¿cómo te\nsientes?{DONE}",
  ["44:6fa8"] = "YASMINA: ¡Oh…!\n¡Qué alivio…!\012Es tan\nestupendo…\012Muchísimas\ngracias.\012Regresaré\nal GIMNASIO…{DONE}",
  ["44:701b"] = "YASMINA: Ya veo.{DONE}",
  ["44:702d"] = "¡AMPHY, aguanta!{DONE}",
  ["44:703f"] = "AMPHY: ¡Am…\nAm… phyphy…!{DONE}",
  ["44:7055"] = "Apenas puede\nrespirar…{DONE}",
  ["44:7079"] = "AMPHY: ¡Amphy!\n¡Amphy!{DONE}",
  ["45:4126"] = "¡Arrg…!\nHas encontrado la\011escalera secreta.{DONE}",
  ["45:414f"] = "El experimento\nfuncionó a las mil\011maravillas.\012Los MAGIKARP no\nvalen nada, pero\012los GYARADOS son\nmuy productivos.{DONE}",
  ["45:41bc"] = "¡Urrg…!\012Los POKéMON dragón\nde ese chico\011son muy fuertes…{DONE}",
  ["45:41e5"] = "LANCE: DRAGONITE,\nHÍPER RAYO.{DONE}",
  ["45:4204"] = "¿Por qué tardaste\ntanto, {PLAYER}?\012Como pensaba,\nesa extraña señal\012de radio viene\nde aquí.{DONE}",
  ["45:4259"] = "Las escaleras\nestán justo aquí.{DONE}",
  ["45:4275"] = "LANCE: {PLAYER},\nseparémonos para\012registrarlo todo.\nYo iré primero.{DONE}",
  ["45:47cd"] = "¡Cuidado!\n¡Un intruso!{DONE}",
  ["45:47e3"] = "¡Vaya…! Fallé…{DONE}",
  ["45:47f4"] = "¡Me toca a mí!\n¡No puedes huir!{DONE}",
  ["45:4814"] = "En las estatuas de\nlos POKéMON hay\012cámaras de\nvigilancia.\012Seguiremos\napareciendo hasta\012que pulses un\nbotón secreto.{DONE}",
  ["45:4876"] = "Esto era una\nguarida ninja.\012Hay trampas para\nconfundir a los\011intrusos como tú.{DONE}",
  ["45:48c6"] = "Lo tengo…{DONE}",
  ["45:48d1"] = "Bien. Te contaré\nun secreto sobre\011nuestra guarida.\012Eso que hay en\nel suelo es un\011panel deslizante.\012Si te colocas\nencima, te\012llevará de vuelta\na la entrada.{DONE}",
  ["45:4972"] = "¡Je, je! ¿Te crees\nafortunado?\012Adelante, da\notro paso.\012¡El suelo está\nlleno de trampas!{DONE}",
  ["45:49cd"] = "¡Kabum!{DONE}",
  ["45:49d6"] = "Yo ni siquiera sé\ndónde están las\011trampas.\012Tendrás que\nser valiente\011y caminar.{DONE}",
  ["45:4a37"] = "Es una estatua de\nPERSIAN…\012Sus ojos tienen un\nbrillo extraño.{DONE}",
  ["45:4a68"] = "¡Un botón secreto!\nMejor pulsarlo.{DONE}",
  ["45:4a8b"] = "El interruptor\nestá apagado.{DONE}",
  ["45:4f65"] = "¡Alto ahí!{DONE}",
  ["45:4f7b"] = "No podemos dejar\nque un mocoso como\011tú nos toree.\012Es malo para el\norgullo del TEAM\011ROCKET.\012Por muy fuerte que\nseas, no podrás\012derrotarnos al\nmismo tiempo.\012Lo siento, chico.\n¡Prepárate para\011ser aniquilado!{DONE}",
  ["45:5044"] = "¡Oye! No seas tan\negoísta. Comparte\011la diversión.{DONE}",
  ["45:5075"] = "¿Qué? ¿Tenías un\ncómplice? ¿Dónde\012está tu sentido\ndel honor?\012Como sustituto\nprovisional\012de GIOVANNI, ¡ya\nte enseñaré yo a\012no meterte con\nel TEAM ROCKET!{DONE}",
  ["45:5114"] = "¡Uau! Eres muy\nfuerte.\012¡Qué lástima!\012Si te unieras al\nTEAM ROCKET,\012podrías llegar a\nser un EJECUTIVO.{DONE}",
  ["45:517e"] = "Esta guarida\nse acabó…\012Pero no importa.\nEl experimento de\012emisión fue\ntodo un éxito.\012Qué más da lo que\npase ahora con\011esta guarida.\012Tenemos planes más\nimportantes.\012Muy pronto\nconocerás el\012verdadero poder\ndel TEAM ROCKET.\012Disfruta mientras\npuedas…\012¡Fufufufu…!{DONE}",
  ["45:5290"] = "LANCE: Funcionó.\nHemos derrotado\012a todos estos\nROCKETS.\012Pero me preocupa\nese joven contra\011el que luché…{DONE}",
  ["45:5306"] = "Perdona, {PLAYER}.\nComo lo estabas\012haciendo tan bien,\nme retiré.\012Lo único que hay\nque hacer ahora es\012apagar esa extraña\nseñal radiofónica.{DONE}",
  ["45:5387"] = "Esta máquina está\ncausando todos\011los problemas.\012Pero no veo ningún\ninterruptor…\012No tenemos\nelección. Hay que\012debilitar a todos\nlos ELECTRODE.\012Eso impedirá que\nesta máquina siga\012transmitiendo esa\nextraña señal.\012Los POKéMON no\ntienen la culpa\012y por eso yo me\nsiento culpable.\012{PLAYER}, mejor\nque nos dividamos\011la tarea.{DONE}",
  ["45:54a2"] = "LANCE: Déjame\neste lado.{DONE}",
  ["45:54c1"] = "LANCE: Por fin\nha parado esa\011extraña señal.\012El LAGO vuelve a\nla normalidad.\012¡Eres un héroe!\nMuchas gracias\012en nombre de\ntodos los POKéMON.\012¡Ah, sí! Toma\nesto.\012Lo encontré aquí,\npero yo no lo\011necesito.{DONE}",
  ["45:55b0"] = "Es TORBELLINO.\nEnséñasela a\012un POKéMON y\npodrá cruzar\011torbellinos.\012Pero recuerda\nque…\012Sólo podrás usarla\nfuera de los\012combates con la\nMEDALLA del\011GIMNASIO CAOBA.{DONE}",
  ["45:564c"] = "{PLAYER}…\012El viaje para ser\nun MAESTRO\012POKéMON es largo\ny difícil.\012Y ya que lo sabes,\n¿quieres seguir?\012…\012Entiendo. No,\ntienes razón.\012Si te rindieras\ntan fácilmente,\012jamás habrías\nperseguido este\012maravilloso\nsueño.\012¡Espero volver\na verte!{DONE}",
  ["45:574f"] = "LANCE: ¿Estás\nbien?\012Tus POKéMON están\nheridos, cansados.\012Toma, dales un\npoco de mi\011medicina.{DONE}",
  ["45:57af"] = "LANCE: {PLAYER},\ntenemos que hacer\012todo lo posible\npor los POKéMON.{DONE}",
  ["45:57da"] = "¿No se abre\nla puerta?\012Bueno, necesitas\nuna contraseña que\012sólo conoce el\nTEAM ROCKET.{DONE}",
  ["45:5831"] = "¿Qué? ¿He perdido?{DONE}",
  ["45:5840"] = "¿Qué? Soy sólo\nun SOLDADO.\012Y no conozco la\ncontraseña. Lo\011siento por ti.{DONE}",
  ["45:5882"] = "¡Oh! ¿Un niño?\nNo me gusta,\012pero debo\neliminarte.{DONE}",
  ["45:58c1"] = "Sabía que\nperdería…{DONE}",
  ["45:58d2"] = "En mi última\nmisión también fui\012derrotado por\nun niño.\012Cuando estábamos\nsecuestrando unos\012POKéMON, un\nchico pelirrojo y\012de extraña mirada\nme machacó…{DONE}",
  ["45:5968"] = "¡Tú! ¡Pequeño\nparásito podrido!{DONE}",
  ["45:5981"] = "¡Grrrr…!{DONE}",
  ["45:5989"] = "¡Oye! Sólo el jefe\nconoce la clave\011de esa puerta.\012¿Dónde está el\njefe? ¡Quién sabe!\011Encuéntralo tú.{DONE}",
  ["45:59f1"] = "La puerta está\ncerrada…\012Requiere una\ncontraseña.{DONE}",
  ["45:5a23"] = "La puerta está\ncerrada…\012{PLAYER} introdujo\nla contraseña.\012¡Puerta abierta!{DONE}",
  ["45:5a5f"] = "La emisora de\nradio está\012emitiendo una\nsiniestra señal.\012Está funcionando a\nmáxima capacidad.{DONE}",
  ["45:5abb"] = "Por fin la emisora\nde radio ha dejado\012de transmitir esa\nmaldita señal.{DONE}",
  ["45:5e2f"] = "LANCE: Necesitas\ndos contraseñas\012para entrar en el\ncuarto del jefe.\012Y sólo conocen\nesas contraseñas\011algunos ROCKETS.\012Me lo ha contado\nese ROCKET que\011está ahí.\012{PLAYER}, busquemos\nesas contraseñas.{DONE}",
  ["45:5eeb"] = "¡Urrgg…! El\nchico de la capa\011es muy fuerte…{DONE}",
  ["45:5f1d"] = "…\012¿No te había\ndicho que iba a\012destruir al TEAM\nROCKET?\012Dime, ¿quién\nera el chico de la\012capa que usaba los\nPOKéMON dragón?\012Mis POKéMON no\npudieron con él.\012No me importa\nperder. Podría\012ganarle con otros\nPOKéMON.\012Lo que me molestó\nes lo que dijo…\012Me dijo que no\namo ni confío\012bastante en mis\nPOKéMON.\012Me enfurece haber\nperdido contra un\011memo como él.\012¡Humph! ¡No tengo\ntiempo para\011gente como tú!{DONE}",
  ["45:60b6"] = "¿Qué? ¿Quién eres?\nÉsta es la oficina\012de nuestro líder,\nGIOVANNI.\012Lleva entrenándose\ndesde que el TEAM\012ROCKET se separó\nhace tres años.\012Pero seguro que\nvolverá algún día\012para retomar el\nmando.\012Por eso estamos\naquí de guardia.\012¡No permitiré que\nnadie perturbe\011este lugar!{DONE}",
  ["45:61c7"] = "Yo…, no pude\nevitarlo…\012GIOVANNI,\nperdóname…{DONE}",
  ["45:61fe"] = "No puedo dejar\nque me afecte.\012Tengo que informar\na los otros…{DONE}",
  ["45:623b"] = "MURKROW: La\ncontraseña es…\012VIVA GIOVANNI.{DONE}",
  ["45:6265"] = "¿Conozco yo la\ncontraseña?\012A lo mejor.\012¡Pero no será de\nningún debilucho!{DONE}",
  ["45:62a7"] = "Muy bien. Espera.\nTe la diré.{DONE}",
  ["45:62c7"] = "La contraseña de\nla oficina del\011jefe es…\012COLASLOWPOKE.\012Pero no te servirá\nde nada si no\011tienes las dos.{DONE}",
  ["45:6327"] = "¡Je, je, je!\012¿Me desafías a\nun combate? ¡Bah!\012¡Estás loco, pero\ntienes agallas!\012¡Eso me gusta!\012¡Si me vences, te\ndiré la contraseña\012de la oficina\ndel jefe!{DONE}",
  ["45:63cd"] = "¡Ji, Ji, Ji!\n¡Eres bueno!{DONE}",
  ["45:63ed"] = "¡Ji, Ji, Ji!\012La contraseña\nde la oficina del\011jefe es…\012¡Eh…! Creo que\nes COLARATICATE.{DONE}",
  ["45:6443"] = "Trabajaba para\nSILPH, pero ahora\012investigo para el\nTEAM ROCKET.\012Un entrometido\ncomo tú debería\011ser castigado.{DONE}",
  ["45:64b8"] = "Un error táctico\nacabó conmigo…{DONE}",
  ["45:64d8"] = "Una señal de radio\nque vuelve locos a\011los POKéMON…\012Mi experimento es\ntodo un éxito.\012Mi ascenso está\nasegurado. Esta\012derrota no\nsignifica nada.{DONE}",
  ["45:6562"] = "Me da igual que\nlos POKéMON sufran\012debido a nuestros\nexperimentos.{DONE}",
  ["45:6595"] = "Mi fuerte es\npensar, no pelear.{DONE}",
  ["45:65c0"] = "Si enviáramos\nnuestra señal de\012radio por todo\nel país…\012¡Me emociono\nsólo de pensarlo!{DONE}",
  ["45:6626"] = "La puerta está\ncerrada…\012Necesitas dos\ncontraseñas.{DONE}",
  ["45:6659"] = "La puerta está\ncerrada…\012{PLAYER} introdujo\ndos contraseñas.\012¡Puerta abierta!{DONE}",
  ["45:6a44"] = "¡Vaya…! Mi jefe\nse va a poner\011furioso…\012Se me escapó el\nFARFETCH'D que\012CORTA árboles para\nconseguir carbón.\012No puedo ir a\nbuscarlo al\011ENCINAR.\012Demasiado grande y\noscuro para mí…{DONE}",
  ["45:6b01"] = "¡Uauu! ¡Muchísimas\ngracias!\012El POKéMON de\nmi jefe no me\012obedecía porque\nno tengo MEDALLAS.{DONE}",
  ["45:6b57"] = "¡Es el POKéMON\nperdido!{DONE}",
  ["45:6b6e"] = "FARFETCH'D: ¡Farf!{DONE}",
  ["45:6b81"] = "¡Mi FARFETCH'D!\012¡Genial! ¡Lo has\nencontrado!\012Sin él no podíamos\nCORTAR árboles\012para conseguir\ncarbón.\012¡Gracias, chico!\012¿Cómo podría\nagradecértelo…?\012¡Ya sé! Toma\nesto.{DONE}",
  ["45:6c29"] = "Es la MO CORTE.\n¡Enséñasela a un\012POKéMON para\ncortar arbustos!\012Pero necesitarás\nla MEDALLA del\012GIMNASIO AZALEA\npara usarla.{DONE}",
  ["45:6ca8"] = "¿Quieres que te\nenseñe a trabajar\011con el carbón?\012¡En diez años\nserás el mejor!{DONE}",
  ["45:6d03"] = "¿Que qué hago?\012Agitar los árboles\ncon GOLPE CABEZA.\012Es muy divertido.\n¡Toma, pruébalo!{DONE}",
  ["45:6d55"] = "Agita los árboles\ncon GOLPE CABEZA.\012A veces caen\nPOKéMON dormidos.{DONE}",
  ["45:6d97"] = "Hay tantos árboles\nen el ENCINAR que\012no se ve ni\nel cielo.\012Por favor, busca\nobjetos que puedan\011haber caído.{DONE}",
  ["45:6e11"] = "SANTUARIO del\nENCINAR…\012Construido en\nhonor del guardián\011del encinar…{DONE}",
  ["46:42dc"] = "Me echaron\ndel CASINO.\012Intentaba hacer\ntrampas usando\011mis POKéMON…{DONE}",
  ["46:4329"] = "¡Caray…!{DONE}",
  ["46:4334"] = "Supongo que\ndebería actuar\011honradamente…{DONE}",
  ["46:4362"] = "¿Tienes en cuenta\nlos tipos durante\011el combate?\012Si conoces bien\nlos distintos\012tipos, rendirás\nmás en combate.{DONE}",
  ["46:43cb"] = "¡Oo, oo, oo!{DONE}",
  ["46:43d8"] = "Conozco mis tipos\nde POKéMON.\012Pero sólo uso un\ntipo de POKéMON.{DONE}",
  ["46:441a"] = "¡Les corté el pelo\na mis POKéMON!\012¡Ahora verás lo\nfuertes que son!{DONE}",
  ["46:4458"] = "¡Ayyyy!{DONE}",
  ["46:4462"] = "Los POKéMON serán\nmás amigos tuyos\012si los llevas a\ncortar el pelo.{DONE}",
  ["46:449b"] = "Creo que tienes\nalgunos POKéMON\011muy raros.\012¡Déjame verlos!{DONE}",
  ["46:44d7"] = "¡Bah! ¡He perdido!\n¡Qué rabia me da!{DONE}",
  ["46:44f9"] = "¿Tienes una\nPOKéDEX? Pues te\011daré una pista.\012El MONTAÑERO de\nla RUTA 33, LUIS,\011es un buen chico.\012Te telefoneará\nsi ve algún\011POKéMON raro.{DONE}",
  ["46:457a"] = "Puerta cerrada…{DONE}",
  ["46:458d"] = "Puerta abierta.{DONE}",
  ["46:45a0"] = "Puerta abierta con\nLLAVE del SÓTANO.{DONE}",
  ["46:45c3"] = "¡Hola! ¡Yo dirijo\012la PELUQUERÍA\nPOKéMON!\012Soy el mayor y\nel mejor de los\012dos HERMANOS\nPELUQUEROS.\012Puedo poner guapos\na tus POKéMON por\011sólo 500¥.\012¿Quieres que les\ncorte el pelo?{DONE}",
  ["46:4664"] = "¿A qué POKéMON\nle corto el pelo?{DONE}",
  ["46:4682"] = "¡Vale! ¡Verás lo\nbien que queda!{DONE}",
  ["46:46a2"] = "¡Bien! ¡Ya está!{DONE}",
  ["46:46b4"] = "¿De verdad?\n¡Qué vergüenza!{DONE}",
  ["46:46d3"] = "Necesitarás más\ndinero.{DONE}",
  ["46:46f5"] = "Sólo corto el pelo\nuna vez al día.\011Ya vale por hoy.{DONE}",
  ["46:4726"] = "¡Bienvenido a la\nPELUQUERÍA!\012Soy el más joven y\nel más novato de\012los dos HERMANOS\nPELUQUEROS.\012Pondré guapos a\ntus POKéMON por\011sólo 300¥.\012¿Qué dices?{DONE}",
  ["46:47bb"] = "¿A qué POKéMON\nle corto el pelo?{DONE}",
  ["46:47d8"] = "¡Vale! Ya verás lo\nbien que queda.{DONE}",
  ["46:47f4"] = "¡Muy bien!\n¡Ya está!{DONE}",
  ["46:480c"] = "¿No?\n¡Qué lástima!{DONE}",
  ["46:4825"] = "No te queda\nmucho dinero.{DONE}",
  ["46:4845"] = "Sólo corto el pelo\nuna vez al día.\012Perdona, pero hoy\nno trabajo más.{DONE}",
  ["46:4889"] = "{STRBUF}\nparece un poco\011más feliz.{DONE}",
  ["46:48a6"] = "{STRBUF}\nparece feliz.{DONE}",
  ["46:48b8"] = "¡{STRBUF}\nestá encantado!{DONE}",
  ["46:48ce"] = "Lo siento,\nhemos cerrado.{DONE}",
  ["46:48e4"] = "PROHIBIDO PASAR\nDE ESTE PUNTO{DONE}",
  ["46:4e67"] = "¡Alto ahí!\012Te he visto y te\nhe seguido.\012No quiero verte\ncerca mientras\012me ocupo del TEAM\nROCKET.\012Espera un segundo.\nMe venciste antes,\011¿verdad?\012¡Tuviste mucha\nsuerte!\012¡Pero yo pago\nmis deudas!{DONE}",
  ["46:4f27"] = "¿Por qué? ¿Cómo\nhe podido perder?\012He usado a mis\nmejores POKéMON.\012No he bajado la\nguardia.\012¿Cómo he perdido?{DONE}",
  ["46:4f8c"] = "No lo\nentiendo…\012¿Es verdad lo que\ndijo ese LANCE?\012¿Qué no cuido bien\na mis POKéMON?\012Amor…\012Confianza…\012¿Es eso lo que\nme falta?\012¿Es eso lo que me\nimpide ganar?\012Yo… No lo\nentiendo.\012Pero esto no\nacaba aquí.\012Ahora no. No por\nesta razón.\012¡No renunciaré a\nmi sueño de ser el\012mejor entrenador\nPOKéMON del mundo!{DONE}",
  ["46:50cc"] = "¡Bah! ¡Mira\nqué fuerte soy!\012Destruiré al\nTEAM ROCKET.\012Y machacaré a\nese tal LANCE.{DONE}",
  ["46:5140"] = "Me desafiaron a\nun combate en el\011piso de abajo.\012Ahí abajo son muy\nduros. Mejor que\011tengas cuidado.{DONE}",
  ["46:519a"] = "Abajo hay algunas\ntiendas…\012Pero también hay\nentrenadores.\012Me da miedo\nbajar ahí.{DONE}",
  ["46:51f5"] = "Una puerta se abre\ny otra se cierra.\012¡Seguro que no\nconsigues llegar!{DONE}",
  ["46:5239"] = "¡Caramba! ¡Perdí\npor mi indecisión!{DONE}",
  ["46:525a"] = "Tampoco lo sé…\nPrimero hay que\012pulsar el último\nbotón, pero…{DONE}",
  ["46:52a2"] = "¡Ajajaja!\012¿Confundido con\ntanta llave?\012¡Te contaré un\nsecreto si logras\011vencerme!{DONE}",
  ["46:52ff"] = "¡Ohhh…!\nFallé.{DONE}",
  ["46:5311"] = "Bien. ¡Una pista!\012Cambia el orden al\npulsar botones.\012Y cambiará la\nforma en que se\012abren y se cierran\nlas puertas.{DONE}",
  ["46:5378"] = "¡Paga tus\ndeudas!{DONE}",
  ["46:5391"] = "¡Misericordia!{DONE}",
  ["46:5399"] = "¡Robar y vender!\n¡La base de todo\011acto criminal!{DONE}",
  ["46:53c5"] = "Abandonaron este\nproyecto antes\011de terminarlo.\012Estoy buscando\nrestos.{DONE}",
  ["46:5416"] = "¡Por encima!{DONE}",
  ["46:5425"] = "¿Al ALMACÉN\nSUBTERRÁNEO?\012¿Para qué quieres\nir ahí?\012Ahí abajo no\nhay nada.{DONE}",
  ["46:547c"] = "¡Qué me importa si\nte has perdido!\012Apareciste aquí,\n¡eres sólo una\011víctima!{DONE}",
  ["46:54c6"] = "¡Seguro! Te crees\ngenial, ¿verdad?{DONE}",
  ["46:54e9"] = "Debes de tener\nhielo en las venas\012para enfrentarte\nal TEAM ROCKET.{DONE}",
  ["46:551e"] = "Viene marcado\ncomo BOTÓN 1.{DONE}",
  ["46:5535"] = "¿Estás perdido?\nNo, es imposible.\012No pareces\nasustado.\012¡Te daré algo\nque te\011asustará!{DONE}",
  ["46:55a0"] = "¿Cómo ha sido?{DONE}",
  ["46:55b0"] = "¡Ve a donde\nquieras! ¡Lárgate!\011¡No me importa!{DONE}",
  ["46:55e1"] = "Está APAGADO.\n¿ENCENDERLO?{DONE}",
  ["46:55f7"] = "Está ENCENDIDO.\n¿APAGARLO?{DONE}",
  ["46:560d"] = "Viene marcado\ncomo BOTÓN 2.{DONE}",
  ["46:5624"] = "Viene marcado\ncomo BOTÓN 3.{DONE}",
  ["46:563b"] = "Viene marcado\ncomo EMERGENCIA.{DONE}",
  ["46:5795"] = "¡Eh, chico! ¡Estás\ninterrumpiéndonos!\012¡Tenemos por\ncostumbre trabajar\012sin que nadie\nnos vea!{DONE}",
  ["46:57f7"] = "Pierdo las ganas\nde trabajar si hay\011alguien mirando.\012¡Venga, chaval,\nfuera de aquí!{DONE}",
  ["46:5840"] = "¡Oohah! ¡Oohah!\012Hay cosas tiradas\npor el suelo.\012¡Recógelas si\nquieres!{DONE}",
  ["46:5886"] = "MACHOKE: ¡Machok!{DONE}",
  ["46:59b3"] = "¿Cómo has llegado\nhasta aquí?\012Supongo que no\npudieron evitarlo.\011¡Acabaré contigo!{DONE}",
  ["46:59fd"] = "Acabó conmigo…{DONE}",
  ["46:5a11"] = "El TEAM ROCKET\nseguirá esperando\012el regreso de\nGIOVANNI.\012Haremos lo que\nsea necesario.{DONE}",
  ["46:5a70"] = "¡No vas a ir\nmás lejos!\012¡Soy implacable\ncon mis enemigos\012y con cualquier\nmocoso!{DONE}",
  ["46:5abf"] = "¡Maldición!{DONE}",
  ["46:5aca"] = "He perdido…\012¡Perdóname,\nGIOVANNI!{DONE}",
  ["46:5af0"] = "¡Ji, ji, ji!\n¡Te recuerdo!\012¡Me diste bien\nen la guarida!{DONE}",
  ["46:5b34"] = "¡Ji, ji, ji!\n¿Así funcionas?{DONE}",
  ["46:5b57"] = "¡Ji, ji, ji!\n¡Vaya combate!\011¡No te olvidaré!{DONE}",
  ["46:5b8f"] = "DIRECTOR: ¿Quién?\n¿Qué? ¿Has venido\011a rescatarme?\012¡Gracias!\012La TORRE de RADIO.\012¿Qué está pasando\nahí dentro?\012¿Invadida por el\nTEAM ROCKET?\012Mira. Toma esta\nLLAVE MAGNÉTICA.{DONE}",
  ["46:5c24"] = "DIRECTOR: Úsala\npara abrir las\011puertas de la P2.{DONE}",
  ["46:5c56"] = "Te ruego que\nme ayudes.\012¡Quién sabe lo\nque harían si se\012apoderaran de la\nemisora!\012¡Podrían hasta\ncontrolar a los\012POKéMON usando una\nseñal especial!\012Sólo tú puedes\nayudarme.\012Salva la TORRE\nde RADIO…\012¡Y a todos los\nPOKéMON del mundo!{DONE}",
  ["46:5f3d"] = "¡Hola!\012¡Soy el REY\ndel KARATE!\012¡Me entreno solo\nen la oscuridad!\012¡Tú!\n¡Lucha conmigo!\012¡Uaaarggh!{DONE}",
  ["46:5f99"] = "¡Aaaargg!\n¡He perdido!{DONE}",
  ["46:5fb0"] = "He… perdido…\012Tendré que seguir\nentrenándome…\012Pero una derrota\nes una derrota.\012Como prueba de tu\nvictoria, te voy\012a dar un raro\nPOKéMON de lucha.{DONE}",
  ["46:6045"] = "{PLAYER} recibió\na TYROGUE.{DONE}",
  ["46:605a"] = "TYROGUE es del\ntipo lucha.\012Evoluciona en\nun POKéMON\011más fuerte.\012Sigue así.\nYo también seguiré\011entrenándome.\012¡Adiós!{DONE}",
  ["46:60cf"] = "¡No tienes sitio\nen tu equipo!{DONE}",
  ["46:61cc"] = "La piedra cayó\npor el agujero.{DONE}",
  ["46:6267"] = "Está empotrado\nen el hielo.{DONE}",
  ["47:41c8"] = "¡Gyaaas!{DONE}",
  ["47:4292"] = "…\n…{DONE}",
  ["47:4297"] = "…{DONE}",
  ["47:429a"] = "…\n…{DONE}",
  ["47:438b"] = "¡Uauu! ¡Me has\nasustado!\012Tenía puestas las\nGAFAS DE SOL y\012no me di cuenta\nde tu presencia.\012¿Que qué estoy\nhaciendo aquí?\012No te preocupes\npor eso.\012Te daré unas GAFAS\nDE SOL si olvidas\012que me has\nvisto, ¿vale?{DONE}",
  ["47:4458"] = "Las GAFAS DE SOL\naumentan el poder\012de los movimientos\nde tipo siniestro.{DONE}",
  ["47:459c"] = "DÉBORA: Muy bien.\nReconozco tu\012verdadero poder.\nToma esta MEDALLA.{DONE}",
  ["47:45e1"] = "{PLAYER} recibió\nla MEDALLA DRAGÓN.{DONE}",
  ["47:45fa"] = "La MEDALLA DRAGÓN\npermitirá que tus\012POKéMON usen el\nmovimiento para\011subir cascadas.\012Y los POKéMON\nte reconocerán\012como entrenador y\nobedecerán todas\012tus órdenes sin\nrechistar.\012Además, te voy\na dar esta MT.{DONE}",
  ["47:46d6"] = "Esta MT contiene\nDRAGOALIENTO.\012No, no tiene\nnada que ver\011con mi aliento.\012Si no la quieres,\nno es necesario\011que la aceptes.{DONE}",
  ["47:4754"] = "Así que has\nconseguido todas\011las MEDALLAS.\012Ahora debes\ndirigirte a la\012LIGA POKéMON\nde MESETA AÑIL.\012¿Sabes cómo llegar\nhasta allí?\012Desde aquí, ve a\nPUEBLO PRIMAVERA.\012Luego haz SURF\nhacia el Este.\011No será fácil.\012¡Ni se te ocurra\nperder en la LIGA\011POKéMON!\012Si pierdes, ¡me\nsentiré aún peor\012por haber perdido\ncontra ti!{DONE}",
  ["47:4881"] = "SANTUARIO DRAGÓN\012Erigido en honor\nde los POKéMON\012dragón de la\nGUARIDA DRAGÓN{DONE}",
  ["47:48d6"] = "…\n¿Qué? ¿{PLAYER}?\012No, no lucharé\ncontra ti…\012Mis POKéMON no\npueden ganarte.\012Y ahora no puedo\npresionarles.\012La disciplina es\nclave para ser el\012mejor entrenador\nPOKéMON.{DONE}",
  ["47:4980"] = "…\012¡Vaya…!\012Aprende a no\ncruzarte en\011mi camino.{DONE}",
  ["47:49a6"] = "¡{PLAYER} encontró\n{STRBUF}!{DONE}",
  ["47:49b8"] = "Pero {PLAYER} no\npuede llevar\011más cosas.{DONE}",
  ["48:4101"] = "¡Uau! ¡Tu POKéGEAR\nes impresionante!\012¿Te la ha dado\ntu madre?{DONE}",
  ["48:413e"] = "¡Espera, {PLAYER}!{DONE}",
  ["48:4148"] = "¿Qué crees que\nestás haciendo?{DONE}",
  ["48:4168"] = "¡Es peligroso\nsalir sin\011un POKéMON!\012De camino hacia la\nsiguiente ciudad\012te encontrarás\nPOKéMON salvajes.{DONE}",
  ["48:41ce"] = "¡Oh, tu POKéMON es\nadorable! ¡Ojalá\011tuviera yo uno!{DONE}",
  ["48:41fc"] = "¡Hola, {PLAYER}!\n¿Te vas otra vez?\012Deberías decirle\na tu madre que\011te vas.{DONE}",
  ["48:4240"] = "Llama a tu madre\ncon la POKéGEAR\012y cuéntale cómo\nte va.{DONE}",
  ["48:427e"] = "¡Hola, {PLAYER}!\012Dicen que el PROF.\nELM ha descubierto\011nuevos POKéMON.{DONE}",
  ["48:42b0"] = "……\012Así que éste es el\nfamoso LABORATORIO\011POKéMON de ELM…{DONE}",
  ["48:42d7"] = "¿Qué estás\nmirando?{DONE}",
  ["48:42f2"] = "PUEBLO PRIMAVERA\012El pueblo donde\nsoplan vientos de\011un nuevo amanecer{DONE}",
  ["48:4332"] = "CASA DE {PLAYER}{DONE}",
  ["48:433c"] = "LABORATORIO DE ELM{DONE}",
  ["48:434a"] = "CASA DE ELM{DONE}",
  ["48:45ae"] = "Eres un entrenador\nnovato, ¿verdad?\011¡Estoy seguro!\012¡Está bien! ¡Todo\nel mundo es novato\011alguna vez!\012Si quieres, te\npuedo enseñar\011algunas cosas.{DONE}",
  ["48:463a"] = "¡De acuerdo!\n¡Sígueme!{DONE}",
  ["48:4650"] = "Esto es un\nCENTRO POKéMON.\012Aquí curan a\ntus POKéMON.\012Vas a necesitar\nmucho de ellos,\012así que mejor\nconocerlos.{DONE}",
  ["48:46cf"] = "Esto es una TIENDA\nPOKéMON.\012Hay POKé BALL para\ncapturar POKéMON\012salvajes y otras\nmuchas cosas.{DONE}",
  ["48:4724"] = "La RUTA 30 está\npor aquí.\012En ella luchan\nlos entrenadores\012con sus queridos\nPOKéMON.{DONE}",
  ["48:4772"] = "Como puedes ver,\nesto es el mar.\012Algunos POKéMON\nsólo viven en\011el agua.{DONE}",
  ["48:47b7"] = "Y…\012¡Ésta es mi casa!\nGracias por\011acompañarme.\012Déjame darte\nun regalito.{DONE}",
  ["48:4803"] = "¡Ahora el POKéGEAR\nde {PLAYER}\011tiene un MAPA!{DONE}",
  ["48:481c"] = "El POKéGEAR será\nmás útil cuando\011añadas TARJETAS.\012¡Mucha suerte\nen tu aventura!{DONE}",
  ["48:486a"] = "¡Oh…! Me\ngusta hacerlo…\012Vale. Ven a verme\ncuando quieras.{DONE}",
  ["48:48ad"] = "¿Qué…?\012¿Te han dado\nun POKéMON\011en el LABORATORIO?\012¡Qué desperdicio!\n¡Eres tan inútil!\012…\012¿No entiendes\nlo que digo?\012Pues yo también\ntengo un buen\012POKéMON. ¡Te\nlo demostraré!{DONE}",
  ["48:4942"] = "¿Estás contento\nde haber ganado?{DONE}",
  ["48:4961"] = "…\012¿Mi nombre?\012Voy a ser el\nmejor entrenador\012POKéMON del\nmundo.{DONE}",
  ["48:49a5"] = "¡Vaya pérdida\nde tiempo!{DONE}",
  ["48:49c7"] = "…\012¿Mi nombre?\012Voy a ser el\nmejor entrenador\012POKéMON del\nmundo.{DONE}",
  ["48:4a0b"] = "¿Has hablado con\nel anciano que\012está cerca del\nCENTRO POKéMON?\012Te dará un MAPA\nde JOHTO para tu\011POKéGEAR.{DONE}",
  ["48:4a63"] = "Cuando vas con los\nPOKéMON, cualquier\011sitio está bien.{DONE}",
  ["48:4a91"] = "La casa del SR.\nPOKéMON está\011más adelante.{DONE}",
  ["48:4abc"] = "He luchado contra\nlos entrenadores\011del camino.\012Mis POKéMON han\nperdido. ¡Están\012fatal! Los llevaré\nal CENTRO POKéMON.{DONE}",
  ["48:4b21"] = "Atrapé un POKéMON\ncon un objeto.\012Creo que es\nAGUA MÍSTICA.\012No lo necesito,\n¿lo quieres?{DONE}",
  ["48:4b7c"] = "Pues yo me\nvoy a pescar.{DONE}",
  ["48:4b9b"] = "CIUDAD CEREZO\012La ciudad de las\nflores bonitas y\011fragantes{DONE}",
  ["48:4bd0"] = "CASA DEL GUÍA{DONE}",
  ["48:4d29"] = "¡Hola! ¿Eres un\nentrenador? ¿Has\012ganado al LÍDER\ndel GIMNASIO?{DONE}",
  ["48:4d62"] = "¡Oh la la!\n¡Muy bien!{DONE}",
  ["48:4d81"] = "¿Es verdad? ¡Pues\ntú estudiarás!\011¡Sígueme!{DONE}",
  ["48:4daf"] = "El profesor soy\nyo. ¡Bien está\011que aquí estudies!{DONE}",
  ["48:4ddf"] = "Dicen que en la\nTORRE BELLSPROUT\011hay fantasmas.\012Y dicen que los\nPOKéMON normales\012no afectan\na los fantasmas.{DONE}",
  ["48:4e49"] = "¿Eres entrenador\nPOKéMON?\012¡Si ganas a este\nLÍDER de GIMNASIO,\012estarás en el\ncamino del éxito!{DONE}",
  ["48:4ea5"] = "¡PEGASO, del\nGIMNASIO POKéMON\012de CIUDAD MALVA,\nes magnífico!\012Heredó el\ngimnasio de su\012padre y ha hecho\nun gran trabajo.{DONE}",
  ["48:4f1b"] = "¡He visto un árbol\nque se mueve!\012¡Si lo tocas,\nse retuerce y\011baila! ¡Es genial!{DONE}",
  ["48:4f68"] = "CIUDAD MALVA\012La ciudad de los\naromas nostálgicos{DONE}",
  ["48:4f92"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011MALVA: PEGASO\012El elegante\nmaestro de los\011POKéMON voladores{DONE}",
  ["48:4fda"] = "TORRE BELLSPROUT\012Vive la vida\nPOKéMON{DONE}",
  ["48:5003"] = "ACADEMIA POKéMON\nDE PRIMO{DONE}",
  ["48:51e7"] = "Dime una\ncosa…\012¿Es cierto que\nel TEAM ROCKET\011ha vuelto?\012¿Qué? ¿Los has\nderrotado? ¡Anda!\011¡No me mientas!\012¿Bromeas?\nPues a ver lo\011bueno que eres.{DONE}",
  ["48:5280"] = "¡Vaya!\n¡Inútiles POKéMON!\012¡Escúchame! ¡Has\nganado porque\012mis POKéMON\neran débiles!{DONE}",
  ["48:52cd"] = "Odio a los\ndébiles.\012Ya sean POKéMON\no entrenadores. Da\011igual quién o qué.\012Seré fuerte\ny acabaré con los\011enclenques.\012Eso también va por\nel TEAM ROCKET.\012Son fuertes cuando\nestán en grupo,\012pero si están\nsolos, son unos\011cobardes.\012¡Cuánto les odio!\012¡Fuera de mi\nvista! ¡Eres tan\012insignificante\ncomo el resto!{DONE}",
  ["48:53f5"] = "¡Ja! Sabía\nque mentías.{DONE}",
  ["48:5415"] = "Entrar ahí es muy\npeligroso, por eso\011estoy de guardia.\012¿A que soy un\nbuen samaritano?{DONE}",
  ["48:5461"] = "¿Sabes algo sobre\nlas COLASLOWPOKE?\012¡Dicen que son\nmuy sabrosas!\012¿Contento de que\nte lo haya dicho?{DONE}",
  ["48:54b5"] = "Los SLOWPOKE han\ndesaparecido del\011pueblo…\012Dicen que venden\nsus COLAS en algún\011lugar.{DONE}",
  ["48:550d"] = "Los SLOWPOKE\nhan vuelto.\012Conociéndolos,\nquizá han estado\012remoloneando en\nalgún lugar.{DONE}",
  ["48:5568"] = "¿Viste a CÉSAR\npara que te diera\011algunas BALL?\012Muchas personas\nlo hacen.{DONE}",
  ["48:55b4"] = "Ataja por PUEBLO\nAZALEA y llegarás\011al ENCINAR.\012Pero estos\narbolitos te\011impiden pasar.\012Los POKéMON del\nCARBONERO pueden\011CORTAR árboles.{DONE}",
  ["48:564a"] = "SLOWPOKE: …\012…… …… ……{DONE}",
  ["48:565d"] = "(bostezo)……{DONE}",
  ["48:5679"] = "PUEBLO AZALEA\nDonde la gente y\012los POKéMON viven\nen feliz armonía{DONE}",
  ["48:56b2"] = "CASA DE CÉSAR{DONE}",
  ["48:56c0"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\011AZALEA: ANTÓN\012La enciclopedia\nandante de los\011POKéMON bicho{DONE}",
  ["48:5706"] = "POZO SLOWPOKE\012Conocido también\ncomo POZO LLUVIA.\012Los nativos creen\nque el bostezo de\012SLOWPOKE invoca\nla lluvia.\012Hace 400 años\nun bostezo de\012SLOWPOKE acabó\ncon una sequía.{DONE}",
  ["48:57ac"] = "CASA DEL CARBONERO{DONE}",
  ["48:57bb"] = "EL ENCINAR\012Entra por la\npuerta{DONE}",
  ["48:5936"] = "¿Has cruzado el\nmar para llegar\012hasta aquí? ¡Habrá\nsido duro!\012Todo sería mucho\nmás fácil si tus\012POKéMON supieran\nVUELO…{DONE}",
  ["48:59a8"] = "Pero no puedes\nusar VUELO sin la\012MEDALLA de esta\nciudad.\012Si vences al LÍDER\nde este GIMNASIO,\011ven a verme.\012Te daré un\nbonito regalo.{DONE}",
  ["48:5a28"] = "¡Es la MEDALLA de\nCIUDAD ORQUÍDEA!\012¡Toma esta\nMO!{DONE}",
  ["48:5a62"] = "Enseña VUELO a\ntus POKéMON.\012En un instante\npodrás VOLAR a\012cualquier lugar al\nque ya hayas ido.{DONE}",
  ["48:5abc"] = "Mi marido perdió\ncontra ti. Debería\011entrenarse más.\012Menos mal, porque\nya estaba\011engordando.{DONE}",
  ["48:5b24"] = "Si usas VUELO,\npodrás volver a\012CIUDAD OLIVO\nenseguida.{DONE}",
  ["48:5b5e"] = "Las piedras del\nnorte del pueblo\011se pueden romper.\012Quizá escondan\nalgo.\012Tus POKéMON pueden\nusar el GOLPE ROCA\011para romperlas.{DONE}",
  ["48:5bd9"] = "ANÍBAL, el LÍDER\ndel GIMNASIO,\012pelea con sus\nPOKéMON de lucha.{DONE}",
  ["48:5c78"] = "CIUDAD ORQUÍDEA\012Un puerto rodeado\nde agitadas aguas{DONE}",
  ["48:5ca7"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\012ORQUÍDEA: ANÍBAL\012Sus puños\nhablan por él{DONE}",
  ["48:5cee"] = "500 años de\ntradición\012FARMACIA DE\nCIUDAD ORQUÍDEA\012Aceptamos\npedidos{DONE}",
  ["48:5d3d"] = "ESTUD. FOTOGRÁFICO\nDE CIUDAD ORQUÍDEA\012¡Hazte una foto\nde recuerdo!{DONE}",
  ["48:5ec6"] = "Han construido una\nTORRE RADIO nueva\012que sustituye a\nla antigua.{DONE}",
  ["48:5f06"] = "Sé que hay una\nnueva TIENDA de\012BICIS, pero no\nla encuentro.{DONE}",
  ["48:5f43"] = "¿Ese hombre de\nnegro se ha\012vestido como uno\ndel TEAM ROCKET?\011¡Qué tonto!{DONE}",
  ["48:5f8a"] = "¿Pertenecía ese\nhombre de negro\012al TEAM ROCKET?\n¡Es increíble!{DONE}",
  ["48:5fd0"] = "La TORRE de RADIO\nde CIUDAD TRIGAL\011es muy importante.\012Ahora están en\nuna campaña\011promocional.\012Modificarán tu\nPOKéGEAR para\012que te sirva\ntambién de radio.{DONE}",
  ["48:6071"] = "¡Oh, tu POKéGEAR\nsirve de radio!{DONE}",
  ["48:6093"] = "¡Eh, eh, eh…!\012Me he metido en\nlíos por jugar en\012el sótano del\nCENTRO COMERCIAL.{DONE}",
  ["48:60e0"] = "El hombre de esa\ncasa evalúa los\012nombres de\ntus POKéMON.\012Y puede renombrar\na tus POKéMON.{DONE}",
  ["48:612c"] = "¡Uau! Esta ciudad\nes muy grande.\012No sé dónde\nestá nada.{DONE}",
  ["48:616a"] = "Así que ésta es la\nTORRE de RADIO…{DONE}",
  ["48:6187"] = "¿Qué quieres,\npesado? ¡Fuera!{DONE}",
  ["48:61ab"] = "¡Fuera de mi\ncamino! ¡Pesado!{DONE}",
  ["48:61ca"] = "Asaltemos la\nTORRE de RADIO…\012¿Qué? ¡Y a ti\nqué te importa!{DONE}",
  ["48:6207"] = "¿Los POKéMON?\n¡Sólo son\012herramientas para\nganar dinero!{DONE}",
  ["48:623f"] = "Nuestro sueño se\ncumplirá pronto…\012Ha sido una lucha\ntan larga…{DONE}",
  ["48:627c"] = "¡Eh, mocoso! ¡Tú\nno eres de aquí!\011¡Lárgate!{DONE}",
  ["48:62a8"] = "¡Prueba el\nverdadero terror\011del TEAM ROCKET!{DONE}",
  ["48:62d4"] = "ESTACIÓN DE\nCIUDAD TRIGAL{DONE}",
  ["48:62ec"] = "TORRE DE RADIO\nDE CIUDAD TRIGAL{DONE}",
  ["48:6308"] = "¡Una gran gama de\nartículos POKéMON!\012CENTRO COMERCIAL\nDE CIUDAD TRIGAL{DONE}",
  ["48:6341"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011TRIGAL: BLANCA\012¡La increíble y\nbella señorita!{DONE}",
  ["48:6386"] = "CIUDAD TRIGAL\012La alegre ciudad\nde rico encanto{DONE}",
  ["48:63b8"] = "¡El mundo es un\ncamino de bicis!\011TIENDA DE BICIS{DONE}",
  ["48:63de"] = "¡Tu zona de juego!\012CASINO DE\nCIUDAD TRIGAL{DONE}",
  ["48:640b"] = "INSPECTOR DE MOTES\012Evalúa los motes\nde tus POKéMON{DONE}",
  ["48:6435"] = "ENTRADA\nSUBTERRÁNEA{DONE}",
  ["48:644b"] = "ENTRADA\nSUBTERRÁNEA{DONE}",
  ["49:40d7"] = "…\012¿Tú otra vez?\012¿Y a mí qué me\nimporta? No me\012asustan los\ncanijos como tú.\012Y hablando de\ndebiluchos, la\012LÍDER del GIMNASIO\nno está aquí.\012Se supone que está\ncuidando a un\012POKéMON enfermo\nen el FARO.\012¡Buuuu! ¡Fuera\nlos POKéMON\011enfermos!\012¡Los POKéMON que\nno pueden luchar\011son unos inútiles!\012¿Por qué no vas\na entrenar al\011FARO?\012¿Quién sabe?\n¡A lo mejor\011te refuerza!{DONE}",
  ["49:4235"] = "Las calles oscuras\nson muy peligrosas\011por la noche.\012Pero si es noche\ncerrada, ¡el mar\012es aún más\ntraicionero!\012Si no les guiara\nla luz del FARO,\012los barcos no\npodrían navegar.{DONE}",
  ["49:42e1"] = "Eso que tienes\nes un POKéGEAR,\012¿verdad? ¡Uauu!\n¡Es genial!{DONE}",
  ["49:431e"] = "¡Uauu, tienes una\nPOKéDEX! Es\012realmente\nincreíble.{DONE}",
  ["49:434e"] = "¡Hola, chaval!\n¡Me gusta el mar!\012¡Canta conmigo!\n¡Yo jo!\011¡Yo jo…!{DONE}",
  ["49:439a"] = "CIUDAD OLIVO\012El puerto a\ntierras lejanas{DONE}",
  ["49:43ca"] = "PUERTO OLIVO\nMUELLE DEL FERRY{DONE}",
  ["49:43e7"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011OLIVO: YASMINA\012La chica\nde acero{DONE}",
  ["49:442a"] = "FARO DE OLIVO\nTambién conocido\012como el FARO\nBRILLANTE.{DONE}",
  ["49:4604"] = "En CIUDAD IRIS\nhabía dos torres:\012una en el Este y\notra en el Oeste.{DONE}",
  ["49:4646"] = "¡Ah, chaval!\n¿Has aprendido a\012bailar como las\nCHICAS KIMONO?\012Si vas a su\nTEATRO de DANZA,\012un anciano raro te\ndará algo bonito.\011Eso me han dicho.{DONE}",
  ["49:46de"] = "Voy a practicar en\nel TEATRO de\012DANZA. ¿Vienes\nconmigo?{DONE}",
  ["49:471d"] = "Esa torre era\nmucho más alta,\012pero se quemó\nen un incendio.{DONE}",
  ["49:4761"] = "Tres POKéMON\nhuyeron en tres\012direcciones.\n¿Qué eran?{DONE}",
  ["49:47a4"] = "He oído un rumor\nsobre el FARO\011OLIVO.\012El POKéMON que\nusan como luz\012ha caído enfermo.\nParece que tienen\011problemas.{DONE}",
  ["49:481d"] = "El POKéMON de\nFARO OLIVO se\011ha curado.\012Los barcos pueden\nvolver a navegar\011seguros de noche.{DONE}",
  ["49:487e"] = "Los POKéMON están\ncausando estragos\012en el LAGO DE\nLA FURIA. Me\011encantaría verlo.{DONE}",
  ["49:48c3"] = "CIUDAD IRIS\nUna ciudad donde\012conviven el pasado\ny el presente{DONE}",
  ["49:4905"] = "TORRE HOJALATA\012Aquí duerme un\nPOKéMON\011legendario.{DONE}",
  ["49:493a"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011IRIS: MORTI\012El místico adivino\ndel futuro{DONE}",
  ["49:497e"] = "TEATRO DE DANZA\nDE CIUDAD IRIS{DONE}",
  ["49:4996"] = "TORRE QUEMADA\012Destruida por\nun misterioso\011incendio.\012¡Atención!\n¡Peligro!{DONE}",
  ["49:4b65"] = "¡Hola, hijito! Ya\nveo que eres nuevo\011en PUEBLO CAOBA.\012¡Ya que eres nuevo\ndeberías probar\012el delicioso\nCARAMELO FURIA!\012¡Puede ser tuyo\npor sólo 300¥!\011¿Quieres uno?{DONE}",
  ["49:4c03"] = "¡Bien! ¡Saboréalo!{DONE}",
  ["49:4c14"] = "No tienes\nbastante dinero.{DONE}",
  ["49:4c31"] = "¡Oh, de acuerdo…!{DONE}",
  ["49:4c41"] = "No tienes\nespacio para esto.{DONE}",
  ["49:4c5f"] = "CARAMELOS FURIA\nagotados.\012Estoy haciendo las\nmaletas. No me\011molestes, hijito.{DONE}",
  ["49:4ca2"] = "¿Vas al LAGO a ver\na los violentos\011GYARADOS?{DONE}",
  ["49:4cda"] = "MAGIKARP ha\nvuelto al LAGO\011DE LA FURIA.\012Son buenas\nnoticias para\011los pescadores.{DONE}",
  ["49:4d33"] = "Has venido de muy\nlejos. Tómate\012tiempo para ver\nel paisaje.\012Deberías ir hacia\nel Norte y ver lo\012que pasa en el\nLAGO DE LA FURIA.{DONE}",
  ["49:4daf"] = "Visita la tienda\nde la Abuela. Hay\012cosas que sólo\nella tiene.{DONE}",
  ["49:4deb"] = "PUEBLO CAOBA\012Bienvenido al\nhogar de los Ninja{DONE}",
  ["49:4e1b"] = "¡Si visitas PUEBLO\nCAOBA, prueba\011un CARAMELO FURIA!{DONE}",
  ["49:4e4e"] = "LÍDER DEL GIMNASIO\nPOKéMON DE PUEBLO\011CAOBA: FREDO\012El maestro del\ncrudo invierno{DONE}",
  ["49:5063"] = "Este LAGO\nestá lleno de\011GYARADOS…\012Así que los\nMAGIKARP\012deben haber\nevolucionado.{DONE}",
  ["49:50c0"] = "¿Has venido hasta\naquí por los\011rumores?\012¿Eres {PLAYER}?\nYo soy LANCE, un\011entrenador más.\012He oído rumores\ny he venido a\011investigar…\012Te he visto\nluchar, {PLAYER}.\012Creo que como\nentrenador eres\011muy bueno.\012Si no te importa,\n¿quieres ayudarme\011a investigar?{DONE}",
  ["49:51d2"] = "LANCE: ¡Excelente!\012Parece que los\nMAGIKARP del LAGO\012se ven obligados a\nevolucionar.\012La razón es una\nmisteriosa emisión\012de radio desde\nPUEBLO CAOBA.\012Te esperaré\nallí, {PLAYER}.{DONE}",
  ["49:527d"] = "¡Oh…! Si\ncambias de opinión\012agradecería tu\nayuda.{DONE}",
  ["49:52b1"] = "LANCE: ¿Qué?\n¿Me vas a ayudar?{DONE}",
  ["49:52d7"] = "GYARADOS: ¡Gyaraa!{DONE}",
  ["49:52eb"] = "{PLAYER} obtuvo\nuna ESCAMA ROJA.{DONE}",
  ["49:5304"] = "¡Los GYARADOS\nestán enfadados!\012¡Mal presagio!{DONE}",
  ["49:532d"] = "¡Ajaa! ¡Los\nMAGIKARP pican!{DONE}",
  ["49:5350"] = "Dicen que este\nlago fue obra\012de violentos\nGYARADOS.\012Me pregunto si eso\nestará relacionado\012con su actual\nrebelión.{DONE}",
  ["49:53c7"] = "¿Me han engañado\nmis ojos? He visto\012un GYARADOS rojo\nen el LAGO…\012Yo pensaba que\nlos GYARADOS eran\011siempre azules.{DONE}",
  ["49:542e"] = "¡Déjame luchar con\nel POKéMON que\011acabo de atrapar!{DONE}",
  ["49:545a"] = "Puede que sea un\npescador experto,\012pero soy un mal\nentrenador…{DONE}",
  ["49:549b"] = "¡No perderé como\npescador! Me paso\012el día capturando\nPOKéMON.{DONE}",
  ["49:54cc"] = "Haga lo que haga,\nsiempre capturo\012los mismos\nPOKéMON…{DONE}",
  ["49:5503"] = "Mi caña se ha\nenredado…{DONE}",
  ["49:551d"] = "¿Por qué no atrapo\nbuenos POKéMON?{DONE}",
  ["49:553e"] = "Si un entrenador\nse encuentra con\012otro entrenador,\ndebe desafiarle.\012Ése es nuestro\ndestino.{DONE}",
  ["49:5594"] = "¡Uauu…!\nBuen combate.{DONE}",
  ["49:55a8"] = "Los POKéMON y su\nentrenador se\012hacen más fuertes\ncuanto más luchan.{DONE}",
  ["49:55eb"] = "¿Qué ocurrió con\nel GYARADOS rojo?\012¿Se ha ido?\012¡Maldición! ¿He\nvenido para nada?\012Ya sé.\n¡Luchemos!{DONE}",
  ["49:5651"] = "¡Muy bien!{DONE}",
  ["49:565e"] = "Pensándolo bien,\ncreo que vi un\011BUTTERFREE rosa.{DONE}",
  ["49:5690"] = "MIGUEL: Hola,\n¿qué tal estás?\012Hoy es miércoles\ny yo soy MIGUEL,\012por lo de\nmiércoles.{DONE}",
  ["49:56e9"] = "Encantado de\nconocerte. Toma\011un recuerdo.{DONE}",
  ["49:5717"] = "MIGUEL: CINTURÓN\nNEGRO potencia los\011ataques de lucha.{DONE}",
  ["49:5750"] = "MIGUEL: Como me\nhas encontrado,\012habrás visto a\nmis hermanos.\012¿O es que has\ntenido suerte?{DONE}",
  ["49:57b5"] = "MIGUEL: Hoy no\nes miércoles.\011¡Qué pena!{DONE}",
  ["49:57e3"] = "LAGO DE LA FURIA,\nconocido como\011LAGO DE GYARADOS.{DONE}",
  ["49:580f"] = "CASA DEL GURÚ\nPESCADOR{DONE}",
  ["49:5994"] = "Lo siento.\012Nuestro LÍDER de\nGIMNASIO está\012entrenando en una\ncueva aquí detrás.\012No tengo ni idea\nde cuándo volverá.{DONE}",
  ["49:5a01"] = "Te espera el LÍDER\ndel GIMNASIO.\012Pero es imposible\nque le gane un\012entrenador del\nmontón.{DONE}",
  ["49:5a6b"] = "¿Venciste al LÍDER\ndel GIMNASIO? ¡Es\011increíble!\012Con tu poder,\nseguro que\012triunfas en la\nLIGA POKéMON.{DONE}",
  ["49:5ad0"] = "Aquí sólo pueden\nentrenar los que\012usan dragones.\nVete, por favor.{DONE}",
  ["49:5b0e"] = "DÉBORA, la maestra\nde los dragones,\012da su permiso, así\nque puedes entrar.{DONE}",
  ["49:5b4e"] = "¿Mi radio está\nrota? Sólo recibo\011esta rara señal.{DONE}",
  ["49:5b87"] = "¡Auu! ¡Voces en\nmi cabeza! ¿Cómo?\012¡Estoy escuchando\nla radio!{DONE}",
  ["49:5bc1"] = "¿Quieres que\ntus POKéMON\012olviden algún\nmovimiento?{DONE}",
  ["49:5bf5"] = "Voy a usar\ndragones como\011hace DÉBORA.{DONE}",
  ["49:5c1f"] = "SABINO: …\012Es sábado…\012Soy SABINO, por\nsábado…{DONE}",
  ["49:5c4f"] = "Toma esto…{DONE}",
  ["49:5c63"] = "SABINO: …\012HECHIZO…\012Mejora los\nmovimientos de\011tipo fantasma.\012Te voy a\nasustar…{DONE}",
  ["49:5cae"] = "SABINO: …\012Nos vemos otro\nsábado…\012Pero ya no tendré\nmás regalos…{DONE}",
  ["49:5cf8"] = "SABINO: Hoy no\nes sábado…{DONE}",
  ["49:5d16"] = "¡Uau! ¿Has venido\npor la RUTA\011HELADA?\012¡Debes de ser un\nentrenador genial!{DONE}",
  ["49:5d5f"] = "CIUDAD ENDRINO\012Un tranquilo\nrefugio de montaña{DONE}",
  ["49:5d89"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011ENDRINO: DÉBORA\012La gran experta en\nPOKéMON dragón{DONE}",
  ["49:5dd1"] = "CASA DEL\nQUITA-MOVIMIENTOS{DONE}",
  ["49:5de7"] = "HACIA LA GUARIDA\nDEL DRAGÓN{DONE}",
  ["49:5dfb"] = "PISTAS ENTRENADOR\012Todo POKéMON que\nvaya equipado con\012una BAYA MILAGRO\nse curará a sí\011mismo en combate.{DONE}",
  ["49:5f27"] = "MT. PLATEADO{DONE}",
  ["4a:4175"] = "Estoy haciendo\nlos últimos\012preparativos para\nla LIGA POKéMON.{DONE}",
  ["4a:41ab"] = "¡Caramba!{DONE}",
  ["4a:41b7"] = "Va a ser difícil\nganar en la\011LIGA.\012Tengo que\nentrenar más.\012Dicen que el ALTO\nMANDO es más duro\012que los LÍDERES\nde GIMNASIO.{DONE}",
  ["4a:4246"] = "Es en estos duros\ncombates donde\011ganas más poder.{DONE}",
  ["4a:4276"] = "¡La vida es\naún más dura!{DONE}",
  ["4a:4293"] = "Para llegar a la\nLIGA POKéMON,\012hay que pasar por\nla CALLE VICTORIA.\012Pero la CALLE\nVICTORIA es dura.\012¡No va allí\ncasi nadie!{DONE}",
  ["4a:430b"] = "Si has llegado tan\nlejos, debes de\011ser muy bueno.\012¡Voy a dar todo\nlo que tengo en\011este combate!{DONE}",
  ["4a:436c"] = "¡No! ¡No puedo\ncreerlo!{DONE}",
  ["4a:4386"] = "Como había vencido\na ocho LÍDERES\012de GIMNASIO, me\nconfié demasiado.\012Tendré que\nesforzarme más.{DONE}",
  ["4a:43e5"] = "He perdido contra\n{RIVAL}.\012Era realmente\nfuerte, pero…\012Parecía como si\ntuviera que ganar\011a toda costa.\012Me dieron pena\nsus POKéMON.{DONE}",
  ["4a:446e"] = "Los POKéMON no son\narmas de guerra.{DONE}",
  ["4a:4488"] = "Los POKéMON son\nvaliosos amigos\011para toda la vida.{DONE}",
  ["4a:44b3"] = "¡Uau! ¡Cuántas\nMEDALLAS! Estoy\011impresionado.\012Pero no te basta\nsólo con\012coleccionarlas,\n¿verdad?{DONE}",
  ["4a:4519"] = "¡Buena batalla!{DONE}",
  ["4a:4527"] = "Las personas y los\nPOKéMON se\012enriquecen con la\nexperiencia.\012No seas vago\ny conformista.{DONE}",
  ["4a:4573"] = "¡Hoy me siento\nmuy bien!\012¡Siento que podría\nvencer hasta al\011CAMPEÓN de LIGA!{DONE}",
  ["4a:45bc"] = "¡No! ¡En esta\nbatalla, no!{DONE}",
  ["4a:45d5"] = "Como en la pesca,\ncon los POKéMON\012todo está perdido\nsi te rindes.{DONE}",
  ["4a:4613"] = "RUTA 26\012RECEPCIÓN DE LA\nLIGA POKéMON{DONE}",
  ["4a:486a"] = "¡Eh!{DONE}",
  ["4a:4870"] = "¿Sabes lo que\nacabas de hacer?\012Acabas de\nentrar en\011KANTO.\012Consulta el MAPA\ndel POKéGEAR.{DONE}",
  ["4a:48d8"] = "Pareces muy\nfuerte. ¡Déjame\011luchar contigo!{DONE}",
  ["4a:4904"] = "¡Yau!{DONE}",
  ["4a:490a"] = "Si continúas por\neste duro camino,\012¡conocerás la\nverdad!\012Lo siento, pero me\napetecía decir\011algo chulo.{DONE}",
  ["4a:497b"] = "¿Mmm? Eres bueno,\n¿verdad?{DONE}",
  ["4a:4997"] = "¡Tal como pensaba!{DONE}",
  ["4a:49ab"] = "Un buen entrenador\nsabe reconocer a\012otros buenos\nentrenadores.{DONE}",
  ["4a:49de"] = "No deberías\nsubestimar a los\012POKéMON salvajes\nde esta zona.{DONE}",
  ["4a:4a18"] = "¡Oh! ¡Qué\nfuerte eres!{DONE}",
  ["4a:4a34"] = "Eres sólo un niño,\npero tampoco\012se te puede\nsubestimar.{DONE}",
  ["4a:4a72"] = "Es raro que venga\nalguien por aquí.\012¿Te estás\nentrenando solo?{DONE}",
  ["4a:4ab3"] = "¡Oh! ¡Eres\nmuy fuerte!{DONE}",
  ["4a:4acd"] = "Estoy investigando\nlos POKéMON antes\012y después de que\nevolucionen.\012Los POKéMON se\nhacen más fuertes\011al evolucionar.\012Pero aprenderán\nnuevos movimientos\012mucho más despacio\nque antes.{DONE}",
  ["4a:4b54"] = "¡No digas nada!\012Déjame adivinar lo\nque piensas.\012¡Mmmmmmm…!\012¡Listo! ¡Estás\nen la LIGA\011POKéMON!{DONE}",
  ["4a:4bc0"] = "¡Eres demasiado!{DONE}",
  ["4a:4bd1"] = "Con tus\nhabilidades,\012te irá bien\nen la LIGA.\012Eso es lo que\npresiento.{DONE}",
  ["4a:4c21"] = "¡Pío! ¡Pío!\n¡Píooo!{DONE}",
  ["4a:4c39"] = "¡Pío!{DONE}",
  ["4a:4c41"] = "Los ORNITÓLOGOS\nimitan el canto de\012los pájaros para\ncontrolar POKéMON.{DONE}",
  ["4a:4c7e"] = "CATARATAS TOHJO\012La conexión entre\nKANTO y JOHTO.{DONE}",
  ["4a:4d53"] = "RUTA 28{DONE}",
  ["4a:4ed2"] = "Los POKéMON se\nesconden en la\012hierba. Nadie sabe\ncuando salen…{DONE}",
  ["4a:4f0a"] = "Te he visto un par\nde veces. ¿Cuántos\012POKéMON has\natrapado?\012¿Quieres que te\nenseñe a atrapar\011POKéMON?{DONE}",
  ["4a:4f78"] = "Así es como\nse hace.\012Si los debilitas,\nlos POKéMON\012son más fáciles\nde atrapar.{DONE}",
  ["4a:4fc2"] = "¡Ah! ¡Muy bien!\012Pero si quieres\natrapar POKéMON,\012tendrás que\ncaminar mucho.{DONE}",
  ["4a:500e"] = "¿Qué? ¿Quieres que\nte enseñe a\011atrapar POKéMON?{DONE}",
  ["4a:503f"] = "¿Cómo están tus\nPOKéMON?\012Si están débiles y\nno pueden luchar,\012no entres en\nla hierba.{DONE}",
  ["4a:5097"] = "¿Ves esos setos?\nDa miedo\011saltarlos.\012Pero puedes ir a\nPUEBLO PRIMAVERA\012sin pasar por\nla hierba.{DONE}",
  ["4a:5104"] = "Quería descansar\nun poco, así que\012guardé la\npartida.{DONE}",
  ["4a:5177"] = "Estoy esperando a\nlos POKéMON\012que aparecen sólo\npor la noche.{DONE}",
  ["4a:51a7"] = "Estoy esperando a\nlos POKéMON\012que aparecen sólo\npor la mañana.{DONE}",
  ["4a:51dd"] = "MARTA: Creo que\nes la primera\012vez que nos\nvemos.\012Déjame que me\npresente. Soy\012MARTA, por\nmartes.{DONE}",
  ["4a:525a"] = "Como presentación,\npor favor, toma\012este regalo:\nun LAZO ROSA.{DONE}",
  ["4a:529a"] = "MARTA: ¿No\ncrees que es\011adorable?\012Fortalece los\nataques normales.\012Seguro que te\nserá muy útil.{DONE}",
  ["4a:5312"] = "MARTA: ¿Has visto\na LUNA, mi hermana\011mayor?\012¿O a mi hermano\npequeño, MIGUEL?\012Soy la segunda de\nsiete hermanos.{DONE}",
  ["4a:5384"] = "MARTA: Hoy no es\nmartes. ¡Qué\011pena…!{DONE}",
  ["4a:53b9"] = "RUTA 29\012CIUDAD CEREZO -\nPUEBLO PRIMAVERA{DONE}",
  ["4a:53e4"] = "RUTA 29\012CIUDAD CEREZO -\nPUEBLO PRIMAVERA{DONE}",
  ["4a:55ad"] = "¡Ve, RATTATA!\012¡PLACAJE!{DONE}",
  ["4a:55c3"] = "¿Qué? ¡Es un\ngran combate!\011¡Déjame en paz!{DONE}",
  ["4a:55f0"] = "Acabo de perder\ny estoy buscando\011más POKéMON.\012¡Espera! ¡Pareces\ndébil! ¡Venga,\011luchemos!{DONE}",
  ["4a:5649"] = "¡Vaya! No tengo\nmás POKéMON.{DONE}",
  ["4a:566a"] = "Necesito tener\nmás POKéMON\011para luchar.\012¡Voy a atrapar\nunos cuantos más!{DONE}",
  ["4a:56ae"] = "Eres un entrenador\nPOKéMON, ¿verdad?\012¡Pues entonces\nluchemos!{DONE}",
  ["4a:56e5"] = "¡Qué extraño!\n¡Creí que ganaría!{DONE}",
  ["4a:5703"] = "Es muy duro llegar\na ser un buen\011entrenador.\012Tengo que luchar\ncontra más gente\011para mejorar.{DONE}",
  ["4a:575e"] = "¡En lugar de un\nPOKéMON bicho,\012he encontrado\nun entrenador!{DONE}",
  ["4a:5789"] = "¡Arg! ¡Eres\nmuy fuerte!{DONE}",
  ["4a:57a2"] = "Me quedé sin\nPOKé BALL mientras\011atrapaba POKéMON.\012Debería haber\ncomprado más…{DONE}",
  ["4a:57f0"] = "¿La casa del SR.\nPOKéMON? Está un\011poco más adelante.{DONE}",
  ["4a:581a"] = "¡Todo el mundo se\ndivierte luchando!\012¡Tú también\ndeberías hacerlo!{DONE}",
  ["4a:584a"] = "No soy una\nentrenadora.\012Pero si miras a\nuno a los ojos,\012prepárate\na luchar.{DONE}",
  ["4a:5891"] = "RUTA 30\012CIUDAD MALVA -\nCIUDAD CEREZO{DONE}",
  ["4a:58ba"] = "CASA SR. POKéMON\n¡Todo recto!{DONE}",
  ["4a:58db"] = "CASA SR. POKéMON{DONE}",
  ["4a:58ec"] = "PISTAS ENTRENADOR\012¡No robes los\nPOKéMON de otros!\012¡Las POKé BALL\nsólo se lanzan a\011POKéMON salvajes!{DONE}",
  ["4a:5b1e"] = "CUEVA OSCURA…\012Si los POKéMON\npudieran\012iluminarla,\nla exploraría.{DONE}",
  ["4a:5b54"] = "He atrapado un\nmontón de POKéMON.\011¡Luchemos!{DONE}",
  ["4a:5b87"] = "¡Auuuu…!{DONE}",
  ["4a:5b90"] = "Puedes atrapar\nPOKéMON aunque\012ya lleves seis\ncontigo.\012Si atrapas alguno\nmás, será enviado\011a la CAJA.{DONE}",
  ["4a:5bf8"] = "¡Arg…! ¿Eh?\012Hoy he caminado\nmucho buscando\011POKéMON.\012Me duelen los pies\ny tengo sueño…\012Si fuera un\nPOKéMON salvaje,\012sería fácil\natraparme…\012¡Zzzz…!{DONE}",
  ["4a:5c80"] = "Zzzz… ¿Eh?\012¿Qué es eso? ¿Una\nCARTA para mí?{DONE}",
  ["4a:5caf"] = "{PLAYER} entregó\nel POKéMON que\011lleva la CARTA.{DONE}",
  ["4a:5cd9"] = "Veamos…\012La C. OSCURA lleva\na otro camino.\012Es bueno\nsaberlo.\012Gracias por\ntraerme esto.\012Mi amigo es un\nbuen chico. ¡Tú\012también eres\nincreíble!\012¡Me gustaría\ndevolverte el\011favor!\012¡Ya sé!\n¡Toma esto!{DONE}",
  ["4a:5dbb"] = "MT50 es PESADILLA.\012Es un movimiento\nterrible que\012reduce los PS de\nun rival dormido.\012¡Ooooh…!\n¡Qué miedo…!\012No me gustan las\npesadillas.{DONE}",
  ["4a:5e46"] = "Esta CARTA no\nes para mí.{DONE}",
  ["4a:5e5e"] = "¿Por qué es espe-\ncial este POKéMON?\012No tiene ninguna\nCARTA.{DONE}",
  ["4a:5e97"] = "¿Qué? ¿No\nquieres nada?{DONE}",
  ["4a:5eb6"] = "Si te quito ese\nPOKéMON, ¿qué\012vas a usar en los\ncombates?{DONE}",
  ["4a:5efa"] = "He encontrado un\nbuen POKéMON en\011la CUEVA OSCURA.\012Voy a criarlo\npara enfrentarme\011a PEGASO.\012Es el líder del\nGIM. de C. MALVA.{DONE}",
  ["4a:5f6a"] = "RUTA 31\012CIUDAD MALVA -\nCIUDAD CEREZO{DONE}",
  ["4a:5f93"] = "CUEVA OSCURA{DONE}",
  ["4b:42a5"] = "¡Espera!\n¿Por qué corres?{DONE}",
  ["4b:42c0"] = "{PLAYER}, ¿verdad?\nUn tipo con\012gafas te estaba\nbuscando.\012Compruébalo tú\nmismo. Te está\012esperando en el\nCENTRO POKéMON.{DONE}",
  ["4b:43c5"] = "¿Has ido al\nGIMNASIO POKéMON?\012Allí puedes probar\na tus POKéMON\011y a ti mismo.\012¡Es un rito para\ntodos los\011entrenadores!{DONE}",
  ["4b:443a"] = "Tienes POKéMON\nmuy buenos.\012Seguro que es por\nhaberlos entrenado\012en los alrededores\nde CIUDAD MALVA.\012El entrenamiento\nen el GIMNASIO ha\012debido de ser de\ngran ayuda.\012Toma esto como\nrecuerdo de\011CIUDAD MALVA.\012Aumenta el poder\nde los movimientos\011de tipo planta.{DONE}",
  ["4b:452a"] = "Tu experiencia en\nCIUDAD MALVA\012debería ayudarte\nen tu viaje.{DONE}",
  ["4b:456e"] = "¿Te gustaría tener\nesta sabrosa y\012nutritiva\nCOLASLOWPOKE?\012¡Sólo te costará\n1.000.000¥!\012¡Te gustará!{DONE}",
  ["4b:45e4"] = "¡Vaya! Pensaba que\nlos niños de hoy\012en día estaban\nforrados…{DONE}",
  ["4b:4611"] = "¿No la quieres?\nPues lárgate.{DONE}",
  ["4b:4636"] = "¡Vaya!\012¡Se me escapó ese\npez por tu culpa!{DONE}",
  ["4b:4659"] = "¡Splash!{DONE}",
  ["4b:4663"] = "Paciencia… La\nbase de la pesca\012y de los POKéMON\nes la misma.{DONE}",
  ["4b:46a4"] = "Soy un buen\npescador, pero\012como entrenador\nsoy aún mejor.{DONE}",
  ["4b:46d3"] = "Intenté acelerar\nlas cosas…{DONE}",
  ["4b:46f1"] = "¡Pescar es una\npasión eterna y\012los POKéMON son\namigos eternos!{DONE}",
  ["4b:4863"] = "¿Mi POKéMON?\n¡Recién pescado!{DONE}",
  ["4b:487d"] = "¡Splash!{DONE}",
  ["4b:4886"] = "Los POKéMON\nrecién atrapados\012no son comparables\ncon los criados.{DONE}",
  ["4b:48c2"] = "No te había\nvisto antes.\012¿Te crees\nmuy duro?{DONE}",
  ["4b:4907"] = "¡Eres fuerte!{DONE}",
  ["4b:4916"] = "Intentaré ser el\nmejor con mis\011favoritos.\012No uso los mismos\nPOKéMON que\011todo el mundo.{DONE}",
  ["4b:497c"] = "¡He encontrado\nPOKéMON muy buenos\011en la hierba!\012¡Creo que me\nservirán!{DONE}",
  ["4b:49bf"] = "¡Maldición! Creía\nque podía ganar.{DONE}",
  ["4b:49dd"] = "En la hierba hay\ncosas pegajosas.{DONE}",
  ["4b:4a02"] = "Esa mirada…\nMe intriga.{DONE}",
  ["4b:4a20"] = "¡Mmmm! ¡Qué\ndecepción!{DONE}",
  ["4b:4a3e"] = "Si no quieres\nluchar, evita el\011contacto visual.{DONE}",
  ["4b:4a73"] = "Sí. Y sabes\nque…\012¿Luchar? ¡Estoy\nal teléfono!\012Vale. Pero que\nsea rápido.{DONE}",
  ["4b:4ad2"] = "¡Tranquilízate!\n¡Eso no está bien!{DONE}",
  ["4b:4aed"] = "Yo también estaba\ncharlando.{DONE}",
  ["4b:4b0c"] = "¡Esa MEDALLA! ¡Es\nde CIUDAD MALVA!\012¿Ganaste a PEGASO?{DONE}",
  ["4b:4b41"] = "Conozco mis\ndebilidades.{DONE}",
  ["4b:4b61"] = "Debería volver a\nentrenarme en el\012GIMNASIO de\nCIUDAD MALVA.{DONE}",
  ["4b:4bc0"] = "¡GRRR!\n¡TODOS HUYEN\012CUANDO RUJO! ¡PERO\nTÚ HAS VENIDO!\012¡ESO ME GUSTA!\n¡TOMA ESTO!{DONE}",
  ["4b:4c19"] = "¡GRRR!\n¡ES RUGIDO! HASTA\012LOS POKéMON HUYEN\nCON UN RUGIDO.{DONE}",
  ["4b:4c4e"] = "VICKI: ¡Yuju!\n¡Es viernes!\012Soy VICKI, por\nviernes.\012¡Mucho gusto!{DONE}",
  ["4b:4c91"] = "¡Toma una FLECHA\nVENENOSA!{DONE}",
  ["4b:4caf"] = "VICKI: Dásela a un\nPOKéMON de tipo\011veneno.\012¡Oh!\012¡Es terrible!\012¡Te sorprenderá\nver cómo mejora\012los movimientos\nde tipo veneno!{DONE}",
  ["4b:4d27"] = "VICKI: ¡Hola! ¿Qué\ndía prefieres?\012A mí me gusta el\nviernes. Sin duda.\012¿No crees que\nes genial?{DONE}",
  ["4b:4d8c"] = "VICKI: ¿Hoy no\nes viernes?\012¡Me aburro cuando\nno lo es!{DONE}",
  ["4b:4dc7"] = "RUTA 32\012CIUDAD MALVA -\nPUEBLO AZALEA{DONE}",
  ["4b:4deb"] = "RUINAS ALFA\nENTRADA ESTE{DONE}",
  ["4b:4e08"] = "Hacia la\nCUEVA UNIÓN{DONE}",
  ["4b:4fad"] = "Crucé el túnel\ny todavía me\012queda mucha\nenergía.{DONE}",
  ["4b:4ff1"] = "¡Uauu, chico! ¡Qué\nmarcha tienes!{DONE}",
  ["4b:5011"] = "Los MONTAÑEROS\nsomos felices en\011las montañas.{DONE}",
  ["4b:503e"] = "RUTA 33{DONE}",
  ["4b:52ee"] = "¡Aquí es donde\nentreno!{DONE}",
  ["4b:530f"] = "¿Qué ha pasado?{DONE}",
  ["4b:531f"] = "Voy a entrenar\nmás aún.\012Estoy intentado\nconvertirme en un\011LÍDER de GIMNASIO.{DONE}",
  ["4b:536c"] = "Soy el mejor de mi\nclase en POKéMON.{DONE}",
  ["4b:538e"] = "¡No! Hay mejores\nentrenadores…{DONE}",
  ["4b:53b0"] = "Estoy esforzándome\npara ser el mejor\011de mi clase.{DONE}",
  ["4b:53e2"] = "Confío en mi\ncapacidad para\011criar POKéMON.\012¿Quieres verlo?{DONE}",
  ["4b:541a"] = "¿No lo hice lo\nbastante bien?{DONE}",
  ["4b:5439"] = "Quizá debería\ndejar uno en la\012GUARDERÍA.\n¿Qué debo hacer?{DONE}",
  ["4b:5473"] = "¿Eres entrenador?\012Libremos un\ncombate de prueba.{DONE}",
  ["4b:54a4"] = "¡Oh, no! No\npuedo ganar…{DONE}",
  ["4b:54be"] = "Eres demasiado\nfuerte para\011practicar conmigo.{DONE}",
  ["4b:54ea"] = "¿Quién anda ahí?\n¿Qué es lo que\011quieres?{DONE}",
  ["4b:550f"] = "Eres un chaval\nmuy fuerte.{DONE}",
  ["4b:552a"] = "Hoy no veo\nnada malo. Sé\012bueno y no te\nmetas en líos.{DONE}",
  ["4b:5570"] = "Estoy buscando\nindividuos\011sospechosos.{DONE}",
  ["4b:559c"] = "Acabo de recoger\nmi POKéMON de la\011GUARDERÍA.\012¡Veamos lo fuerte\nque es ahora!{DONE}",
  ["4b:55e7"] = "¿Por qué acaba\nasí?{DONE}",
  ["4b:5602"] = "Mi POKéMON sabía\nmovimientos que yo\011desconocía.\012¡Eso me confundió\nmuchísimo!{DONE}",
  ["4b:5649"] = "MAR: ¡Vaya, nos\nha visto un chico!{DONE}",
  ["4b:5669"] = "MAR: ¡Ohhhh!\n¡Es muy fuerte!{DONE}",
  ["4b:5688"] = "MAR: ¡Mi hermana\nLISA te lo hará\011pagar!{DONE}",
  ["4b:56b6"] = "MAR: ¿No te parece\nuna playa genial?\012¡Es nuestro\npequeño refugio!{DONE}",
  ["4b:56f4"] = "ILDA: ¡No puedes\nvencer a MAR e\011irte sin más!{DONE}",
  ["4b:5722"] = "ILDA: ¡Lo siento\nmucho, MAR!{DONE}",
  ["4b:573f"] = "ILDA: ¡No seas\nchulo! ¡Mi hermana\011LISA es fuerte!{DONE}",
  ["4b:576f"] = "ILDA: El sol\nfortalece tu\011cuerpo.{DONE}",
  ["4b:5799"] = "LISA: ¡Seguro que\nhas sido malo con\011mis hermanitas!{DONE}",
  ["4b:57c9"] = "LISA: ¡He perdido!\n¡Increíble!{DONE}",
  ["4b:57eb"] = "LISA: Eres muy\nfuerte. No pude\011hacer nada.\012Toma. Te lo\nmereces.{DONE}",
  ["4b:5834"] = "LISA: Sentimos\nhaberte atacado.\012Pensábamos que\naquí nadie nos\012encontraría. ¡Nos\nhas sorprendido!{DONE}",
  ["4b:58b1"] = "RUTA 34\012CIUDAD TRIGAL -\nPUEBLO AZALEA\012EL ENCINAR\nEntre medias{DONE}",
  ["4b:58f6"] = "PISTAS ENTRENADOR\012Todos los días\ncrecen BAYAS\011en los árboles.\012Toma nota de los\ntipos de BAYAS que\011tiene cada árbol.{DONE}",
  ["4b:595a"] = "GUARDERÍA\012¡Déjanos criar a\ntu POKéMON por ti!{DONE}",
  ["4b:5c09"] = "He estado cogiendo\ndatos de POKéMON\012de mi radio. Creo\nque soy bueno.{DONE}",
  ["4b:5c44"] = "¡Me rindo!{DONE}",
  ["4b:5c4d"] = "La música de la\nradio cambia el\012ánimo de los\nPOKéMON salvajes.{DONE}",
  ["4b:5c81"] = "Le voy a demostrar\na mi novia lo\011bueno que soy.{DONE}",
  ["4b:5cac"] = "Ojalá hubieras\nperdido por mí…{DONE}",
  ["4b:5cd0"] = "Me humillaste\ndelante de mi\011novia…{DONE}",
  ["4b:5cfd"] = "Mi novio es débil.\nAsí que no puedo\011confiar en él.{DONE}",
  ["4b:5d29"] = "¡Cielos! ¡Eres tan\nfuerte!{DONE}",
  ["4b:5d43"] = "Confío más en\nmis POKéMON\011que en mi novio.{DONE}",
  ["4b:5d73"] = "¿Vas al GIMNASIO?\n¡Yo también!{DONE}",
  ["4b:5d96"] = "¡Vaya! No pude\nganar…{DONE}",
  ["4b:5daa"] = "Me gustan las\nMEDALLAS de\012los GIMNASIOS.\nLas colecciono.{DONE}",
  ["4b:5dd6"] = "¿Qué tipo de\nPOKé BALL usas?{DONE}",
  ["4b:5df8"] = "¡Vaya! ¡No lo\nbastante rápido!{DONE}",
  ["4b:5e11"] = "Algunos POKéMON\nhuyen enseguida.\012Intenta atraparlos\ncon la RAPID BALL\011de CÉSAR.\012Cuando encuentro\nun BONGURI BLA, se\011lo llevo a CÉSAR.\012Él lo convierte en\nuna POKé BALL.{DONE}",
  ["4b:5eaa"] = "¡Observa cómo uso\nlas POKé BALL!{DONE}",
  ["4b:5ece"] = "¡Uauuu! ¡Vaya\nsacudida!{DONE}",
  ["4b:5ee6"] = "Quería\nimpresionarte con\011mi premio POKéMON.\012¡Pero tu habilidad\nme ha electrizado!{DONE}",
  ["4b:5f36"] = "Iré a cualquier\nlugar donde haya\011POKéMON bicho.{DONE}",
  ["4b:5f61"] = "Ya veo. Ésta es tu\nforma de luchar.{DONE}",
  ["4b:5f81"] = "Mi VENONAT ganó\nel Concurso de\012Captura de Bichos\ndel PARQUE\011NACIONAL.{DONE}",
  ["4b:5fc3"] = "Practico mi\naliento de fuego.{DONE}",
  ["4b:5fe5"] = "¡Me he quemado la\npunta de la nariz!{DONE}",
  ["4b:6009"] = "La Marcha POKéMON\nde la radio atrae\011POKéMON salvajes.{DONE}",
  ["4b:6037"] = "¡El peligro acecha\npor la noche!{DONE}",
  ["4b:6053"] = "¡Uy!{DONE}",
  ["4b:605c"] = "Ya sabes, la noche\nes divertida a su\011manera.\012Pero no te pases,\n¿vale?{DONE}",
  ["4b:60a3"] = "Tus POKéMON son\nbastante fuertes.\012Estarás seguro en\ncualquier parte.{DONE}",
  ["4b:60e1"] = "RUTA 35{DONE}",
  ["4b:6321"] = "Un árbol extraño.\n¿Usar REGADERA?{DONE}",
  ["4b:6346"] = "{PLAYER} usó\nla REGADERA.{DONE}",
  ["4b:6360"] = "¡Al árbol extraño\nno le gusta la\011REGADERA!\012¡El árbol extraño\natacó!{DONE}",
  ["4b:63a7"] = "¡Cielos!\012Iba a quitar\nese árbol con\012un gran\nderechazo.\012Pero no pude.\n¡Soy un fracaso!{DONE}",
  ["4b:6408"] = "¿Quitaste ese\npobre árbol?\012¡Estoy\nimpresionado! Toma\011esto.{DONE}",
  ["4b:6464"] = "Se trata del\nGOLPE ROCA.\012Puedes destrozar\nrocas con un\012simple golpe bien\ndirigido.\012Si encuentras una\nroca en tu camino,\011¡destrózala!{DONE}",
  ["4b:64f0"] = "Un árbol extraño\nbloquea el camino\011a CIUDAD TRIGAL.\012No me permite\nir de compras.\012Habría que hacer\nalgo.{DONE}",
  ["4b:6568"] = "Ese árbol extraño\ndesapareció sin\011dejar rastro.\012¡Oh! ¿Ese árbol\nera un POKéMON?{DONE}",
  ["4b:65b7"] = "¡Te voy a leer\nel pensamiento!{DONE}",
  ["4b:65d8"] = "¡Te malinterpreté!{DONE}",
  ["4b:65e8"] = "Sería fuerte si\npudiera saber lo\012que está pensando\nmi rival.{DONE}",
  ["4b:662a"] = "¡Gracias a mis\nestudios, estoy\012preparado para\ncualquier POKéMON!{DONE}",
  ["4b:665a"] = "¡Uups! ¿Error de\ncálculo?{DONE}",
  ["4b:6674"] = "Yo también estudio\n5 horas al día.\012Leyendo libros\npuedes aprender\011muchas cosas.{DONE}",
  ["4b:66cc"] = "JOSUÉ: ¿Quién\neres tú?\012Soy JOSUÉ, por\njueves.{DONE}",
  ["4b:66f9"] = "Toma. Coge\nesto.{DONE}",
  ["4b:6713"] = "JOSUÉ: Debería\nusarlo un POKéMON\012con habilidades\nde tipo roca.\012Mejora los ataques\nde tipo roca.{DONE}",
  ["4b:6776"] = "JOSUÉ: Soy JOSUÉ,\npor jueves. Soy\012el segundo de\nsiete hermanos.{DONE}",
  ["4b:67bf"] = "JOSUÉ: Hoy no\nes jueves. ¡Qué\011desilusión!{DONE}",
  ["4b:67f0"] = "RUTA 36{DONE}",
  ["4b:67fa"] = "RUINAS ALFA\nENTRADA NORTE{DONE}",
  ["4b:6818"] = "PISTAS ENTRENADOR\012Las habilidades de\nlos POKéMON varían\012incluso dentro de\nuna misma especie.\012Al principio, sus\nhabilidades pueden\011parecerse.\012Sin embargo, las\ndiferencias surgen\012a medida que el\nPOKéMON crece.{DONE}",
  ["4b:68ba"] = "PISTAS ENTRENADOR\012Usa EXCAVAR para\nvolver a la\011entrada.\012Es útil para\nexplorar cuevas\012y otros\nlugares.{DONE}",
  ["4c:4093"] = "ANA: ¡ANY y yo\nestamos en esto\011juntas!{DONE}",
  ["4c:40bc"] = "ANA-ANY: ¡Eres\nmuy malo!{DONE}",
  ["4c:40d5"] = "ANA: Sé lo que\nestán pensando\012mi hermana y mis\nPOKéMON.{DONE}",
  ["4c:410f"] = "ANY: ¡ANA y yo\nestamos en esto\011juntas!{DONE}",
  ["4c:4138"] = "ANA-ANY: ¡Eres\nmuy malo!{DONE}",
  ["4c:4151"] = "ANY: Sentimos\nlo mismo que\011nuestros POKéMON.{DONE}",
  ["4c:4180"] = "Los POKéMON no\npueden hacer nada\011dormidos.\012¡Yo te enseñaré el\nmiedo que da eso!{DONE}",
  ["4c:41ca"] = "He perdido. ¡Qué\npena…!{DONE}",
  ["4c:41e5"] = "Dormir o paralizar\na los POKéMON\012son buenas\ntécnicas de lucha.{DONE}",
  ["4c:422d"] = "DOMINGO: ¡Hola!\012Soy DOMINGO, por\nel día. Es decir,\011¡hoy es domingo!{DONE}",
  ["4c:4269"] = "¡Me dijeron que\nte diera esto si\011te veía!{DONE}",
  ["4c:4294"] = "DOMINGO: Eso…\012¡Um…!\012¿Qué era…?\012…\012¡Ah! ¡Ahora lo\nrecuerdo!\012Debería llevarlo\nun POKéMON\012con habilidades\neléctricas.\012¡Mi hermana LUNA\ndice que mejora\012las habilidades\neléctricas!{DONE}",
  ["4c:4336"] = "DOMINGO: Mis\nhermanos son\011LUNA, MARTA,\011MIGUEL, JOSUÉ,\011VICKY y SABINO.\012¡Son todos\nmayores que yo!{DONE}",
  ["4c:43a8"] = "DOMINGO: ¿Hoy no\nes domingo?\011¡Um…! ¡Lo olvidé!{DONE}",
  ["4c:43d1"] = "RUTA 37{DONE}",
  ["4c:45a8"] = "¡Vuela alto hacia\nel cielo, querido\011pájaro POKéMON!{DONE}",
  ["4c:45d6"] = "¡Me apetece salir\nvolando ahora!{DONE}",
  ["4c:45f9"] = "Pienso entrenar en\nCIUDAD ORQUÍDEA\012y enseñar a volar\na mis POKéMON.{DONE}",
  ["4c:4638"] = "Déjame probar\nalgo que he\011aprendido hoy.{DONE}",
  ["4c:4661"] = "Creo que no\nestudié bastante.{DONE}",
  ["4c:4681"] = "Tengo que hacer\nmuchos exámenes y\012no tengo tiempo\npara los POKéMON.\012Así que, cuando\npuedo jugar, me\011concentro mucho.{DONE}",
  ["4c:46f0"] = "¿Estás\nentrenándote?\012Si es así, ¿puedes\nenseñarme cómo?{DONE}",
  ["4c:472e"] = "Ya veo. De modo\nque luchas así.{DONE}",
  ["4c:4752"] = "¡Tengo una buena\nnoticia!\012La leche de la\nGRANJA MUU-MUU\012es famosa por\nsu sabor.{DONE}",
  ["4c:4796"] = "¡Hola! ¡Eres\nmuy guapo!\012¿Me dejas ver a\ntus POKéMON?{DONE}",
  ["4c:47ca"] = "Encantada de\nhaber visto\011a tus POKéMON.{DONE}",
  ["4c:47eb"] = "Cuando veo\nPOKéMON me\011tranquilizo.{DONE}",
  ["4c:481d"] = "He estado en el\nextranjero. ¡Así\012que conozco todo\ntipo de POKéMON!{DONE}",
  ["4c:4856"] = "¡Tu destreza es de\ncategoría mundial!{DONE}",
  ["4c:4872"] = "Gentes de todo el\nmundo viven\012felices con\nlos POKéMON.{DONE}",
  ["4c:48b2"] = "RUTA 38\012CIUDAD OLIVO -\nCIUDAD IRIS{DONE}",
  ["4c:48d9"] = "PISTAS ENTRENADOR\012Si un POKéMON\nva a evolucionar,\011puedes pararlo.\012Pulsa el Botón B\nmientras intenta\011evolucionar.\012Esto asusta al\nPOKéMON y detiene\011su evolución.{DONE}",
  ["4c:4abc"] = "MUU-MUU: ¡Muu!{DONE}",
  ["4c:4acc"] = "Acabo de volver\nde CIUDAD OLIVO.\012¿Te apetece luchar\ncon los POKéMON?{DONE}",
  ["4c:4b05"] = "¡Awaaargh!{DONE}",
  ["4c:4b10"] = "Mis POKéMON han\nsido atrapados y\012entrenados en el\nextranjero.\012Son mis compañeros\nde esos largos\011viajes.{DONE}",
  ["4c:4b68"] = "¿Te importa si\npresumo de mis\011POKéMON?{DONE}",
  ["4c:4b94"] = "No puedo\npresumir…{DONE}",
  ["4c:4bae"] = "¡No te estoy\nescuchando!\012¡Los POKéFANS\ntenemos la norma\012de no escuchar a\nlos presumidos!{DONE}",
  ["4c:4c11"] = "¡Qué POKéMON\nmás encantadores!\012Enseñemos nuestros\nPOKéMON al\011mismo tiempo.{DONE}",
  ["4c:4c53"] = "No me importa\nperder.{DONE}",
  ["4c:4c68"] = "¿Sabes algo sobre\nlos POKéMON bebés?\012¡Seguro que\nson adorables!{DONE}",
  ["4c:4ca2"] = "Déjame ver de qué\nson capaces tus\011POKéMON.{DONE}",
  ["4c:4ccd"] = "¡Ooh! Tus POKéMON\ntienen potencial.{DONE}",
  ["4c:4ced"] = "¿Sabes que\nlos POKéMON\012tienen distintas\nhabilidades?\012Son como las\npersonas. Cada\012uno tiene su\npropio potencial.{DONE}",
  ["4c:4d5a"] = "RUTA 39\012CIUDAD OLIVO -\nCIUDAD IRIS{DONE}",
  ["4c:4d81"] = "GRANJA MUU-MUU\012Prueba nuestra\nrica leche fresca{DONE}",
  ["4c:4dad"] = "PISTAS ENTRENADOR\012Usa GOLPE CABEZA\nen los árboles\012para que salgan\nPOKéMON.\012De los árboles\npueden caer varios\011tipos de POKéMON.{DONE}",
  ["4c:4f84"] = "Debes calentar\nantes de entrar\011en el agua.\012Es imprescindible.{DONE}",
  ["4c:4fc3"] = "¡Vale! ¡Me rindo!{DONE}",
  ["4c:4fd7"] = "CIUDAD ORQUÍDEA\nestá bastante\011lejos de aquí.{DONE}",
  ["4c:5009"] = "Un joven como tú\ndebería nadar.\012No hagas SURF\nsobre tus POKéMON.{DONE}",
  ["4c:5044"] = "¡Oh, he perdido…!{DONE}",
  ["4c:5054"] = "La natación\nfortalece tu\011cuerpo. Es sana.{DONE}",
  ["4c:5087"] = "¿Vas a CIUDAD\nORQUÍDEA?\012¿Te apetece luchar\nantes?{DONE}",
  ["4c:50c3"] = "¡He perdido!{DONE}",
  ["4c:50d5"] = "Creo que nado\nmejor que tú.\011¡Sin duda!{DONE}",
  ["4c:5103"] = "Yo no necesito\nflotador.\012¡Voy agarrada a\nun POKéMON de mar!{DONE}",
  ["4c:5137"] = "¡Ooh, estoy\nmareada!{DONE}",
  ["4c:514f"] = "Mientras flote\nasí, las olas\011me llevarán.{DONE}",
  ["4c:5183"] = "Aunque no se ve\ndesde aquí, CIUDAD\012ORQUÍDEA está al\notro lado del mar.{DONE}",
  ["4c:51c4"] = "LUNA: Encantada de\nconocerte. Soy\012LUNA, por lunes.{DONE}",
  ["4c:51f4"] = "¡Como prueba de\nnuestra amistad,\012tengo un regalo\npara ti!{DONE}",
  ["4c:522a"] = "LUNA: Es un objeto\nque aumenta el\012poder de los\nataques de vuelo.\012Deberías dar este\nobjeto a un\011POKéMON pájaro.{DONE}",
  ["4c:529a"] = "LUNA: Mis hermanos\ny hermanas están\012por todas\npartes.\012¡A ver si los\nencuentras!{DONE}",
  ["4c:52f5"] = "LUNA: No creo\nque hoy sea\011lunes. ¡Qué pena…!{DONE}",
  ["4c:5325"] = "RUTA 40\012CIUDAD ORQUÍDEA -\nCIUDAD OLIVO{DONE}",
  ["4c:54a1"] = "Aquí el agua está\ntemplada. Estoy\011muy a gusto.\012Por supuesto,\n¡lucharé contigo!{DONE}",
  ["4c:54e4"] = "¡Vaya! ¡Estoy\ncomo una pasa!{DONE}",
  ["4c:5500"] = "¡Qué relajante\nes flotar\011así!{DONE}",
  ["4c:552b"] = "Estoy cansado. Si\ngano, ¿me prestas\011tus POKéMON?{DONE}",
  ["4c:5559"] = "(jadeo…){DONE}",
  ["4c:5566"] = "CIUDAD ORQUÍDEA\nestá muy lejos.\012Pero tampoco es\nfácil volver a\011CIUDAD OLIVO.\012¿Qué hacer?{DONE}",
  ["4c:55c0"] = "¿Ves esas islas\naisladas por\011torbellinos?\012¡Tiene que haber\nun secreto!{DONE}",
  ["4c:5612"] = "¿Cuál es tu\nsecreto?{DONE}",
  ["4c:5636"] = "Era de noche\ny llovía…\012Vi un POKéMON\ngigante volando\011desde las islas.\012Dejaba caer las\nplumas de sus\011alas plateadas.{DONE}",
  ["4c:56b8"] = "Aquí hay mucho\noleaje.\012Cuesta mucho\nnadar.{DONE}",
  ["4c:56f4"] = "¡Me has vencido!{DONE}",
  ["4c:56fe"] = "La corriente me\nimpide llegar\011a las islas.{DONE}",
  ["4c:572f"] = "¿Estás buscando\nel secreto de las\011ISLAS REMOLINO?{DONE}",
  ["4c:575e"] = "¡Ooh, tienes una\ngran resistencia!{DONE}",
  ["4c:577f"] = "Un secreto sobre\nISLAS REMOLINO…\012¡Dentro está muy\noscuro!{DONE}",
  ["4c:57b6"] = "Voy hacia las\nISLAS REMOLINO.\012Voy a explorarlas\ncon unos amigos.{DONE}",
  ["4c:57f9"] = "¿Así es como\nlo haces?{DONE}",
  ["4c:5811"] = "Dicen que hay un\ngran POKéMON\012bajo las\nISLAS REMOLINO.\012Me pregunto\ncómo será…{DONE}",
  ["4c:586c"] = "Estás tan elegante\nmontado en tu\011POKéMON.{DONE}",
  ["4c:5896"] = "He perdido.{DONE}",
  ["4c:58a3"] = "¿No había una\ncanción famosa\012sobre un niño que\nmontaba un LAPRAS?{DONE}",
  ["4c:58d8"] = "¡Hace muy buen\ndía! ¡Estoy\011aturdida!{DONE}",
  ["4c:5904"] = "¡Ohhh!{DONE}",
  ["4c:590b"] = "El sol es muy malo\npara la piel.\012Pero yo no uso\nprotección solar.\012No quiero\nensuciar el agua.{DONE}",
  ["4c:5962"] = "Si necesitas\ndescansar, ve por\011el agua.\012El viento te\nempujará y podrás\012seguir siendo\nfuerte.{DONE}",
  ["4c:59c5"] = "¡Oh! Tienes más\nenergía que yo.{DONE}",
  ["4c:59ea"] = "He oído rugidos\nprocedentes de\011las ISLAS.{DONE}",
  ["4c:5a17"] = "Por la noche,\nlos STARYU se\012reúnen cerca de la\nsuperficie.{DONE}",
  ["4c:5a49"] = "¡Oh, querido…!{DONE}",
  ["4c:5a54"] = "Los grupos de\nSTARYU se iluminan\011al mismo tiempo.\012Es muy bonito,\npero da miedo.{DONE}",
  ["4c:5c16"] = "¡Déjame que te\nenseñe el poder de\011mis POKéMON!{DONE}",
  ["4c:5c4a"] = "¿Qué? Eso no está\nbien.{DONE}",
  ["4c:5c62"] = "Quiero convertirme\nen un CAMPEÓN\012con los POKéMON\nque he atrapado.\012¡Eso es lo mejor\nde la pesca!{DONE}",
  ["4c:5cbf"] = "¡Ah! ¡Qué bien\nestar fuera! ¡Me\011siento tan libre!{DONE}",
  ["4c:5cec"] = "¡Gahahah!{DONE}",
  ["4c:5cf6"] = "¡Perder no tiene\nimportancia si lo\012comparas con el\ninmenso cielo!{DONE}",
  ["4c:5d33"] = "¡OYE!\012¡Éste es mi lugar\nsecreto! ¡Fuera de\011aquí, intruso!{DONE}",
  ["4c:5d6a"] = "Debí haber usado\nmi PIEDRA LUNAR…{DONE}",
  ["4c:5d8d"] = "¿Tienes una\nPOKéDEX?\012¡Uau, habrás visto\nPOKéMON muy\011raros!\012¿Puedo verla,\npor favor?{DONE}",
  ["4c:5dee"] = "RUTA 42\012CIUDAD IRIS -\nPUEBLO CAOBA{DONE}",
  ["4c:5e16"] = "MONTE MORTERO\012CUEVA CASCADA\nInterior{DONE}",
  ["4c:5e3a"] = "MONTE MORTERO\012CUEVA CASCADA\nInterior{DONE}",
  ["4c:5e5e"] = "RUTA 42\012CIUDAD IRIS -\nPUEBLO CAOBA{DONE}",
  ["4d:418e"] = "¡Me encantan\nlos POKéMON!\012¡Ésa es la razón\npor la que empecé\012a coleccionar\nPOKéMON!{DONE}",
  ["4d:41d8"] = "¿Cómo me has\npodido hacer esto?{DONE}",
  ["4d:41f6"] = "¿Que qué me gusta\nademás de los\011POKéMON?\012Oír a ROSA en la\nradio. ¡Seguro que\011es muy guapa!{DONE}",
  ["4d:423d"] = "¡Eh! ¿Tienes algún\nPOKéMON raro?{DONE}",
  ["4d:425e"] = "¡Oh, mis pobres\nPOKéMON!{DONE}",
  ["4d:427d"] = "Sería feliz con\nsólo tener un\011POKéMON raro.{DONE}",
  ["4d:42aa"] = "¿Te lo puedes\ncreer?\012¡{RIVAL} se ha\nburlado de mi\011POKéMON!\012¡Maldición! ¡Mi\nPOKéMON es genial!{DONE}",
  ["4d:42fa"] = "¡Mi NIDOKING lo\nha hecho muy bien!{DONE}",
  ["4d:431c"] = "Es bueno que a la\ngente le gusten\012distintos tipos de\nPOKéMON.\012No sólo se trata\nde tener el\011más fuerte.{DONE}",
  ["4d:4385"] = "No estoy de racha.\012Quizá sea por el\nequipo que uso.\012Luchemos. A ver si\ncambia mi suerte.{DONE}",
  ["4d:43d4"] = "He perdido, pero\nme siento mejor.{DONE}",
  ["4d:43f7"] = "Las CEBO BALL de\nCÉSAR son las\012mejores para\npescar POKéMON.\012Son mucho más\nefectivas que las\011ULTRA BALL.{DONE}",
  ["4d:4459"] = "Puedo hacer muchas\ncosas con mis\012POKéMON.\n¡Es muy divertido!{DONE}",
  ["4d:4489"] = "Perder no es nada\ndivertido…{DONE}",
  ["4d:44a2"] = "¿Qué ocurre en el\nLAGO DE LA FURIA?\012Teníamos pensado\nacampar aquí.{DONE}",
  ["4d:44e5"] = "¿Tú también vas al\nLAGO DE LA FURIA?\012¡Juguemos un\nratito!{DONE}",
  ["4d:4528"] = "¡He jugado mucho!{DONE}",
  ["4d:453c"] = "Voy a ir de picnic\ncon mis POKéMON.\012¿No te vienes?{DONE}",
  ["4d:456f"] = "RUTA 43\012LAGO DE LA FURIA -\nPUEBLO CAOBA{DONE}",
  ["4d:4596"] = "RUTA 43\012LAGO DE LA FURIA -\nPUEBLO CAOBA{DONE}",
  ["4d:45bd"] = "PISTAS ENTRENADOR\012Todos los POKéMON\ntienen ventajas y\012desventajas según\nel tipo.\012Entre dos POKéMON\nde distinto tipo,\012puede perder el\nde nivel superior.\012Aprende qué tipos\nson fuertes o\012débiles contra tu\ntipo de POKéMON.{DONE}",
  ["4d:488b"] = "¡Me has hecho\nperder a POLIWAG!\012¿Qué vas a hacer\npara remediarlo?{DONE}",
  ["4d:48d1"] = "¡Simplemente,\nolvídalo!{DONE}",
  ["4d:48e8"] = "Ese POLIWAG que\nescapó…\011Era enorme.\012¡Juraría que medía\nunos 5 metros!{DONE}",
  ["4d:4937"] = "Pesco hasta que\nno puedo más.\012Y lucho hasta\ndesfallecer.\012Ésta es la\nrelación que tengo\011con mis POKéMON.{DONE}",
  ["4d:4995"] = "¡Mmmmm…!\nEso no está bien.{DONE}",
  ["4d:49af"] = "Son 100 victorias\ny 101 derrotas.\012No lucharé\nen un rato.{DONE}",
  ["4d:49ef"] = "¿Sabes algo sobre\nel POKéMON\011pájaro legendario?{DONE}",
  ["4d:4a1b"] = "¡Uauu! Eres un\nhacha.{DONE}",
  ["4d:4a33"] = "ARTICUNO, ZAPDOS y\nMOLTRES son los\012pájaros POKéMON\nlegendarios.\012Aunque dicen que\nhay otros pájaros\011legendarios.{DONE}",
  ["4d:4aa7"] = "¡Voy a ganar!\n¡Seguro!{DONE}",
  ["4d:4ac0"] = "¡Arrgh…! No\nesperaba perder.{DONE}",
  ["4d:4adf"] = "Es importante\ntener confianza\011en uno mismo.{DONE}",
  ["4d:4b0f"] = "¡Haré lo que sea\npara conseguir\011POKéMON raros!{DONE}",
  ["4d:4b3e"] = "Oooh, tus POKéMON\nson muy bonitos.{DONE}",
  ["4d:4b61"] = "Los POKéMON\nde colores\012poco habituales\ntienen más valor.\012¿Qué? ¿Insinúas\nque no es cierto?{DONE}",
  ["4d:4bbf"] = "Con sólo mirarte\nsé si eres un\011buen entrenador.\012Yo soy bueno con\nlos POKéMON y veo\011que tú también.{DONE}",
  ["4d:4c26"] = "¡Vaya! Ha sido una\nauténtica derrota.{DONE}",
  ["4d:4c49"] = "¡Uauu! Tienes\nmuchas MEDALLAS.\012No me extraña que\nseas tan fuerte.\012Me pregunto si\nMORTI, de GIMNASIO\012IRIS, estará\naún entrenándose.\012Él sí que me\ndio una paliza.{DONE}",
  ["4d:4cd0"] = "Pareces fuerte.\012Los buenos\nentrenadores\012siempre buscan\nbuenos rivales.{DONE}",
  ["4d:4d14"] = "¡No! Esto no\nservirá para nada.{DONE}",
  ["4d:4d30"] = "Todos mejoramos\nluchando\011muchas veces.\012He luchado mucho\npara llegar a ser\012lo que soy hoy:\nuna campeona.{DONE}",
  ["4d:4d96"] = "RUTA 44\nHACIA RUTA HELADA{DONE}",
  ["4d:4daf"] = "RUTA 44\012PUEBLO CAOBA -\nCIUDAD ENDRINO{DONE}",
  ["4d:4feb"] = "¡Prepárate para\ncualquier cosa!\012¡Déjame ver si\nhas entrenado bien\011a tus POKéMON!{DONE}",
  ["4d:5039"] = "¡Oh, he perdido!{DONE}",
  ["4d:504b"] = "Volveré a la RUTA\nHELADA de CIUDAD\012ENDRINO y seguiré\nentrenándome.{DONE}",
  ["4d:5087"] = "¡Eres valiente!\nPero…\012¿Sabes qué?\nPara valiente,\011¡yo!{DONE}",
  ["4d:50dc"] = "¡A mis POKéMON les\nfaltaron agallas!{DONE}",
  ["4d:50fb"] = "¡Cómo me gusta\nMÁS PS! ¡Mmmm!\012¡Me bebo la de mis\nPOKéMON!\012No puedo evitarlo.{DONE}",
  ["4d:5147"] = "¡Mis POKéMON son\nmuy poderosos!{DONE}",
  ["4d:5162"] = "¡Buaaaaa! ¡Soy un\nperdedor!{DONE}",
  ["4d:517e"] = "No se me da muy\nbien pensar.\012¡Así que utilizo\nsólo la fuerza!{DONE}",
  ["4d:51c4"] = "¿Que por qué\nescalo montañas?\012Porque están\nahí.\012¿Que por qué\nentreno POKéMON?\012¡Porque están\nahí!{DONE}",
  ["4d:5220"] = "Las derrotas…\n¡También están!{DONE}",
  ["4d:523b"] = "Lo mejor que me ha\npasado nunca fue\012descubrir a los\nPOKéMON.{DONE}",
  ["4d:5276"] = "Estaba entrenando\naquí solo.\012¡Observa el fruto\nde mi trabajo!{DONE}",
  ["4d:52b1"] = "¡Waaaargh!{DONE}",
  ["4d:52bc"] = "Debo tomar\nmedidas extremas.\012Debo ir a los\nmontes y entrenar\011allí, en soledad.{DONE}",
  ["4d:530e"] = "¿Qué piensas sobre\nla educación\011de los POKéMON?{DONE}",
  ["4d:5339"] = "Te has ganado\nmi respeto.{DONE}",
  ["4d:5350"] = "Veo que estás\neducando a tus\012POKéMON\ncon cariño.\012El vínculo que\nos une os salvará\012en las situaciones\ndifíciles.{DONE}",
  ["4d:53b2"] = "¿Cuál es tu\nestrategia?\012Es de tontos usar\nataques fuertes\012de forma\nindiscriminada.{DONE}",
  ["4d:5405"] = "Vale. He perdido.{DONE}",
  ["4d:5414"] = "No soy partidaria\nde los ataques\011demasiado fuertes.\012Quiero ganar, pero\nno quiero herir\011a los POKéMON.{DONE}",
  ["4d:5490"] = "RUTA 45\nCAMINO MONTAÑA{DONE}",
  ["4d:561f"] = "De acuerdo. ¡Te\nenseñaré el poder\012de los POKéMON\nde montaña!{DONE}",
  ["4d:5652"] = "¡Me has demostrado\ntu poder!{DONE}",
  ["4d:5674"] = "Se acabó. Pero no\nme importa. \012Los MONTAÑEROS\nsomos así.{DONE}",
  ["4d:56a5"] = "¡Yo también\nentreno POKéMON!\012¿Quieres luchar\ncontra mí?{DONE}",
  ["4d:56d6"] = "¿Qué…?{DONE}",
  ["4d:56dd"] = "Hice lo que pude\npero no sirvió.\012No hay excusa que\nvalga. He perdido.{DONE}",
  ["4d:571b"] = "¡Yo también\nentreno POKéMON!\012¡Luchemos!{DONE}",
  ["4d:573b"] = "¡Oh, maldición!{DONE}",
  ["4d:5749"] = "He estado en\nmuchos GIMNASIOS,\012pero mi favorito\nes el de TRIGAL.\012¡Está lleno de\npreciosas flores!{DONE}",
  ["4d:57aa"] = "RUTA 46\nCAMINO MONTAÑA{DONE}",
  ["4d:588a"] = "¿Has ido al GIM.\nde C. PLATEADA?\012El LÍDER utiliza\nPOKéMON roca.{DONE}",
  ["4d:58c8"] = "Por la noche,\nCLEFAIRY sale a\011jugar al MT. MOON.\012Pero no todas\nlas noches.{DONE}",
  ["4d:590e"] = "¡Vaya! ¿Vienes\nde JOHTO?\012Me trae muchos\nrecuerdos. Cuando\012era joven, fui a\nJOHTO a entrenar.\012Te pareces\nmucho a mí\012cuando yo\ntenía tu edad.\012Me gustaría darte\neste objeto que\011encontré en JOHTO.{DONE}",
  ["4d:59f2"] = "Visitar nuevos\nsitios y conocer\011gente nueva…\012Eso es lo\nbueno de viajar.{DONE}",
  ["4d:5a47"] = "CIUDAD PLATEADA\nLa ciudad de\011piedra grisácea{DONE}",
  ["4d:5a66"] = "LÍDER POKéMON\nDEL GIMNASIO DE\011C. PLATEADA: BROCK\012El Entrenador\nPOKéMON más\012fuerte que\nuna roca.{DONE}",
  ["4d:5aa6"] = "Aquí hay una\nnota…\012MUSEO DE LA\nCIENCIA DE CIUDAD\012PLATEADA: Cerrado\npor obras…{DONE}",
  ["4d:5af1"] = "Aquí hay una\nnota…\012¡TIENDA DE REGALOS\nMT. MOON abierta!{DONE}",
  ["4d:5b24"] = "¡Bienvenido a\nCIUDAD PLATEADA!{DONE}",
  ["4d:5c1a"] = "Mis POKéMON bicho\nson muy fuertes.\012¡Prepárate para\nperder!{DONE}",
  ["4d:5c43"] = "Me vencieron…{DONE}",
  ["4d:5c53"] = "Voy a buscar\nPOKéMON bichos\011más fuertes.{DONE}",
  ["4d:5c7c"] = "Si caminas por la\nhierba alta con\012pantalones cortos,\n¿no te arañas?{DONE}",
  ["4d:5cc2"] = "¡Au, au, au!{DONE}",
  ["4d:5cd5"] = "Seguro que te\npican si te\011bañas.{DONE}",
  ["4d:5d00"] = "¿Por qué a las\nchicas no les\012gustan los\nPOKéMON bicho?{DONE}",
  ["4d:5d1f"] = "¡Muy mal!{DONE}",
  ["4d:5d29"] = "Los POKéMON bicho\nparecen muñecos\012de goma cuando les\naprietas la tripa.\012¡Me encanta\ntocarlos!{DONE}",
  ["4d:5d80"] = "RUTA 2\012CIUDAD VERDE -\nCIUDAD PLATEADA{DONE}",
  ["4d:5da5"] = "CUEVA DIGLETT{DONE}",
  ["4e:4062"] = "¡Hola, chico! ¡Me\nacabo de tomar un\012café doble y estoy\ncomo una moto!\012¡Tengo que hablar\ncon alguien, así\011que te toca a ti!\012Puede que ahora no\nlo parezca, pero\012yo era un experto\natrapando POKéMON.\012¿Me crees?{DONE}",
  ["4e:412c"] = "Muy bien. Sí, yo\nera algo fuera de\012lo normal. ¡Déjame\ncontártelo!{DONE}",
  ["4e:4174"] = "¿Qué? ¡Pequeño\nbribón!\012Si fuera un poco\nmás joven, te\012enseñaría un par\nde cosas. ¡Vaya!{DONE}",
  ["4e:41ce"] = "Este GIMNASIO no\nha tenido LÍDER\011hasta hace poco.\012Un joven de\nPUEBLO PALETA se\012convirtió en LÍDER\npero viaja mucho.{DONE}",
  ["4e:423b"] = "¿Vas a enfrentarte\nal LÍDER?\012¡Buena suerte! ¡La\nvas a necesitar!{DONE}",
  ["4e:4281"] = "¡Qué sueño!\012Me habré quedado\ndormido al sol.\012He soñado que\nun DROWZEE se\012comía mi sueño.\nEs raro, ¿verdad?\012¿Eh?\n¿Qué es esto?\012¿De dónde ha\nsalido esta MT?\012¡Esto es muy\nmisterioso! Aquí\011tienes esta MT.{DONE}",
  ["4e:4343"] = "MT42 contiene\nCOME SUEÑOS…\012¡Zzzzz…!{DONE}",
  ["4e:4367"] = "Dicen que en el\nsuelo del BOSQUE\012VERDE hay muchos\nobjetos.{DONE}",
  ["4e:43ac"] = "CIUDAD VERDE\012El Paraíso\nEternamente Verde{DONE}",
  ["4e:43d8"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\011CIUDAD VERDE:…\012El resto del texto\nes ilegible…{DONE}",
  ["4e:441d"] = "Bienvenido a\nCIUDAD VERDE,\012la entrada a\nla MESETA AÑIL{DONE}",
  ["4e:4456"] = "CASA DE ENTRENADOR\012Club de Mejores\nEntrenadores{DONE}",
  ["4e:44fc"] = "LIGA POKéMON\012ENTRADA A\nCALLE VICTORIA{DONE}",
  ["4e:455e"] = "Luchar es lo\nprimero que hacen\012los entrenadores\nsi se encuentran.{DONE}",
  ["4e:4592"] = "Tengo el récord de\ncombates perdidos.{DONE}",
  ["4e:45b2"] = "Es obvio que los\nentrenadores\012luchemos cuando\nnos encontremos.{DONE}",
  ["4e:45f0"] = "¡Estás ahí!\n¿Quieres luchar?{DONE}",
  ["4e:460c"] = "He perdido…{DONE}",
  ["4e:461b"] = "Eres fuerte.\012Seguro que te has\nentrenado mucho.{DONE}",
  ["4e:4650"] = "RUTA 1\012PUEBLO PALETA -\nCIUDAD VERDE{DONE}",
  ["4e:46c2"] = "Yo también entreno\nPOKéMON. Son\012mis guardaespaldas\npersonales.{DONE}",
  ["4e:46fb"] = "¡La tecnología es\nincreíble!\012Ahora puedes\ncambiar POKéMON\012con el pasado,\ncomo un e-mail.{DONE}",
  ["4e:4746"] = "PUEBLO PALETA\012Un tranquilo lugar\nde paz y pureza{DONE}",
  ["4e:4778"] = "CASA DE ROJO{DONE}",
  ["4e:4785"] = "LABORATORIO DE\nINVESTIGACIÓN\011POKéMON DE OAK{DONE}",
  ["4e:479c"] = "CASA DE AZUL{DONE}",
  ["4e:482b"] = "Tierra a la vista.\n¡Sigamos adelante!{DONE}",
  ["4e:4847"] = "¡Glup…!{DONE}",
  ["4e:484e"] = "Ese chico tan\narrogante estaba\012en el volcán de\nISLA CANELA.{DONE}",
  ["4e:487b"] = "¡Hola!\012Me iba a poner\nun poco de\011protección solar.{DONE}",
  ["4e:48ab"] = "No quiero\nquemarme…{DONE}",
  ["4e:48c6"] = "Debería tener\ncuidado con las\012manchas causadas\npor el sol.{DONE}",
  ["4e:48fc"] = "Estoy aburrido de\npescar. ¡Luchemos!{DONE}",
  ["4e:4921"] = "Un fracaso…{DONE}",
  ["4e:4931"] = "Seguiré\npescando…{DONE}",
  ["4e:49a7"] = "¿Quién eres tú?\012Es evidente\nque eres un\011entrenador…\012Me llamo AZUL.\012Y una vez fui el\nCAMPEÓN, pero sólo\012durante poco\ntiempo…\012El entrometido de\nROJO me ganó…\012¡Pero qué más da!\n¿Y tú qué quieres?\012¿Has venido a\ndesafiarme?\012Lo siento, pero\nno, ahora no\012tengo ganas\nde luchar.\012Echa un vistazo a\ntu alrededor…\012Un volcán entra\nen erupción y una\012ciudad entera\ndesaparece.\012En POKéMON se\npuede ganar y\012perder, pero si\nse tuercen las\012cosas, se puede\nperder enseguida.\012…\012Así son las\ncosas…\012Sin embargo, sigo\nsiendo entrenador.\012Y encontrarme con\nun rival fuerte me\011anima a luchar.\012Si quieres luchar\ncontra mí, ven\012al GIMNASIO de\nla CIUDAD VERDE.\012Y aceptaré\ntu desafío…{DONE}",
  ["4e:4c48"] = "Aquí hay una\nnota…\012El GIMNASIO DE\nISLA CANELA se ha\012trasladado a ISLAS\nESPUMA.\012BLAINE{DONE}",
  ["4e:4c97"] = "ISLA CANELA\012La abrasadora isla\ndel ardiente deseo{DONE}",
  ["4e:4d3d"] = "Me siento más\nligera en el agua.{DONE}",
  ["4e:4d5f"] = "¡Oh, no!{DONE}",
  ["4e:4d68"] = "La natación\nfortalece todo el\012cuerpo. ¡Es muy\nbuena!{DONE}",
  ["4e:4da5"] = "¡Vaya colección\nde MEDALLAS\012de GIMNASIO!\n¡Luchemos!{DONE}",
  ["4e:4de5"] = "¡No!{DONE}",
  ["4e:4dea"] = "SURF ya no es el\núnico movimiento\012que se utiliza\nen el agua.{DONE}",
  ["4e:4e20"] = "Supongo que es\nimposible ir\012nadando hasta\nJOHTO.{DONE}",
  ["4e:4e58"] = "¡Aiyaa!{DONE}",
  ["4e:4e60"] = "Además de nadar\nen el mar, puedo\012nadar en estanques\ny ríos.{DONE}",
  ["4e:4e97"] = "¿Qué pone en\neste letrero?\012LÍDER del GIMNASIO\nde ISLA CANELA:\011BLAINE{DONE}",
  ["4e:4fa6"] = "¿Has nadado alguna\nvez en el mar por\011la noche?{DONE}",
  ["4e:4fd8"] = "¡Glup…!{DONE}",
  ["4e:4fdf"] = "De noche, el mar\nestá oscuro. Da la\012impresión de que\nte va a tragar.{DONE}",
  ["4e:5025"] = "(Resoplido)…\nUn… poco más…\012y… llegaré…\na CIUDAD FUCSIA…{DONE}",
  ["4e:5058"] = "¡Me ahogo!{DONE}",
  ["4e:5066"] = "Le… pedí a mi\nnovia que nadara\011a CIUDAD FUCSIA…{DONE}",
  ["4e:509a"] = "¡No me gustan los\ncanijos!{DONE}",
  ["4e:50b9"] = "Podría ganarte\nnadando…{DONE}",
  ["4e:50d8"] = "No hay que nadar\nmucho desde CIUDAD\012FUCSIA a las ISLAS\nESPUMA…\012¡Mi novio es un\ngrandullón!\012¡Qué canijo!{DONE}",
  ["4e:5144"] = "Soy malísimo\nnadando.\012Sólo estoy\nchapoteando por\012estas aguas poco\nprofundas.{DONE}",
  ["4e:5191"] = "Creía que podía\nganar.{DONE}",
  ["4e:51a9"] = "Puede que no nade\nmuy bien, pero me\011encanta el mar.{DONE}",
  ["4e:51da"] = "Lo siento. La\ncarretera está\011cortada por obras.\012Si quieres llegar\na ISLA CANELA, ve\012por el Sur, desde\nPUEBLO PALETA.{DONE}",
  ["4e:524f"] = "Estoy sudando.\n¡Voy a bañarme!{DONE}",
  ["4e:5270"] = "A saber cuánto se\ntardaría en mover\011esta roca…{DONE}",
  ["4e:52a8"] = "Las obras de la\ncarretera ya han\011terminado.\012Ya puedo volver a\npescar.{DONE}",
  ["4e:52e7"] = "RUTA 19\012CIUDAD FUCSIA -\nISLAS ESPUMA{DONE}",
  ["4e:5310"] = "Por favor, ten\ncuidado si vas\012nadando hasta las\nISLAS ESPUMA\012POLICÍA C. FUCSIA{DONE}",
  ["4e:53eb"] = "Un miembro del\nALTO MANDO era el\012LÍDER del GIMNASIO\nde CIUDAD FUCSIA.{DONE}",
  ["4e:5429"] = "La hija de KOGA le\nha sucedido como\012LÍDER del GIMNASIO\ncuando él se unió\011al ALTO MANDO.{DONE}",
  ["4e:5479"] = "La ZONA SAFARI\nestá cerrada. Da\012pena, ya que es\nla mayor atracción\011de CIUDAD FUCSIA.{DONE}",
  ["4e:54c8"] = "CIUDAD FUCSIA\012¡Mirad la CIUDAD\nFUCSIA! ¡La pasión\011rosa!{DONE}",
  ["4e:54f0"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011FUCSIA: SACHIKO\012La venenosa\nmaestra ninja.{DONE}",
  ["4e:5531"] = "Aquí hay una\nnota…\012El PUESTO GUARDA\nDE LA ZONA SAFARI\012está cerrado hasta\nnuevo aviso.{DONE}",
  ["4e:557b"] = "CASA DEL GUARDA\nDE LA ZONA SAFARI{DONE}",
  ["4e:5596"] = "El GUARDA está\nde viaje. Ésa es\012la razón por la\nque la ZONA SAFARI\011está cerrada.{DONE}",
  ["4e:55dd"] = "No ensuciar.\012Por favor, no\ntirar basura.{DONE}",
  ["4e:56d3"] = "Si estás buscando\nPOKéMON, mira\012en las zonas de\nhierba alta.{DONE}",
  ["4e:5713"] = "¡Ayyyy!{DONE}",
  ["4e:571c"] = "Siendo tan fuerte,\ndebe de ser muy\011divertido luchar.{DONE}",
  ["4e:574e"] = "El CAMINO BICIS es\nun atajo a CIUDAD\011AZULONA.{DONE}",
  ["4e:577c"] = "¡Uau…!{DONE}",
  ["4e:5784"] = "Si no tienes una\nBICI, no podrás\012usar el atajo.{DONE}",
  ["4e:57c8"] = "RUTA 18\012CIUDAD AZULONA -\nCIUDAD FUCSIA{DONE}",
  ["4e:587f"] = "¡Eh, tú! Eres de\nJOHTO, ¿verdad?{DONE}",
  ["4e:58a1"] = "¡Venga, golpea!{DONE}",
  ["4e:58b2"] = "¡No seas chulo,\npunki de JOHTO!{DONE}",
  ["4e:58d3"] = "¡Uau! ¡Qué BICI\nmás guay!{DONE}",
  ["4e:58ef"] = "Pero tú no\npareces guay…{DONE}",
  ["4e:590d"] = "Soy guay, pero\nestoy débil. Por\011eso no lo parezco.\012Debería entrenar\nmucho más…{DONE}",
  ["4e:5957"] = "¡Eh! ¿Un combate\nrapidito?{DONE}",
  ["4e:597a"] = "¡Vaya! ¡Qué\nvitalidad!{DONE}",
  ["4e:599c"] = "Montar sin manos\nen el CAMINO BICIS\011es muy guay.{DONE}",
  ["4e:59d3"] = "¡Somos estrellas\nde la carretera!{DONE}",
  ["4e:59f1"] = "¡Arrrg! ¡Chocar y\narder!{DONE}",
  ["4e:5a0a"] = "¡Conducir de forma\nimprudente causa\012accidentes! ¡Ten\ncuidado!{DONE}",
  ["4e:5aa6"] = "CAMINO BICIS\012¡Cuesta abajo\npor la costa!{DONE}",
  ["4e:5b3a"] = "Este POLIWRATH es\nmi compañero.\012Me pregunto si\nalgún día\012evolucionará en\nuna rana POKéMON.{DONE}",
  ["4e:5b88"] = "POLIWRATH: ¡Polii!{DONE}",
  ["4e:5b9b"] = "Volví a perder en\nlas tragaperras.\012Las chicas también\njugamos a las\012tragaperras.\nPrueba tú también.{DONE}",
  ["4e:5c00"] = "Últimamente han\naparecido GRIMER.\012¿Ves esa charca\nque hay delante de\012la casa? Ahí\nviven GRIMER.\012¿De dónde han\nvenido? Es un\011grave problema…{DONE}",
  ["4e:5c99"] = "¡Bravo! ¡Este\nGIMNASIO es\012genial! ¡Es sólo\npara chicas!{DONE}",
  ["4e:5cd2"] = "¿Te cuento\nun secreto?\012La MANSIÓN AZULONA\ntiene una puerta\011trasera secreta.{DONE}",
  ["4e:5d12"] = "Hay un concurso\nde tragones\011en el restaurante.\012Sólo verlo hace\nque me sienta\011lleno…{DONE}",
  ["4e:5d7a"] = "El C. COMERCIAL\nde CIUDAD AZULONA\012dispone de los\nmejores artículos.\012Si no encuentras\nalgo aquí, no lo\012encontrarás en\nningún otro sitio.\012¡Vaya…! Parezco\nuna vendedora.{DONE}",
  ["4e:5e18"] = "Me he mareado de\nir mirando al\012suelo mientras\ncaminaba.{DONE}",
  ["4e:5e52"] = "CIUDAD AZULONA\012La ciudad de los\nsueños de arcoiris{DONE}",
  ["4e:5e7b"] = "LÍDER DEL GIMNASIO\nPOKéMON DE\012CIUDAD AZULONA:\nERIKA\012La princesa amante\nde la naturaleza{DONE}",
  ["4e:5ebb"] = "¡Encuentra lo que\nnecesitas en el\012CENTRO COMERCIAL\nDE CIUDAD AZULONA!{DONE}",
  ["4e:5ee6"] = "MANSIÓN AZULONA{DONE}",
  ["4e:5ef7"] = "CASINO DE CIUDAD\nAZULONA: Zona de\011juego para todos{DONE}",
  ["4e:5f2a"] = "PISTAS ENTRENADOR\012PROTEC. ESP\nprotege a los\012POKéMON de\nataques ESPECIALES\011como fuego y agua.\012¡Consigue los\nobjetos en el\012CENTRO COMERCIAL\nde CIUDAD AZULONA!{DONE}",
  ["4e:6081"] = "¿Y este cartel?\012Algunos\nentrenadores han\012estado luchando en\nVÍA SUBTERRÁNEA.\012Tras numerosas\nquejas de los\012vecinos, la VÍA\nSUBTERRÁNEA ha\012sido cerrada\nindefinidamente.\012POLICÍA C. AZULONA{DONE}",
  ["4e:614f"] = "Está cerrada…{DONE}",
  ["4f:407f"] = "¿Has olvidado\nalgo?{DONE}",
  ["4f:409d"] = "¡Kiaaa!{DONE}",
  ["4f:40a6"] = "Antes de ser\nmaestra, solía\012olvidarme de\nmuchas cosas.{DONE}",
  ["4f:40e4"] = "Creo que si hace\nsol, los niños\012deberían estar\njugando en el\012patio en lugar\nde estar en clase.{DONE}",
  ["4f:414c"] = "No quería\nperder…{DONE}",
  ["4f:4163"] = "Es importante\nestudiar, pero\012hacer deporte\ntambién.{DONE}",
  ["4f:419c"] = "Espera. Tengo que\nllamar a mamá.{DONE}",
  ["4f:41be"] = "¡Lo siento, mamá!\n¡Me han vencido!{DONE}",
  ["4f:41d9"] = "Mi madre se\npreocupa mucho por\012mí, tengo que\nllamarla siempre.{DONE}",
  ["4f:421d"] = "Luchemos.\n¡No perderé!{DONE}",
  ["4f:4238"] = "¡Me olvidé de\nhacer los deberes!{DONE}",
  ["4f:4255"] = "¡Sayonara! Lo he\naprendido en la\011clase de japonés.{DONE}",
  ["4f:428a"] = "Vamos a la TORRE\nRADIO de LAVANDA\012para realizar unos\nestudios sociales.{DONE}",
  ["4f:42cc"] = "¡Eres demasiado\nduro!{DONE}",
  ["4f:42e3"] = "Estoy cansado de\ncaminar. Necesito\011un descanso.{DONE}",
  ["4f:4313"] = "¡Mi asignatura\nfavorita es la\011gimnasia!{DONE}",
  ["4f:432e"] = "¡Oh, no! ¿Cómo he\npodido perder?{DONE}",
  ["4f:4349"] = "¡Si los POKéMON\nfueran una\012asignatura, yo\nsería el mejor!{DONE}",
  ["4f:437c"] = "RUTA 15\012CIUDAD FUCSIA -\nPUEBLO LAVANDA{DONE}",
  ["4f:4458"] = "Que sepas que\nme costó mucho\012atrapar a mis\nqueridos POKéMON.{DONE}",
  ["4f:4495"] = "¡Auuuu!{DONE}",
  ["4f:449e"] = "SQUIRTLE, CHARMAN-\nDER y BULBASAUR.\012Creo que es una\nbuena combinación.{DONE}",
  ["4f:44e8"] = "Mi sueño es volar\ncon mi querido\011POKéMON pájaro.{DONE}",
  ["4f:4517"] = "Puedo soñar, pero\nnunca podré volar.{DONE}",
  ["4f:453a"] = "¿Tienes POKéMON\nque conozcan la\012MO VUELO? ¿Sí?\n¡Qué envidia!{DONE}",
  ["4f:457a"] = "¿Has luchado\ncon todos los\012entrenadores\nde GIMNASIO?{DONE}",
  ["4f:45a0"] = "¡Oh! ¡Demasiado\nfuerte para mí!{DONE}",
  ["4f:45bd"] = "Las MEDALLAS de\nKANTO te ayudarán\012en los combates\ncon el CABLE LINK.{DONE}",
  ["4f:46a7"] = "¡Arrodíllate ante\nmi regio POKéMON!{DONE}",
  ["4f:46c7"] = "¿Qué? ¡Te burlas\nde la realeza!{DONE}",
  ["4f:46e8"] = "¿Acaso no quiere\nser rey todo\011el mundo?{DONE}",
  ["4f:4714"] = "¡Jijiji! ¿Quieres\nluchar contra mi\011grupo de PIKACHU?{DONE}",
  ["4f:4747"] = "¡PI, PIKACHU!{DONE}",
  ["4f:4754"] = "Parece que tienes\nmuchos POKéMON,\012pero PIKACHU es\nel mejor.{DONE}",
  ["4f:4796"] = "La agilidad es\nla clave de los\011POKéMON pájaro.{DONE}",
  ["4f:47c2"] = "Me venciste con\ntu velocidad…{DONE}",
  ["4f:47e0"] = "Tus POKéMON\nestán muy bien\011entrenados.{DONE}",
  ["4f:4809"] = "Mira mis\nPOKéMON. Fíjate\012en su color y\nen su plumaje.{DONE}",
  ["4f:484e"] = "¡Vaya! ¡No soy lo\nbastante bueno!{DONE}",
  ["4f:4867"] = "Los POKéMON son\nfelices si los\011pones guapos.{DONE}",
  ["4f:488b"] = "Debería ir al\nTÚNEL ROCA para\011conseguir un ONIX.{DONE}",
  ["4f:48be"] = "He perdido…{DONE}",
  ["4f:48c7"] = "Parece que las\nformas geológicas\011no cambian.\012Pero sí que\ncambian, aunque\011poco a poco.{DONE}",
  ["4f:4921"] = "PISTAS ENTRENADOR\012¡Mira! Allí, a\nla izquierda\011del poste.{DONE}",
  ["4f:4960"] = "RUTA 13 HACIA EL\012NORTE AL PUENTE\nSILENCIO{DONE}",
  ["4f:4982"] = "HACIA EL NORTE\nAL PUEBLO LAVANDA\012HACIA EL OESTE\nA CIUDAD FUCSIA{DONE}",
  ["4f:4a69"] = "La paciencia es la\nclave para pescar\011y criar POKéMON.{DONE}",
  ["4f:4a9a"] = "¡Guaaa!{DONE}",
  ["4f:4aa3"] = "No tengo paciencia\npara la pesca…{DONE}",
  ["4f:4ac2"] = "Me gusta pescar\nmientras escucho\012canciones por\nla radio.{DONE}",
  ["4f:4b0b"] = "¡Mi estúpida radio\nme ha distraído!{DONE}",
  ["4f:4b2b"] = "¿Conoces las\nemisoras de\012radio de KANTO?\nTenemos muchas.{DONE}",
  ["4f:4b74"] = "¿Qué es lo más\nimportante en\011nuestras vidas?{DONE}",
  ["4f:4ba5"] = "¡La respuesta\nvendrá luego!{DONE}",
  ["4f:4bc4"] = "Creo que la\nelectricidad es lo\012más importante en\nnuestras vidas.\012Si no lo fuera, no\nse habría montado\012tanto follón\ncuando se estropeó\012la CENTRAL\nde ENERGÍA.{DONE}",
  ["4f:4c6b"] = "¿Te acuerdas?{DONE}",
  ["4f:4c7d"] = "Te acuerdas, ¿no?{DONE}",
  ["4f:4c8f"] = "El tirón de la\nCAÑA cuando ha\012picado un\nPOKéMON…\012Ésa es la mejor\nsensación para un\011pescador como yo.{DONE}",
  ["4f:4cf7"] = "RUTA 12\012PUEBLO LAVANDA\nHACIA EL NORTE{DONE}",
  ["4f:4d18"] = "COTO DE PESCA{DONE}",
  ["4f:4de8"] = "No se puede hacer\ntrampa en POKéMON.\012¡Que quede bien\nclaro!{DONE}",
  ["4f:4e25"] = "¿Qué? ¿Cómo ha\npodido ocurrir?{DONE}",
  ["4f:4e40"] = "He luchado con\nhonor.\012No me\navergüenzo.{DONE}",
  ["4f:4e81"] = "Cuando llevo\npantalones cortos\012por la hierba, me\npican las piernas.{DONE}",
  ["4f:4ebf"] = "¡Ayyyy!\n¡Me han pisado!{DONE}",
  ["4f:4ed8"] = "Voy a capturar\nmás POKéMON en\011la hierba.{DONE}",
  ["4f:4f03"] = "…{DONE}",
  ["4f:4f06"] = "…{DONE}",
  ["4f:4f09"] = "…\012Perdí cuando tenía\nlos ojos cerrados.{DONE}",
  ["4f:4f2f"] = "Ya veo…\012Todo lo que hay\nque ver de ti…{DONE}",
  ["4f:4f5b"] = "No me imaginaba\ntu poder…{DONE}",
  ["4f:4f7a"] = "Fuerza de\nconvicción…\012Eres fuerte porque\nconfías en tus\011POKéMON.{DONE}",
  ["4f:4fc6"] = "RUTA 11{DONE}",
  ["4f:5048"] = "Menudo\nedificio, ¿eh?\012Es la TORRE de\nRADIO de KANTO.{DONE}",
  ["4f:5080"] = "KANTO tiene muchos\nprogramas buenos.{DONE}",
  ["4f:50a2"] = "Viene gente de\ntodas partes a\012rendir homenaje\na las almas de\012los POKéMON\nque han partido.{DONE}",
  ["4f:50f2"] = "Para despertar a\nlos POKéMON,\012sintoniza FLAUTA\nPOKéMON.\012¡Todo entrenador\ndebería saberlo!{DONE}",
  ["4f:513d"] = "PUEBLO LAVANDA\012El noble pueblo\npúrpura{DONE}",
  ["4f:5162"] = "EMISORA DE\nKANTO\012¡Tus programas\nfavoritos a\011cualquier hora!{DONE}",
  ["4f:51a7"] = "CASA POKéMON\nDE VOLUNTARIOS DE\011PUEBLO LAVANDA{DONE}",
  ["4f:51c6"] = "CEMENTERIO\012Que las almas de\nlos POKéMON\011descansen en paz{DONE}",
  ["4f:5308"] = "CIUDAD CARMÍN\nes el puerto\012más importante\nde KANTO.\012En él atracan\nlujosos\012transatlánticos\nde todo el mundo.{DONE}",
  ["4f:5362"] = "Mi POKéMON está\npreparando el\012terreno donde\nedificar.\012Pero no tengo\ndinero para el\011proyecto…{DONE}",
  ["4f:53bd"] = "MACHOP: ¡Machop\nmachop!{DONE}",
  ["4f:53d5"] = "Un MACHOP gruñe\nmientras pisotea\011el suelo.{DONE}",
  ["4f:540d"] = "En KANTO hay ocho\nGIMNASIOS.\012Ese gran edificio\nes el GIMNASIO\012POKéMON de CIUDAD\nCARMÍN.{DONE}",
  ["4f:5457"] = "SNORLAX duerme\nplácidamente…{DONE}",
  ["4f:5477"] = "El POKéGEAR está\ncerca del\011SNORLAX dormido.\012…\012¡SNORLAX se\ndespertó!{DONE}",
  ["4f:54bb"] = "Los entrenadores\nexpertos se reúnen\011en KANTO.\012Los LÍDERES de\nGIMNASIO son\011muy fuertes.\012No serán fáciles\nde vencer.{DONE}",
  ["4f:551e"] = "¿Has conseguido ya\nalguna MEDALLA de\011GIMNASIO de KANTO?\012¿A que los\nentrenadores\012de KANTO son\nmuy fuertes?{DONE}",
  ["4f:557b"] = "Supongo que pronto\nhabrás conseguido\012todas las MEDALLAS\nde KANTO.\012Cuando tengas\nlas ocho MEDALLAS,\011dímelo.{DONE}",
  ["4f:55e6"] = "¡Enhorabuena!\012Tienes todas las\nMEDALLAS de KANTO.\012Te recompensaré\npor tu esfuerzo.{DONE}",
  ["4f:563d"] = "Llevar distintos\ntipos de POKéMON\012te debería ayudar\nen el combate.\012Seguro que las\nMEDALLAS de KANTO\011te ayudarán.{DONE}",
  ["4f:56ac"] = "CIUDAD CARMÍN\012El puerto de los\nocasos exquisitos{DONE}",
  ["4f:56da"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\012CIUDAD CARMÍN:\nLT. SURGE\012El Rayo\nAmericano{DONE}",
  ["4f:571b"] = "CLUB DE FANS\nDE POKéMON\011¡Bienvenidos!{DONE}",
  ["4f:5741"] = "CUEVA DE DIGLETT{DONE}",
  ["4f:5751"] = "ENTRADA AL PUERTO\nCARMÍN{DONE}",
  ["4f:5820"] = "La carretera está\ncortada hasta que\012arreglen la\nCENTRAL ENERGÍA.{DONE}",
  ["4f:5864"] = "VÍA SUBTERRÁNEA\012CIUDAD CELESTE -\nCIUDAD CARMÍN{DONE}",
  ["4f:5923"] = "Aquí vive una niña\nque es experta en\012imitar a la\ngente.\012Imita incluso a\nla gente con\012la que habla,\ny te confunde.{DONE}",
  ["4f:59a3"] = "La COPIONA parecía\nmuy triste.\012Había perdido\nsu POKé MUÑECO\011CLEFAIRY favorito.{DONE}",
  ["4f:59f6"] = "¿Eres de\nJOHTO?\012Si funcionara el\nMAGNETOTRÉN, no\012tardarías nada en\nvolver a casa.{DONE}",
  ["4f:5a44"] = "¿Eres de\nJOHTO?\012Con el MAGNETOTRÉN\nenseguida estarás\011en casa.{DONE}",
  ["4f:5a94"] = "Iba al GIMNASIO\na luchar contra\011entrenadores…\012Y acabé en el\nviejo GIMNASIO\012que hay\nal lado.\012¡Chico, qué\nvergüenza pasé!{DONE}",
  ["4f:5b24"] = "Es SILPH S.A.,\nfamosa por sus\011artículos POKéMON.\012En el pasado, el\nTEAM ROCKET quiso\012hacerse con esta\ncompañía por esa\011misma razón.{DONE}",
  ["4f:5b92"] = "¡Ñam… ñam…!\012Dicen que en la\nCENTRAL de ENERGÍA\012tienen muchos\nproblemas.\012¡Ñam… ñam…!{DONE}",
  ["4f:5be1"] = "¡Ñam… ñam…!\012Dicen que hay\nproblemas en la\011CENTRAL ENERGÍA.\012¡Ñam… ñam…!\n¡Estoy lleno!{DONE}",
  ["4f:5c3b"] = "Entrar por primera\nvez en un callejón\012me pone un\npoco nervioso.{DONE}",
  ["4f:5c7b"] = "En CIUDAD VERDE\nhay un lugar\012llamado la CASA\ndel ENTRENADOR,\012donde se reúne\ngente de todas\011partes.{DONE}",
  ["4f:5cdb"] = "Nuestra ciudad\nsalió en un\011programa de radio.\012Está bien oír\nalabanzas sobre tu\012ciudad, pero\ntambién da un poco\011de vergüenza.{DONE}",
  ["4f:5d4d"] = "CIUDAD AZAFRÁN\012La brillante y\ndorada tierra del\011comercio{DONE}",
  ["4f:5d7c"] = "LÍDER DEL GIMNASIO\nPOKéMON DE CIUDAD\011AZAFRÁN: SABRINA\012Maestra de los\nPOKéMON psíquicos{DONE}",
  ["4f:5dbf"] = "¡Bienvenidos!\nDOJO-KARATE{DONE}",
  ["4f:5de0"] = "EDIFICIO-OFICINAS\nSILPH S.A.{DONE}",
  ["4f:5dfb"] = "CASA DEL\nSR. PSÍQUICO{DONE}",
  ["4f:5e0f"] = "ESTACIÓN DEL\nMAGNETOTRÉN DE\011CIUDAD AZAFRÁN{DONE}",
  ["4f:5f1e"] = "La carretera está\ncortada hasta que\012arreglen la\nCENTRAL ENERGÍA.{DONE}",
  ["4f:5f62"] = "VÍA SUBTERRÁNEA\012CIUDAD CELESTE -\nCIUDAD CARMÍN{DONE}",
  ["4f:5f93"] = "¿Qué es esto?\012Casa en venta…\nNo vive nadie.{DONE}",
  ["4f:60b0"] = "La CENTRAL de\nENERGÍA de KANTO\012está al final de\nla RUTA 9. Hubo\012una especie de\naccidente.{DONE}",
  ["4f:610c"] = "¿Vas a atrapar\ntodos los tipos\011de POKéMON?\012Parece un gran\ndesafío, pero\011será divertido.{DONE}",
  ["4f:6170"] = "El CABO Norte es\nideal para llevar\012a una chica.\n¡Les encanta!{DONE}",
  ["4f:61b1"] = "SLOWBRO: ¿Slow?{DONE}",
  ["4f:61c2"] = "¡Mi SLOWBRO y yo\nformamos un equipo\011impresionante!{DONE}",
  ["4f:61f1"] = "¡SLOWBRO, enséñame\ntu CONFUSIÓN!{DONE}",
  ["4f:6213"] = "…{DONE}",
  ["4f:6216"] = "Soy un gran\nseguidor de\012la LÍDER MISTY\nde CIUDAD CELESTE.{DONE}",
  ["4f:623d"] = "Vi a ese tipo\nsospechoso de\012camino al CABO de\nCIUDAD CELESTE.{DONE}",
  ["4f:6271"] = "Antes había una\ncueva aquí que\012tenía POKéMON\nrealmente fuertes.{DONE}",
  ["4f:62b6"] = "¡Caray!\012Mi BUSCAOBJETOS\nresponde…{DONE}",
  ["4f:62da"] = "CIUDAD CELESTE\012Una misteriosa\naura azulada la\011rodea{DONE}",
  ["4f:630d"] = "LÍDER DEL GIMNASIO\nPOKéMON DE LA\012CIUDAD CELESTE:\nMISTY\012La Sirena\nDistorsionada{DONE}",
  ["4f:6349"] = "Aquí hay una\nnota…\012La TIENDA DE BICIS\nse ha trasladado a\012CIUDAD TRIGAL, en\nJOHTO…{DONE}",
  ["4f:6394"] = "Aquí hay una\nnota…\012¡Acaba con los\nladrones y haz que\012la ciudad sea más\ngrata y alegre!\012POLICÍA C. CELESTE{DONE}",
  ["4f:6403"] = "Hacia el\nCABO CELESTE{DONE}",
  ["4f:6418"] = "Está cerrado…{DONE}",
  ["50:4080"] = "He venido a\nexplorar el\011TÚNEL ROCA.{DONE}",
  ["50:40a0"] = "¡Uau! Peligro.{DONE}",
  ["50:40b4"] = "Hirieron a mis\nPOKéMON antes\012de entrar al\nTÚNEL ROCA.\012Será mejor que los\nlleve ahora mismo\012a un CENTRO\nPOKéMON.{DONE}",
  ["50:411a"] = "¿Has ido alguna\nvez de picnic?\012¡Es muy\ndivertido!{DONE}",
  ["50:414f"] = "¡Ohhhh!{DONE}",
  ["50:4157"] = "Hacemos dulces y\nlos repartimos\012entre todos. ¡Son\ndeliciosos!{DONE}",
  ["50:419d"] = "¡Eh, tú!\n¡No tires basura!{DONE}",
  ["50:41b5"] = "Sólo estaba\ndiciendo que…{DONE}",
  ["50:41d1"] = "Perdón. No estabas\ntirando basura. Me\011he equivocado.{DONE}",
  ["50:4202"] = "La gente no\ndebería dejar la\011basura por ahí.{DONE}",
  ["50:422c"] = "¡Ohh…! Perdí…{DONE}",
  ["50:423a"] = "Es importante\nahorrar energía,\012pues el entorno es\naún más vital.{DONE}",
  ["50:4283"] = "Ella se desviará\npor MT. PLATEADO\011cuando venga…\012MT. PLATEADO está\nen JOHTO, ¿verdad?{DONE}",
  ["50:42d2"] = "Estaba ocupado\ncantando…{DONE}",
  ["50:42eb"] = "Los combates son\ncuestión de\011concentración.{DONE}",
  ["50:430d"] = "Te contaré un\nsecreto.\012Pero primero,\n¡luchemos!{DONE}",
  ["50:433b"] = "¡Caray!\nHe perdido…{DONE}",
  ["50:4353"] = "La CENTRAL ENERGÍA\nestá al otro lado\011de un riachuelo.{DONE}",
  ["50:437d"] = "RUTA 9\012CIUDAD CELESTE -\nTÚNEL ROCA{DONE}",
  ["50:443b"] = "¡Eh, chico! ¡Un\nmiembro del TEAM\011ROCKET ser yo!\012Ser de otro país.\nEntrenador número\011uno, ¡yo ése!\012Pensar hice. Si\ncortar energía,\012¡mucho pánico\naquí todos!\012Misión secreta\nes, ¡no contar\011a ti!\012Pero, si ganar a\nmí, un hombre\012soy y secreto mío\na ti contar.\012¡Eh, chico!\n¡Lucha empezar!{DONE}",
  ["50:4574"] = "¡Ayyyy! ¡No, no,\nno! ¡Creer no\011puedo!\012¡Fuerte mucho\neres! ¡Rival\011para ti no soy!{DONE}",
  ["50:45cd"] = "Vale. Secreto\ncontar a ti.\012MAQUINARIA robar\nhice, en el GIM.\012de CIUDAD\nCELESTE guardé.\012En agua meter.\nEn el agua estar,\012en el centro\ndel GIMNASIO.\012¡Chico, olvidar\na mí, no!\012TEAM ROCKET ganar\na ti seguro.\012Amigos míos\nvenir de JOHTO.\012Sí, venganza\nhabrá.{DONE}",
  ["50:46f3"] = "…\012¿Dices que TEAM\nROCKET adiós?\012¿Roto? ¿Eso\ndices?\012¡Oh, no! ¿Debo\nir por cuenta\011mía ahora?{DONE}",
  ["50:48e7"] = "MISTY: ¡Eh!\n¿Por qué\012has venido a\nmolestarnos ahora?\012¿Sabes cómo llaman\na la gente\011como tú?\012¡Pesados! Me has\noído bien, pesado.\012…\012¡Oh! Esas\nMEDALLAS… ¿Son\012de los GIMNASIOS\nde JOHTO?\012Si tienes ocho,\nserás muy bueno.\012De acuerdo. Ven\nal GIMNASIO de\011CIUDAD CELESTE.\012Me enfrentaré a\nti encantada.\012Soy MISTY, la\nLÍDER del GIMNASIO\011de CIUDAD CELESTE.{DONE}",
  ["50:4a2e"] = "¡Véncenos a los\nseis para ganar\012un fantástico\npremio!\012¿Lo conseguirás?{DONE}",
  ["50:4a83"] = "¡Uau! Muy bien.{DONE}",
  ["50:4a96"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4ab9"] = "Ahora me toca a\nmí. ¡En guardia!{DONE}",
  ["50:4ad6"] = "¿Cómo he\npodido perder?{DONE}",
  ["50:4ae9"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4b0c"] = "¡Soy el tercero!\nY no será fácil.{DONE}",
  ["50:4b2a"] = "¡Au! ¡Se acabó!{DONE}",
  ["50:4b3d"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4b60"] = "¡Yo soy la cuarta!\n¿Cansado?{DONE}",
  ["50:4b7a"] = "He perdido…{DONE}",
  ["50:4b87"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4baa"] = "Yo soy el quinto.\n¡Te machacaré!{DONE}",
  ["50:4bc8"] = "¡Uau! Demasiado.{DONE}",
  ["50:4bd9"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4bfc"] = "Y por último yo,\npero te lo aviso,\011¡soy la mejor!{DONE}",
  ["50:4c2c"] = "¿Estás bromeando?{DONE}",
  ["50:4c3c"] = "Hice lo que pude.\nNo me arrepiento.{DONE}",
  ["50:4c5f"] = "¡Mufufufu…!\012No tengo nada que\nver con los otros\011seis entrenadores.\012Pero he esperado a\nque estés cansado\012de tanto pelear\npara vencerte.{DONE}",
  ["50:4ce2"] = "¿No estás\ncansado?{DONE}",
  ["50:4cfb"] = "Lo siento… No\nharé más trampas.{DONE}",
  ["50:4d1c"] = "Tuviste que\nluchar una\012vez más, pero\nganaste.\012Como te prometí,\nel premio es tuyo.{DONE}",
  ["50:4d7e"] = "Pero después de\nverte luchar, me\012gustaría saber\ncómo me iría a mí.\012Déjame luchar\ncontra ti.{DONE}",
  ["50:4dde"] = "¡Nunca había visto\nnada igual!{DONE}",
  ["50:4e01"] = "¡Ha sido\nfantástico!\012Tus POKéMON y tú\nsois realmente\011buenos.{DONE}",
  ["50:4e48"] = "CASA DEL MAR\nCASA DE BILL{DONE}",
  ["50:4f79"] = "¡Ah! Hace un\ntiempo estupendo.{DONE}",
  ["50:4f9c"] = "Hace sol, pero\nestoy mojado…{DONE}",
  ["50:4fb8"] = "Cuando llueve,\nes difícil\011encenderlo…{DONE}",
  ["50:4fe2"] = "¡Mmm…! No sé\nqué hacer…{DONE}",
  ["50:5001"] = "Sabía que\nperdería…{DONE}",
  ["50:5012"] = "Parecías fuerte.\012Me daba miedo\ndesafiarte…{DONE}",
  ["50:5043"] = "¡Puedo correr\ncomo el viento!{DONE}",
  ["50:505d"] = "¡He perdido!{DONE}",
  ["50:506a"] = "Siempre llevo\npantalones cortos.\012Ésa es mi forma\nde vestir.{DONE}",
  ["50:50a8"] = "¡Sube y echa\nun vistazo!{DONE}",
  ["50:50c8"] = "¡Uau! ¡Eso quema!{DONE}",
  ["50:50d9"] = "Soy el mejor\nCOMEFUEGOS de\011KANTO.\012Pero no el mejor\nentrenador…{DONE}",
  ["50:5124"] = "PLAZA MT. MOON\012Sube las\nescaleras{DONE}",
  ["50:51d5"] = "Las noticias dicen\nque ha pasado algo\011en la C. ENERGÍA.{DONE}",
  ["50:520a"] = "¿Perdí? ¡Vaya\nnoticia!{DONE}",
  ["50:5223"] = "Tengo que ir a la\nCENTRAL ENERGÍA.\012¿Está cerca del\nTÚNEL ROCA?{DONE}",
  ["50:525b"] = "Presiento que\npuedo ganar.\012¡Veamos si\ntengo razón!{DONE}",
  ["50:5293"] = "¡Uau! Eres\ndemasiado fuerte.{DONE}",
  ["50:52ad"] = "Dicen que CLEFAIRY\naparece en el\012MT. MOON.\n¿Pero dónde?{DONE}",
  ["50:52eb"] = "¡Umm…!\nYo…{DONE}",
  ["50:52f3"] = "…{DONE}",
  ["50:52f6"] = "…Creo que seguiré\nentrenándome…{DONE}",
  ["50:5311"] = "PLAZA MT. MOON\012Sube las\nescaleras{DONE}",
  ["50:53ef"] = "Somos el grupo de\nentrenadores de la\012FEDERACIÓN POKéMON\nde KANTO.\012¡Te vamos a\narrollar!{DONE}",
  ["50:543f"] = "¡Lo…, lo siento!{DONE}",
  ["50:5449"] = "¡Viva la\nFEDERACIÓN\011POKéMON de KANTO!{DONE}",
  ["50:5475"] = "Los polis han\ncerrado la VÍA\012SUBTERRÁNEA. ¡Qué\nfastidio!{DONE}",
  ["50:54b5"] = "¡Per…, perdóname!{DONE}",
  ["50:54c4"] = "Destruido por\nun gamberro\011de JOHTO…{DONE}",
  ["50:54e8"] = "Somos la\nFEDERACIÓN\012POKéMON de KANTO.\n¡Adelante, tío!{DONE}",
  ["50:551b"] = "¡Vaya! ¡Perdona!{DONE}",
  ["50:552a"] = "Intentaremos no\nmolestar a nadie\011a partir de ahora.{DONE}",
  ["50:5557"] = "¿Cómo funciona\nel MAGNETOTRÉN?{DONE}",
  ["50:557a"] = "Quiero ver el\nMAGNETOTRÉN…{DONE}",
  ["50:55a0"] = "¡El poder de los\nimanes es inmenso!{DONE}",
  ["50:55c4"] = "Necesitamos\nelectricidad.\012La CENTRAL ENERGÍA\nnos suministra la\011electricidad.{DONE}",
  ["50:5615"] = "¡No malgastes\nelectricidad!{DONE}",
  ["50:562e"] = "La C. ENERGÍA, al\nnorte de LAVANDA,\012suministra energía\nal MAGNETOTRÉN.{DONE}",
  ["50:5675"] = "Está cerrada…{DONE}",
  ["50:5682"] = "El cartel\nestá roto.\012Es imposible\nleerlo…{DONE}",
  ["50:571c"] = "CENTRAL DE\nENERGÍA DE KANTO{DONE}",
  ["50:5776"] = "¡Ja, ja, ja!{DONE}",
  ["50:5780"] = "¡Aaaaaaachís!{DONE}",
  ["50:5790"] = "¡La alergia me\nhace estornudar!\011¡AAACHÚS!{DONE}",
  ["50:57bd"] = "Te gustan los\nPOKéMON, ¿verdad?\012¡A mí también!{DONE}",
  ["50:57df"] = "Tengo que decir\nque son mi ruina.{DONE}",
  ["50:57fe"] = "Mira lo que\nhas hecho a\011mis POKéMON.\012No lo\nolvidaré…{DONE}",
  ["50:5831"] = "RUTA 10\012CIUDAD CELESTE -\nPUEBLO LAVANDA{DONE}",
  ["50:588f"] = "MESETA AÑIL\012¡El objetivo\nfinal de los\011entrenadores!\012El CG de la\nLIGA POKéMON{DONE}",
  ["51:400e"] = "Los marineros son\nmuy generosos.\012Uno enseñó FUERZA\na mi POKéMON y\012ahora puede mover\ngrandes rocas.{DONE}",
  ["51:4067"] = "Hay una persona en\nCIUDAD ORQUÍDEA,\011cruzando el mar.\012¡Dicen que\npresume de sus\011raros POKéMON!{DONE}",
  ["51:419a"] = "Gracias por\nayudarnos en el\011FARO…\012Pero esto es\ndistinto. Déjame\011que me presente.\012Soy YASMINA, una\nLÍDER de GIMNASIO.\011Uso el tipo acero.\012¿Sabes algo\ndel tipo acero?\012Fue descubierto\nhace poco\011tiempo.\012¡Um…! ¡Veamos!{DONE}",
  ["51:429c"] = "Eres mejor\nentrenador que yo,\012tanto en habilidad\ncomo en simpatía.\012De acuerdo con las\nnormas de la LIGA,\012te concedo esta\nMEDALLA.{DONE}",
  ["51:431b"] = "{PLAYER}\nrecibió la\011MEDALLA MINERAL.{DONE}",
  ["51:4335"] = "La MEDALLA MINERAL\naumenta la DEFENSA\011de los POKéMON.\012¡Eh…! Toma\nesto también…{DONE}",
  ["51:4386"] = "Usa esta MT\npara enseñar\011COLA FÉRREA.{DONE}",
  ["51:43b2"] = "¡Eh…! No sé\ncómo decirlo, pero\011buena suerte…{DONE}",
  ["51:43e3"] = "YASMINA usa el\ntipo acero recién\011descubierto.\012No sé mucho\nsobre ese tipo.{DONE}",
  ["51:4432"] = "Ha sido increíble.\012¿El tipo acero,\neh?\012¡Ha sido un gran\ncombate de un\011tipo desconocido!{DONE}",
  ["51:4489"] = "YASMINA, la LÍDER\ndel GIMNASIO, está\011en el FARO.\012Ha estado cuidando\na un POKéMON\011enfermo.\012Un buen entrenador\ndebe de ser\011compasivo.{DONE}",
  ["51:4583"] = "Cuando mis POKéMON\nenfermaron, el\012FARMACÉUTICO de\nCIUDAD IRIS me\011dio una medicina.{DONE}",
  ["51:45d1"] = "RHYDON: ¡Rhydo!{DONE}",
  ["51:4624"] = "De camino a CIUDAD\nORQUÍDEA, hay\012cuatro islas\ndesiertas.\012¡A los niños malos\nlos llevan a\012las islas como\ncastigo!{DONE}",
  ["51:4692"] = "Cuando me meto en\nlíos, papá siempre\011se enfada.{DONE}",
  ["51:472a"] = "¡CIUDAD OLIVO está\njunto al mar!\012¡Y si está junto\nal mar, tiene que\011haber peces!\012Llevo 30 años\npescando aquí.\012¿Quieres mirar\nal mar y\011pescar?{DONE}",
  ["51:47bc"] = "¡Ah, ja, ja!\n¡Ya tenemos un\011nuevo pescador!{DONE}",
  ["51:47e8"] = "No sólo hay peces\nen el mar. Puedes\012encontrarlos allí\ndonde haya agua.{DONE}",
  ["51:482d"] = "¿Quééé? ¿¡No te\ngusta pescar!?\011¡Incomprensible!{DONE}",
  ["51:4860"] = "¿Qué tal va todo?\n¿Pica el grande?{DONE}",
  ["51:48bd"] = "¡Ajá! ¡Tus POKéMON\nparecen muy\011débiles!\012No son capaces\nde mover\011rocas.\012¡Toma! ¡Usa esto\ny enséñales\011FUERZA!\012Necesitas la\nMEDALLA TRIGAL\012para usar FUERZA\nfuera del combate.{DONE}",
  ["51:4980"] = "¡En el mar sólo\npuedes confiar\011en ti mismo!\012¡Y yo estoy en\nplena forma!{DONE}",
  ["51:49e0"] = "¿Vas a cruzar el\nmar? Pues escucha:\012hay torbellinos\nde camino hacia\011CIUDAD ORQUÍDEA.\012Para pasar los\ntorbellinos,\012tienes que conocer\nun movimiento más.{DONE}",
  ["51:4aaa"] = "¿Tus POKéMON saben\nun movimiento para\012llevar personas\npor el agua?{DONE}",
  ["51:4aec"] = "Mi BUTTERFREE ha\nestado con mi\011novio.\012Y me ha traído\nuna CARTA suya.\012¿Quieres saber\nlo que dice?\012Veamos… ¡No!\n¡Es un secreto!{DONE}",
  ["51:4bb0"] = "¿De dónde has\ndicho que eras?\012¿De PUEBLO\nPRIMAVERA?\012El PROF. ELM vive\npor allí, ¿no?\012Has recorrido un\nlargo camino.{DONE}",
  ["51:4d04"] = "MUU-MUU está\nenferma…\012Necesita muchas\nBAYAS.{DONE}",
  ["51:4d30"] = "¡Estamos dando de\ncomer a MUU-MUU!{DONE}",
  ["51:4d46"] = "MUU-MUU: ¡Muu…!{DONE}",
  ["51:4d56"] = "Está débil…{DONE}",
  ["51:4d68"] = "MILTANK: ¡MUU!{DONE}",
  ["51:4d77"] = "¿Dar una BAYA a\nMUU-MUU?{DONE}",
  ["51:4d91"] = "{PLAYER} dio una\nBAYA a MUU-MUU.{DONE}",
  ["51:4dad"] = "¡MUU-MUU está un\npoco mejor!{DONE}",
  ["51:4dd1"] = "¡MUU-MUU está\nmucho mejor!{DONE}",
  ["51:4df0"] = "¡MUU-MUU se ha\nrecuperado!{DONE}",
  ["51:4e11"] = "{PLAYER} no tiene\nBAYAS…{DONE}",
  ["51:4e24"] = "{PLAYER} no le\nda una BAYA.\012MUU-MUU parece\ntriste.{DONE}",
  ["51:4f0d"] = "Mi MUU-MUU ya\nno me da\011leche.\012La leche de esta\nGRANJA es famosa.\012Casi todos\nquieren probarla.\012Supongo que si\nle doy muchas\012BAYAS me dará\nmucha leche.{DONE}",
  ["51:4fb7"] = "¿Te gusta mi\nLECHE MU-MU?\012Es mi orgullo y\nmi alegría, hijo.\012¡Dásela a los\nPOKéMON para\011restaurar sus PS!\012Tuya es por\nsólo 500¥.{DONE}",
  ["51:5031"] = "¡Toma! ¡Bébetela\ny disfruta!{DONE}",
  ["51:5050"] = "Lo siento, hijo.\n¡Si no hay dinero,\011no hay trato!{DONE}",
  ["51:506f"] = "Hijo, tu MOCHILA\nestá llena.{DONE}",
  ["51:508e"] = "¿No la quieres?\nVuelve otro día.{DONE}",
  ["51:50b3"] = "Mejor que me vaya\na ordeñar.{DONE}",
  ["51:50cd"] = "Nuestra leche\nllega hasta KANTO.\012Así que si nuestra\nMUU-MUU no nos da\012leche, tendremos\nproblemas.{DONE}",
  ["51:512d"] = "Has curado a\nnuestra MUU-MUU.\012Ya vuelve a dar\nLECHE MU-MU.\012Aquí tienes algo\nque te ayudará.{DONE}",
  ["51:519e"] = "Esto es\nRONQUIDO.\012Es un movimiento\nraro que sólo\012funciona cuando el\nPOKéMON duerme.\012Mejor que pienses\ncómo vas a\011utilizarlo.{DONE}",
  ["51:526c"] = "Dicen que ha\naparecido un\012GYARADOS rojo\nen el LAGO.\012¡Qué raro, porque\nen el lago no son\012frecuentes ni los\nGYARADOS comunes!{DONE}",
  ["51:52de"] = "¿Mi programa de\nradio favorito? La\011MÚSICA POKéMON.{DONE}",
  ["51:530d"] = "He estado oyendo\nrisas en la\012radio… Es\nespeluznante.{DONE}",
  ["51:545d"] = "Los POKéMON viven\ntodo tipo de\011experiencias.\012Yo también he\nvisto y sufrido\011mucho en mi vida.\012Soy más mayor, así\nque te enseñaré lo\011que quiero decir.\012He estado con los\nPOKéMON desde\012antes de que tú\nnacieras.\012Y no pierdo\nfácilmente.\012¡Yo, FREDO, el\nentrenador del\012invierno, te\nmostraré mi poder!{DONE}",
  ["51:5583"] = "¡Ah! Me impresiona\ntu valor.\012Con tu gran\nvoluntad, sé que\012superarás todos\nlos obstáculos.\012¡Te mereces\nesta MEDALLA!{DONE}",
  ["51:560b"] = "{PLAYER}\nrecibió la\011MEDALLA GLACIAR.{DONE}",
  ["51:5625"] = "Esta MEDALLA sube\nlas habilidades\012ESPECIALES de los\nPOKéMON.\012Y tus POKéMON\nusarán TORBELLINO\012para pasar los\ntorbellinos.\012¡Además, te voy\na hacer un regalo!{DONE}",
  ["51:56bf"] = "Esta MT contiene\nVIENTO HIELO.\012Causa daño y baja\nla velocidad.\012Demuestra la\ndureza del\011invierno.{DONE}",
  ["51:5729"] = "La primavera llega\ncuando se derrite\012el hielo y la\nnieve.\012Tú y tus POKéMON\npasaréis juntos\011muchos años.\012¡Pasadlo\nbien!{DONE}",
  ["51:57b1"] = "¡Congelaré a tus\nPOKéMON! ¡No\011podrás hacer nada!{DONE}",
  ["51:57e0"] = "Maldición. No\npude hacer nada.{DONE}",
  ["51:57fd"] = "Hay un movimiento\nque se puede usar\012cuando el POKéMON\nestá congelado.{DONE}",
  ["51:5835"] = "Este GIMNASIO\ntiene un suelo\012resbaladizo. ¿A\nque es divertido?\012¡Pero oye, aquí\nno estamos\011jugando!{DONE}",
  ["51:588d"] = "¿Ves lo serios\nque somos?{DONE}",
  ["51:58ad"] = "Este GIMNASIO es\ngenial. ¡Me\012encanta patinar\ncon mis POKéMON!{DONE}",
  ["51:58df"] = "Conozco el secreto\nde FREDO.{DONE}",
  ["51:58f6"] = "Te contaré el\nsecreto de FREDO.{DONE}",
  ["51:5917"] = "El secreto del\npoder de FREDO…\012Medita todos los\ndías bajo una\012cascada para\nmejorar su cuerpo\011y su mente.{DONE}",
  ["51:597e"] = "Para vencer a\nFREDO, el LÍDER\012del GIM., piensa\nantes de patinar.{DONE}",
  ["51:59c4"] = "¡No perderé ante\nti esquiando!{DONE}",
  ["51:59e6"] = "Si no patinas con\nprecisión, no\012lograrás nada en\neste GIMNASIO.{DONE}",
  ["51:5a27"] = "¡Mira qué bien\nesquío!{DONE}",
  ["51:5a44"] = "¡No! ¡He perdido!{DONE}",
  ["51:5a5f"] = "No debería haber\npresumido sobre mi\011forma de esquiar.{DONE}",
  ["51:5a8f"] = "FREDO es veterano.\nLleva entrenando\012POKéMON desde\nhace 50 años.\012Dicen que es bueno\ncongelando a sus\012rivales con los\nataques de hielo.\012¡Eso quiere decir\nque deberías\012derretirle con tu\nardiente ambición!{DONE}",
  ["51:5b45"] = "¡FREDO es bueno,\npero tú eres\011aún mejor!\012¡Ha sido un gran\ncombate que acortó\012distancias entre\ngeneraciones!{DONE}",
  ["51:5c32"] = "¿Qué pasa?\n¿Ha vuelto el\011TEAM ROCKET?\012He visto hombres\nde negro en el\011LAGO DE LA FURIA.{DONE}",
  ["51:5c83"] = "No permito que\nmis POKéMON\012evolucionen\ndemasiado pronto.\012Antes de dejarles\nevolucionar, les\012enseño algunos\nmovimientos.{DONE}",
  ["51:5ce8"] = "Al evolucionar,\nlos POKéMON se\012fortalecen, pero\ntardan más en\011aprender ataques.{DONE}",
  ["51:5d88"] = "MONTE MORTERO es\ncomo un laberinto.\012Ten cuidado. No\nte pierdas.{DONE}",
  ["52:406c"] = "Sin la MEDALLA\ndel GIMNASIO de\012CIUDAD IRIS, no se\nentra en la TORRE\012HOJALATA. ¡Vaya,\ntendrás que irte!{DONE}",
  ["52:40cc"] = "Sin la MEDALLA\nde CIUDAD IRIS,\012no se entra en\nTORRE HOJALATA.\012¡Ah!\012¡La MEDALLA de\nla CIUDAD IRIS!\011Puedes pasar.{DONE}",
  ["52:413f"] = "La TORRE HOJALATA\nse construyó como\012morada para los\nPOKéMON voladores.{DONE}",
  ["52:417d"] = "¡La TORRE HOJALATA\nse ha movido! ¡Se\012habrá posado un\nPOKéMON arriba!{DONE}",
  ["52:41b9"] = "Dos torres…\nDos POKéMON…\012Pero cuando una\nse quemó, los dos\012POKéMON huyeron\ny nunca volvieron.{DONE}",
  ["52:4304"] = "Hola, soy BILL.\n¿Quién eres tú?\012¿Eh? {PLAYER}.\n¡Has llegado\011justo a tiempo!{DONE}",
  ["52:434e"] = "Ya he terminado de\najustar la CÁPSULA\011del TIEMPO.\012Sabes que puedes\ncambiar POKéMON,\011¿verdad?\012Mi CÁPSULA del\nTIEMPO sirve para\012cambiar POKéMON\ncon el pasado.\012Pero no podrás\nenviar nada que\012no existiera en\nel pasado.\012Si lo haces, el PC\ndel pasado podría\011estropearse.\012Así que debes\neliminar cualquier\012cosa que no\nexistiera antes.\012Esto es, no envíes\nnuevos movimientos\012o nuevos POKéMON\na esta CÁPSULA.\012No te preocupes.\nYa he acabado\011de ajustarla.\012Mañana funcionarán\ntodas las CÁPSULAS\012del TIEMPO de los\nCENTROS POKéMON.\012Debo volver pronto\na CIUDAD TRIGAL.\011Mi familia espera.\012¡Hasta luego!{DONE}",
  ["52:4581"] = "Las CHICAS KIMONO\nson unas geniales\012bailarinas, además\nde magníficas\011con sus POKéMON.{DONE}",
  ["52:45d6"] = "MORTI, el LÍDER\ndel GIMNASIO, es\011muy bueno.\012Y sus POKéMON\nson muy fuertes.{DONE}",
  ["52:461c"] = "LAGO DE LA FURIA.\012Un montón de\nGYARADOS…\012¡Esto huele a\nconspiración!{DONE}",
  ["52:46d3"] = "Sucedió cuando\nera joven.\012El cielo se\noscureció de\012repente. Un enorme\nPOKéMON estaba\011tapando el sol.\012Me pregunto qué\nsería ese POKéMON,\012mezcla de pájaro\ny dragón.{DONE}",
  ["52:4782"] = "¿Existe un POKéMON\ntan grande? Si\012existe, debe de\nser muy fuerte.{DONE}",
  ["52:48b8"] = "Tus POKéMON son\nencantadores.\011¿Cómo luchan?{DONE}",
  ["52:48e9"] = "¡Oh! ¡Eres muy\nfuerte!{DONE}",
  ["52:4903"] = "Me ha gustado el\ncombate. Espero\011volver a verte.{DONE}",
  ["52:4938"] = "Yo siempre bailo\ncon mis POKéMON.\012Y también los\nentreno, claro.{DONE}",
  ["52:4974"] = "¡Estuve cerca!\nPor poco te venzo.{DONE}",
  ["52:4995"] = "El ritmo es muy\nimportante para\012la danza y para\nlos POKéMON.{DONE}",
  ["52:49c9"] = "¿Te gusta\nmi pasador?\012¡Ah! ¿Un combate\nPOKéMON?{DONE}",
  ["52:49f6"] = "No me queda ningún\nPOKéMON…{DONE}",
  ["52:4a12"] = "Cada mes pongo\nuna flor nueva\011en mi pasador.{DONE}",
  ["52:4a4a"] = "¡Oh! ¡Eres\ntan mono!\011¿Quieres luchar?{DONE}",
  ["52:4a7f"] = "Eres más fuerte de\nlo que pareces.{DONE}",
  ["52:4a9e"] = "He entrenado mucho\ny creía que tenía\012posibilidades,\npero no.{DONE}",
  ["52:4ae6"] = "¿Te gusta como\nbailo? Y también\012soy hábil con\nlos POKéMON.{DONE}",
  ["52:4b14"] = "¡Oh! ¡Tú también\neres bueno!{DONE}",
  ["52:4b32"] = "Sigo bailando\nporque hay gente\012a la que le gusta\nlo que hago.\012Mis POKéMON\nme animan.{DONE}",
  ["52:4b94"] = "Las CHICAS KIMONO\nno sólo bailan.\012También son\nextraordinarias\011con los POKéMON.\012Yo siempre las\ndesafío pero nunca\012les he hecho\nni un rasguño…{DONE}",
  ["52:4c1b"] = "¡Chico! Si vences\na todas las CHICAS\012KIMONO, te daré\nun regalo.{DONE}",
  ["52:4c5e"] = "Verte luchar ha\nsido como ver\011una danza.\012¡Ha sido un\nextraño combate!\012Me gustaría darte\nesto. Adelante,\011¡tuyo es!{DONE}",
  ["52:4cdf"] = "Es SURF.\012Un movimiento\nque permite nadar\011a los POKéMON.{DONE}",
  ["52:4d19"] = "Ojalá mis POKéMON\nfueran tan\012elegantes como las\nCHICAS KIMONO…{DONE}",
  ["52:4d4e"] = "RHYDON: ¡Rhydo,\nrhydo!{DONE}",
  ["52:4d68"] = "Ese hombre siempre\nva con su RHYDON.\012Dice que quiere un\nPOKéMON que baile\011y haga SURF.\012¿Intenta crear\nun POKéMON que\012haga natación\nsincronizada?{DONE}",
  ["52:4dee"] = "Las CHICAS KIMONO\nson tan guapas…\012Pero tienen que\nentrenar mucho.\012Y deben aprender\nlos distintos\012bailes antes\nde actuar.\012Pero si te gusta\nalgo, todo\011es posible.{DONE}",
  ["52:4ebd"] = "Es un elegante\npanel decorado\011con flores.{DONE}",
  ["52:4f8c"] = "Mi EEVEE\nevolucionó en\011ESPEON.\012Pero el EEVEE\nde mi amigo\012evolucionó en\nUMBREON.\012No sé por qué. Los\ndos educamos a\012nuestros EEVEE de\nla misma forma…{DONE}",
  ["52:5019"] = "Si usas REVIVIR,\nel POKéMON\012debilitado se\nreanimará.{DONE}",
  ["52:516b"] = "Me alegro de que\nhayas venido.\012En CIUDAD IRIS,\nveneramos a los\011POKéMON.\012Dicen que a los\nentrenadores más\012fuertes se les\naparecerán los\012POKéMON\nlegendarios.\012Yo lo creo y he\nentrenado aquí\012en secreto toda\nmi vida.\012Por eso, ahora\nveo lo que otros\011no ven.\012Un poco más…\012Un poco más y\nen el futuro\012encontraré a\nlos POKéMON\011legendarios.\012¡Y tú me vas a\nayudar a llegar\011a ese nivel!{DONE}",
  ["52:52f4"] = "Aún no soy lo\nbastante bueno…\012De acuerdo. Esta\nMEDALLA es tuya.{DONE}",
  ["52:532d"] = "{PLAYER}\nrecibió la\011MEDALLA NIEBLA.{DONE}",
  ["52:5343"] = "Con la MEDALLA\nNIEBLA, te\012obedecerán todos\nlos POKéMON\011hasta el nivel 50.\012Y los POKéMON\nque sepan SURF\012podrán usarlo en\ncualquier momento.\012Quédate con\nesto también.{DONE}",
  ["52:53d6"] = "Es BOLA SOMBRA.\nCausa daños y\012puede reducir la\nDEFENSA ESPECIAL.\012Úsala si te\ngusta.{DONE}",
  ["52:542f"] = "Entiendo…\012Tu viaje te\nha llevado a\011tierras lejanas.\012Y has presenciado\nmuchas más cosas\011que yo.\012¡Cómo te\nenvidio…!{DONE}",
  ["52:54a7"] = "Pasé la primavera\ncon mis POKéMON.\012Y el verano, otoño\ne invierno.\012Luego volvió la\nprimavera. Hemos\012vivido juntos\nmucho tiempo.{DONE}",
  ["52:5527"] = "Viví victorias\ny derrotas.{DONE}",
  ["52:554d"] = "¿De dónde vienen\nlos POKéMON?{DONE}",
  ["52:5568"] = "¿Puedes causar\nalgún daño a\011nuestros POKéMON?{DONE}",
  ["52:5591"] = "¡Ah! ¡Bien hecho!{DONE}",
  ["52:55a1"] = "Sólo usamos\nPOKéMON fantasma.\012¡Los ataques\nnormales no les\011hacen daño!{DONE}",
  ["52:55e5"] = "¡Ganaré!{DONE}",
  ["52:55f3"] = "¡He… he perdido!{DONE}",
  ["52:5602"] = "¡Ganará el que\nmás lo desee!{DONE}",
  ["52:5628"] = "¿Atónito por el\nsuelo invisible?\012¡Si quieres una\npista, vénceme!{DONE}",
  ["52:5669"] = "¿Có-Cómo?{DONE}",
  ["52:5674"] = "Bien. Te contaré\nel secreto\012del suelo\ninvisible.\012¡La ruta está\nenfrente de ti!{DONE}",
  ["52:56d2"] = "Estos entrenadores\ntienen motivos\011secretos.\012Si les ganas,\npodrían contarte\012algunos secretos\nsobre CIUDAD IRIS.{DONE}",
  ["52:573c"] = "¡Uauu, {PLAYER}!\n¡Genial!\012¡Me escondí en\nel rincón\011muerto de miedo!{DONE}",
  ["52:58cc"] = "¡Ah! ¿Vas de\naventura con tus\011POKéMON?\012¿Y qué es una\naventura sin\011un tesoro?\012¿Tengo razón\no no?{DONE}",
  ["52:5945"] = "¡Bien! Entiendes\nel verdadero\012espíritu de\nla aventura.\012¡Me gusta!\nToma esto.{DONE}",
  ["52:599e"] = "Por aquí hay\nmuchos objetos\012que no se ven\ntan fácilmente.\012Utiliza el\nBUSCAOBJETOS para\012saber si hay algún\nobjeto cerca.\012Éste no indica el\nlugar exacto, así\012que tú tendrás\nque encontrarlo.\012¡Ah, sí! Dicen que\nhay muchos objetos\012en TORRE QUEMADA\nde CIUDAD IRIS.{DONE}",
  ["52:5a95"] = "¡Oh! A cada uno lo\nsuyo, supongo…{DONE}",
  ["52:5ab6"] = "HISTORIA de\nCIUDAD IRIS\012¿Quieres leerla?{DONE}",
  ["52:5adc"] = "En CIUDAD IRIS\nhabía dos torres.\012Cada una acogía a\nun fuerte POKéMON\011volador.\012Pero una de\nellas se quemó.\012Y desde entonces\nno se ha visto a\012ninguno de los\ndos POKéMON.\012¿Seguir leyendo?{DONE}",
  ["52:5b92"] = "En CIUDAD IRIS\ntambién vivían\012tres POKéMON\nque corrían por\011toda la ciudad.\012Dicen que habían\nnacido del agua,\012del fuego y del\nrayo.\012Pero como no\npodían contener su\011enorme fuerza…\012Huyeron hacia\nlos pastos.{DONE}",
  ["53:40f3"] = "Soy DÉBORA, la\nmejor maestra\012de dragones\ndel mundo.\012No pueden conmigo\nni los miembros\012del ALTO MANDO de\nla LIGA POKéMON.\012¿Todavía quieres\nluchar conmigo?\012Está bien.\n¡Luchemos!\012¡Como entrenadora,\nusaré todo mi\012poder contra\ncualquier rival!{DONE}",
  ["53:41cf"] = "¿He perdido?\012No puedo creerlo.\nHa debido de haber\011algún error…{DONE}",
  ["53:4207"] = "No lo\nadmitiré.\012Habré perdido,\npero aún no estás\012preparado para la\nLIGA POKéMON.\012Lo sé. Deberías\nenfrentarte al\012desafío de los\nque usan dragones.\012Detrás de este\nGIMNASIO está la\011GUARIDA DRAGÓN.\012Ve allí y tráeme\nel COLMILLO de\012DRAGÓN que hay\nen la GUARIDA.\012Ésa es la prueba\nque debes aceptar\012si de verdad usas\ndragones.\012Si lo logras,\nte aceptaré\011como entrenador.\012Hasta entonces, no\nte daré ninguna\011MEDALLA.{DONE}",
  ["53:4391"] = "DÉBORA: ¿Cuál es\nel problema?\012Esta prueba no te\ncostará, salvo que\012hayas ganado\nde chiripa.{DONE}",
  ["53:43f0"] = "DÉBORA: No has\nconseguido eso en\011la GUARIDA DRAGÓN.\012Estás haciendo\ntrampas…\012Me has\ndecepcionado.{DONE}",
  ["53:4451"] = "DÉBORA: Me has\ndemostrado lo que\011vales.\012Esta MT es\npara ti.{DONE}",
  ["53:44a7"] = "Esta MT contiene\nDRAGOALIENTO.\012No, no tiene\nnada que ver con\011mi aliento.\012Si no la quieres,\nno es necesario\011que la aceptes.{DONE}",
  ["53:4525"] = "Así que has\nconseguido todas\011las MEDALLAS.\012Ahora debes\ndirigirte a la\012LIGA POKéMON\nde MESETA AÑIL.\012¿Sabes cómo llegar\nhasta allí?\012Desde aquí, ve a\nPUEBLO PRIMAVERA.\012Luego haz SURF\nhacia el Este. Es\011una ruta difícil.\012¡Ni se te ocurra\nperder en la\011LIGA POKéMON!\012¡Si pierdes, me\nsentiré aún peor\012por haber perdido\nante ti!{DONE}",
  ["53:4651"] = "¿Tu primer combate\ncontra dragones?\012¡Te mostraré lo\nfuertes que son!{DONE}",
  ["53:4696"] = "¡Qué decepción!{DONE}",
  ["53:46a8"] = "¿Viste a LANCE, el\nmaestro de los\012dragones? No puede\nser cierto.{DONE}",
  ["53:46e5"] = "¿Mis posibilidades\nde perder? ¡Ni el\011uno por ciento!{DONE}",
  ["53:4711"] = "Es extraño.{DONE}",
  ["53:471d"] = "Ahora sé cuál es\nmi punto débil.\012¡Gracias por\nenseñármelo!{DONE}",
  ["53:4753"] = "Los dragones son\nPOKéMON sagrados.\012Están llenos de\nenergía vital.\012Si no eres\nserio, no\012podrás acabar\ncon ellos.{DONE}",
  ["53:47c0"] = "¡Adelante!{DONE}",
  ["53:47cc"] = "Los dragones son\ndébiles contra los\012movimientos del\ntipo dragón.{DONE}",
  ["53:47fa"] = "¡Hola, futuro\ncampeón!\012¡Ha sido un largo\nviaje, pero casi\012hemos acabado!\n¡Confía en mí!\012DÉBORA usa los\nmíticos y sagrados\012POKéMON de tipo\ndragón.\012No son fáciles\nde dañar.\012Pero se supone\nque son débiles\012contra los ataques\ndel tipo hielo.{DONE}",
  ["53:48e8"] = "¡Genial! ¡Has\nvencido a DÉBORA!\012Sólo te queda el\ndesafío de la\011LIGA POKéMON.\012¡Vas a convertirte\nen el CAMPEÓN\011POKéMON!{DONE}",
  ["53:4a3f"] = "No es como si\ntodos usáramos\011POKéMON dragón.\012Mi política es\nusar POKéMON más\012fuertes que los\nPOKéMON dragón.{DONE}",
  ["53:4aa9"] = "Eres especial…{DONE}",
  ["53:4abb"] = "¡Tú observa!\nMis POKéMON se\012harán aún más\nfuertes.\012Seremos un\nentrenador y un\012equipo POKéMON\nmás fuertes.{DONE}",
  ["53:4b20"] = "DÉBORA nos ha\nentrenado a\012conciencia. No\npuedo perder.{DONE}",
  ["53:4b69"] = "¡Arrrg!\n¡Qué disgusto!{DONE}",
  ["53:4b83"] = "¡Uau…! ¡Tendré\nque replantearme\011mi entrenamiento!{DONE}",
  ["53:4bad"] = "¡La piedra cayó\npor el agujero!{DONE}",
  ["53:4c64"] = "DÉBORA y LANCE\nentrenaron aquí\012para perfeccionar\nsus técnicas.{DONE}",
  ["53:4ca4"] = "DRATINI: ¡Draa!{DONE}",
  ["53:4d20"] = "No puedes comprar\nMÁX. REVIVIR. Pero\012éste reanima\na un POKéMON\011debilitado.\012Atención: No\nrestaura los PP o\012PUNTOS de PODER de\nlos movimientos.{DONE}",
  ["53:4d9f"] = "MÁX. REPEL evita\nque se acerquen\011POKéMON débiles.\012Es el repelente\nmás duradero\011de todos.{DONE}",
  ["53:4e3b"] = "En el corazón de\nla remota MESETA\012AÑIL se celebra la\nLIGA POKéMON.\012Dicen que allí se\nreúnen los mejores\012entrenadores de\ntodo el país.{DONE}",
  ["53:4eb3"] = "Tenía un\nmovimiento que\012quería enseñar\na mi POKéMON.\012Así que usé el\nQUITA-MOVIMIENTOS\011y eliminé una MO.{DONE}",
  ["53:4fa7"] = "Parece que BLAINE,\ndel GIMNASIO de\012ISLA CANELA, vive\nsolo en la cueva\011de ISLAS ESPUMA…{DONE}",
  ["53:4ff1"] = "El volcán hizo\nerupción hace\011un año.{DONE}",
  ["53:507c"] = "El volcán de ISLA\nCANELA ha entrado\011en erupción.\012Y ha lanzado rocas\nque han cortado la\012RUTA 19 hasta\nnuevo aviso.\012Me pregunto si la\ngente de ISLA\012CANELA estará\nbien…{DONE}",
  ["53:50fc"] = "Nadie en ISLA\nCANELA resultó\012herido por la\nerupción. ¡Bien!{DONE}",
  ["53:51ba"] = "BLAINE: ¡Buaaa!\012Mi GIMNASIO de\nISLA CANELA se ha\011quemado.\012El volcán nos ha\ndejado sin casa a\012mis POKéMON\ncomefuego y a mí.\012¡Buaaaa!\012Pero sigo haciendo\nmi trabajo de\012LÍDER de GIMNASIO\nen esta cueva.\012Si me vences,\nte daré una\011MEDALLA.\012¡Ja! Espero que\ntengas ANTIQUEMAR.{DONE}",
  ["53:52b8"] = "BLAINE: Increíble.\nMe consumí…\012¡Has ganado la\nMEDALLA VOLCÁN!{DONE}",
  ["53:52f5"] = "{PLAYER} recibió\nla MED. VOLCÁN.{DONE}",
  ["53:530f"] = "BLAINE: Esta vez\nhe perdido, pero\012la próxima te\nganaré.\012Cuando reconstruya\nmi GIMNASIO de I.\012CANELA, tendremos\nla revancha.{DONE}",
  ["53:538e"] = "BLAINE: Mis\nPOKéMON de fuego\012serán más fuertes.\n¡Ya lo verás!{DONE}",
  ["53:53cb"] = "¡Vaya!\012¿Eh…? ¿Ya\nha acabado?\012¡Lo siento, tío!\012El GIMNASIO de\nISLA CANELA ya no\012existe y no sabía\ndónde encontrarte.\012Pero eres fuerte\nhasta sin mis\012consejos. ¡Sabía\nque ganarías!{DONE}",
  ["53:5477"] = "Los GIMNASIOS\nPOKéMON están allí\012donde se encuentre\nsu LÍDER.\012No es necesario\nun edificio.{DONE}",
  ["53:5521"] = "Te has\nperdido…\012Aquí he meditado.\nUn nuevo poder se\012ha despertado\ndentro de mí.\012Déjame compartir\nmi poder con tus\012POKéMON.\nToma esto, hijo.{DONE}",
  ["53:55b4"] = "¿Lo ves? ¡Es PODER\nOCULTO!\012Saca el poder de\nlos POKéMON para\011atacar.\012Recuerda: su tipo\ny poder dependen\012del POKéMON\nque lo usa.{DONE}",
  ["53:5649"] = "Estoy meditando…{DONE}",
  ["53:5704"] = "El LAGO DE LA\nFURIA es un cráter\012obra de violentos\nGYARADOS.\012El cráter se llenó\nde agua de la\012lluvia y se formó\nel LAGO.\012Esta historia la\ncontó por primera\012vez el tatarabuelo\nde mi abuelo.\012Antes se podían\npescar MAGIKARP\012en el lago,\npero…\012No entiendo lo\nque ocurre ahora.{DONE}",
  ["53:5823"] = "En el LAGO pasan\ncosas raras desde\012que llegaron esos\nhombres de negro.{DONE}",
  ["53:5866"] = "La normalidad ha\nvuelto al LAGO DE\012LA FURIA. Vuelve a\nhaber MAGIKARP.\012Quizá se cumpla\nmi sueño de ver\012al MAGIKARP más\ngrande del mundo.\012¿Tienes una CAÑA?\nSi tienes una,\011ayúdame por favor.{DONE}",
  ["53:5914"] = "¡Ah, tienes un\nMAGIKARP! A ver\012lo grande que es\nese bebé.{DONE}",
  ["53:594d"] = "¡Uau! ¡Éste es\nimpresionante!\012¡Me quito el\nsombrero ante ti!\012¡Toma esto como\nrecuerdo!{DONE}",
  ["53:5999"] = "Lo importante es\nel récord. ¡Piensa\012en él como una\nbonificación!{DONE}",
  ["53:59d7"] = "¡Uau! ¡Éste es\nimpresionante!\012Ojalá no tuviera\nque decirlo, pero\012he visto uno más\ngrande antes.{DONE}",
  ["53:5a32"] = "¿Qué? ¡Eso no es\nun MAGIKARP!{DONE}",
  ["53:5a4f"] = "¿No tienes ninguno\nbueno para\012enseñármelo? Quizá\nla próxima vez.{DONE}",
  ["53:5af5"] = "Últimamente sólo\npasaron por aquí\012los que iban al\nLAGO DE LA FURIA.{DONE}",
  ["53:5b3b"] = "Ahora nadie\nva al LAGO\011DE LA FURIA.{DONE}",
  ["53:5ca8"] = "¡Alto ahí,\nseñor!\012El precio por\npasar es 1000¥.{DONE}",
  ["53:5ce1"] = "¡Gracias, señor!{DONE}",
  ["53:5cf2"] = "Entonces paga\nlo que tengas.{DONE}",
  ["53:5d13"] = "¡Je, je! Nos\nestamos forrando.\012Todo el mundo\nquiere ver lo que\012ocurre en el LAGO\nDE LA FURIA.{DONE}",
  ["53:5d6d"] = "Esos gamberros de\nnegro me echaron\011de mi puesto.\012Se dejaron\nesto.\012Me molesta.\n¿Podrías\011llevártelo?{DONE}",
  ["53:5dff"] = "Usa esta puerta\npara no andar\011por la hierba.{DONE}",
  ["54:4005"] = "¿Coleccionas las\nMEDALLAS DE KANTO?{DONE}",
  ["54:405a"] = "Dicen que hay\nun tipo sospechoso\011merodeando.\012Si resulta ser\nel ladrón, le\011detendré.{DONE}",
  ["54:40c3"] = "Ya nos atracaron\nantes.{DONE}",
  ["54:40e7"] = "DIGLETT: Dig, dig.{DONE}",
  ["54:414d"] = "Mi marido vive\nfeliz con los\012POKéMON que ha\nintercambiado.{DONE}",
  ["54:418a"] = "Soy tan feliz…{DONE}",
  ["54:419c"] = "KANGASKHAN: Kangas\nkangas.{DONE}",
  ["54:41b5"] = "ZUBAT: Zuba zubaa.{DONE}",
  ["54:4218"] = "La RUTA 9 va hacia\nel Este. La\012CENTRAL de ENERGÍA\nestá al final.{DONE}",
  ["54:4257"] = "El MAGNETOTRÉN\nviaja a unos\012550 Km/h. Puede\nllevarte de\012KANTO a JOHTO en\npocos segundos.\012Hace que sea muy\nfácil ir a JOHTO.{DONE}",
  ["54:4453"] = "¡Uups! ¡Yo sentir!\nTú no hacer daño,\011¿de acuerdo?\012Yo muy ocupado.\nNo tener tiempo\012para hablar\ncontigo. No poder\011verme nadie.{DONE}",
  ["54:44cc"] = "¡Oh, no! ¡Tú\nverme! ¡Yo cometer\011gran error!{DONE}",
  ["54:44fd"] = "¡Oye! Tú olvidar\nque me has visto,\012¿vale? Tú ver, oír\ny saber nada, ¿de\012acuerdo?\n¡Adiós, chico!\012¡Hasta la vista!{DONE}",
  ["54:4568"] = "Lo siento, estaré\nfuera un tiempo.\012MISTY, LÍDER del\nGIMNASIO{DONE}",
  ["54:459a"] = "Como MISTY ha\nsalido, nosotros\012tampoco estaremos.\nLos ENTRENADORES{DONE}",
  ["54:45cc"] = "MISTY: Te estaba\nesperando,\011pesado.\012Puede que tengas\nmuchas MEDALLAS de\012JOHTO, pero será\nmejor que me tomes\011en serio.\012¡Mis POKéMON de\nagua son fuertes!{DONE}",
  ["54:4664"] = "MISTY: Eres\nrealmente bueno…\012Reconozco que eres\nun experto…\012Aquí tienes la\nMEDALLA CASCADA.{DONE}",
  ["54:46c0"] = "{PLAYER} recibió\nMEDALLA CASCADA.{DONE}",
  ["54:46da"] = "MISTY: ¿Hay muchos\nentrenadores\012fuertes en JOHTO?\nComo tú, digo.\012Un día viajaré y\nlucharé contra\012entrenadores\nexpertos.{DONE}",
  ["54:4762"] = "Siento haber\nestado fuera.\011¡A lo nuestro!{DONE}",
  ["54:4790"] = "¡Me rindo! ¡Has\nganado!{DONE}",
  ["54:47ae"] = "Estaré nadando\ntranquilamente.{DONE}",
  ["54:47c8"] = "No te desanimes\npor mi elegante\011forma de nadar.{DONE}",
  ["54:47f7"] = "¡Ooh! Has acabado\nconmigo…{DONE}",
  ["54:4818"] = "No fardes tanto de\nhaberme vencido.\012MISTY acabará\ncontigo si te\011confías demasiado.{DONE}",
  ["54:486a"] = "¡Glup…!\012¡Soy el primero!\n¡Ven a por mí!{DONE}",
  ["54:488c"] = "No puede ser…{DONE}",
  ["54:489b"] = "MISTY ha mejorado\nmucho en los\011últimos años.\012¡No bajes la\nguardia o acabarás\011machacado!{DONE}",
  ["54:48ff"] = "¡Hola, futuro\nCAMPEÓN!\012Como MISTY no\nestaba, salí\012a divertirme un\nrato. ¡Je, je, je!{DONE}",
  ["54:4952"] = "¡Uauu! ¡Qué\nfuerte eres!\012¡Como siempre, ha\nsido un combate\011realmente bueno!{DONE}",
  ["54:4a25"] = "Encontrarás muchos\nentrenadores de\012camino hacia\nCABO CELESTE.\012Quieren saber cómo\nson en comparación\012con otros\nentrenadores.{DONE}",
  ["54:4a9e"] = "MISTY es casi la\núnica persona de\012la ciudad capaz de\nvencer a los\012ENTRENADORES de\nCABO CELESTE.{DONE}",
  ["54:4b49"] = "¿Un CENTRO POKéMON\njunto a una cueva?\012¡Qué bien!\n{DONE}",
  ["54:4b7e"] = "El DIRECTOR de la\nC. ENERGÍA busca\012a un entrenador\nPOKéMON fuerte.\012Necesita ayuda\npara recuperar\012algo que le\nrobaron.{DONE}",
  ["54:4bf6"] = "Dicen que el TEAM\nROCKET se reunió\012en JOHTO, pero se\nvolvió a separar.\012No tenía ni idea\nde eso.{DONE}",
  ["54:4c64"] = "Cuando salgas,\nverás el tejado\012de un edificio\nmuy grande.\012Eso es la CENTRAL\nde ENERGÍA.{DONE}",
  ["54:4e31"] = "Entró un ladrón en\nla C. ENERGÍA…\012¿Adónde vamos a\nir a parar?{DONE}",
  ["54:4e73"] = "Tengo noticias de\nCIUDAD CELESTE.\012Parece que ha\nestado merodeando\012por allí un hombre\nmuy sospechoso.{DONE}",
  ["54:4ed0"] = "¿Puedo pedirte\nayuda?{DONE}",
  ["54:4ef3"] = "Tendremos que\nreforzar nuestra\011seguridad.{DONE}",
  ["54:4f20"] = "Alguien ha robado\nuna pieza que\012necesitamos para\nel generador.\012¡Sin ella, el\nnuevo generador no\011sirve para nada!{DONE}",
  ["54:4f89"] = "El generador ya\nfunciona y está\012generando mucha\nelectricidad.{DONE}",
  ["54:4fca"] = "Esta CENTRAL de\nENERGÍA había\012sido abandonada\nhace mucho tiempo.\012Volvimos a ponerla\nen funcionamiento\012para poder usar\nel MAGNETOTRÉN.{DONE}",
  ["54:5040"] = "¡El generador\nya funciona!{DONE}",
  ["54:505f"] = "El DIRECTOR de la\nCENTRAL ENERGÍA\011está ahí delante.\012Pero está triste y\nenfadado porque\012alguien ha\nestropeado el\011generador…{DONE}",
  ["54:50d0"] = "El DIRECTOR está\ncontento porque\012el generador ya\nestá arreglado.{DONE}",
  ["54:5113"] = "El MAGNETOTRÉN\nconsume mucha\011electricidad.\012No se puede mover\nsi el nuevo\012generador no\nfunciona.{DONE}",
  ["54:5176"] = "¡Muy bien!\nEl MAGNETOTRÉN\012puede volver a\nfuncionar.{DONE}",
  ["54:51b5"] = "DIRECTOR: ¡Me voy\na enfadar con\011alguien!\012¿Quién ha roto mi\ngenerador?\012¡Con el tiempo que\nle he dedicado!\012¡Como lo atrape,\nva a saber lo\012que es mi\nELECTROCAÑÓN!{DONE}",
  ["54:5259"] = "DIRECTOR: ¡Nunca\nle perdonaré!\012Aunque el culpable\nllore y suplique\012perdón, ¡le\nmachacaré!\012¡Ja, ja, ja!{DONE}",
  ["54:52bf"] = "DIRECTOR: ¡Sí!\012¡Ésa es la pieza\nque le faltaba a\012mi generador! ¿La\nencontraste tú?{DONE}",
  ["54:5315"] = "¡Yuju! ¡Gracias!\012¡Toma esta MT\ncomo recompensa!{DONE}",
  ["54:5345"] = "DIRECTOR: La MT07\nes mi ELECTRO-\012CAÑÓN. ¡Es muy\npotente!\012Aunque presenta\nel inconveniente\012de no ser muy\nprecisa.{DONE}",
  ["54:53c6"] = "DIRECTOR: ¡Mi\nquerido generador!\012¡Sigue generando\nelectricidad!{DONE}",
  ["54:5612"] = "¿Conoces a BILL?\nEs mi nieto.\012Está en JOHTO\ntrabajando con\012los PC. Yo le\ncuido la casa.{DONE}",
  ["54:5676"] = "Si tienes ese\nPOKéMON, ¿me\011dejas verlo?{DONE}",
  ["54:56a4"] = "¿Me lo dejas ver?\n¡Qué amable eres!{DONE}",
  ["54:56c8"] = "¿No lo tienes?\n¡Qué pena…!{DONE}",
  ["54:56ea"] = "¡Ah! ¿es ése\n{STRBUF}?\012¡Qué mono!\nEres muy\011simpático.{DONE}",
  ["54:5725"] = "¡Gracias!\012Toma esto como\nagradecimiento.{DONE}",
  ["54:5752"] = "Vuelve cuando\nquieras.{DONE}",
  ["54:576e"] = "Gracias por\nmostrarme tantos\012POKéMON\nbonitos.\012Me he divertido\nmucho. Me alegro\012de haber vivido\ntantos años.{DONE}",
  ["54:57d5"] = "¿Mmm?\012Ése no es el\nPOKéMON del\011que me hablaron.{DONE}",
  ["54:5804"] = "Mi nieto BILL me\ndijo que había un\012POKéMON con una\nlengua muy larga.{DONE}",
  ["54:5843"] = "Mi nieto mencionó\na un POKéMON verde\012y redondo al que\nle crecen hojas en\011la cabeza.{DONE}",
  ["54:5897"] = "¿Conoces a un\nPOKéMON de mar que\012tiene una esfera\nroja en el cuerpo?\012Ya sabes, ése\nque tiene forma\011de estrella.\012Dicen que sale\npor la noche.\012Me encantaría\nverlo.{DONE}",
  ["54:5942"] = "BILL me habló de\nun POKéMON que\012es muy fiel a su\nentrenador.\012Se supone que\nRUGE bien.{DONE}",
  ["54:599b"] = "He oído hablar de\nun POKéMON que\011tiene seis colas.\012Me gustaría\nabrazar a un\011POKéMON así.{DONE}",
  ["54:59f5"] = "¿Conoces a ese\nPOKéMON tan\011popular?\012El POKéMON de\ncuerpo amarillo\011y mejillas rojas.\012Me gustaría\nverlo antes\012de que\nevolucione.{DONE}",
  ["55:4013"] = "¿Tus POKéMON saben\nmovimientos MO?\012Se pueden usar\nestos movimientos\012aunque el POKéMON\nesté debilitado.{DONE}",
  ["55:4067"] = "En el PC de BILL\nse almacenan 20\011POKéMON por CAJA.{DONE}",
  ["55:4092"] = "¿Sabes algo sobre\nlos BONGURI?\012Abre uno, vacíalo\ny rellénalo con\012un aparato\nespecial.\012Así podrás atrapar\nPOKéMON.\012Antes de que se\ninventaran las\012POKé BALL, todos\nusaban BONGURI.{DONE}",
  ["55:41ed"] = "Todos los SLOWPOKE\ndel pueblo\011han desaparecido.\012Quizá el guardián\ndel ENCINAR esté\011enfadado…\012Puede ser un mal\npresagio. Mejor\011no salir.{DONE}",
  ["55:4276"] = "Los SLOWPOKE han\nvuelto…\012Pero mi APRENDIZ\nno ha vuelto del\011ENCINAR.\012¿Dónde demonios\nestá ese vago?{DONE}",
  ["55:42ec"] = "¿Expulsaste al\nTEAM ROCKET y\012fuiste solo al\nENCINAR?\012¡Qué valiente! Me\ngustas. Entrena\011con nosotros.{DONE}",
  ["55:4359"] = "¿Adónde han ido\nlos SLOWPOKE?\012¿Están jugando\nfuera?{DONE}",
  ["55:439e"] = "Lo siento. Olvidé\ndarte las gracias.\012Éste es el CARBÓN\nque he fabricado.\012A los POKéMON de\nfuego les gustará\011llevarlo.{DONE}",
  ["55:440c"] = "Los SLOWPOKE han\nvuelto, hasta\011FARFETCH'D.\012¡Eres el mejor,\ntío!{DONE}",
  ["55:445e"] = "FARFETCH'D: ¡Farf!{DONE}",
  ["55:44c6"] = "Aquí no hay SÚPER\nBALL. Tendrás que\012conformarte con\nlas POKé BALL.\012¡Ojalá me pudiera\nfabricar CÉSAR\011alguna BALL!{DONE}",
  ["55:452f"] = "Mejor una SÚPER\nBALL para capturar\012POKéMON que una\nPOKé BALL.\012Pero a veces,\nlas de CÉSAR\011son mejores.{DONE}",
  ["55:47ee"] = "¿Quién eres?\012{PLAYER},\n¿quieres que haga\011alguna BALL?\012Lo siento, pero\ndeberás esperar.\012¿Conoces al TEAM\nROCKET? ¡Bah!\012No importa. Yo\nte lo contaré.\012Se trata de una\nbanda malvada que\012usa POKéMON para\nel trabajo sucio.\012Se supone que se\ndisolvieron hace\011tres años.\012¡Pero están en el\nPOZO cortando\012COLAS de SLOWPOKE\npara venderlas!\012¡Así que voy a\nir allí a darles\011una lección!\012¡Resistid,\nSLOWPOKE!\011¡CÉSAR os ayudará!{DONE}",
  ["55:4990"] = "CÉSAR: ¡{PLAYER}!\012Te has portado\ncomo un auténtico\011héroe en el POZO.\012¡Tienes estilo!\012Sería un honor\nhacer alguna BALL\012para un entrenador\ncomo tú.\012Ahora sólo tengo\nésta. Tuya es.{DONE}",
  ["55:4a44"] = "CÉSAR: Fabrico\nlas BALL de\011los BONGURI.\012Recógelos de\nlos árboles\011y traémelos.\012Los usaré para\nhacer las BALL.{DONE}",
  ["55:4ab1"] = "CÉSAR: ¿Tienes\nun BONGURI?\012¡Vale! Te haré\nuna BALL.{DONE}",
  ["55:4af4"] = "CÉSAR: Tardaré un\ndía en fabricar\012una BALL. Vuelve\nmañana a por ella.{DONE}",
  ["55:4b37"] = "CÉSAR: ¡Oh…!\n¡Qué decepción!{DONE}",
  ["55:4b53"] = "CÉSAR: ¡Estoy\ntrabajando! ¡Vete!{DONE}",
  ["55:4b76"] = "CÉSAR: ¡{PLAYER}!\nAcabo de terminar\011tu BALL. Tuya es.{DONE}",
  ["55:4ba5"] = "CÉSAR: Ha salido\nmuy bien.\012Intenta capturar\nPOKéMON con ella.{DONE}",
  ["55:4bde"] = "Los SLOWPOKE se\nhan ido…\012¿Se los ha llevado\nla gente mala?{DONE}",
  ["55:4c1a"] = "El abuelo se fue.\nEstoy tan sola…{DONE}",
  ["55:4c38"] = "¡El SLOWPOKE\nque me regaló mi\012padre ha vuelto!\n¡Y su COLA\011vuelve a crecer!{DONE}",
  ["55:4c7e"] = "Papá trabaja en\nSILPH y estudia\011las POKé BALL.\012Tengo que quedarme\nen casa con el\011abuelo y SLOWPOKE.{DONE}",
  ["55:4cdb"] = "SLOWPOKE: ¡Mmm!\n(Bostezo).{DONE}",
  ["55:4cee"] = "¿Un joven\nPROF. OAK?{DONE}",
  ["55:4d03"] = "Es una estatua\ndel guardián\011del encinar.{DONE}",
  ["55:4e83"] = "¡Soy ANTÓN!\nSoy invencible\012con los\nPOKéMON bicho.\012¡Mis estudios me\nvan a convertir en\012una autoridad de\nlos POKéMON bicho!\012Te enseñaré lo\nque he aprendido.{DONE}",
  ["55:4f26"] = "¡Uauu, increíble!\n¡Eres un experto\011en POKéMON!\012Mi investigación\naún no ha acabado.\012Vale, tú ganas.\nToma esta MEDALLA.{DONE}",
  ["55:4f8c"] = "{PLAYER}\nrecibió la\011MEDALLA COLMENA.{DONE}",
  ["55:4fa3"] = "¿Conoces las\nventajas de la\011MEDALLA COLMENA?\012Si la tienes, los\nPOKéMON hasta N.30\011te obedecerán.\012Y los POKéMON\nque sepan CORTE\012podrán usarlo\nfuera del combate.\012Mira, también te\ndaré esto.{DONE}",
  ["55:5060"] = "MT49 contiene\nCORTEFURIA.\012Si no fallas, se\nhace cada vez\011más fuerte.\012Cuanto más dure\nel combate, más\011fuerte será.\012¿No es genial?\n¡Lo descubrí yo!{DONE}",
  ["55:50fe"] = "Los POKéMON bicho\nson muy complejos.\012Quedan muchos\nmisterios por\011resolver.\012Estudia a fondo\ntus favoritos.{DONE}",
  ["55:515e"] = "Los POKéMON bicho\nevolucionan pronto\012y se hacen fuertes\nmucho antes.{DONE}",
  ["55:519d"] = "¡No se trata sólo\nde evolucionar!{DONE}",
  ["55:51b9"] = "Los POKéMON se\nhacen más fuertes\011si evolucionan.{DONE}",
  ["55:51e7"] = "¡Los POKéMON bicho\nson buenos y muy\012fuertes! ¡Te lo\ndemostraré!{DONE}",
  ["55:521a"] = "Has demostrado lo\nfuerte que eres…{DONE}",
  ["55:5239"] = "Son geniales,\npero la mayoría de\012las chicas odian\nlos POKéMON bicho.\012No sé por qué…{DONE}",
  ["55:527e"] = "¿Has salvado a los\nSLOWPOKE? ¡Uauu!\011¡Eres muy fuerte!\012¡Pero mis\nPOKéMON\012entrenados también\nson muy fuertes!{DONE}",
  ["55:52da"] = "¡Urrggg!{DONE}",
  ["55:52e4"] = "Supongo que\ndebería enseñarles\011mejores ataques…{DONE}",
  ["55:530f"] = "AMY: ¿Vas a\ndesafiar al LÍDER?\011¡Ni lo sueñes!{DONE}",
  ["55:5341"] = "AMY-MAY: ¡Oh,\ndoble bondad!{DONE}",
  ["55:5362"] = "AMY: ¡Eres\nmuy fuerte!{DONE}",
  ["55:537d"] = "MAY: ¿Quieres ver\nal LÍDER?\012¡Pues nosotras\nvamos primero!{DONE}",
  ["55:53ae"] = "AMY-MAY: ¡Oh,\ndoble bondad!{DONE}",
  ["55:53cf"] = "MAY: Han perdido\nnuestros POKéMON.\011¡Qué lástima!{DONE}",
  ["55:53fc"] = "¡Hola, valiente!\012ANTÓN es joven,\npero conoce muy\012bien a los POKéMON\nbicho.\012Y sin mis consejos\nte resultaría aún\011más duro.\012Veamos… A los\nPOKéMON bicho no\011les va el fuego.\012Y los ataques de\ntipo volador son\011muy efectivos.{DONE}",
  ["55:54bf"] = "¡Eso es! Ha sido\nun gran encuentro\012entre jóvenes\ncon talento.\012Con gente como tú,\n¡el futuro de los\012POKéMON será\nmaravilloso!{DONE}",
  ["56:400f"] = "Cuando atrapas un\nPOKéMON, puede\011estar débil.\012Pero éste crecerá\ny se hará más\011fuerte.\012Es importante\ntratar a los\012POKéMON con\nmucho cariño.{DONE}",
  ["56:4090"] = "Los POKéMON pueden\nir equipados con\012objetos como\nPOCIÓN y ANTÍDOTO.\012Pero parece que\nno saben usar los\012objetos hechos\npor el hombre.{DONE}",
  ["56:41e0"] = "¡Soy PEGASO, líder\ndel GIMNASIO de\011CIUDAD MALVA!\012Dicen que una\nsacudida eléctrica\012puede acabar con\nlas alas de los\011POKéMON voladores.\012¡No permitiré\nque hablen así\011de ellos!\012¡Yo te enseñaré el\nauténtico poder de\012los magníficos\npájaros POKéMON!{DONE}",
  ["56:42b7"] = "¡Maldición! Los\nqueridos POKéMON\011de mi padre…\012¡Muy bien!\nToma esto.\012Es la MEDALLA\nCÉFIRO oficial de\011la LIGA POKéMON.{DONE}",
  ["56:431c"] = "{PLAYER} recibió\nla MEDALLA CÉFIRO.{DONE}",
  ["56:4335"] = "La MEDALLA CÉFIRO\nmejora el ataque\011de los POKéMON.\012Y permite que\nlos POKéMON\012usen DESTELLO, si\nlo tienen.\012Toma, también\nte daré esto.{DONE}",
  ["56:43b5"] = "Al usar una MT, el\nPOKéMON aprenderá\012inmediatamente un\nnuevo movimiento.\012Piensa antes de\nactuar, ya que las\012MT sólo se pueden\nusar una vez.\012MT31 contiene\nBOFETÓN-LODO.\012Reduce la\nprecisión del\012enemigo y causa\ngrandes daños.\012Es decir, es tanto\ndefensiva como\011ofensiva.{DONE}",
  ["56:44a2"] = "Encontrarás\nGIMNASIOS POKéMON\012en las ciudades\ny en los pueblos.\012Deberías probar\ntus habilidades en\011estos GIMNASIOS.\012¡Yo seguiré\nentrenándome para\012ser el maestro de\nlos pájaros!{DONE}",
  ["56:453a"] = "¡La clave está en\ntener valor!\012Éstos entrenan\nnoche y día para\012convertirse en\nmaestros POKéMON.\012¡Adelante!{DONE}",
  ["56:459c"] = "¡Aaah!{DONE}",
  ["56:45a4"] = "¡La destreza de\nPEGASO es real!\012¡No te confíes\npor haberme\011vencido!{DONE}",
  ["56:45ec"] = "¡Demuéstrame que\neres lo bastante\011bueno para PEGASO!{DONE}",
  ["56:4620"] = "¡No puede\nser cierto!{DONE}",
  ["56:4634"] = "¡Qué patético!\nHe perdido contra\011un novato…{DONE}",
  ["56:4666"] = "¡Hola! ¡No soy\nentrenador pero te\011puedo aconsejar!\012¡Créeme!\nSi confías, tus\012sueños de triunfo\npodrían cumplirse.\012¿Confías? Pues\nescucha.\012El tipo planta es\ndébil contra el\012tipo volador.\n¡No lo olvides!{DONE}",
  ["56:4735"] = "¡Bonita batalla!\n¡Sigue así y\011serás el CAMPEÓN!{DONE}",
  ["56:48a8"] = "¡Soy yo, PRIMO!\012¡Fantásticos son\nlos POKéMON!\012¡A ti yo te\nenseñaré a ser un\011entrenador mejor!\012¿Quieres saber\ncómo ser un\011ganador?{DONE}",
  ["56:492a"] = "¡Bien! ¡A ti yo\nte enseñaré!\012¡En combate, los\nprimeros POKéMON\011salen antes!\012¡Quizá sea más\nfácil si cambias\011el orden!\012¿Quieres que te\ncuente más cosas?{DONE}",
  ["56:49be"] = "¿Quieres saber\ncómo educar bien\011a los POKéMON?{DONE}",
  ["56:49e8"] = "¡Bien! ¡A ti yo\nte enseñaré!\012Si un POKéMON\nsale al combate,\012aunque brevemente,\ngana puntos EXP.\012¡Pon arriba los\nPOKéMON débiles,\012y cámbialos rápido\nen el combate!\012¡Así se harán\nfuertes los\011POKéMON débiles!{DONE}",
  ["56:4a9e"] = "¡Oh! ¡Un alumno\nlisto eres! ¡Nada\011más quieres saber!\012¡Bueno en POKéMON\ndebes de ser!{DONE}",
  ["56:4aed"] = "Estoy tomando\napuntes de lo que\011dice el profesor.\012Y debería copiar\ntambién lo escrito\011en la pizarra.{DONE}",
  ["56:4b47"] = "He cambiado a mis\nmejores POKéMON\011con mi compañero.{DONE}",
  ["56:4b74"] = "¡El POKéMON que\nhe conseguido va\011equipado con algo!{DONE}",
  ["56:4ba6"] = "Si un POKéMON va\nequipado con una\012BAYA, se curará él\nsolo en combate.\012Los POKéMON pueden\nir equipados con\011muchos objetos…\012Es muy duro\ntomar apuntes…{DONE}",
  ["56:4c1f"] = "La pizarra indica\ncómo cambian de\012estado los POKéMON\nen combate.{DONE}",
  ["56:4c6b"] = "Si un POKéMON\nes envenenado,\011perderá PS.\012El envenenamiento\ncontinúa tras el\012combate y al\ncaminar seguirá\011perdiendo PS.\012Para curarlo,\nusa ANTÍDOTO.{DONE}",
  ["56:4ced"] = "La parálisis baja\nla velocidad y\012puede impedir el\nmovimiento.\012Permanece tras el\ncombate, así que\011usa ANTIPARALIZ.{DONE}",
  ["56:4d4f"] = "Si tu POKéMON\nse queda dormido\012no podrá realizar\nningún movimiento.\012Un POKéMON dormido\nno se despierta\011tras el combate.\012Despiértalo con\nDESPERTAR.{DONE}",
  ["56:4dc2"] = "Las quemaduras\nconsumen PS,\012reducen el poder\ndel ataque\012y permanecen\ntras el combate.\012Usa ANTIQUEMAR\ncomo cura.{DONE}",
  ["56:4e38"] = "Si tu POKéMON está\ncongelado, no\011podrá hacer nada.\012Seguirá congelado\ntras el combate.\012Descongélalo con\nANTIHIELO.{DONE}",
  ["56:4ea3"] = "Es el cuaderno de\neste niño…\012Captura POKéMON\nusando POKé BALL.\012Tu equipo puede\ntener hasta seis.\012¿Seguir leyendo?{DONE}",
  ["56:4f04"] = "Antes de lanzar la\nPOKé BALL, debes\011debilitarlo.\012Atrapar un\nPOKéMON quemado\012o envenenado es\nmucho más fácil.\012¿Seguir leyendo?{DONE}",
  ["56:4f74"] = "Algunos ataques\ncausan confusión.\012Un POKéMON confuso\npuede atacarse a\011sí mismo.\012Retirarlo del\ncombate, eliminará\011su confusión.\012¿Seguir leyendo?{DONE}",
  ["56:4ff4"] = "Quienes atrapan\nPOKéMON y los usan\012para luchar son\nentrenadores.\012Su misión es ir\na los GIMNASIOS\012y vencer a otros\nentrenadores.\012La hoja siguiente\nestá… ¡vacía!\012Niño: ¡Eh, eh…!\012No he escrito\nnada más…{DONE}",
  ["56:5167"] = "Ella usa los\nnombres de sus\011comidas favoritas.\012Quiero decir,\ncomo motes para\011sus POKéMON.{DONE}",
  ["56:51cb"] = "¡A mi PIDGEY le\nllamo FRESITA!{DONE}",
  ["56:51e9"] = "FRESITA: ¡Pidgey!{DONE}",
  ["56:52c2"] = "¡{PLAYER}, cuánto\ntiempo sin verte!\012El PROF. ELM te\nestá buscando.\012Quiere pedirte\notro favor.\012¿Puedes llevar el\nHUEVO POKéMON?{DONE}",
  ["56:5332"] = "Hemos descubierto\nque los POKéMON\012salen del HUEVO\ncuando crecen.\012Para que el HUEVO\nse abra, debe de\012estar con otros\nPOKéMON activos.\012{PLAYER}, sólo\npodemos confíar\011en ti.\012Llama al PROF. ELM\ncuando se abra el\011HUEVO, por favor.{DONE}",
  ["56:5400"] = "¡Oh, no! No puedes\nllevar más\011POKéMON.\012Esperaré aquí a\nque le hagas\011sitio al HUEVO.{DONE}",
  ["56:545f"] = "Pero…\nEl PROF. ELM\011preguntó por ti.{DONE}",
  ["56:547f"] = "{PLAYER},\n¿quieres el HUEVO?{DONE}",
  ["56:549a"] = "El sistema de\nalmacenamiento del\012PC es de un chico\nllamado BILL.{DONE}",
  ["56:54cd"] = "Fue hace unos\ntres años.\012El TEAM ROCKET\nquería hacer daño\011a los POKéMON.\012Pero prevaleció la\njusticia y un niño\011acabó con ellos.{DONE}",
  ["56:5549"] = "Los POKéMON son\nlistos y no\012obedecen a quien\nno respetan.\012Sin las MEDALLAS\nnecesarias, harán\012lo que ellos\nquieran.{DONE}",
  ["56:5628"] = "Los POKéMON que\nse intercambian\011crecen rápido.\012Pero si no tienes\nla MEDALLA\012adecuada, podrían\ndesobedecerte.{DONE}",
  ["56:56c7"] = "RUINAS ALFA\012Centro Turístico\n¡Mírame y Tócame!\012¡Intenta mover las\npiezas de piedra!{DONE}",
  ["56:5712"] = "¿Estás estudiando\nlas RUINAS?\012Eres un científico\nen potencia.{DONE}",
  ["56:574e"] = "Hay dibujos en las\npiezas de piedra.\012Intenté moverlas.\nMe pregunto\011qué serán.{DONE}",
  ["56:5814"] = "Éste es un buen\nsitio para pescar.\012¿Has visto a\ngente pescando?\011¿Y tú?\012¿Quieres una\nde mis CAÑAS?{DONE}",
  ["56:5879"] = "Eso está\nbien.\012¡Ahora ya eres\nun pescador!{DONE}",
  ["56:58ac"] = "¡Pescar es genial!\012Si ves agua, ya\nsea el mar o un\012río, utiliza\ntu CAÑA.{DONE}",
  ["56:58fd"] = "¡Vaya! Me has\ndecepcionado…{DONE}",
  ["56:591e"] = "Hola, jovencito.\n¿Qué? ¿Pican?{DONE}",
  ["56:5943"] = "¿Cómo equipar\na mi POKéMON?\012Quizá con un\nobjeto que aumente\011su ATAQUE…{DONE}",
  ["56:5a70"] = "¡Perdona, chaval!\n¿Puedes hacerme\011un favor?\012¿Puedes darle este\nPOKéMON con CARTA\011a mi amigo?\012Está en la\nRUTA 31.{DONE}",
  ["56:5adb"] = "¿Lo harás? Genial.\n¡Gracias, chaval!\012Mi amigo es un\nchico gordinflón\012que siempre está\ndurmiendo.\012¡Le reconocerás\nenseguida!{DONE}",
  ["56:5b4b"] = "{PLAYER} recibió\nPOKéMON con CARTA.{DONE}",
  ["56:5b69"] = "Puedes leerla,\n¡pero no la\011pierdas! ¡RUTA 31!\012Ah, sí. Un extraño\nárbol bloqueaba\011el camino.\012¿Lo habrán\nretirado ya?{DONE}",
  ["56:5be9"] = "No puedes llevar\notro POKéMON…{DONE}",
  ["56:5c07"] = "¡Oh…! Entonces,\nno importa…{DONE}",
  ["56:5c1e"] = "¡Gracias, chaval!\n¡Muchas gracias\012por habérselo\nllevado!\012¡Toma esto por\nlas molestias!{DONE}",
  ["56:5c6c"] = "¿A que mi amigo\nestaba durmiendo?\011Te lo dije.{DONE}",
  ["56:5c9d"] = "Un extraño árbol\nbloquea el camino.\012Si le hablas,\nse mueve.\012Dicen que se\nvolvió loco cuando\012alguien lo mojó\ncon una REGADERA.{DONE}",
  ["56:5d2d"] = "Me gusta la Nana\nPOKéMON que ponen\011en la radio.{DONE}",
  ["56:5ef2"] = "Hoy es {STRBUF}.\nEso significa que\012hoy es el Concurso\nCaptura de Bichos.\012Las reglas son\nsencillas.\012Usa uno de tus\nPOKéMON y captura\012un POKéMON bicho\npara ganar.\012¿Te gustaría\nintentarlo?{DONE}",
  ["56:5fa4"] = "Aquí tienes las\nPARQUE BALL para\011el Concurso.{DONE}",
  ["56:5fce"] = "{PLAYER} recibió\n20 PARQUE BALL.{DONE}",
  ["56:5fe9"] = "Aquél que consiga\nel POKéMON bicho\012más fuerte será\nel ganador.\012Tienes 20\nminutos.\012Si te quedas sin\nPARQUE BALL, has\011perdido.\012Puedes quedarte\nel último POKéMON\011que captures.\012¡Sal y captura\nel POKéMON\012bicho más fuerte\nque encuentres!{DONE}",
  ["56:60cd"] = "¡Oh, oh…!\012Tienes más de\nun POKéMON.\012Tendrás que usar\na {STRBUF},\012el primer POKéMON\nde tu equipo.\012¿Te parece\nbien?{DONE}",
  ["56:613e"] = "Bien, guardaremos\nlos otros POKéMON\011mientras compites.{DONE}",
  ["56:6172"] = "Los POKéMON de\n{PLAYER} se quedan\011con el AYUDANTE.{DONE}",
  ["56:619e"] = "Elige el POKéMON\nque usarás en\012el Concurso y\nluego ven a verme.{DONE}",
  ["56:61e3"] = "Muy bien.\nEsperamos verte\011pronto por aquí.{DONE}",
  ["56:620f"] = "¡Oh, oh…!\nEl primer POKéMON\012de tu equipo no\npuede luchar.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.{DONE}",
  ["56:6283"] = "¡Oh, oh…!\nTu equipo y\012tu CAJA del PC\nestán llenos.\012No tienes sitio\npara guardar el\011POKéMON bicho.\012Haz sitio en\ntu equipo o en\012la CAJA del PC y\nluego ven a verme.{DONE}",
  ["56:6326"] = "¡Oh, oh…! Tienes\nun HUEVO como\012primer POKéMON\nde tu equipo.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.{DONE}",
  ["56:63a1"] = "Aún te quedan\n{STRBUF} minuto(s).\012¿Quieres terminar\nahora?{DONE}",
  ["56:63e2"] = "Bien. Espera en\nla Puerta Norte a\012que se anuncien\nlos ganadores.{DONE}",
  ["56:642a"] = "Vale. Vuelve fuera\ny termina\011el juego.{DONE}",
  ["56:6456"] = "El Concurso ha\nacabado. Esperamos\012volveros a ver\naquí pronto.{DONE}",
  ["56:649b"] = "En el PARQUE se\nsuelen celebrar\012muchos Concursos.\nDeberías probar.{DONE}",
  ["56:64df"] = "¿Cuándo será el\npróximo Concurso\011Captura de Bichos?{DONE}",
  ["56:6515"] = "El Concurso de\nCaptura de Bichos\012es los martes,\njueves y sábados.\012No sólo ganas\nun premio por\012participar, sino\nque también puedes\012quedarte con un\nPOKéMON bicho.{DONE}",
  ["56:660d"] = "¿No te imaginas\nquién podría\012hacer algo así?\n¿Y por qué?{DONE}",
  ["56:6648"] = "¿Has visto ese\nextraño árbol en\011el camino?\012Eso explica por\nqué vienen menos\012personas a visitar\nlas RUINAS ALFA.{DONE}",
  ["56:69c0"] = "Hoy es {STRBUF}.\nEso significa que\012hoy es el Concurso\nCaptura de Bichos.\012Las reglas son\nsencillas.\012Usa uno de tus\nPOKéMON y captura\012un POKéMON bicho\npara ganar.\012¿Te gustaría\nintentarlo?{DONE}",
  ["56:6a70"] = "Aquí tienes las\nPARQUE BALL para\011el Concurso.{DONE}",
  ["56:6a9a"] = "{PLAYER} recibió\n20 PARQUE BALL.{DONE}",
  ["56:6ab5"] = "Aquél que consiga\nel POKéMON bicho\012más fuerte será\nel ganador.\012Tienes 20\nminutos.\012Si te quedas sin\nPARQUE BALL, estás\011perdido.\012Puedes quedarte\nel último POKéMON\011que captures.\012¡Sal y captura\nel POKéMON\012bicho más fuerte\nque encuentres!{DONE}",
  ["56:6b99"] = "¡Oh, oh…!\012Tienes más de\nun POKéMON.\012Tendrás que usar\n{STRBUF}, el\012primer POKéMON de\ntu equipo.\012¿Te parece\nbien?{DONE}",
  ["56:6c0a"] = "Bien, guardaremos\nlos otros POKéMON\011mientras compites.{DONE}",
  ["56:6c3e"] = "Los POKéMON de\n{PLAYER} se quedan\011con el AYUDANTE.{DONE}",
  ["56:6c6a"] = "Elige los POKéMON\nque usarás en\012el Concurso y\nluego ven a verme.{DONE}",
  ["56:6caf"] = "Bien. Esperamos\nvolver a verte\011por aquí pronto.{DONE}",
  ["56:6cdb"] = "¡Oh, oh…!\nEl primer POKéMON\012de tu equipo no\npuede luchar.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.{DONE}",
  ["56:6d4f"] = "¡Oh, oh…!\nTu equipo y\012tu CAJA del PC\nestán llenos.\012No tienes sitio\npara guardar el\011POKéMON bicho.\012Haz sitio en\ntu equipo o en\012la CAJA del PC y\nluego ven a verme.{DONE}",
  ["56:6df2"] = "¡Oh, oh…! Tienes\nun HUEVO como\012primer POKéMON\nde tu equipo.\012Sustitúyelo por\nel POKéMON que\012quieras usar y\nluego ven a verme.{DONE}",
  ["56:6e6d"] = "Aún te quedan {STRBUF}\nminutos.\012¿Quieres terminar\nahora?{DONE}",
  ["56:6eac"] = "Bien. Por favor,\nespera aquí\012a que se anuncien\nlos ganadores.{DONE}",
  ["56:6ee7"] = "Bien. Por favor,\nvuelve fuera y\011termina.{DONE}",
  ["56:6f12"] = "El Concurso ha\nacabado. Esperamos\012volver a veros\npor aquí pronto.{DONE}",
  ["56:6f57"] = "Algunos POKéMON\nsólo aparecen en\011el PARQUE.{DONE}",
  ["56:6f80"] = "RAFA: ¡Uau! Me\nhas vencido. Eres\011bastante bueno.{DONE}",
  ["56:6fab"] = "RAFA: La suerte\ncuenta mucho.\012Nunca se sabe\nqué POKéMON\011va a aparecer.{DONE}",
  ["56:6ff6"] = "SAM: Te envidio.\nEsta vez no\011lo he conseguido.{DONE}",
  ["56:7027"] = "SAM: ¿Has usado\nPOKéMON grandes?{DONE}",
  ["56:7049"] = "NANO: ¡Eso es!\nVoy a entrenar\012mejor a mis\nPOKéMON.{DONE}",
  ["56:707d"] = "NANO: Quizá ganes\nmás puntos por\012un POKéMON de\nun color inusual.{DONE}",
  ["56:70c1"] = "GUILLE: ¿Eres el\nganador? ¿Qué\011has atrapado?{DONE}",
  ["56:70f1"] = "GUILLE: Me alegra\nhaber atrapado\012el POKéMON\nque quería.{DONE}",
  ["56:7135"] = "TINO: Enhorabuena.\n¡Te has ganado mi\011respeto!{DONE}",
  ["56:7163"] = "TINO: He atrapado\nun SCYTHER,\011pero he perdido.{DONE}",
  ["56:7197"] = "BENITO: El POKéMON\nque has atrapado…\011es impresionante.{DONE}",
  ["56:71c4"] = "BENITO: Es más\nfácil ganar con\012un POKéMON bicho\nde nivel alto.\012Pero creo que\ntambién cuentan\011otros aspectos.{DONE}",
  ["56:7232"] = "CINDY: ¿Ganaste?\n¡Qué bien!\012¿Te apetece buscar\nPOKéMON bicho\011conmigo?{DONE}",
  ["56:727f"] = "CINDY: ¡Adoro\nlos POKéMON bicho!{DONE}",
  ["56:729f"] = "KAI: ¡No…!\nNo me puedo creer\011que haya perdido.{DONE}",
  ["56:72d0"] = "KAI: ¡Dicen que\nalguien ha ganado\011con un CATERPIE!{DONE}",
  ["56:7302"] = "SAMUEL: La próxima\nvez ganaré yo.{DONE}",
  ["56:7327"] = "SAMUEL: Vaya,\ncreí que obtendría\011más puntos…{DONE}",
  ["56:7356"] = "KOLDO: ¿Me das\nalgún consejo?\012Quiero estudiar\ntu estilo.{DONE}",
  ["56:7396"] = "KOLDO: He\nestudiado mucho,\012pero eso no vale\npara ganar.{DONE}",
  ["56:74dd"] = "¡Vaya…! Tu MOCHILA\nestá llena.\012Guardaremos\ntu premio, pero\011sólo hoy.\012Haz sitio en ella\ny ven a verme.{DONE}",
  ["56:754c"] = "¿{PLAYER}?\012Aquí tienes el\npremio que te\011guardábamos.{DONE}",
  ["57:4122"] = "¡Hola! Soy BLANCA.\012¡Todos jugaban a\nPOKéMON, así\011que yo también!\012¡Los POKéMON son\nmuy monos!\012¿Quieres luchar?\n¡Te lo advierto!\011¡Soy muy buena!{DONE}",
  ["57:41a5"] = "¡Ayy…!\012¡Uaaaaaaa!\n¡Eres malo!\012¡No deberías ser\ntan serio! ¡Sí,\011tú, niño, tú!{DONE}",
  ["57:41f5"] = "¡Uaaaaa!\012¡Uaaaaa!\012¡Buaa, buaa…!\n¡Eres malo!{DONE}",
  ["57:4223"] = "¡Sniff…!\012¿Qué quieres?\n¿Una MEDALLA?\012¡Ah, sí! Se me\nolvidaba. Toma la\011MEDALLA PLANICIE.{DONE}",
  ["57:4278"] = "{PLAYER}\nrecibió la\011MEDALLA PLANICIE.{DONE}",
  ["57:4290"] = "Con MED. PLANICIE\nlos POKéMON\012podrán usar FUERZA\nfuera del combate.\012Además, aumentará\nla VELOCIDAD de\011tus POKéMON.\012¡Ah, toma esto\ntambién!{DONE}",
  ["57:4307"] = "¡Es ATRACCIÓN!\nUtiliza todo el\012encanto de un\nPOKéMON.\012¿No es perfecto\npara una monada\011como yo?{DONE}",
  ["57:4365"] = "¡Ah, ha estado\nmuy bien!\012¡Vuelve cuando\nquieras! ¡Adiós!{DONE}",
  ["57:43a0"] = "¡No creas que será\nfácil vencerme!{DONE}",
  ["57:43bb"] = "¡Vaya…! Pensaba\nque eras débil…{DONE}",
  ["57:43db"] = "En el mundo de los\nPOKéMON, ¿quién\012es más fuerte: el\nmacho o la hembra?{DONE}",
  ["57:441b"] = "Prefiero un\nPOKéMON mono a\011un POKéMON fuerte.\012¡Mis POKéMON son\nmonos y fuertes!{DONE}",
  ["57:4469"] = "¡Oh, no, no, no!{DONE}",
  ["57:447a"] = "Intento vencer a\nBLANCA, pero…\011es deprimente.\012¡De acuerdo! ¡Si\npierdo, volveré\012a intentarlo\notra vez!{DONE}",
  ["57:44de"] = "¡Oh, no! Has hecho\nllorar a BLANCA.\012¡No te preocupes!\nPronto dejará de\012llorar. Siempre\nllora si pierde.{DONE}",
  ["57:4537"] = "¡Eres muy\ngracioso! ¡Me\012gustas! ¡Pero\nno me rendiré!{DONE}",
  ["57:457e"] = "Veamos… ¡Uups!\n¿Ya está?{DONE}",
  ["57:4599"] = "¡Uau! ¡Debes de\nser muy bueno para\012haberme ganado!\n¡Adelante!{DONE}",
  ["57:45c8"] = "¡Hazlo lo mejor\nque puedas o\011acabaré contigo!{DONE}",
  ["57:45f7"] = "¡No! ¡Oh, MEOWTH,\nlo siento mucho!{DONE}",
  ["57:4615"] = "Le había enseñado\na MEOWTH todo tipo\011de ataques…{DONE}",
  ["57:4644"] = "¡Hola, futuro\ncampeón!\012Este GIMNASIO es\npara entrenadores\012que usan POKéMON\nde tipo normal.\012Te recomiendo usar\nlos POKéMON de\011tipo lucha.{DONE}",
  ["57:46b1"] = "¿Has ganado?\n¡Genial! Yo estaba\012ocupado mirando\na las chicas.{DONE}",
  ["57:4791"] = "(Suspiro…)\nMe trasladé aquí,\012pero no vendo mis\nBICIS. ¿Por qué?\012¿Montarías en una\nBICI para hacerme\011publicidad?{DONE}",
  ["57:4802"] = "¿De verdad? ¡Bien!\012Dime tu nombre y\nnúmero de teléfono\012y te prestaré\nuna BICI.{DONE}",
  ["57:4852"] = "{PLAYER} tomó\nprestada una BICI.{DONE}",
  ["57:4869"] = "¡Mis BICIS son de\ngran calidad!\012Puedes usarlas en\ncualquier lugar.{DONE}",
  ["57:48a2"] = "(Suspiro…)\n¡Oh, por el amor\011de Dios…!{DONE}",
  ["57:48f7"] = "¡Es una BICI\nnovísima!{DONE}",
  ["57:49ad"] = "Si tratas bien a\ntus POKéMON,\012ellos te\nquerrán.\012¿Eh? Déjame ver\ntu {STRBUF}…{DONE}",
  ["57:4a06"] = "¡Parece muy feliz!\nTe debe de\011querer mucho.{DONE}",
  ["57:4a36"] = "Me parece que\nconfía mucho\011en ti.{DONE}",
  ["57:4a64"] = "Es cariñoso\ncontigo. Parece\011feliz.{DONE}",
  ["57:4a98"] = "Es bastante mono.{DONE}",
  ["57:4aa9"] = "Deberías tratarlo\nmejor. No está\011acostumbrado a ti.{DONE}",
  ["57:4adb"] = "Da la impresión de\nque no le gustas.\011Parece malvado.{DONE}",
  ["57:4b0e"] = "No dejo de perder\nen los combates y\012mis POKéMON acaban\ndesmayándose…\012Quizá sea ésa la\nrazón por la que\011no les gusto…{DONE}",
  ["57:4b71"] = "¡Si uso un objeto\ncon mi POKéMON,\011se pone contento!{DONE}",
  ["57:4c7e"] = "BILL: ¡Hola,\n{PLAYER}! Haznos\012un favor y acepta\neste EEVEE.\012Apareció cuando\najustaba la\011CÁPSULA de TIEMPO.\012Alguien tiene que\ncuidarlo y a mí\011no me gusta salir.\012¿Puedo confiar en\nti para jugar con\011él, {PLAYER}?{DONE}",
  ["57:4d49"] = "BILL: ¡Lo sabía!\n¡Ahí te lo dejo,\012héroe! ¡Eres\ngenial, tío!\012Vale, confío en\ntí. Cuídalo\011bien.{DONE}",
  ["57:4db5"] = "¡{PLAYER}\nrecibió\011a EEVEE!{DONE}",
  ["57:4dc8"] = "BILL: ELM dice que\nEEVEE evoluciona\012en formas nuevas\ny desconocidas.{DONE}",
  ["57:4e09"] = "No, espera. No\npuedes llevar\011más POKéMON.{DONE}",
  ["57:4e34"] = "¡Oh…! ¿Qué\nhacer ahora?{DONE}",
  ["57:4e49"] = "BILL: Solía\nexperimentar con\011un TELETRANSPORTE.\012Debería\nprofundizar más.{DONE}",
  ["57:4e93"] = "¡Oh! ¿Coleccionas\nPOKéMON? Mi hijo\012BILL es un\nexperto.\012Pero ha tenido\nque ir al CENTRO\012POKéMON de\nCIUDAD IRIS.{DONE}",
  ["57:4efa"] = "Qué alegría me\nda volver a ver\011a mi hijo.{DONE}",
  ["57:4f1d"] = "¿Eres entrenador?\012Tengo un número\nde teléfono que\011te será útil.{DONE}",
  ["57:4f58"] = "{PLAYER} grabó\nel número de BILL.{DONE}",
  ["57:4f72"] = "Mi hermano creó\nel sistema de\012almacenamiento de\nPOKéMON del PC.\012Te iba a dar el\nteléfono de\011BILL…{DONE}",
  ["57:4fc5"] = "No puedes grabar\nningún número más.{DONE}",
  ["57:4fe8"] = "Mi hermano BILL\ncreó el sistema\012de almacenamiento\nde los POKéMON.{DONE}",
  ["57:50d7"] = "El tren no ha\nllegado…\012¡Tengo una idea!\n¡Llevaré a cuestas\011a los pasajeros!\012Aunque no creo\nque funcione.{DONE}",
  ["57:512e"] = "Pronto saldremos\npara C. AZAFRÁN.\012¿Quiere\nsubir?{DONE}",
  ["57:5164"] = "Por favor, ¿puedo\nver su PASE?\012Vale. Pase por\naquí, señor.{DONE}",
  ["57:51a0"] = "Lo siento, pero\nno tiene PASE.{DONE}",
  ["57:51c3"] = "Siempre a su\nservicio.{DONE}",
  ["57:51de"] = "Hemos llegado a\nCIUDAD TRIGAL.\012Siempre a su\nservicio.{DONE}",
  ["57:5217"] = "Soy el PRESIDENTE.\012Mi sueño era crear\nun tren que fuera\012más rápido que\ncualquier POKéMON.\012Hace que JOHTO\nesté mucho más\011cerca de KANTO.{DONE}",
  ["57:5311"] = "¡Oh! ¡Eres mejor\nque BLANCA!\012¿Conoces ese árbol\nque se mueve?\012Si lo mojas con\nuna REGADERA,\011ataca.\012Pero como tienes\nalgunas MEDALLAS,\011no te pasará nada.{DONE}",
  ["57:53b6"] = "Lalala lalalala.\n¡Échale mucha\011agua, cariño!{DONE}",
  ["57:53e9"] = "¡Cuando regué ese\nárbol que se movía\012en la RUTA 36, dio\nun salto!\012Creo que se trata\nde un POKéMON.\012Pero sólo alguien\ncomo nuestra LÍDER\012de GIM., BLANCA,\npodría vencerle.{DONE}",
  ["57:5485"] = "¿Conoces ese árbol\nque se mueve?\012Si lo riegas,\n¡da un salto\011de sorpresa!{DONE}",
  ["57:5513"] = "El COLISEO del\npiso de arriba del\012CENTRO POKéMON es\npara conectarse.\012Los récords de los\ncombates están en\012la pared. No puedo\npermitirme perder.{DONE}",
  ["57:5597"] = "Me pregunto\ncuántos tipos de\012POKéMON hay en\nel mundo.\012Hace tres años, el\nPROF. OAK dijo que\012había 150 tipos\ndistintos.{DONE}",
  ["57:5614"] = "Un POKéMON de\nnivel superior no\011siempre gana.\012Aún así, su tipo\npuede tener alguna\011desventaja.\012No creo que haya\nun único POKéMON\012que sea el más\nfuerte.{DONE}",
  ["57:56fe"] = "Un día estaba\nluchando y mis\012POKéMON no se\npodían mover.\012Sus movimientos no\ntenían ningún\012PUNTO de PODER,\no PP.{DONE}",
  ["57:576f"] = "A veces, un\nPOKéMON sano\012no puede usar\nsus movimientos.\012Si ocurre esto,\ncúralo en el\012CENTRO POKéMON,\no usa un objeto.{DONE}",
  ["57:5a38"] = "Bienvenido al\nCENTRO COMERCIAL\011de CIUDAD TRIGAL\n{DONE}",
  ["57:5a5c"] = "El CENTRO\nCOMERCIAL tiene\011buenos artículos.\012Pero algunos\nobjetos sólo se\012consiguen en\nel CASINO.{DONE}",
  ["57:5abf"] = "¡Me encanta\nir de compras!{DONE}",
  ["57:5adf"] = "Mamá es experta\nen gangas.\012Siempre compra\ncosas a precios\011más bajos.{DONE}",
  ["57:5b25"] = "PB INFORMACIÓN\012P1 TIENDA DE\n   ENTRENADORES\012P2 ARTÍCULOS DE\n   COMBATE\012P3 BOTIQUÍN\012P4 TIENDA DE MT\012P5 ÚLTIMO PISO{DONE}",
  ["57:5cb7"] = "El POKéGEAR puede\nalmacenar hasta\011diez números.\012Es difícil decidir\nqué numeros debes\011guardar.{DONE}",
  ["57:5d0d"] = "Conseguí mi ABRA\nen el CASINO.\012Ahora es mi mejor\ncompañero.{DONE}",
  ["57:5d49"] = "Este CENTRO\nCOMERCIAL indica\012que CIUDAD TRIGAL\nes muy grande.\012Su gama de\nproductos no\011tiene rival.{DONE}",
  ["57:5dba"] = "Tu Compañero\nde Viaje\012P1 TIENDA DE\n   ENTRENADORES{DONE}",
  ["57:5e5e"] = "¡Estoy muy\ninquieto!\012Uso VELOCIDAD X\npara acelerar\011a mis POKéMON.{DONE}",
  ["57:5ea7"] = "¡Eh! ¿Utilizas\nESPECIAL X cuando\011luchas?\012¡Es increíble!\n¡Aumenta las\012características\nESPECIALES!{DONE}",
  ["57:5f09"] = "Para los amantes\nde la victoria\012P2 COLECCIÓN\n   DE COMBATE{DONE}",
  ["57:5f9d"] = "Me encantan los\nPOKéMON fuertes.\012Les doy PROTEÍNAS\npara mejorar su\011ATAQUE.{DONE}",
  ["57:5fe7"] = "El HIERRO mejora\nsu DEFENSA.{DONE}",
  ["57:6009"] = "Algunos POKéMON\nsólo evolucionan\012al intercambiarlos\ncon el Game Link.\012Por ejemplo:\nMACHOKE, KADABRA,\012HAUNTER y\nGRAVELER.\012Dicen que hay\notros también.{DONE}",
  ["57:60a2"] = "¡Curamos a\ntus POKéMON!\012P3 BOTIQUÍN{DONE}",
  ["57:61d8"] = "Hola. ¡Oh, tus\nPOKéMON…!{DONE}",
  ["57:61ef"] = "Están muy unidos\na ti.\012Este movimiento\nsería perfecto\011para vosotros.{DONE}",
  ["57:623b"] = "¡Son adorables!\012Enséñales unas\nbuenas MT.{DONE}",
  ["57:626d"] = "Parece malvado.\n¿Qué te parece\011esta MT para él?{DONE}",
  ["57:6297"] = "Seguro que hay\nMT que serían\012perfectas para\ntus POKéMON.{DONE}",
  ["57:62d6"] = "REGALO MISTERIOSO.\012Con un simple\nbeep, recibes\012un regalo. Búscalo\nen el menú.{DONE}",
  ["57:630e"] = "La opción REGALO\nMISTERIOSO es para\011Game Boy Color.{DONE}",
  ["57:6342"] = "Los domingos viene\nuna señora a\011examinar POKéMON.\012¡Regala\nhasta las MT!{DONE}",
  ["57:6388"] = "No puedes cambiar\nel nombre de un\012POKéMON que has\nintercambiado.\012El nombre refleja\nlos sentimientos\012del entrenador\noriginal.{DONE}",
  ["57:63f9"] = "Personaliza a tus\nPOKéMON\012P4 TIENDA DE MT{DONE}",
  ["57:6560"] = "¡Una máquina\nexpendedora!{DONE}",
  ["57:6584"] = "¡Clang! ¡Salió\nuna lata de\011{STRBUF}!{DONE}",
  ["57:65a7"] = "¡Uups! No tienes\nbastante dinero.{DONE}",
  ["57:65c0"] = "No hay sitio\npara nada más.{DONE}",
  ["57:65e0"] = "¿Escuchas el CANAL\nde la SUERTE?\012Si quieres ganar,\ncambia POKéMON\012con mucha gente\npara conseguir\011muchos números ID.{DONE}",
  ["57:665f"] = "Si estás cansado,\nprueba las bebidas\011de las máquinas.\012A tus POKéMON\nles gustarán.{DONE}",
  ["57:66af"] = "¡Tómate un\nrespiro!\012P5 ÚLTIMO PISO{DONE}",
  ["57:6ab5"] = "¡Bienvenido!\012¡Aquí cambiamos\ntus fichas por\011premios fabulosos!{DONE}",
  ["57:6af0"] = "¿Qué premio\nquieres?{DONE}",
  ["57:6b0d"] = "{STRBUF}.\n¿De acuerdo?{DONE}",
  ["57:6b22"] = "¡Aquí tienes!{DONE}",
  ["57:6b30"] = "¡Vaya! ¡Necesitas\nmás fichas!{DONE}",
  ["57:6b4d"] = "Lo siento. No\ntienes más sitio.{DONE}",
  ["57:6b6e"] = "Vale. ¡Guarda tus\nfichas y vuelve\011cuando quieras!{DONE}",
  ["57:6b9a"] = "¡Vaya! No tienes\nun MONEDERO.{DONE}",
  ["57:6bba"] = "Yo siempre juego\nen esta máquina.\012Gano más fichas\nque en otras.{DONE}",
  ["57:6c03"] = "Me encanta esta\nnueva tragaperras.\012Es más difícil\nque las de\011CIUDAD AZULONA.{DONE}",
  ["57:6c59"] = "Vivir es un juego,\ny yo jugaré hasta\011que no pueda más.{DONE}",
  ["57:6c90"] = "Las cartas…\012Las prefiero a las\ntragaperras porque\012son más fáciles\nde acertar.\012Pero se gana\nmucho menos.{DONE}",
  ["57:6cfc"] = "¡No pararé hasta\nque gane!{DONE}",
  ["57:6d16"] = "Enseñé VENTISCA a\nmi POKéMON.\012Ha sido difícil\nganar bastantes\012fichas pero ha\nmerecido la pena.{DONE}",
  ["57:6d72"] = "No gané en las\ntragaperras y\012lo perdí todo en\nlas cartas…\012Me enfadé tanto\nque tiré mi\012MONEDERO al\nSUBTERRÁNEO.{DONE}",
  ["57:6f2c"] = "El ENCINAR es muy\ngrande. ¡Cuidado!\011No te pierdas.{DONE}",
  ["57:6f5c"] = "El ENCINAR está\nvigilado por su\011guardián.\012¡No hagas\nnada malo!{DONE}",
  ["57:6ffe"] = "¿Estás completando\nuna POKéDEX?\012Sería duro si los\nPOKéMON no\012aparecieran.\nPrueba esta MT.{DONE}",
  ["57:7057"] = "Es DULCE AROMA.\012Úsala siempre que\naparezcan POKéMON.\012Atraerá a los\nPOKéMON.{DONE}",
  ["57:70a2"] = "BUTTERFREE: ¡Free!{DONE}",
  ["57:70b6"] = "¿Has visto el\nsantuario en honor\011del guardián?\012Protege el\nBOSQUE desde\011antaño.\012Creo que debe\nde ser un POKéMON\011del tipo planta.{DONE}",
  ["57:71b8"] = "El abuelo te\nestaba buscando.{DONE}",
  ["59:400b"] = "Soy el GURÚ\nPESCADOR, el mayor\012de los HERMANOS\nPESCADORES.\012¿Conoces al\nPESCADOR DAVID?\012Pesca en la\nRUTA 44.\012Me contó un truco\nsorprendente\011por teléfono.\012Gracias a él,\natrapé muchos\012POKéMON raros.\n¡Menudo día aquél!{DONE}",
  ["59:40fa"] = "Es una foto de\ngente pescando…\012Lo están pasando\nmuy bien…{DONE}",
  ["59:4177"] = "Hay un POKéMON\ndormido delante de\011la CUEVA DIGLETT.\012¡El momento ideal\npara atraparlo!\012¿Pero cómo\ndespertarlo?{DONE}",
  ["59:41ef"] = "Antes había un\nPOKéMON durmiendo\012delante de la\nCUEVA de DIGLETT.\012Pero parece que\nha desaparecido.{DONE}",
  ["59:4255"] = "El FERRY es un\nbuen lugar para\012conocer y luchar\ncon entrenadores.{DONE}",
  ["59:4292"] = "Tienes algunas\nMEDALLAS que no\011había visto nunca.\012¡Claro! Las has\nganado en JOHTO.{DONE}",
  ["59:43d8"] = "Soy el PRESIDENTE\ndel CLUB de FANS\011de POKéMON.\012He curado a más\nde 150 POKéMON.\012Soy muy exigente\ncuando se trata de\011POKéMON.\012¿Has venido\npara saber\011de mis POKéMON?{DONE}",
  ["59:4468"] = "¡Muy bien!\n¡Pues escucha!\012Mi… preferido\nes RAPIDASH…\012Es… gracioso…\ncariñoso… veloz\011e increíble…\011¿No crees…? Es\011sorprendente…\011simpático…\011¡Y lo quiero!\012Si lo abrazas…\ncuando duerme…\011es tan cálido…\011y mimoso… Es\011espectacular…\011encantador…\011¡Uuups! ¡Mira qué\011hora es! ¡Hablo\011demasiado!{DONE}",
  ["59:4594"] = "¡Gracias por\nescucharme!\011¡Toma esto!{DONE}",
  ["59:45c9"] = "Es un CARAMELORARO\nque fortalece a\011los POKéMON.\012Prefiero que mis\nPOKéMON luchen\012para fortalecerse.\n¡Así que toma!{DONE}",
  ["59:4637"] = "¡Hola, {PLAYER}!\012¿Has vuelto para\nsaber más cosas\011sobre mis POKéMON?\012¿No? Pues tengo\nmás historias…{DONE}",
  ["59:468f"] = "¡Qué pena…!\012¡Vuelve cuando\nquieras!{DONE}",
  ["59:46c4"] = "Al PRESIDENTE\nle encanta hablar\012cuando se trata de\nPOKéMON…{DONE}",
  ["59:46f7"] = "Me encanta el\nmodo en que\012CLEFAIRY mueve el\ndedo para usar\012METRÓNOMO. ¡Es\ntan adorable!{DONE}",
  ["59:4756"] = "Me gusta CLEFAIRY,\npero jamás podría\012atrapar uno.\nPor eso me\012conformo con este\nPOKé MUÑECO\011que he encontrado.{DONE}",
  ["59:47b1"] = "¡Ah, entiendo! La\nniña que perdió el\012POKé MUÑECO\nestá triste…\012Vale. ¿Podrías\ndevolverle este\012POKé MUÑECO a\nesa pobre niña?\012Un día me haré\namigo de un\012CLEFAIRY real.\n¡No te preocupes!{DONE}",
  ["59:4861"] = "{PLAYER} recibió\nPOKé MUÑECO.{DONE}",
  ["59:4875"] = "¡Ya verás! Voy\na hacerme amigo\012de un auténtico\nCLEFAIRY.{DONE}",
  ["59:48af"] = "Tu MOCHILA está\nrepleta.{DONE}",
  ["59:48ca"] = "¡Mira mi precioso\nBAYLEEF!\012¡Lleva una hoja\ntan mona!{DONE}",
  ["59:4908"] = "¡Es un CLEFAIRY!\n¿Verdad?\012¡No! Es un\nPOKé MUÑECO\011CLEFAIRY.{DONE}",
  ["59:4940"] = "BAYLEEF: ¡Li liif!{DONE}",
  ["59:4953"] = "Escuchemos\natentamente a\011los entrenadores.{DONE}",
  ["59:4980"] = "Si alguno alardea,\nhazlo tú también.{DONE}",
  ["59:4a17"] = "¿Has oído hablar\ndel MAGNETOTRÉN?\012Es un tren que\nva hasta CIUDAD\011TRIGAL, en JOHTO.{DONE}",
  ["59:4a6d"] = "Quiero ir a CIUDAD\nAZAFRÁN para ver\011el MAGNETOTRÉN.{DONE}",
  ["59:4ae2"] = "El TEAM ROCKET ya\nno está en KANTO.\012Eso hace que\nme sienta mejor.{DONE}",
  ["59:4b21"] = "Estoy pensando en\nir a comprar a\011CIUDAD AZAFRÁN.{DONE}",
  ["59:4b8b"] = "Durante años,\nDIGLETT ha estado\012excavando un gran\ntúnel.\012El túnel lleva a\nuna ciudad lejana.{DONE}",
  ["59:4c99"] = "SURGE: ¡Oye,\nchaval!\012Lo reconozco.\nPuede que no seas\012tan listo como\npara retirarte,\012¡pero eres\nvaliente!\012¡En cuanto a\nlos POKéMON\012eléctricos, soy\nel número uno!\012Nunca he perdido\nen combate.\012¡Acabaré contigo,\ntal y como hice\012con mis enemigos\nen la guerra!{DONE}",
  ["59:4d8a"] = "SURGE: ¡Arrrgh!\n¡Eres muy fuerte!\012¡Muy bien! ¡Toma\nla MEDALLA TRUENO!{DONE}",
  ["59:4dc9"] = "{PLAYER} recibió\nla MEDALLA TRUENO.{DONE}",
  ["59:4de3"] = "SURGE: La MEDALLA\nTRUENO aumenta la\012velocidad de los\nPOKéMON.\012Te la mereces por\nhaberme vencido.\012Llévala con\norgullo, ¿me oyes?{DONE}",
  ["59:4e55"] = "SURGE: ¡Hola,\nchaval! ¿Aún\012luchando y\nresoplando?\012¡Mis POKéMON y yo\nseguimos en ello!{DONE}",
  ["59:4ea8"] = "¿Vienes a derrotar\nal LT. SURGE?\012¡No, si yo\npuedo impedirlo!{DONE}",
  ["59:4ede"] = "¡Cuánto siento\nhaberle fallado,\011LT. SURGE!{DONE}",
  ["59:4f02"] = "Cuando aún estaba\nen el ejército, el\012LT. SURGE me salvó\nla vida.{DONE}",
  ["59:4f3a"] = "El LT. SURGE\nreconoció mi\012potencial con\nlos POKéMON\011eléctricos.\012¿Crees que puedes\nvencerme?{DONE}",
  ["59:4f89"] = "¡Ooh! ¡Increíble!{DONE}",
  ["59:4f9d"] = "Si funcionaran las\ntrampas del\012GIMNASIO, no lo\nhabrías logrado.{DONE}",
  ["59:4fd9"] = "¡Voy a acabar\ncontigo! ¡Vas\011a echar chispas!{DONE}",
  ["59:500c"] = "¡Vaya! Me has\nvencido…{DONE}",
  ["59:5028"] = "No te relajes\npor haberme\012vencido… LT.\nSURGE es fuerte.{DONE}",
  ["59:5069"] = "¡Hola, futuro\nCAMPEÓN!\012Esta vez no\ntendrás tanta\011suerte.\012El LT. SURGE es\nmuy prudente. Ha\012puesto trampas por\ntodo el GIMNASIO.\012Pero (risas),\nlas trampas no\011están activadas.\012Te será fácil\nencontrar al\011LT. SURGE.{DONE}",
  ["59:5131"] = "¡Vaya combate más\nelectrizante!\012¡Me has puesto\nmuy nervioso!{DONE}",
  ["59:5170"] = "¡Bah! Aquí sólo\nhay basura.{DONE}",
  ["59:5250"] = "¡Bienvenido a\nCIUDAD AZAFRÁN,\012hogar del\nMAGNETOTRÉN!\012Eso es lo que\nsuelo decir, pero\012el MAGNETOTRÉN no\nfunciona ahora.\012No recibe\nelectricidad\012porque hay un\nproblema en la\012CENTRAL de\nENERGÍA.{DONE}",
  ["59:531d"] = "El MAGNETOTRÉN\nes lo más\012famoso de\nCIUDAD AZAFRÁN.{DONE}",
  ["59:53bb"] = "¡Hola!\012ROJO lleva fuera\nmucho tiempo.\012Tampoco ha\nllamado, así que\012no sé dónde está,\nni lo que ha\011estado haciendo.\012Dicen que si no\nhay noticias es\012que todo va bien,\npero estoy\011preocupada por él.{DONE}",
  ["59:547c"] = "Me preocupa que\nROJO esté herido o\012enfermo, pero es\nun chico. Estoy\012orgullosa de que\nesté haciendo\012lo que quiere.{DONE}",
  ["59:54e3"] = "Tienen programas\nque no se emiten\011en JOHTO…{DONE}",
  ["59:554b"] = "{PLAYER} jugó\na la N64.\012Mejor irse. No hay\ntiempo que perder.{DONE}",
  ["59:5582"] = "Parece que nadie\nlo ha usado en\011mucho tiempo…{DONE}",
  ["59:562b"] = "DALIA: ¡Hola! Mi\nhermano es LÍDER\012del GIMNASIO de\nCIUDAD VERDE.\012Pero sale tanto de\nla ciudad que trae\012problemas a los\nentrenadores.{DONE}",
  ["59:56b1"] = "DALIA: ¡Llegas\na tiempo! Iba a\011tomar un té.\012¿Quieres\ntomarte uno?\012Tus POKéMON están\nun poco sucios.\012¿Quieres que\nlimpie a uno?{DONE}",
  ["59:573f"] = "DALIA: ¿Qué\nPOKéMON limpio?{DONE}",
  ["59:5761"] = "DALIA: Vale, haré\nque mejore su\011aspecto enseguida.{DONE}",
  ["59:5791"] = "{STRBUF}\nparece contento.{DONE}",
  ["59:57a5"] = "DALIA: ¡Ya está!\n¡Listo!\012¿Qué? ¿Tiene buen\naspecto o no?\012¡Qué POKéMON\nmás mono!{DONE}",
  ["59:57f5"] = "DALIA: Siempre\ntomo té a esta\012hora. Ven cuando\nquieras.{DONE}",
  ["59:582f"] = "DALIA: ¿No quieres\nque te limpie un\012POKéMON? Vale, tan\nsólo tomaremos té.{DONE}",
  ["59:5872"] = "DALIA: Lo siento.\nNo puedo\011limpiar un HUEVO.{DONE}",
  ["59:5922"] = "OAK: ¡Ah, {PLAYER}!\nMe alegro de\012que hayas venido\nhasta KANTO.\012¿Qué opinas de los\nentrenadores que\012hay por aquí? Son\nfuertes, ¿verdad?{DONE}",
  ["59:599d"] = "¿Qué tal va tu\nPOKéDEX?\012Veamos…{DONE}",
  ["59:59c3"] = "Si pasas por aquí,\nespero que vengas\011a visitarme.{DONE}",
  ["59:59f7"] = "OAK: ¡Uau!\n¡Excelente!\012Has conseguido las\nMEDALLAS de todos\012los GIMNASIOS de\nKANTO. ¡Muy bien!\012Sabía que\neras bueno.\012¿Sabes qué,\n{PLAYER}? Arreglaré\012todo para que\npuedas ir a MONTE\011PLATEADO.\012MONTE PLATEADO es\nuna gran montaña\012llena de\nPOKéMON salvajes.\012Es muy peligroso\npara un entrenador\012normal, así que\nestá prohibido ir.\012Pero en tu caso,\n{PLAYER}, haremos\011una excepción.\012Sube hasta la\nMESETA AÑIL. Desde\012allí puedes llegar\na MONTE PLATEADO.{DONE}",
  ["59:5b9d"] = "OAK: ¿Cómo? ¿No\nhas conseguido las\011MEDALLAS DE KANTO?\012Los LÍDERES de los\nGIMNASIOS de KANTO\012son tan fuertes\ncomo los de JOHTO.\012Te aconsejo que\nte enfrentes a\011ellos.{DONE}",
  ["59:5c37"] = "OAK: ¿Quieres\nconseguir las\011MEDALLAS DE KANTO?\012No será fácil,\npero la\012experiencia\ntambién cuenta.\012Ven a verme cuando\nlas tengas todas.\011Te haré un regalo.\012¡Sigue así,\n{PLAYER}!{DONE}",
  ["59:5cf6"] = "El programa de\nla HORA POKéMON\012del PROF. OAK\nno se emite aquí,\011en KANTO.\012¡Qué pena! ¡Me\ngustaría oírlo!{DONE}",
  ["59:5d54"] = "Gracias a tu\ntrabajo en la\012POKéDEX, la\ninvestigación del\011PROF. ha avanzado.{DONE}",
  ["59:5da2"] = "No se lo digas a\nnadie, pero la\012HORA DE OAK\nno es en directo.{DONE}",
  ["59:5de5"] = "Pulsa START para\nacceder al MENÚ.{DONE}",
  ["59:5e04"] = "La opción GUARDAR\nestá en el MENÚ.\012Utilízala con\nfrecuencia.{DONE}",
  ["59:5e40"] = "Aquí no hay\nnada…{DONE}",
  ["59:5e59"] = "Hay un nuevo\ne-mail en el PC.\012…\012PROF. OAK,\n¿cómo van sus\011investigaciones?\012Yo no paro\nde estudiar.\012Dicen que\n{PLAYER} se está\011haciendo famoso.\012Me alegra mucho\noirlo.\012ELM, desde PUEBLO\nPRIMAVERA.{DONE}",
  ["5a:400f"] = "¡NIDORAN, agítate!{DONE}",
  ["5a:4020"] = "NIDORAN: ¡Nidoo!{DONE}",
  ["5a:40cb"] = "BROCK: ¡Uau! No\ntodos los días\012nos desafía\nalguien de JOHTO.\012Soy BROCK, LÍDER\ndel GIM. de C.\012PLATEADA y experto\nen POKéMON roca.\012Mis POKéMON son\ninsensibles a la\012mayoría de ataques\nfísicos. Te será\012muy difícil\nhacerles daño.\012¡Venga!{DONE}",
  ["5a:41b6"] = "BROCK: Mi dura\ndefensa no soportó\012los ataques de\ntus POKéMON…\012Eres más fuerte de\nlo que pensaba…\012Toma. Coge\nesta MEDALLA.{DONE}",
  ["5a:4238"] = "{PLAYER} recibió\nla MEDALLA ROCA.{DONE}",
  ["5a:4252"] = "BROCK: Gracias,\n{PLAYER}. Me gustó\012luchar contigo,\naunque estoy un\011poco triste.\012La MEDALLA ROCA\nhará que tus\012POKéMON sean aún\nmás fuertes.{DONE}",
  ["5a:42d5"] = "BROCK: El mundo es\nenorme. Hay muchos\012entrenadores tan\nfuertes como tú.\012Espera y verás.\nYo también me voy\012a hacer más\nfuerte.{DONE}",
  ["5a:435d"] = "Los entrenadores\nde este GIMNASIO\011usan POKéMON roca.\012Los de roca tienen\nmayor DEFENSA.\012Los combates\npueden durar mucho\012tiempo. ¿Estás\npreparado?{DONE}",
  ["5a:43ec"] = "Tengo que ganar\nestos combates…{DONE}",
  ["5a:440a"] = "¡Eh, tú! ¡Chico\nde JOHTO! BROCK\012es muy duro. Te\ncastigará si no\012le tomas en\nserio.{DONE}",
  ["5a:4469"] = "¡Eh, futuro\nCAMPEÓN! Eres\012realmente temible.\n¿Vas a enfrentarte\012a los LÍDERES DE\nGIMNASIO de KANTO?\012Son fuertes y\nentregados, igual\012que los LÍDERES de\nGIMNASIO de JOHTO.{DONE}",
  ["5a:4502"] = "¡Hola, futuro\nCAMPEÓN! Este\012GIMNASIO no te\nha costado mucho.\012Tu forma de atacar\nha sido realmente\012increíble. Lo\ndigo en serio.{DONE}",
  ["5a:45d3"] = "¡Hola! ¡Mira mi\nGYARADOS!\012Procede de un\nMAGIKARP. No me\012puedo creer lo\nfuerte que es.{DONE}",
  ["5a:4635"] = "Había una vez\nun anciano muy\012raro que vendía\nMAGIKARP.\012Decía que\nlos MAGIKARP del\012LAGO DE LA FURIA\neran excelentes.{DONE}",
  ["5a:46fc"] = "¡Sí! Ya no hay\nGIMNASIO en la\012ISLA CANELA. Me\nquedé de piedra.\012¿Sí? Estoy al\nteléfono. ¡Fuera!{DONE}",
  ["5a:4758"] = "JIGGLYPUFF: Puff,\npuff.{DONE}",
  ["5a:4770"] = "Casi todos los\nPOKéMON se duermen\012al oír cantar a\nJIGGLYPUFF.\012Cuando un POKéMON\nestá dormido sólo\012se pueden usar\nciertos ataques.{DONE}",
  ["5a:485a"] = "Me gusta dormirme\ncon la radio en…\011¡Zzzz…!{DONE}",
  ["5a:4a24"] = "En la LIGA\nPOKéMON, serás\012puesto a prueba\npor el ALTO MANDO.\012Deberás vencerlos\na todos. ¡Si\012pierdes, volverás\na empezar!{DONE}",
  ["5a:4aa1"] = "Espera.\012¿Te vas a\nenfrentar ahora\012al desafío de la\nLIGA POKéMON?\012Pues yo no\nlo creo.\012Mis POKéMON\nestán muy bien\012entrenados y van a\nacabar contigo.\012¡{PLAYER}!\n¡Te desafío!{DONE}",
  ["5a:4b41"] = "…\012Vale. He perdido.{DONE}",
  ["5a:4b50"] = "¡Maldición…!\nSigo sin ganar…\012Yo… Tengo que\npensar más en mis\011POKéMON…\012¡Umm! ¡Procura\nno perder!{DONE}",
  ["5a:4ba9"] = "…\012¡Uau…!\nCon ayuda de mis\012compañeros, ¡voy a\nser el CAMPEÓN!{DONE}",
  ["5a:4be1"] = "¿Qué? ¿Vas a\ndesafiar al ALTO\012MANDO? ¿Seguro que\nestás preparado?\012Si necesitas\nentrenarte más, mi\012ABRA te puede\nayudar.\012ABRA te puede\nTELETRANSPORTAR.\012¿Te gustaría\nvolver a casa?{DONE}",
  ["5a:4c93"] = "Vale. Concéntrate\nen la imagen\011de tu casa…{DONE}",
  ["5a:4cbd"] = "Vale, vale. ¡Que\ntengas suerte!{DONE}",
  ["5a:4cdf"] = "ABRA: Aabra…{DONE}",
  ["5a:4ddd"] = "Bienvenido a la\nLIGA POKéMON.\012Permíteme que me\npresente. Me llamo\011MENTO.\012Me he entrenado\npor todo el mundo\012para mejorar a mis\nPOKéMON psíquicos.\012Y, por fin, me han\naceptado en el\011ALTO MANDO.\012¡Sólo puedo seguir\nmejorando!\012¡Es imposible\nque pierda!{DONE}",
  ["5a:4ed8"] = "No… Esto es…\nincreíble…{DONE}",
  ["5a:4ef0"] = "Aunque haya\nperdido, no\012cambiaré mis\nplanes.\012¡Seguiré luchando\nhasta ser el mejor\012de todos los\nentrenadores!\012Y ahora {PLAYER},\nexperimenta toda\012la fuerza del\nALTO MANDO.{DONE}",
  ["5a:503f"] = "¡Ja, ja, ja!\012Soy KOGA, del ALTO\nMANDO. Vivo en las\012sombras, como un\nninja.\012¡Te confundiré y\nte destruiré con\011mi estilo!\012Confusión, sueño,\nveneno…\012¡Prepárate para\nser víctima de\011mis técnicas!\012¡Ja, ja, ja!\012Los POKéMON no\nutilizan sólo\012la fuerza bruta.\n¡Ya lo verás!{DONE}",
  ["5a:5155"] = "¡Ah! ¡Has\ndemostrado\011tu valor!{DONE}",
  ["5a:5176"] = "He probado\ncontigo todo\011lo que sé.\012Pero he fallado.\nDebería\011entrenarme más.\012¡Entra en la\nsala siguiente,\012y demuestra tus\nhabilidades!{DONE}",
  ["5a:52aa"] = "Soy BRUNO, del\nALTO MANDO.\012Entreno siempre al\nmáximo porque\012confío en nuestro\npotencial.\012Por eso somos\ntan fuertes.\012¿Resistirás\nnuestro poder?\012¿Mmm? No veo que\ntengas miedo.\012Pareces decidido.\n¡Perfecto!\012¿Listo, {PLAYER}?\n¡Te doblegarás\012ante nuestro\ninmenso poder!\012¡Ja, ja!{DONE}",
  ["5a:53cf"] = "¿Qué? ¿Cómo hemos\npodido perder?{DONE}",
  ["5a:53e8"] = "Como he perdido,\nno tengo derecho\011a decir nada…\012¡Enfréntate al\nsiguiente desafío!{DONE}",
  ["5a:54d3"] = "Soy KAREN, del\nALTO MANDO.\012¿Eres {PLAYER}?\n¡Qué gracia!\012Me gustan los\nPOKéMON de tipo\011siniestro.\012Su naturaleza tan\nfuerte y salvaje\012me parece muy\natractiva.\012¿Crees que podrás\ndetenerlos? ¡A ver\011que tal lo haces!\012¡Vamos allá!{DONE}",
  ["5a:55a4"] = "Eres bueno…\nMe gusta eso\011en un entrenador.{DONE}",
  ["5a:55d5"] = "POKéMON fuertes.\012POKéMON débiles.\012Ésa es la visión\negoísta que tiene\011todo el mundo.\012Si un entrenador\nes bueno, debería\012ser capaz de ganar\ncon sus favoritos.\012Me gusta tu\nestilo. Sabes\011lo que importa.\012Adelante. El\nCAMPEÓN te espera.{DONE}",
  ["5a:5816"] = "LANCE: Te estaba\nesperando.\012¡{PLAYER}!\012Sabía que con tus\nhabilidades serías\012capaz de llegar\nhasta mí.\012No es necesario\ndecir nada más.\012Lucharemos para\nsaber quién es el\012más fuerte de\nlos dos.\012Como entrenador\nmás poderoso y\012CAMPEÓN de la LIGA\nPOKéMON…\012¡Yo, LANCE, el\nmaestro de los\012dragones, acepto\ntu desafío!{DONE}",
  ["5a:5953"] = "Se acabó…\012Pero es\nextraño.\012No estoy enfadado\npor perder. De\012hecho, estoy\ncontento.\012Estoy contento por\nhaber presenciado\012el nacimiento de\nun nuevo CAMPEÓN.{DONE}",
  ["5a:59e1"] = "¡Uauu…!\012Te has vuelto muy\npoderoso,\011{PLAYER}.\012Tus POKéMON han\nrespondido bien a\012tu fuerza y\ndecisión.\012Como entrenador,\nseguirás creciendo\012fuerte con\ntus POKéMON.{DONE}",
  ["5a:5a8c"] = "ROSA: ¡Oh, no!\n¡Todo ha acabado!\012PROF. OAK, si no\nfuera tan lento.{DONE}",
  ["5a:5aca"] = "PROF. OAK: ¡Ah,\n{PLAYER}! ¡Cuánto\012tiempo sin\nverte!\012Pareces más\nmaduro.\012¡Tu victoria en\nla LIGA ha sido\011fantástica!\012Y todo gracias a\ntu dedicación,\012confianza y amor\npor los POKéMON.\012Tus POKéMON son\ngeniales.\012Confían en ti\ncomo entrenador\012y no se rinden\nnunca.\012¡Enhorabuena,\n{PLAYER}!{DONE}",
  ["5a:5bf6"] = "ROSA: ¡Vamos a\nentrevistar al\011nuevo CAMPEÓN!{DONE}",
  ["5a:5c26"] = "LANCE: Aquí va a\nempezar a haber\011mucho ruido…\012{PLAYER}, ¿puedes\nvenir conmigo?{DONE}",
  ["5a:5c70"] = "ROSA: ¡Espera!\n¡No hemos hecho\011la entrevista!{DONE}",
  ["5a:5d51"] = "LANCE: Ha pasado\nmucho tiempo desde\012la última vez que\nvine aquí.\012Aquí rendimos\nhomenaje a los\012CAMPEONES de la\nLIGA, eternamente.\012Y admitimos\na sus valientes\011POKéMON.\012Hoy hemos\npresenciado el\012nacimiento de un\nnuevo CAMPEÓN\012de la LIGA. Un\nentrenador\012compasivo,\nque confía en\011sus POKéMON.\012Un entrenador que\nha ganado gracias\012a su constancia y\ndeterminación.\012¡Un nuevo CAMPEÓN\nde la LIGA que\012ha demostrado\nsu grandeza!\012{PLAYER}, permíteme\nregistrarte a ti y\012a tus compañeros\ncomo CAMPEONES.{DONE}",
  ["5b:41b3"] = "El barco va a\nzarpar. Por favor,\011suba a bordo.{DONE}",
  ["5b:41de"] = "Lo siento. No\npuedes embarcar.{DONE}",
  ["5b:41fa"] = "Bienvenido al\nFERRY S.S. AQUA.\012¿Vas a embarcar\nhoy?{DONE}",
  ["5b:4238"] = "¿Puedo ver tu\nTICKET BARCO?{DONE}",
  ["5b:4259"] = "¡Esperamos volver\na verte!{DONE}",
  ["5b:4274"] = "{PLAYER} enseña\nel TICKET BARCO.\012Muy bien.\n¡Gracias, señor!{DONE}",
  ["5b:42a9"] = "{PLAYER} intentó\nenseñar el TICKET\011BARCO…\012¡Pero no lo tiene!\012¡Lo siento!\nSólo puedes subir\012si tienes un\nTICKET BARCO.{DONE}",
  ["5b:4310"] = "El FERRY zarpará\nel próximo lunes.{DONE}",
  ["5b:4336"] = "El FERRY zarpará\nel viernes.{DONE}",
  ["5b:435c"] = "Aquí es fácil\natrapar SHELLDER.\012En otros sitios\nson raros.{DONE}",
  ["5b:439d"] = "¿Cuántas CAÑAS\ntienes?\012Las distintas\nCAÑAS sirven para\012atrapar distintos\nPOKéMON.{DONE}",
  ["5b:43de"] = "¡El S.S. AQUA usa\npropulsores para\011surcar las olas!{DONE}",
  ["5b:440a"] = "En KANTO hay\nmuchos POKéMON.\012¡Ojalá pudiera ir!{DONE}",
  ["5b:443f"] = "No queremos que te\ncaigas al mar\012y por eso no\npuedes entrar.{DONE}",
  ["5b:466e"] = "El barco va a\nzarpar. Por favor,\011sube a bordo.{DONE}",
  ["5b:4699"] = "Lo siento. No\npuedes embarcar.{DONE}",
  ["5b:46b5"] = "Bienvenido al\nFERRY S.S. AQUA.\012¿Vas a embarcar\nhoy?{DONE}",
  ["5b:46f3"] = "¿Puedo ver tu\nTICKET BARCO?{DONE}",
  ["5b:4714"] = "¡Esperamos volver\na verte!{DONE}",
  ["5b:472f"] = "{PLAYER} enseñó\nel TICKET BARCO.\012Muy bien.\n¡Gracias, señor!{DONE}",
  ["5b:4764"] = "{PLAYER} intenta\nenseñar el TICKET\011BARCO…\012¡Pero no lo tiene!\012¡Lo siento!\nSólo puedes subir\012si tienes un\nTICKET BARCO.{DONE}",
  ["5b:47cb"] = "El FERRY zarpará\nel miércoles.{DONE}",
  ["5b:47f2"] = "El FERRY zarpará\nel domingo.{DONE}",
  ["5b:4818"] = "¿Vienes de\nJOHTO?\012Dicen que allí\nviven muchos\011POKéMON raros.{DONE}",
  ["5b:49ad"] = "El FERRY S.S. AQUA\nse dirige a\011CIUDAD CARMÍN.\012Daremos un\naviso cuando\011lleguemos.{DONE}",
  ["5b:4a0d"] = "El FERRY S.S. AQUA\nse dirige a\011CIUDAD OLIVO.\012Daremos un\naviso cuando\011lleguemos.{DONE}",
  ["5b:4a6b"] = "Éste es tu\ncamarote.\012Si están heridos\ntus POKéMON,\012échate una\nsiestecita.\012Eso los curará.{DONE}",
  ["5b:4ac1"] = "Es tu camarote.\012Puedes curar a tus\nPOKéMON durmiendo\011una siesta.\012El barco llegará\na su destino\011mientras duermes.{DONE}",
  ["5b:4b32"] = "Los pasajeros son\nentrenadores.\012Están deseando\nluchar en sus\011camarotes.{DONE}",
  ["5b:4b84"] = "¡Uau!\012Disculpa, hijo.\n¡Tenía prisa!\012¡Mi nieta ha\ndesaparecido!\012Es muy pequeña.\nSi la ves, por\012favor, avísame.\n{DONE}",
  ["5b:4c04"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD OLIVO.{DONE}",
  ["5b:4c35"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.{DONE}",
  ["5b:4dba"] = "Voy a KANTO a\nponerme a prueba.{DONE}",
  ["5b:4de0"] = "¡Quería ganar!{DONE}",
  ["5b:4df2"] = "Los entrenadores\nde JOHTO pueden\012luchar contra los\nLÍDERES de KANTO.{DONE}",
  ["5b:4e2a"] = "¡Me entreno para\nser la CAMPEONA!{DONE}",
  ["5b:4e4c"] = "¿En qué somos\ntan diferentes?{DONE}",
  ["5b:4e6e"] = "¡Te ganaré un\ndía de éstos!{DONE}",
  ["5b:4e8d"] = "¿Conoces a LILA?\nEs una DJ muy\011buena de KANTO.{DONE}",
  ["5b:4eb8"] = "¡Yaaaa!{DONE}",
  ["5b:4ec2"] = "LILA es buena pero\nROSA es la mejor.\012¡Me encantaría\nescuchar las\011emisoras de JOHTO!{DONE}",
  ["5b:4f0e"] = "¿Estás solo?\n¡Pues luchemos!{DONE}",
  ["5b:4f30"] = "¡Es demasiado!\n{DONE}",
  ["5b:4f4b"] = "Me pregunto si en\nKANTO habrá\012montañas que valga\nla pena escalar.{DONE}",
  ["5b:4f89"] = "Sí, es verdad,\nsoy un marinero.\012¡No hacía\nnada malo!\012Como el camarote\nestaba vacío, me\011eché un sueñecito.\012¡Ah! ¡Olvídalo!\n¡Luchemos!{DONE}",
  ["5b:500e"] = "¡Lo siento! ¡Todo\nes culpa mía!{DONE}",
  ["5b:5028"] = "Los marineros\nhacemos mucho\012trabajo físico.\n¡Es agotador!{DONE}",
  ["5b:5068"] = "¡Oh, no! He\nperdido algo\011muy importante.{DONE}",
  ["5b:509a"] = "No… No lo\nencuentro…{DONE}",
  ["5b:50ae"] = "Me rindo. Hijo, no\ntienes por qué\012buscarlo.\n¡Olvídalo!{DONE}",
  ["5b:50ec"] = "¡Yujuu!\n¡Qué suerte!{DONE}",
  ["5b:50fc"] = "¡Qué mala suerte!\n¡He perdido!{DONE}",
  ["5b:5112"] = "He encontrado una\nmoneda muy bonita.\012Alguien debe de\nhaberla perdido…{DONE}",
  ["5b:5270"] = "¡Voy a KANTO para\nactuar en un\012espectáculo de\ncomefuegos!{DONE}",
  ["5b:52a4"] = "La débil llama\npierde fuerza.{DONE}",
  ["5b:52be"] = "El fuego es débil\ncontra el agua.\012No te importa,\n¿verdad?{DONE}",
  ["5b:52fa"] = "¡Voy a ver a mi\nabuela para que me\012atrape unos\ncuantos bichos!{DONE}",
  ["5b:5329"] = "¡Ooh! ¡Uau!\n¡Qué duro eres!{DONE}",
  ["5b:5347"] = "Encontrarás muchos\nPOKéMON en los\011árboles de JOHTO.{DONE}",
  ["5b:5379"] = "Intento olvidar a\nmis enemigos.\011¡Luchemos!{DONE}",
  ["5b:53a4"] = "Estoy desolada…{DONE}",
  ["5b:53b5"] = "Lo mejor para\ncurar las penas\012es hacer un\nviaje en barco.\012Pero los viajes\nen FERRY son\012demasiado\ncortos.{DONE}",
  ["5b:5418"] = "Voy a una audición\nde mis canciones\012en la EMISORA de\nCIUDAD TRIGAL.{DONE}",
  ["5b:5456"] = "¡Uauu!\n¡Distorsión total!{DONE}",
  ["5b:5470"] = "Hablando de la\nEMISORA, ¿cuál es\012n° de la suerte\nde esta semana?{DONE}",
  ["5b:54af"] = "¡Una buena cama!\nA dormir…{DONE}",
  ["5b:54cc"] = "¡Ah! Me siento\ncomo nuevo.{DONE}",
  ["5b:54e9"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD OLIVO.{DONE}",
  ["5b:551a"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.{DONE}",
  ["5b:570e"] = "¡Ah! Gracias por\nvenir.\012Estoy agotado\nde entretener\011a esa niña.{DONE}",
  ["5b:5760"] = "¿Te gusta viajar\nen el S.S. AQUA?\012Prácticamente\nvuela por encima\011de las olas.{DONE}",
  ["5b:57aa"] = "Hola, hijo…\nNo encuentro\011a mi nieta.\012Si está en el\nbarco, no hay\012problema. Pero,\n¿y si se ha\011caído al mar?\012Es muy revoltosa.\nPodría estar\012molestando. Estoy\npreocupado…{DONE}",
  ["5b:585a"] = "{PLAYER}, ¿verdad?\nMe han dicho que\012has entretenido a\nmi nieta.\012Quiero darte\nlas gracias.{DONE}",
  ["5b:58b2"] = "¡Me gustaría que\ntuvieras esto!{DONE}",
  ["5b:58d5"] = "Estamos viajando\npor todo el mundo.{DONE}",
  ["5b:58f7"] = "CAPITÁN, venga,\njuegue conmigo.\012¡Me aburro! Quiero\njugar más.{DONE}",
  ["5b:5936"] = "¡Hola! ¿Quieres\njugar conmigo?\012¿Qué…?\012¿Que mi abuelo\nestá preocupado?\012¡Debería irme!\012¡Tengo que buscar\nal abuelo!{DONE}",
  ["5b:599b"] = "¡Hola, abuelo!\nEstaba jugando\012con el CAPITÁN y\neste chico.{DONE}",
  ["5b:59dd"] = "¡Me he divertido\nmucho jugando!{DONE}",
  ["5b:59f9"] = "¡Hola, hijo!\n¿Quieres luchar?{DONE}",
  ["5b:5a1c"] = "¡Eres fuerte!{DONE}",
  ["5b:5a2b"] = "¿Viajas\nsolo?\012¿Tu madre no está\npreocupada?{DONE}",
  ["5b:5a5e"] = "¿Crees que soy\nuna nena?\011¡No es justo!{DONE}",
  ["5b:5a84"] = "¡Oh! ¡Perdimos!{DONE}",
  ["5b:5a92"] = "¡No deberías\nllamar nenas a\011las chicas!{DONE}",
  ["5b:5ab9"] = "¡No soy una nena!\012¡Y no deberías\nllamar así a\012una dama!{DONE}",
  ["5b:5aea"] = "¡Oh! ¡Perdimos!{DONE}",
  ["5b:5af8"] = "A veces, los niños\nson más listos que\011los adultos.{DONE}",
  ["5b:5b25"] = "¡Ssh! ¡Mi cerebro\nestá captando\011señales de radio!{DONE}",
  ["5b:5b51"] = "¡Escucho\nalgo…!{DONE}",
  ["5b:5b67"] = "Entiendo. Puedes\noír la radio de\011JOHTO en el FERRY.{DONE}",
  ["5b:5b9e"] = "¿Qué opinas? Mis\nPOKéMON son\011bonitos, ¿verdad?{DONE}",
  ["5b:5bce"] = "¡Oh, no! ¡Mis\npreciosos POKéMON!{DONE}",
  ["5b:5bec"] = "¡Debo ir a la\nPELUQUERÍA POKéMON\012para ponerlos\nguapos!{DONE}",
  ["5b:5c1f"] = "Me voy de compras\nal C. COMERCIAL\011y luego…{DONE}",
  ["5b:5c4d"] = "¿Qué es lo que\niba a hacer?{DONE}",
  ["5b:5c66"] = "¡Ah, sí! Tengo que\nir a buscar a mis\012POKéMON a la\nGUARDERÍA.{DONE}",
  ["5b:5c97"] = "¿Qué tipos de\nPOKé BALL llevas\011contigo?{DONE}",
  ["5b:5cc4"] = "¡Espera! ¡Detente!\n¡No, por favor!{DONE}",
  ["5b:5cdf"] = "Deberías usar las\nBALL adecuadas\012para cada\nsituación.{DONE}",
  ["5b:5d15"] = "El FERRY S.S. AQUA\nha llegado a\011CIUDAD CARMÍN.{DONE}",
  ["5b:5f4b"] = "¡Eh! ¿Podrías\nbuscar a mi\011compañero?\012¡Está haciendo de\nlas suyas en algún\012sitio! ¡El muy\nvago!\012Me gustaría ir a\nbuscarle, pero\011estoy de servicio.{DONE}",
  ["5b:5fd7"] = "¡Oh…!\012El CAPITÁN se\npondrá furioso…{DONE}",
  ["5b:5ffe"] = "¡Gracias, chico!\n¡Le he echado una\012buena bronca y se\nha tranquilizado!{DONE}",
  ["5b:603d"] = "¿Una niña pequeña?\012Puede que la haya\nvisto por aquí.{DONE}",
  ["5b:606d"] = "El comedor está\nahí delante.\012Las escaleras del\nfondo conducen al\012camarote del\nCAPITÁN.{DONE}",
  ["5b:60bd"] = "No hay nada mejor\nque un combate\012en mi tiempo\nlibre.{DONE}",
  ["5b:60ea"] = "¡Gane o pierda, se\nacabó el descanso!{DONE}",
  ["5b:6108"] = "Supongo que no\nganaré si no me\011lo tomo en serio.{DONE}",
  ["5b:6133"] = "Me aburro tanto.\n¿Quieres luchar?{DONE}",
  ["5b:6151"] = "¡Uau! ¡Eres\ndemasiado fuerte!{DONE}",
  ["5b:6169"] = "AZAFRÁN…\nAZULONA…\012Dicen que hay\nmuchas ciudades\011grandes en KANTO.{DONE}",
  ["5b:61a7"] = "¡Urrf…!\n¡Estoy mareado!{DONE}",
  ["5b:61ba"] = "No me puedo\nmover…{DONE}",
  ["5b:61d2"] = "No vuelvo a ir en\nbarco. La próxima\012vez viajaré en el\nMAGNETOTRÉN.{DONE}",
  ["5b:6210"] = "¡Aquí es donde\ntrabajamos!{DONE}",
  ["5b:6230"] = "He perdido en mi\npropio campo…{DONE}",
  ["5b:624a"] = "Llevamos a muchos\npasajeros desde\012CIUDAD CARMÍN a\nCIUDAD OLIVO.{DONE}",
  ["5b:628c"] = "¡Aunque estemos en\nel mar, no puedo\011pescar!\012¡Qué aburrido!\n¡Luchemos!{DONE}",
  ["5b:62d8"] = "Ya… Ya no\nme aburro…{DONE}",
  ["5b:62f2"] = "Voy a pescar en\nlos muelles de\011CIUDAD CARMÍN.{DONE}",
  ["5b:6317"] = "¡Fortalezco mis\npiernas nadando\012en la estela\ndel barco!{DONE}",
  ["5b:6355"] = "¡Bailemos el Rock\nand Roll!{DONE}",
  ["5b:636e"] = "No pude encontrar\nal REY del KARATE\011en JOHTO.\012Dicen que se está\nentrenando en\011alguna cueva.{DONE}",
  ["5b:63c9"] = "¡Soy marinero!\012Pero entreno\nPOKéMON para\011ser el CAMPEÓN.{DONE}",
  ["5b:640c"] = "Me falta\nentrenamiento…{DONE}",
  ["5b:642f"] = "¡Ocho MEDALLAS!\nEso demuestra que\012has vencido a los\nLÍDERES de GIM.\012¡No me extraña que\nseas tan bueno!{DONE}",
  ["5b:6486"] = "¡No toques a\nmis alumnos!{DONE}",
  ["5b:64a9"] = "¡Aaah!{DONE}",
  ["5b:64b1"] = "Vamos de excursión\na las RUINAS de\012las afueras de\nCIUDAD MALVA.{DONE}",
  ["5b:64e4"] = "¿Conoces las\nRUINAS ALFA?{DONE}",
  ["5b:6504"] = "¡Aarg!{DONE}",
  ["5b:650d"] = "Las radios captan\nseñales extrañas\011en las RUINAS.{DONE}",
  ["5b:653f"] = "En las RUINAS\nALFA hay unas\012extrañas piezas\nde piedra.{DONE}",
  ["5b:6576"] = "¡Estoy agotado!{DONE}",
  ["5b:6586"] = "He leído que hay\ncuatro piezas de\011piedra como ésas.{DONE}",
  ["5b:667f"] = "El FERRY S.S. AQUA\nnavega hasta KANTO\012los lunes y\nlos viernes.{DONE}",
  ["5b:66ed"] = "El FERRY sale\nsiempre los\012miércoles y\nlos domingos.{DONE}",
  ["5b:680b"] = "PLAZA MT. MOON\nNo tirar basura{DONE}",
  ["5b:6882"] = "Cuando el sol se\npone, CLEFAIRY\011sale a jugar.{DONE}",
  ["5b:693b"] = "¡Shaoooh!{DONE}",
  ["5c:400f"] = "Esperaba comprar\nalgunos souvenirs\012en la ZONA SAFARI,\npero está cerrada.{DONE}",
  ["5c:4050"] = "La nieta del\nGUARDA de la ZONA\012SAFARI vive en la\nciudad.{DONE}",
  ["5c:424f"] = "¡Fufufufu…!\012Lo siento\nmucho…\012¡Sólo bromeaba!\012¡Soy la auténtica!\012Soy SACHIKO, del\nGIMNASIO FUCSIA.\011¡La original!{DONE}",
  ["5c:42bb"] = "SACHIKO: Eres un\ntipo duro. ¡Y, sin\011duda, has ganado!\012Aquí tienes la\nMEDALLA ALMA.{DONE}",
  ["5c:4305"] = "{PLAYER} recibió\nla MEDALLA ALMA.{DONE}",
  ["5c:431c"] = "SACHIKO: ¡Eres tan\nfuerte! ¡Tengo un\011regalo para ti!\012Es TÓXICO, un\npotente veneno que\012va agotando los\nPS de la víctima.{DONE}",
  ["5c:438e"] = "SACHIKO: Voy a\nesforzarme por\012mejorar mis\nhabilidades.\012¡Quiero llegar a\nser mejor que mi\011padre y que tú!{DONE}",
  ["5c:4400"] = "¡Fufufu! ¡Soy\nSACHIKO, la LÍDER\011del GIMNASIO!\012¡No, no soy yo!\n¡Qué tonto eres!{DONE}",
  ["5c:4440"] = "Te he engañado…{DONE}",
  ["5c:4453"] = "¿Cómo reconocerás\na la auténtica\011LÍDER?{DONE}",
  ["5c:4480"] = "¡Te he engañado!\n¡Ja ja ja!{DONE}",
  ["5c:4495"] = "¡Oh…! He perdido…\nNo eres débil…{DONE}",
  ["5c:44b3"] = "¿Qué? ¿Mi disfraz\nno era perfecto?{DONE}",
  ["5c:44d5"] = "¡Soy SACHIKO!\012¿Cómo has sabido\nque no era yo?\012¡Luchemos!{DONE}",
  ["5c:450b"] = "¡Maldición!\n¡Quería ganar!{DONE}",
  ["5c:4526"] = "Debes de estar\ncansado.{DONE}",
  ["5c:4542"] = "¡Uajajaja!\012Acertaste, chaval.\n¡Yo soy SACHIKO!{DONE}",
  ["5c:456a"] = "¿A que era bueno\nmi disfraz?{DONE}",
  ["5c:458b"] = "¡Eh, chico!\n¿No era bueno\011mi disfraz?{DONE}",
  ["5c:45ba"] = "¡Hola, futuro\nCAMPEÓN!\012Echa un vistazo a\ntu alrededor.\012Todos los\nentrenadores se\011parecen a SACHIKO.\012¿Cuál será la\nauténtica SACHIKO?{DONE}",
  ["5c:4646"] = "¡Qué bien luchas,\nentrenador\011de JOHTO!{DONE}",
  ["5c:46e4"] = "Mi abuelo está en\ncasa de mi hermano\012BILL, en CABO\nCELESTE.{DONE}",
  ["5c:471a"] = "He visto a unos\nlentos y raros\012POKéMON en el\nCAMINO DE BICIS.{DONE}",
  ["5c:47b5"] = "¡Anda! Tienes un\nnuevo tipo de\011POKéDEX.\012¿Te la ha dado\nel PROF. OAK?{DONE}",
  ["5c:47fd"] = "Me sorprendió\nmucho el GIMNASIO.\012Había tres chicas\nque parecían\011idénticas.{DONE}",
  ["5c:484f"] = "¡Soy SACHIKO!\nAbracadabra…{DONE}",
  ["5c:486f"] = "¿Has visto? ¡Ahora\nsoy como ella!{DONE}",
  ["5c:4907"] = "Mi abuelo es el\nGUARDA de la ZONA\011SAFARI.\012Al menos lo era…\012Decidió irse de\nvacaciones y se\012fue al extranjero\nél solo.\012Así fue como dejó\nde ocuparse de\011la ZONA SAFARI.{DONE}",
  ["5c:49b2"] = "Mucha gente se\nenfadó cuando\012cerraron la ZONA\nSAFARI, pero el\011abuelo es terco.{DONE}",
  ["5c:4a0b"] = "Es una foto de un\nanciano sonriente\012rodeado de\nPOKéMON.{DONE}",
  ["5c:4a47"] = "Es una foto de una\nextensa pradera\012llena de POKéMON\nraros jugando.{DONE}",
  ["5c:4ac2"] = "¿Estás trabajando\nen una POKéDEX?\012Es muy importante.\n¡No te rindas!{DONE}",
  ["5c:4b31"] = "Los entrenadores\nambiciosos escalan\012el MT. PLATEADO a\npesar del peligro.\012Con sus fieles\nPOKéMON, sentirán\012que pueden ir a\ncualquier lado…{DONE}",
  ["5c:4c13"] = "¡Pues vaya!\nMe encontraste.\012Por favor, no se\nlo digas a nadie.\012Te daré esto si\nme guardas el\011secreto. ¿Vale?{DONE}",
  ["5c:4c81"] = "Es muy duro\nser famoso.\012Todo el mundo\nme persigue.\012Sólo quiero que me\ndejen en paz…{DONE}",
  ["5c:4ce3"] = "FEAROW: ¡Fearow!{DONE}",
  ["5c:4fa4"] = "Bienvenido al\nCOLISEO DEL\011CLUB CABLE.\012Aquí puedes luchar\ncontra un amigo.\012¿Quieres\nluchar?{DONE}",
  ["5c:4ffe"] = "Bienvenido al\nCENTRO DE CAMBIO\011DEL CLUB CABLE.\012Aquí puedes\ncambiar POKéMON\011con un amigo.\012¿Quieres cambiar\nPOKéMON?{DONE}",
  ["5c:5068"] = "Bienvenido a la\nCÁPSULA DEL TIEMPO\011DEL CLUB CABLE.\012Puedes viajar al\npasado y cambiar\011tus POKéMON.\012¿Quieres viajar al\npasado?{DONE}",
  ["5c:50e2"] = "Tu amigo no\nestá preparado.{PROMPT}",
  ["5c:50fd"] = "Antes de conectar\nlas consolas,\011guarda el juego.{DONE}",
  ["5c:5130"] = "Espera, por favor.{DONE}",
  ["5c:513e"] = "La conexión se ha\ninterrumpido por\011inactividad.\012Habla con tu\namigo y vuelve\011cuando quieras.{PROMPT}",
  ["5c:519a"] = "Vuelve algún día.{PROMPT}",
  ["5c:51f2"] = "No puedes\nconectarte con\011el pasado aquí.{PROMPT}",
  ["5c:5213"] = "Tu amigo eligió\nuna sala distinta.{PROMPT}",
  ["5c:5238"] = "Entra, por favor.{DONE}",
  ["5c:5258"] = "Perdona. No\npuedes llevar a\011{STRBUF}.{PROMPT}",
  ["5c:5275"] = "No puedes llevar a\n{STRBUF} con\011{STRBUF}.{PROMPT}",
  ["5c:529c"] = "No puedes llevarte\na {STRBUF}\011con la CARTA.{PROMPT}",
  ["5c:52cd"] = "Lo siento. Estamos\narreglando la\011CÁPSULA DE TIEMPO.{DONE}",
  ["5c:52fc"] = "Lo siento. Estamos\najustando la\011MÁQUINA DE CAMBIO.{DONE}",
  ["5c:532c"] = "Lo siento. Estamos\najustando la\011MÁQUINA DE LUCHA.{DONE}",
  ["5c:535d"] = "¡Hola! Tú eres\n{PLAYER}, ¿no?\012¿Quieres recoger\nlo que tengo\011para ti?{DONE}",
  ["5c:5391"] = "¡Aquí tienes!{DONE}",
  ["5c:539f"] = "Esperamos poder\nayudarte de nuevo.{DONE}",
  ["5c:53bc"] = "¡Oh! No tienes\nespacio para esto.\012Para en cualquier\nCENTRO POKéMON\012del país y podrás\nrecogerlo.{DONE}",
  ["5c:541a"] = "¿No? Es muy\nextraño…{DONE}",
  ["5c:553d"] = "Tu amigo está\npreparado.{DONE}",
  ["5c:55be"] = "Tu amigo está\npreparado.{DONE}",
  ["5d:401f"] = "Al norte de\nPUEBLO LAVANDA\012está el TÚNEL\nROCA. Crúzalo\012para llegar a\nla CENTRAL\011de ENERGÍA.{DONE}",
  ["5d:4072"] = "Hay un programa\nde radio que\012pone música de\nPOKé FLAUTA.\012Necesitas una\nTARJETA EXPN para\011sintonizarlo.{DONE}",
  ["5d:40db"] = "La EMISORA no\npuede transmitir\012porque la CENTRAL\nde ENERGÍA no\011funciona.{DONE}",
  ["5d:411e"] = "El DIRECTOR de\nla EMISORA estaba\011muy contento.\012Dijo que han\nvuelto a emitir\012porque la CENTRAL\nde ENERGÍA ya\011funciona.{DONE}",
  ["5d:4222"] = "El SR. FUJI vive\naquí, pero ahora\011no está en casa.\012Debe de estar en\nel CEMENTERIO.{DONE}",
  ["5d:4271"] = "Algunas personas\nson tan crueles\012que abandonan a\nsus POKéMON.\012El abuelo recoge a\nlos POKéMON que\012no tienen hogar\ny los cuida.{DONE}",
  ["5d:42e7"] = "PSYDUCK: ¿Psyay?{DONE}",
  ["5d:42fa"] = "NIDORINO: ¡Nido!{DONE}",
  ["5d:430b"] = "PIDGEY: ¡Pijji!{DONE}",
  ["5d:437e"] = "El PUEBLO LAVANDA\nes un pequeño y\012apacible lugar,\nal pie de las\011montañas.\012Desde que se\nconstruyó la TORRE\012de RADIO, acude\nalgo más de gente.{DONE}",
  ["5d:445a"] = "Si vas a explorar\nuna cueva, debes\012llevar siempre\nREPELENTE.\012Aunque me gusta la\nexploración, aún\012no he explorado\ntodas las cuevas.{DONE}",
  ["5d:44dd"] = "He oído hablar de\nun artesano que\012fabrica POKé BALL\na medida en PUEBLO\012AZALEA, en JOHTO.\n¡Yo quiero una!{DONE}",
  ["5d:4586"] = "SR. FUJI: ¡Hola!\012¡Mmm…! Parece que\nestás educando a\012tus POKéMON con\nmucho cariño.\012Los amantes de los\nPOKéMON vienen a\012rendir homenaje a\nPOKéMON muertos.\012Por favor, muestra\ntu condolencia por\012las almas POKéMON\nque han partido.\012Seguro que eso\nles hará felices.{DONE}",
  ["5d:4680"] = "Creo que aquí hay\notras tumbas de\011POKéMON.\012Hay muchas cámaras\nen las que sólo\012puede entrar\nel SR. FUJI.{DONE}",
  ["5d:46e4"] = "He venido con mi\nmadre a visitar\012las tumbas de los\nPOKéMON…{DONE}",
  ["5d:470e"] = "A los POKéMON que\nvivían conmigo…\012los quería como a\nmis nietos…{DONE}",
  ["5d:47f2"] = "¡Bienvenido!\nMira por donde\012quieras en este\npiso.{DONE}",
  ["5d:482d"] = "Lo siento, pero\nsólo puedes dar\012una vuelta por la\nplanta baja.\012Desde que una\nbanda criminal\012asaltó la TORRE de\nRADIO, tuvimos\012que incrementar\nnuestra seguridad.{DONE}",
  ["5d:48c3"] = "En la TORRE de\nRADIO hay mucha\012gente que trabaja\nduramente.\012Seguro que están\nhaciendo todo lo\012posible por emitir\nbuenos programas.{DONE}",
  ["5d:492e"] = "¡Oh, no, no, no!\012No hemos emitido\ndesde que cerró la\012CENTRAL de\nENERGÍA.\012Si no emitimos, de\nnada servirá el\012esfuerzo realizado\npor la emisora.\012¡Me arruinaré!{DONE}",
  ["5d:49d4"] = "¿Eres tú\n{PLAYER}? ¿El que\012arregló la CENTRAL\nde ENERGÍA?\012Gracias a ti, no\nperdí mi empleo.\012¡Sin duda, tú eres\nmi salvador!\012Toma esto como\nagradecimiento.{DONE}",
  ["5d:4a74"] = "Con eso podrás\nsintonizar los\012programas de\nradio de KANTO.\012¡Jajajaja!{DONE}",
  ["5d:4ac6"] = "¡Oye, tío!\012¡Soy el DIRECTOR\nde MÚSICA!\012¡Vaya! Tu POKéGEAR\nno sintoniza mis\012programas de\nmúsica. ¡Qué pena!\012Si consigues una\nTARJETA EXPN, los\012podrás oír. ¡Hazte\ncon una!{DONE}",
  ["5d:4b83"] = "¡Oye, tío!\012¡Soy el DIRECTOR\nde MÚSICA!\012Soy el encargado\nde las fantásticas\012melodías que se\nemiten aquí.\012No seas anticuado.\n¡Atrapa la música\011de las ondas!{DONE}",
  ["5d:4c26"] = "PB RECEPCIÓN\nP1 VENTAS\011P2 PERSONAL\011P3 PRODUCCIÓN\011P4 DESPACHO DEL\011   DIRECTOR{DONE}",
  ["5d:4c70"] = "Anima a los POKé-\nMON con la melodía\012de la POKé FLAUTA\ndel CANAL 20{DONE}",
  ["5d:4d5c"] = "¿Has estado en\nPUEBLO LAVANDA?\012Hay una TORRE\nde RADIO muy alta.{DONE}",
  ["5d:4df2"] = "Soy el hermano\npequeño del GURÚ\011PESCADOR.\012Veo que te gusta\npescar. ¡No\012tengo ninguna\nduda!\012Sé que tengo\nrazón.{DONE}",
  ["5d:4e72"] = "Sí, sí. ¡Justo lo\nque pensaba!\012¡Aquí tienes!\nToma esto. Es\011una SÚPER CAÑA.{DONE}",
  ["5d:4ebf"] = "Intenta pescar\nallí donde veas\011agua.\012Recuerda: puedes\ncapturar POKéMON\012diferentes usando\ndistintas CAÑAS.{DONE}",
  ["5d:4f2f"] = "¿Eh? ¿Me engañan\nmis ojos?{DONE}",
  ["5d:4ff8"] = "¡Estoy alucinado!\012Vino un chico\nde tu edad, de\012pelo largo y\nmirada penetrante.\012¡Y me obligó a\ndarle mis\011queridos POKéMON!\012Todavía me queda\nuno, ¿pero qué\011hago si vuelve?\012Pareces fuerte.\n¿Podrías cuidar\012de mi POKéMON\nun rato?{DONE}",
  ["5d:50e2"] = "¡Oh, gracias!\012¡Cuídale bien,\npor favor!{DONE}",
  ["5d:5110"] = "{PLAYER} recibió\nun POKéMON.{DONE}",
  ["5d:5124"] = "No puedes llevar\nmás POKéMON.{DONE}",
  ["5d:513e"] = "¡Oh, no…!\n¿Y qué hago\011si vuelve?{DONE}",
  ["5d:5165"] = "¡Hola! ¿Cómo está\nmi POKéMON?\012Creo que ya\npasó el peligro.\011¿Me lo devuelves?{DONE}",
  ["5d:51a6"] = "¡Gracias!{DONE}",
  ["5d:51b2"] = "¡Oye! ¡No llevas\na mi POKéMON\011contigo!{DONE}",
  ["5d:51d8"] = "Mi POKéMON te\nha tomado cariño.\012¡Vale! ¡Quédatelo,\npero prométeme\012que serás bueno\ncon él!{DONE}",
  ["5d:5234"] = "¡Oh, no, no…!\nEs como si me\011hubieran robado.{DONE}",
  ["5d:5261"] = "Para los POKéMON,\nla felicidad es\012estar con quien\nlos quiere.{DONE}",
  ["5d:53ee"] = "¡UAUUUU!\012¡Has llegado\nhasta aquí!\012¡Que sepas que\nsoy muy fuerte!\012¡Mis POKéMON\naplastarán piedras\011y romperán huesos!\012¡Atento!{DONE}",
  ["5d:5464"] = "ANÍBAL: ¡Urgg!\n¡Urgg…!\012¡Oooarrg!{DONE}",
  ["5d:547f"] = "¿Qué? Ahora tienes\nmiedo, ¿no?\012¿Qué? ¿No tiene\nnada que ver con\012los POKéMON?\n¡Es cierto!\012Venga.\n¡Luchemos!{DONE}",
  ["5d:54eb"] = "¿Qué? ¿Cómo?\n¿He perdido?\012¡Muy bien!\n¡Te mereces la\011MEDALLA TORMENTA!{DONE}",
  ["5d:552a"] = "{PLAYER}\nrecibió la\011MEDALLA TORMENTA.{DONE}",
  ["5d:5542"] = "Con MED. TORMENTA,\nte obedecerán los\012POKéMON hasta\nel nivel 70.\012Y permitirá a\ntus POKéMON usar\012VUELO cuando no\nestén luchando.\012¡Toma esto\ntambién!{DONE}",
  ["5d:55cf"] = "Se trata de\nPUÑODINÁMICO.\012¡No siempre golpea\npero cuando lo\012hace produce\nconfusión!{DONE}",
  ["5d:5625"] = "¡UAJAJAA! ¡Ha sido\nmuy divertido!\012¡Pero una derrota\nes una derrota!\012¡Desde ahora, voy\na entrenar 24\011horas al día!{DONE}",
  ["5d:568c"] = "A mis POKéMON y\na mí nos une una\011gran amistad.\012¡Nuestro vínculo\nnunca se romperá!{DONE}",
  ["5d:56de"] = "¡No puede ser!{DONE}",
  ["5d:56ef"] = "¡Parece que tú y\ntus POKéMON estáis\011muy unidos!{DONE}",
  ["5d:5723"] = "¡Los expertos en\nartes marciales no\011tememos a nada!{DONE}",
  ["5d:5745"] = "¡Es increíble!{DONE}",
  ["5d:5756"] = "Los POKéMON de\nlucha temen a los\011psíquicos…{DONE}",
  ["5d:577f"] = "Las palabras no\nsirven. ¡Deja que\011hablen tus puños!{DONE}",
  ["5d:57b2"] = "…{DONE}",
  ["5d:57b5"] = "¡He perdido!\n¡No sé qué decir!{DONE}",
  ["5d:57ce"] = "¡Mis furiosos\npuños destrozarán\011a tus POKéMON!{DONE}",
  ["5d:57f7"] = "¡Me has aplastado!{DONE}",
  ["5d:5809"] = "¡Mis POKéMON han\nperdido! Has\011herido mi orgullo.{DONE}",
  ["5d:58dd"] = "¿Conoces al\nPOKéMANÍACO?\012Siempre está\npresumiendo de sus\011raros POKéMON.{DONE}",
  ["5d:5923"] = "Los entrenadores\nde este GIMNASIO\011son muy peleones.\012Si me quedo, puede\nque vengan\011a por mí.\012Éste es mi\nconsejo: el LÍDER\012del GIMNASIO usa\nPOKéMON de lucha.\012Para confundirle\nutiliza POKéMON\011psíquicos.\012Debilita a sus\nPOKéMON antes de\012que puedan usar\nla fuerza física.{DONE}",
  ["5d:5a2a"] = "¡{PLAYER}! ¡Has\nganado! ¡Con sólo\011mirarte, lo sé!{DONE}",
  ["5d:5ac9"] = "Parece que tus\nPOKéMON están\012bien. ¿Hay algo\nque te preocupa?\012…\012¿El POKéMON del\nFARO tiene\011problemas?\012¡Entendido!\012Esto debería\nayudarte.{DONE}",
  ["5d:5b52"] = "{PLAYER}\nrecibió la\011POCIÓN SECRETA.{DONE}",
  ["5d:5b6c"] = "Mi POCIÓN SECRETA\nes muy potente.\012Sólo la doy en\ncasos de urgencia.{DONE}",
  ["5d:5bf5"] = "Tienes unos\nPOKéMON\011magníficos.\012¿Quieres una foto\nde recuerdo?{DONE}",
  ["5d:5c3e"] = "¡Vale! ¡Sonríe!{DONE}",
  ["5d:5c52"] = "¡Oh! ¡Qué mal!\nPensaba que sería\012un maravilloso\nrecuerdo…{DONE}",
  ["5d:5cb8"] = "¿Vienes de\nCIUDAD OLIVO?\012¿Te acuerdas de\nlas cuatro islas\011del camino?\012Dicen que en\nellas se esconde\012una criatura\nmítica marina.{DONE}",
  ["5d:5d3b"] = "Dicen que sólo\npuedes verla si\012tienes un ALA\nPLATEADA.\012Debe de tener la\nmisma esencia que\011la criatura.{DONE}",
  ["5d:5da5"] = "Los torbellinos\nque rodean las\012islas deben de\nser obra de esa\011criatura.{DONE}",
  ["5e:4011"] = "¡Hola! ¡Bienvenido\nal CENTRO\012COMERCIAL de\nCIUDAD AZULONA!\012El directorio\nestá en la pared.{DONE}",
  ["5e:4057"] = "Este C. COMERCIAL\npertenece a la\012misma cadena que\nel de TRIGAL.\012Los dos fueron\nrenovados al\011mismo tiempo.{DONE}",
  ["5e:40cb"] = "Es la primera vez\nque vengo.\012Es muy grande…\012Me da miedo\nperderme.{DONE}",
  ["5e:410c"] = "PB: INFORMACIÓN\012P1: TIENDA DE\n    ENTRENADORES\012P2: TIENDA DE MT\012P3: REGALOS\012P4: FARMACIA\012P5: MÁQUINAS\n    EXPENDEDORAS{DONE}",
  ["5e:41ed"] = "Hace poco que soy\nentrenador. Mi\012hijo me animó a\nserlo.\012Estoy impresionado\npor la cantidad de\012objetos útiles\nque hay.{DONE}",
  ["5e:4262"] = "A mi padre le está\ncostando aprender\012los nombres de los\nobjetos y cómo se\012supone que debe\nutilizarlos…{DONE}",
  ["5e:42c0"] = "¡Objetos de máxima\ncalidad para\011entrenadores!\012P1: TIENDA DE\n    ENTRENADORES{DONE}",
  ["5e:4377"] = "No sé en qué\nPOKéMON debería\012utilizar esta\nMT…{DONE}",
  ["5e:43aa"] = "¡Oh, oh! Cambié\nmis POKéMON sin\012quitarles la\nMEJORA.{DONE}",
  ["5e:43eb"] = "¡Sí! ¡Ya tengo\nun PORYGON!\012Se me dan muy mal\nlas tragaperras.\012¡Jamás ganaría\nbastantes fichas!\012¿Ehh…?\012¡El PORYGON que he\ncambiado se ha\012convertido en otro\nPOKéMON!{DONE}",
  ["5e:4485"] = "En la TIENDA DE MT\nhay ataques raros.{DONE}",
  ["5e:44a9"] = "P2: TIENDA DE MT\012¡Fortalece a tus\nPOKéMON!{DONE}",
  ["5e:4545"] = "He venido a por\nuna CARTA SURF\011para mi novia.{DONE}",
  ["5e:4579"] = "Éste es el único\nlugar en el que\012encontrarás\nCARTAS AMOR.{DONE}",
  ["5e:45b0"] = "¡Dilo con un\nregalo!\012P3: REGALOS{DONE}",
  ["5e:4647"] = "Quiero comprar\nobjetos que\012aumenten las\nhabilidades de\012mis POKéMON. ¡Pero\nno tengo dinero!{DONE}",
  ["5e:4696"] = "Quiero MÁS PP,\npara aumentar los\012PP de los ataques.\n¡Pero no se vende!{DONE}",
  ["5e:46da"] = "Si usas objetos en\ntus POKéMON, se\011pondrán contentos.\012Sin embargo, odian\nalgunos objetos.{DONE}",
  ["5e:4724"] = "P4: FARMACIA{DONE}",
  ["5e:486c"] = "¡Una máquina\nexpendedora!{DONE}",
  ["5e:4890"] = "¡Clang!\012Salió\n{STRBUF}.{DONE}",
  ["5e:48aa"] = "¡Uups, no tienes\nbastante dinero!{DONE}",
  ["5e:48c3"] = "No hay sitio\npara nada más…{DONE}",
  ["5e:48e3"] = "Una máquina\nexpendedora con\012una ruleta de\npremios…\012Nunca verás\nnada igual.{DONE}",
  ["5e:492c"] = "¡Auu! ¡Aquí no\nhay juegos!\012¡Quería jugar…!{DONE}",
  ["5e:495a"] = "ÚLTIMO PISO\nEXPENDEDORAS{DONE}",
  ["5e:4a32"] = "Mis queridos\nPOKéMON me hacen\012compañía, así que\nnunca estoy sola.\012MEOWTH hasta trae\ndinero a casa.{DONE}",
  ["5e:4a8c"] = "MEOWTH: ¡Meow!{DONE}",
  ["5e:4a9b"] = "CLEFAIRY: ¡Clef\ncleff!{DONE}",
  ["5e:4ab2"] = "NIDORAN: ¡Nido\nnido!{DONE}",
  ["5e:4ac7"] = "DESPACHO DEL JEFE\nDE MANSIÓN AZULONA{DONE}",
  ["5e:4b55"] = "{PLAYER} encendió\nel PC.\012…\012Alguien estaba\nescribiendo\011un e-mail.\012Espero que\nvengas a KANTO.\012Te sorprenderás de\ncuánto han\012cambiado las\ncosas por aquí.\012También verás\nmuchos POKéMON\012que no son nativos\nde JOHTO.\012Al PRODUCTOR\012…{DONE}",
  ["5e:4c48"] = "SALA DE REUNIONES\nDE GAME FREAK{DONE}",
  ["5e:4cea"] = "¡Hola!\012¡Soy el DISEÑADOR\nDEL JUEGO!\012Te costará\ncompletar tu\012POKéDEX, pero\n¡no te rindas!{DONE}",
  ["5e:4d41"] = "¡Uau! ¡Excelente!\n¡Has completado tu\011POKéDEX!\012¡Enhorabuena!{DONE}",
  ["5e:4d7c"] = "…{DONE}",
  ["5e:4d7f"] = "El ARTISTA GRÁFICO\nte imprimirá un\011DIPLOMA.\012Deberías presumir\nde ello.{DONE}",
  ["5e:4dd0"] = "Soy el ARTISTA\nGRÁFICO.\012¡Te he dibujado!{DONE}",
  ["5e:4df4"] = "Soy el ARTISTA\nGRÁFICO.\012¿Has completado\ntu POKéDEX?\012¿Quieres imprimir\ntu DIPLOMA?{DONE}",
  ["5e:4e4c"] = "Avísame si quieres\nque te imprima tu\011DIPLOMA.{DONE}",
  ["5e:4eb1"] = "¿Quién? ¿Yo? Soy\nel PROGRAMADOR.\012¡Juega a las\ntragaperras!{DONE}",
  ["5e:4ee6"] = "¿A que las GEMELAS\nson adorables?\012Y YASMINA también\nes muy guapa.\012¡Me encantan!{DONE}",
  ["5e:4f27"] = "SALA DE DESARROLLO\nDE GAME FREAK{DONE}",
  ["5e:4f44"] = "Es un dibujo\ndetallado de\011una chica guapa.{DONE}",
  ["5e:4f6e"] = "Es el programa\ndel juego. ¡No lo\012toques! ¡Podrías\nestropearlo!{DONE}",
  ["5e:4fb2"] = "Está lleno de\nmaterial de\012referencia: hasta\nun POKé MUÑECO.{DONE}",
  ["5e:50ad"] = "Te contaré una\nhistoria de miedo.{DONE}",
  ["5e:50d0"] = "Pero no te dará\ntanto miedo si\011aún es de día.\012Vuelve cuando\nanochezca, ¿vale?{DONE}",
  ["5e:5129"] = "Érase una vez un\nniño pequeño al\012que le regalaron\nuna BICICLETA…\012Quería probarla\nenseguida…\012Se lo estaba\npasando tan bien\012que olvidó que\nanochecía…\012De vuelta a casa,\nen plena noche,\012¡la bici empezó\na frenarse!\012¡Cada vez era más\ndifícil pedalear!\012Y cuando dejó de\npedalear, ¡la bici\012empezó a moverse\nhacia atrás!\012Era como si la\nbici estuviera\012maldita y él fuera\na desaparecer.\012…\012…\012(¡CHILLIDO!)\012¡Y el niño siguió\nsubiendo por el\011CAMINO de BICIS!\012¡Ba-dum!\n¡Ba-dum ba-dum!\012Por haberme\nescuchado, ¡aquí\011tienes esta MT03!{DONE}",
  ["5e:5339"] = "MT03 es MALDICIÓN.\012Es un terrible\nataque que reduce\012poco a poco los\nPS de la víctima.{DONE}",
  ["5e:53b4"] = "ERIKA es experta\nen POKéMON planta.\012Si no tienes\ncuidado, acabará\011contigo.{DONE}",
  ["5e:5405"] = "El TEAM ROCKET\nestá escondido\012en el sótano del\nCASINO.\012Espera. Eso fue\nhace tres años.{DONE}",
  ["5e:5571"] = "¡Bienvenido!\012Al lado puedes\ncambiar tus\012fichas por\npremios fabulosos.{DONE}",
  ["5e:55b6"] = "Todas las\ntragaperras son de\011última generación.{DONE}",
  ["5e:55e3"] = "Quiero jugar en\nesta máquina.\012Ayer me desplumó,\nasí que hoy\012soltará el\ndinero.{DONE}",
  ["5e:5636"] = "Creo que esta\nmáquina soltará\011el dinero…\012Las posibilidades\nvarían según\011la máquina.{DONE}",
  ["5e:567d"] = "¡Bien!\012¡Las fichas no\ndejan de salir!\012¿Qué, chico?\n¿Quieres jugar?\012¡Compartiré la\nsuerte contigo!{DONE}",
  ["5e:56e6"] = "¡Bien!\012¡Me gusta hacer\nfavores a la\011gente!{DONE}",
  ["5e:572b"] = "¡Eh! No tienes\nningún MONEDERO.\012¿Y cómo te voy a\ndar las fichas,\011chico?{DONE}",
  ["5e:577a"] = "¡Eh! Tu MONEDERO\nestá lleno, chico.\012Tú también debes\nde estar de\011suerte.{DONE}",
  ["5e:57c6"] = "¡Eh! ¡Futuro\nCAMPEÓN!\012¿Tú también juegas\na las tragaperras?\012Quiero conseguir\nbastantes fichas\011para un POKéMON.\012Pero aún no tengo\nbastantes…{DONE}",
  ["5e:584e"] = "¡Mmm…! Los impares\nson mejores para\012la línea PIKACHU.\n¿Qué hago?{DONE}",
  ["5e:5894"] = "¡Eh!\012Debajo de este\npóster…\012¡No hay nada!{DONE}",
  ["5e:58c2"] = "¡Eh!\012Debajo de este\npóster…\012¡No hay nada!{DONE}",
  ["5e:58f0"] = "Aquí hay un\nencendedor.{DONE}",
  ["5e:5908"] = "¡Un refresco!\012Alguien se lo\nhabrá dejado…\012¿Uh? ¡Está vacío!{DONE}",
  ["5e:5c59"] = "Yo quería a\nMR.MIME, pero me\012faltaban 100\nfichas…{DONE}",
  ["5e:5c8a"] = "¡Uauu…!\012Debo permanecer\ntranquilo…\012No puedo perder\nla cabeza o\011perderé todo…{DONE}",
  ["5e:5cdf"] = "¡Bienvenido!\012¡Aquí te cambiamos\ntus fichas por\011premios fabulosos!{DONE}",
  ["5e:5d15"] = "¿Qué premio\nquieres?{DONE}",
  ["5e:5d32"] = "De acuerdo,\n¿{STRBUF}?{DONE}",
  ["5e:5d4e"] = "¡Aquí tienes!{DONE}",
  ["5e:5d5c"] = "No tienes\nbastantes fichas.{DONE}",
  ["5e:5d79"] = "No tienes espacio\nsuficiente.{DONE}",
  ["5e:5d93"] = "¡Vuelve cuando\ntengas fichas!{DONE}",
  ["5e:5db5"] = "¡Vaya! No tienes\nMONEDERO.{DONE}",
  ["5e:5ec9"] = "ERIKA: Hola…\nBonito día,\012¿verdad? Se está\ntan bien…\012Podría hasta\ndormirme…\012Me llamo ERIKA.\nSoy la LÍDER\012del GIMNASIO de\nCIUDAD AZULONA.\012¿Cómo? ¿Vienes\nde JOHTO?\011¡Qué bien…!\012¡Oh! Lo siento,\nno me di cuenta\012de que querías\ndesafiarme.\012Muy bien, pero\nno perderé.{DONE}",
  ["5e:5fdf"] = "ERIKA: ¡Oh! Admito\nque he perdido…\012Eres realmente\nbueno…\012Te daré la MEDALLA\nARCOIRIS…{DONE}",
  ["5e:6037"] = "{PLAYER} recibió\nMEDALLA ARCOIRIS.{DONE}",
  ["5e:6051"] = "ERIKA: Ha sido un\ncombate genial.\012Me has inspirado.\nAcepta esta MT\011como regalo.\012Es GIGA-DRENADO.\012Es un fantástico\nataque que drena\012la mitad del daño\nproducido para\011curar al POKéMON.\012Úsalo si\nquieres…{DONE}",
  ["5e:6130"] = "ERIKA: La derrota\ndeja mal sabor\011de boca…\012Pero saber que\nhay entrenadores\012más fuertes me\nanima a mejorar…{DONE}",
  ["5e:619d"] = "¡Alto! ¡Aquí sólo\npueden entrar\011las chicas!{DONE}",
  ["5e:61c1"] = "¡Oh, maldición!{DONE}",
  ["5e:61cd"] = "No es que no nos\ngusten los chicos.\012Pero hay ciertos\ntemas de los que\012sólo pueden hablar\nlas chicas.{DONE}",
  ["5e:622f"] = "¡Oh! ¿Un combate?\nMe da un poco de\011miedo, pero bueno.{DONE}",
  ["5e:625b"] = "¡Oh! ¿Se acabó?{DONE}",
  ["5e:626a"] = "¡Uauu! ¡Tienes\nmuchas MEDALLAS!\012¡No me extraña\nhaber perdido!{DONE}",
  ["5e:62a1"] = "¿Estabas mirando\nestas flores o\011a mí?{DONE}",
  ["5e:62ce"] = "¡Qué rabia!{DONE}",
  ["5e:62dd"] = "¿Cómo voy a hacer\npara llegar a ser\012tan elegante\ncomo ERIKA?{DONE}",
  ["5e:630e"] = "¡Te enseñaremos\nlos movimientos\012POKéMON que nos\nenseñó ERIKA!{DONE}",
  ["5e:633e"] = "Hemos perdido…{DONE}",
  ["5e:634c"] = "¡ERIKA te lo\nhará pagar!{DONE}",
  ["5e:636d"] = "¡Vamos a proteger\na ERIKA!{DONE}",
  ["5e:638b"] = "No ganamos…{DONE}",
  ["5e:639c"] = "¡ERIKA es mucho,\nmucho más fuerte!{DONE}",
  ["5e:64ba"] = "¡Hola!\012Estamos celebrando\nun concurso\011de tragones.\012Perdona. Ahora no\npodemos atenderte.{DONE}",
  ["5e:6505"] = "¡Ñam, ñam…!{DONE}",
  ["5e:6516"] = "¡No me hables!\012¡Me vas a\ndesconcentrar!{DONE}",
  ["5e:6546"] = "¡Glup…! ¡Ñam…!{DONE}",
  ["5e:6554"] = "¡Mejor cantidad\nque calidad!\012¡Si estoy lleno,\nestoy feliz!{DONE}",
  ["5e:658a"] = "¡Ñam, ñam…!{DONE}",
  ["5e:6599"] = "La comida de aquí\nes buena, pero\012en CIUDAD TRIGAL\nes aún mejor.{DONE}",
  ["5e:65dd"] = "¡Ñam… Ñam…!{DONE}",
  ["5e:65ee"] = "Aquí nadie te va\na dar un MONEDERO.\012Mejor que lo\nbusques en JOHTO.{DONE}",
  ["5e:6630"] = "¡Ñam… ñam…!\012¡Sigo comiendo!{DONE}",
  ["5e:6654"] = "¡Más, JEFE!{DONE}",
  ["5e:6661"] = "¡Concurso de\ntragones! ¡Sin\012tiempo! ¡Una lucha\nsin fin! ¡El mayor\012tragón podrá\ncomer gratis!{DONE}",
  ["5e:66c3"] = "{PLAYER} encontró\n{STRBUF}.{DONE}",
  ["5e:66d5"] = "Pero {PLAYER} no\ntiene espacio…{DONE}",
  ["5e:6757"] = "Si bajas por el\nCAMINO BICIS,\012llegarás a\nCIUDAD FUCSIA.{DONE}",
  ["5e:67e6"] = "Aquí empieza el\nCAMINO BICIS.\012Es todo cuesta\nabajo. Es muy\011emocionante.\012Es una sensación\nque no se\012experimenta en\nbarco o en tren.{DONE}",
  ["5e:6874"] = "¡Eh! ¡Alto!\012No puedes pasar\npor el CAMINO\012BICIS si no vas\nen BICICLETA.{DONE}",
  ["5e:690a"] = "¿Has oído lo del\naccidente de la\011CENTRAL ENERGÍA?\012Se encuentra al\nEste, cerca de\011PUEBLO LAVANDA.{DONE}",
  ["5e:6970"] = "Me tomo muy en\nserio mi trabajo\011de GUARDA.\012¡Eh! Tienes una\nPOKéDEX.\012Vale. Puedes\npasar.{DONE}",
  ["5e:6a0a"] = "CAMINO BICIS\nA partir de aquí,\011es cuesta arriba.{DONE}",
  ["5e:6a2b"] = "¡Alto! ¿No tienes\nuna BICI?\012Aquí empieza el\nCAMINO BICIS.\012Necesitas una\nBICI para seguir.{DONE}",
  ["5f:4057"] = "AZUL: Bien. Por\nfin aquí, ¿no?\012En ISLA CANELA no\nestaba de humor,\012pero ahora estoy\nlisto para luchar.\012…\012¿Dices que has\nganado en todos\012los GIMNASIOS de\nJOHTO?\012¡Bah! Pues los\nGIMNASIOS de JOHTO\012deben de ser\npatéticos.\012Pero, ¡no más\npalabras!\012Sabré si eres\nbueno o no\012luchando contra\nti, ahora mismo.\012¿Preparado, chico?{DONE}",
  ["5f:4188"] = "AZUL: ¿Qué?\012¿Cómo diablos he\nperdido?\012…\012¡Está bien…!\nToma, aquí tienes\011la MEDALLA TIERRA.{DONE}",
  ["5f:41e9"] = "{PLAYER} recibió\nla MEDALLA TIERRA.{DONE}",
  ["5f:4201"] = "AZUL: …\012De acuerdo, me he\nequivocado. Tenías\012razón. Eres un\nbuen entrenador.\012Pero algún día\nte derrotaré.\012¡No lo\nolvides!{DONE}",
  ["5f:4285"] = "AZUL: Escucha.\012Será mejor que no\npierdas hasta que\012yo te derrote.\n¿Entendido?{DONE}",
  ["5f:42c8"] = "¡Hola, futuro\nCAMPEÓN! ¿Qué\012tal te va?\nParece que estás\011de suerte.\012El LÍDER DEL\nGIMNASIO luchó\012contra el CAMPEÓN\nhace 3 años.\012¡Es un tipo duro!\012¡Debes esforzarte\nal máximo!{DONE}",
  ["5f:437a"] = "Tío, eres\nrealmente duro…\012¡Qué batalla más\nemocionante!\012Me ha hecho\nllorar.{DONE}",
  ["5f:442e"] = "¿Dedicas mucho\ntiempo a pensar\012en nombres para\ntus POKéMON?\012Es más divertido\nintercambiarlos\012si les pones\nbuenos motes.{DONE}",
  ["5f:44a5"] = "Son SPEARY, un\nSPEAROW, y RATTEY,\011un RATTATA.{DONE}",
  ["5f:44d8"] = "SPEARY: ¡Spea!{DONE}",
  ["5f:44ea"] = "RATTEY: ¡Ratii!{DONE}",
  ["5f:4559"] = "Bienvenido a la\nCASA DEL\012ENTRENADOR, el\nlugar más popular\011de CIUDAD VERDE.\012Es sólo para\nentrenadores.\012Puedes luchar\ncontra los mejores\012entrenadores en el\npiso de abajo.{DONE}",
  ["5f:45ff"] = "La CIUDAD VERDE\nes la más cercana\011a la MESETA AÑIL.\012Construyeron este\nlugar debido al\012gran número de\nentrenadores que\012pasaban de camino\na la MESETA AÑIL.{DONE}",
  ["5f:468f"] = "Aquí abajo tienen\nlugar combates\011de entrenamiento.\012Me encantaría ver\nlo bien que lucha\012un entrenador de\nJOHTO.{DONE}",
  ["5f:46f7"] = "Creo que no puedes\nser el CAMPEÓN\012si no luchas\ncon toda la gente\012que te encuentres\npor ahí.\012El CAMPEÓN de\nPALETA viajó por\012las ciudades y\npueblos de KANTO.{DONE}",
  ["5f:47a3"] = "¡Ah…! Estoy\ndescansando de los\011combates POKéMON.{DONE}",
  ["5f:47ce"] = "Los combates de\nentrenamiento se\012celebran en HALL\nDE ENTRENAMIENTO.\012Los entrenadores\nmás hábiles están\011invitados.{DONE}",
  ["5f:4837"] = "No existen reglas\nsobre los combates\012de prueba. Al\nigual que en los\012combates reales,\naquí vale todo.{DONE}",
  ["5f:489b"] = "¿Qué es esto?\n¿Una estrategia?\012Esta letra se\nparece a las\012huellas de ONIX…\n¡Es ilegible…!{DONE}",
  ["5f:49fa"] = "Bienvenido al HALL\nDE ENTRENAMIENTO.\012Puedes luchar\ncon un entrenador\011cada día.{DONE}",
  ["5f:4a44"] = "{STRBUF}\nserá hoy tu rival.{DONE}",
  ["5f:4a61"] = "¿Quieres\nluchar?{DONE}",
  ["5f:4a7c"] = "Entra, por\nfavor.\012Puedes empezar\nahora mismo.{DONE}",
  ["5f:4ab0"] = "Lo siento. Sólo\npueden entrar\012aquéllos que van\na luchar.{DONE}",
  ["5f:4af7"] = "Lo siento, señor.\nÉsta es la segunda\012vez que viene hoy.\nSólo se puede\012entrar una vez\nal día.{DONE}",
  ["5f:4b57"] = "He perdido…\n¡Qué pena…!{DONE}",
  ["5f:4b66"] = "He viajado hasta\naquí sólo para\011luchar contra ti.{DONE}",
  ["5f:4bd3"] = "El LÍDER de este\nGIMNASIO es\011genial.{DONE}",
  ["5f:4bf9"] = "¿Has estado en\nISLA CANELA?\012Es una isla muy\nal sur de aquí.{DONE}",
  ["5f:4c8c"] = "¿Dónde estará el\nLÍDER del GIMNASIO\012de CIUDAD VERDE?\nQuería desafiarle.{DONE}",
  ["5f:4cd4"] = "No hay ningún\nENTRENADOR en\012el GIMNASIO de\nCIUDAD VERDE.\012El LÍDER dice que\nsu política es\012ganar sin tener\nsubordinados.{DONE}",
  ["5f:4d4a"] = "Dicen que el\nGIMNASIO de ISLA\012CANELA está\ndestruido.\012Me pregunto que\nhabrá sido de\011BLAINE, su LÍDER.{DONE}",
  ["5f:4da7"] = "Mi sueño es ser\nLÍDER de GIMNASIO.{DONE}",
  ["5f:4e44"] = "¡Hola! Me alegro\nde verte.\012Eres la primera\nvisita que recibo\012desde hace\nmucho tiempo.\012¡Estoy muy\ncontento! Te voy\012a hacer un\npequeño regalo.{DONE}",
  ["5f:4ec4"] = "Es una PEPITA.\012No puedo darte\npepitas de la\012sabiduría,\n¡sólo esto!{DONE}",
  ["5f:4f34"] = "¿Eres {PLAYER}?\012Soy el AYUDANTE\ndel PROF. OAK.\012No sabía que\nestabas aquí.\012El LAB. del PROF.\nOAK está cerca de\011PUEBLO PALETA.{DONE}",
  ["5f:5008"] = "Sólo pueden pasar\nlos entrenadores\012que demuestren\nsu valía.{DONE}",
  ["5f:503e"] = "No tienes todas\nlas MEDALLAS\011de JOHTO.\012Lo siento, pero no\npuedo dejarte\011pasar.{DONE}",
  ["5f:5093"] = "¡Oh! ¡Las ocho\nMEDALLAS de JOHTO!\012¡Le ruego que\npase, señor!{DONE}",
  ["5f:50d0"] = "Este camino lleva\na MT.PLATEADO.\012Donde verás a unos\nPOKéMON fuertes\011y terribles.{DONE}",
  ["5f:5116"] = "Vas a la LIGA\nPOKéMON, ¿verdad?\012El ALTO MANDO es\ntan fuerte que da\012miedo. ¡Están\nesperándote!{DONE}",
  ["60:43f7"] = "ELM: ¡{PLAYER}!\n¡Eres tú!\012Quería pedirte\nun favor.\012Conozco a un tal\nSR. POKéMON,\011que siempre está\012descubriendo\ncosas nuevas\012y presumiendo\nde ellas.\012Acabo de recibir\nun e-mail suyo\012diciendo que esta\nvez va en serio.\012Me intriga, pero\nestamos ocupados\012estudiando a los\nPOKéMON.\012¿Podrías indagar\npor nosotros?\012Te daré un POKéMON\npara que te\011acompañe.\012Todos son POKéMON\nraros que acabamos\011de encontrar.\012Venga. ¡Elige uno!{DONE}",
  ["60:4590"] = "Si aparece un\nPOKéMON salvaje,\012haz que tu POKéMON\nluche contra él.{DONE}",
  ["60:45c2"] = "ELM: ¡Espera!\n¿Adónde vas?{DONE}",
  ["60:45e3"] = "ELM: ¿Quieres a\nCYNDAQUIL, el\011POKéMON de fuego?{DONE}",
  ["60:460e"] = "ELM: ¿Quieres a\nTOTODILE, el\011POKéMON de agua?{DONE}",
  ["60:463a"] = "ELM: ¿Quieres a\nCHIKORITA, el\011POKéMON planta?{DONE}",
  ["60:4668"] = "ELM: Piénsalo\ncon cuidado.\012Tu compañero es\nimportante.{DONE}",
  ["60:46a2"] = "ELM: ¡Yo también\ncreo que es un\011POKéMON genial!{DONE}",
  ["60:46c8"] = "¡{PLAYER}\nrecibió a\011{STRBUF}!{DONE}",
  ["60:46db"] = "El SR. POKéMON\nvive cerca de\011CIUDAD CEREZO.\012Está casi en\nlínea recta.{DONE}",
  ["60:472f"] = "Si hieren a tu\nPOKéMON, cúralo\011con esta máquina.{DONE}",
  ["60:476c"] = "Éste es mi número\nde teléfono.\012Llámame si surge\nalgo.{DONE}",
  ["60:47a9"] = "{PLAYER} anotó\nel número de ELM.{DONE}",
  ["60:47c3"] = "El SR. POKéMON va\na todas partes y\011encuentra rarezas.\012¡Qué pena que\nsean tan raros\011y tan inútiles!\012¡{PLAYER},\nconfío en ti!{DONE}",
  ["60:4835"] = "Contiene un\nPOKéMON atrapado\011por el PROF. ELM.{DONE}",
  ["60:485d"] = "Me pregunto qué\nserá esto.{DONE}",
  ["60:4877"] = "¿Curar a\ntus POKéMON?{DONE}",
  ["60:4883"] = "ELM: {PLAYER},\n¡qué horror…!\012¡Ah, sí! ¿Cuál\nera el gran\012descubrimiento del\nSR. POKéMON?{DONE}",
  ["60:48c8"] = "{PLAYER} le dio el\nHUEVO MISTERIOSO\011al PROF. ELM.{DONE}",
  ["60:48ef"] = "ELM: ¿Esto?{DONE}",
  ["60:48fb"] = "Pero… ¿Es un\nHUEVO de POKéMON?\012Si lo es, ¡vaya\ndescubrimiento!{DONE}",
  ["60:4936"] = "ELM: ¿¡Qué!?\012¿El PROF. OAK te\ndio una POKéDEX?\012{PLAYER}, ¿es eso\ncierto? ¡Mm…,\011increíble!\012OAK no suele\nequivocarse al\012juzgar a un\nentrenador.\012¡Oh, {PLAYER}!\nPuede que tengas\012lo necesario para\nser un CAMPEÓN.\012Además, pareces\nllevarte bien con\011los POKéMON.\012Deberías aceptar\nel desafío de un\011GIMNASIO POKéMON.\012El GIMNASIO más\ncercano es el de\011CIUDAD MALVA.{DONE}",
  ["60:4a85"] = "{PLAYER}. El\ncamino hacia la\012gloria será\nlargo.\012Antes de irte, no\nolvides hablar\011con tu madre.{DONE}",
  ["60:4af2"] = "ELM: ¡No te\nrindas! Si sé algo\012sobre ese HUEVO,\nte llamaré.{DONE}",
  ["60:4b33"] = "ELM: ¿{PLAYER}?\n¿No has visto a\011mi ayudante?\012Te esperaba con\nel HUEVO en el\012CENTRO POKéMON\nde CIUDAD MALVA.\012Si no lo has\nvisto, búscalo\011ahí.{DONE}",
  ["60:4bd1"] = "ELM: ¿Alguna\nnovedad?{DONE}",
  ["60:4bf6"] = "¿{PLAYER}? Creía\nque el huevo se\011había abierto.\012¿Dónde está el\nPOKéMON?{DONE}",
  ["60:4c28"] = "ELM: ¡Qué buen\naspecto, {PLAYER}!{DONE}",
  ["60:4c41"] = "¿Qué?\n¿¡Ese POKéMON!?{DONE}",
  ["60:4c55"] = "¡El HUEVO se\nabrió! Los POKéMON\011deben nacer así.\012Quizá no todos\nlos POKéMON.\012¡Uauu! Aún nos\nqueda mucho por\011aprender.{DONE}",
  ["60:4cd2"] = "¡Gracias, {PLAYER}!\nNos estás ayudando\012a descubrir los\nmisterios POKéMON.\012¡Recibe esto\ncomo prueba\011de nuestra estima!{DONE}",
  ["60:4d43"] = "Eso es una\nPIEDRAETERNA.\012Algunos POKéMON\nevolucionan al\012alcanzar ciertos\nniveles.\012Si un POKéMON\nva equipado con la\012PIEDRAETERNA,\nno evolucionará.\012Dásela al POKéMON\n\nque no quieras que\011evolucione.{DONE}",
  ["60:4ded"] = "ELM: {PLAYER},\nsi surge algo,\011te llamaré.{DONE}",
  ["60:4e1b"] = "(Suspiro…). El\nPOKéMON robado.\012Me pregunto\ncómo estará.\012Dicen que los\nPOKéMON educados\012por malas personas\nse vuelven malos.{DONE}",
  ["60:4e86"] = "ELM: ¡{PLAYER}!\nGracias a ti,\012mis estudios\nvan fenomenal.\012Toma esto como\nprueba de mi\011estima.{DONE}",
  ["60:4ee7"] = "¡La MASTER BALL\nes la mejor!\012¡Es la BALL\ndefinitiva! Atrapa\012cualquier tipo\nde POKéMON.\012Sólo la tienen\nlos auténticos\012investigadores\nde POKéMON.\012¡Toma, {PLAYER}!\n¡Creo que a ti\012te ayudará más\nque a mí!{DONE}",
  ["60:4fa4"] = "ELM: ¡{PLAYER}!\n¿Qué tal?\012Te he llamado\nporque tengo\011algo para ti.\012Es un TICKET\nde BARCO.\012Ahora podrás\natrapar POKéMON\011en KANTO.{DONE}",
  ["60:5020"] = "El barco zarpa de\nCIUDAD OLIVO.\012Pero eso ya lo\nsabías, {PLAYER}.\012Has viajado por\ntodas partes con\011tus POKéMON.\012¡Dale recuerdos\nal PROF. OAK\011en KANTO!{DONE}",
  ["60:50e9"] = "{PLAYER}, toma\nesto por las\011molestias.{DONE}",
  ["60:5116"] = "Sólo somos dos,\nasí que siempre\011estamos ocupados.{DONE}",
  ["60:5146"] = "Oimos un ruido\nmuy fuerte…\012Y cuando salimos\na mirar, alguien\012nos robó un\nPOKéMON.\012¡Es horrible\nque alguien\011hiciera eso!\012(Suspiro…) El\nPOKéMON robado.\012Me pregunto cómo\nestará.\012Dicen que los\nPOKéMON educados\012por malas personas\nse vuelven malos.{DONE}",
  ["60:5229"] = "¡{PLAYER}!\012¡Usa esto para\nllenar tu POKéDEX!{DONE}",
  ["60:524b"] = "Atrapa POKéMON\npara completar\011tu POKéDEX.\012Atrapa POKéMON\nsalvajes usando\011las POKé BALL.{DONE}",
  ["60:52a1"] = "Dicen que han\nrobado un POKéMON.\012Y acabo de recibir\ncierta información\011del PROF. ELM.\012Parece que fue un\njoven pelirrojo,\011de pelo largo.\012¿Qué?\012¿Que tú te has\nenfrentado a un\011entrenador así?\012¿Y sabes cómo\nse llama?{DONE}",
  ["60:5371"] = "¡Bien! Así que su\nnombre es {RIVAL}.\012¡Gracias por tu\ncolaboración!{DONE}",
  ["60:53ae"] = "La ventana está\nabierta.\012Entra una\nsuave brisa.{DONE}",
  ["60:53e2"] = "¡Entró por\naquí!{DONE}",
  ["60:53fd"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 1:\012Pulsa START para\nabrir el MENÚ.{DONE}",
  ["60:543b"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 2:\012¡Graba tu viaje\ncon GUARDAR!{DONE}",
  ["60:5477"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 3:\012Abre tu MOCHILA y\npulsa SELECT para\011mover objetos.{DONE}",
  ["60:54c6"] = "{PLAYER} abrió\nun libro.\012Pista de viaje 4:\012Mira los ataques\nde tus POKéMON.\012Pulsa A para\ncambiar de ataque.{DONE}",
  ["60:5521"] = "Dentro está el\nenvoltorio del\012tentempié que se\ntomó el PROF. ELM.{DONE}",
  ["60:5719"] = "¡Ah, {PLAYER}…!\nNuestro vecino,\012el PROF. ELM, te\nestaba buscando.\012Dijo que quería\nque le hicieras\011un favor.\012¡Ah! ¡Casi se me\nolvida! Ya han\012traído tu POKéGEAR\ndel taller.\012¡Aquí tienes!{DONE}",
  ["60:57d2"] = "El POKéMON GEAR o\nsólo POKéGEAR.\012Es básico si\nquieres ser un\011buen entrenador.\012¡Ah! Falta el día\nde la semana.\012¡No olvides\nponerlo!{DONE}",
  ["60:5857"] = "¿Es horario\nde verano?{DONE}",
  ["60:5878"] = "Vuelve a casa\npara cambiar de\011hora el reloj.\012Por cierto,\n¿sabes cómo usar\011el TELÉFONO?{DONE}",
  ["60:58e0"] = "¿Recuerdas que\nhay que encender\012el POKéGEAR\ny elegir el\011TELÉFONO?{DONE}",
  ["60:591c"] = "Te leeré las\ninstrucciones.\012Enciende el\nPOKéGEAR y elige\011el TELÉFONO.{DONE}",
  ["60:5965"] = "Los números están\nen la memoria.\012Elige el nombre\nque quieras.\012¿No te parece\nestupendo?{DONE}",
  ["60:59ca"] = "El PROF. ELM te\nestá esperando.\012¡Date prisa!{DONE}",
  ["60:59fa"] = "¿Qué quería\nel PROF. ELM?\012…\012Parece muy\ndíficil.\012Deberías estar\norgulloso de\012que la gente\nconfíe en ti.{DONE}",
  ["60:5a6c"] = "¡Vamos, {PLAYER}!\012¡Cuentas con\ntoda mi ayuda!{DONE}",
  ["60:5a92"] = "¡La especialidad\nde mi madre!\012¡HAMBURGUESA\nVOLCÁN CANELA!{DONE}",
  ["60:5abc"] = "El fregadero está\nimpecable. A mamá\011le gusta limpio.{DONE}",
  ["60:5ae9"] = "Veamos qué hay\nen la nevera…\012¡AGUA FRESCA y una\nsabrosa LIMONADA!{DONE}",
  ["60:5b28"] = "Una peli en TV:\ndos niños suben\012a un tren bajo un\ncielo estrellado.\012¡Mejor que yo\ntambién me vaya!{DONE}",
  ["60:5c5c"] = "¡La HORA POKéMON\ndel PROF. OAK!\012¡Sintonízanos la\npróxima vez!{DONE}",
  ["60:5c8d"] = "¡EL CANAL POKéMON!{DONE}",
  ["60:5c9c"] = "¡Soy la DJ ROSA,\nla presentadora!{DONE}",
  ["60:5cbc"] = "¡POKéMON!\nCANAL POKéMON…{DONE}",
  ["60:5d64"] = "PIKACHU es un\nPOKéMON\011evolucionado.\012Los hallazgos del\nPROF. ELM me\011sorprendieron.\012Es famoso por\nsus estudios\012sobre la evolución\nde los POKéMON.\012(Suspiro…).\012Me gustaría ser\nuna investigadora\011como él…{DONE}",
  ["60:5e09"] = "¡La HORA POKéMON\ndel PROF. OAK!\012¡Sintonízanos la\npróxima vez!{DONE}",
  ["60:5e3a"] = "¡CANAL POKéMON!{DONE}",
  ["60:5e49"] = "¡Soy la DJ ROSA,\nla presentadora!{DONE}",
  ["60:5e69"] = "¡POKéMON!\nCANAL POKéMON…{DONE}",
  ["60:5eb8"] = "¡Hola, {PLAYER}!\nMi marido siempre\012está muy ocupado.\n¡Ojalá esté bien!\012Cuando estudia\na los POKéMON,\012se olvida hasta\nde comer.{DONE}",
  ["60:5f2c"] = "¡Cuando sea mayor,\nayudaré a mi\011padre!\012¡Voy a ser un\ngran profesor\011POKéMON!{DONE}",
  ["60:5fdc"] = "Los POKéMON.\n¿De dónde vienen?\012¿Adónde van?\012¿Por qué no ha\npresenciado nadie\012el nacimiento de\nun POKéMON?\012¡Quiero saber!\n¡Quiero dedicar mi\012vida al estudio de\nlos POKéMON!\012…\012Son algunos\npapeles del\011PROF. ELM.{DONE}",
  ["60:610b"] = "Tus POKéMON\nparecen cansados.\012Deberías dejarlos\ndescansar un poco.{DONE}",
  ["60:6149"] = "¡Vaya! ¡Tus\nPOKéMON tienen\011buen aspecto!\012¡Sigue así!{DONE}",
  ["60:61b7"] = "Aquí hay algo\nescrito.\012¿Quieres leerlo?{DONE}",
  ["60:61e0"] = "A mis hermanos y\nhermanas:\012Nos orgullece\nayudar a los\012entrenadores\nPOKéMON.\012Cuando habléis con\nlos entrenadores,\011dadles algo útil.\012Besos,\nLUNA\012¿Seguir leyendo?{DONE}",
  ["60:6277"] = "Lunes, LUNA\nRUTA 40\012Martes, MARTA\nRUTA 29\012Miércoles, MIGUEL\nLAGO DE LA FURIA\012Jueves, JOSUÉ\nRUTA 36\012Viernes, VICKI\nRUTA 32\012Sábado, SABINO\nCIUDAD ENDRINO\012Domingo, DOMINGO\nRUTA 37{DONE}",
  ["60:6384"] = "¿A dónde vas con\nlos POKéMON?\012¿A la LIGA\nPOKéMON?\012¿Son tus POKéMON\nlo bastante\012fieles como para\npemitirte ganar?\012Déjame ver…{DONE}",
  ["60:63e9"] = "¡Ah! Tus POKéMON\nconfían mucho\011en ti.\012Da gusto ver a un\nbuen entrenador.\012Toma. Un regalo\npara el viaje.{DONE}",
  ["60:644d"] = "MT37 contiene\nTORMENTA ARENA.\012Este movimiento\ndaña a ambos\011combatientes.\012Es para entrenado-\nres avanzados.\012Úsala si te\natreves. ¡Suerte!{DONE}",
  ["60:64dd"] = "Si no confían\nmás en ti,\012tendrás problemas\npara ganar.\012La confianza es el\nvínculo entre los\012POKéMON y sus\nentrenadores.{DONE}",
  ["60:657f"] = "No puedes cruzar\nsetos.\012Pero puedes saltar\npor encima de\011ellos para atajar.{DONE}",
  ["60:65cb"] = "Más adelante\naparecen muchos\012tipos de\nPOKéMON.\012Si quieres hacerte\ncon todos, tendrás\012que buscar por\ntodas partes.{DONE}",
  ["61:400d"] = "¡Hola!\012El REY del KARATE,\nel maestro del\012DOJO-KARATE, está\nentrenando en una\011cueva de JOHTO.{DONE}",
  ["61:4061"] = "¡Lo que tenga que\nser será!{DONE}",
  ["61:4081"] = "¡Enemigos por\ntodas partes!{DONE}",
  ["61:4180"] = "SABRINA: Sabía\nque vendrías…\012Hace tres años\ntuve una visión\011de tu llegada.\012Tú lo que quieres\nes mi MEDALLA.\012No me gusta\nluchar, pero mi\012deber como LÍDER\nes conceder\012MEDALLAS a todo\naquel que se las\011merezca.\012Como eso es lo que\nquieres, mira mis\011poderes psíquicos.{DONE}",
  ["61:4295"] = "SABRINA: Tu\npoder…\012supera con creces\nlo que esperaba…\012Quizá no se pueda\npredecir del todo\012lo que nos espera\nen el futuro…\012Vale, tú ganas.\nTe has ganado la\011MEDALLA PANTANO.{DONE}",
  ["61:4336"] = "{PLAYER} recibió\nMEDALLA PANTANO.{DONE}",
  ["61:434e"] = "SABRINA: La\nMEDALLA PANTANO\012muestra tus\npoderes ocultos.\012Aunque no supe\npredecir tu poder\012con exactitud,\nsabía que valías\011mucho.\012¡Te convertirás en\nun amado y alabado\011CAMPEÓN!{DONE}",
  ["61:440d"] = "SABRINA: Tu amor\npor tus POKéMON\012supera mi poder\npsíquico…\012Creo que el poder\ndel amor es un\012tipo de poder\npsíquico…{DONE}",
  ["61:448a"] = "¡El poder de todos\nlos que venciste\011está en mí!{DONE}",
  ["61:44bc"] = "Fuerte…\nMuy fuerte…{DONE}",
  ["61:44d5"] = "¿De dónde proviene\ntu poder?{DONE}",
  ["61:44f8"] = "El poder psíquico\nes el poder de tu\011alma.{DONE}",
  ["61:4522"] = "¡Tu alma tiene más\npoder que la mía!{DONE}",
  ["61:4547"] = "Has fortalecido tu\nalma, no sólo tus\011habilidades.{DONE}",
  ["61:457e"] = "¡Fufufufu…!\nLo veo claramente.\012¡Puedo leer\ntu alma!{DONE}",
  ["61:45b5"] = "A pesar de leerte\nel pensamiento,\011he perdido…{DONE}",
  ["61:45d7"] = "¡Maldición! Olvidé\nque predije mi\011derrota contra ti.{DONE}",
  ["61:460d"] = "El DOJO-KARATE era\nel GIMNASIO\011de esta ciudad.{DONE}",
  ["61:4643"] = "¡Eres bueno…!{DONE}",
  ["61:4654"] = "El REY del KARATE,\nel maestro del\012DOJO-KARATE, acaba\nde ser machacado\011por SABRINA.{DONE}",
  ["61:46a2"] = "¡Hola, futuro\nCAMPEÓN!\012Un entrenador tan\nhabilidoso como tú\012no necesita que le\ndigan cómo luchar\012contra POKéMON\npsíquicos, ¿no?\012¡Espero mucho\nde ti!\012¡Buena suerte!{DONE}",
  ["61:4741"] = "¡Otro combate\nfantástico!{DONE}",
  ["61:486d"] = "En PUEBLO LAVANDA\nhay una gran TORRE\011de RADIO.{DONE}",
  ["61:4894"] = "Quiero ser más\nfuerte, pero aún\011soy muy mala…\012¿Podrías enseñarme\ncómo algún día?{DONE}",
  ["61:493b"] = "Hay una enorme\nCENTRAL de ENERGÍA\012al norte de PUEBLO\nLAVANDA.{DONE}",
  ["61:496e"] = "Acabo de cruzar\nel TÚNEL ROCA.\012Pasaba algo en\nla CENTRAL de\011ENERGÍA.{DONE}",
  ["61:49c9"] = "Las cuevas suelen\nderrumbarse.\012Últimamente han\ndesaparecido\012varias cuevas,\ncomo la de\011CIUDAD CELESTE.\012Para un MONTAÑERO\nprofesional, eso\011es obvio.{DONE}",
  ["61:4a60"] = "La OFICINA CENTRAL\nde SILPH S.A. y\012la ESTACIÓN del\nMAGNETOTRÉN son\012los lugares más\nvistos de AZAFRÁN.{DONE}",
  ["61:4b33"] = "…\012…\012…\012¡Lo conseguí!\012¡Tú lo quisiste!{DONE}",
  ["61:4b56"] = "MT29 es PSÍQUICO.\012Puede reducir\nlas HABILIDADES\012ESPECIALES del\nblanco.{DONE}",
  ["61:4c45"] = "Lo siento, pero el\nMAGNETOTRÉN no\011funciona ahora.{DONE}",
  ["61:4c79"] = "Pronto saldremos\nhacia CIUDAD\011TRIGAL.\012¿Quiere\nsubir?{DONE}",
  ["61:4cb3"] = "¿Por favor, puedo\nver su PASE?\012Bien. Ya puede\npasar, señor.{DONE}",
  ["61:4cef"] = "Lo siento, pero\nno tiene un PASE.{DONE}",
  ["61:4d11"] = "Siempre a\nsu servicio.{DONE}",
  ["61:4d2c"] = "Hemos llegado a\nCIUDAD AZAFRÁN.\012Siempre a\nsu servicio.{DONE}",
  ["61:4d63"] = "El MAGNETOTRÉN es\nun tren ultra-\012moderno, accionado\npor electricidad\012e imanes. Su\nvelocidad es\011increíble.\012Sin embargo,\nsi no hay\011electricidad…{DONE}",
  ["61:4dfa"] = "¡Caramba…!\012¡Cuántas veces he\nido de KANTO a\012JOHTO y de JOHTO\na KANTO!{DONE}",
  ["61:4e44"] = "Antes de que se\nconstruyera la\012ESTACIÓN, ahí\nhabía una casa.\012Y en ella vivía\nuna niña\011llamada COPIONA.{DONE}",
  ["61:4eb9"] = "Hola. ¿Tienes un\nPASE? Yo sí. Toda\012la gente de CIUDAD\nAZAFRÁN que usa el\012MAGNETOTRÉN tiene\nun PASE.{DONE}",
  ["61:4f9c"] = "Bienvenido a la\nOFICINA CENTRAL\011de SILPH S.A.{DONE}",
  ["61:4fcf"] = "Al piso de arriba\nsólo pueden subir\011los empleados.\012Pero como has\nvenido desde tan\012lejos, toma este\npequeño recuerdo.{DONE}",
  ["61:5041"] = "Es lo último de\nSILPH S.A. Aún\012no se encuentra\na la venta.{DONE}",
  ["61:50cd"] = "A mi hija le gusta\nimitar a la gente.\012Y por eso la\nllaman la\011COPIONA.{DONE}",
  ["61:512e"] = "Mi hija es muy\nintrovertida…\012Tiene muy\npocos amigos.{DONE}",
  ["61:516c"] = "Acaba de perder\nel POKé MUÑECO que\012le regaló un niño\nhace tres años.\012Desde entonces,\nimita a la gente\011mucho mejor…{DONE}",
  ["61:51e4"] = "BLISSEY: ¡Bliisii!{DONE}",
  ["61:52f1"] = "{PLAYER}: ¿Te gusta\nPOKéMON?\012{PLAYER}: No, yo\nsólo preguntaba.\012{PLAYER}: ¿Eh?\n¡Eres muy rara!{DONE}",
  ["61:533f"] = "COPIONA: ¿Cómo?\n¿Que no imite?\012¡Pero si es mi\nhobby favorito!{DONE}",
  ["61:537b"] = "{PLAYER}: ¡Hola!\nDicen que has\012perdido tu POKé\nMUÑECO favorito.\012{PLAYER}: Si lo\nencuentro, ¿me\011darás un PASE?\012{PLAYER}: Iré\na buscarlo.\012¿Crees que lo\nperdiste en\011CIUDAD CARMÍN?{DONE}",
  ["61:542d"] = "COPIONA: ¿Perdona?\012¿No tendría que\ndecirte yo lo\011que debes hacer?\012Estoy preocupada.\n¿Y si alguien\011lo encuentra?{DONE}",
  ["61:5496"] = "COPIONA: ¡Sí! ¡Ése\nes mi POKé MUÑECO\011CLEFAIRY!\012¿Ves el descosido\nque tiene en la\012pata derecha?\n¡Ésa es la prueba!{DONE}",
  ["61:54f9"] = "Está bien. ¡Aquí\ntienes el PASE del\012MAGNETOTRÉN que\nte prometí!{DONE}",
  ["61:552b"] = "COPIONA: Ése es\nel PASE para el\011MAGNETOTRÉN.\012La empresa de\nferrocarriles me\012lo dio cuando\nderribaron nuestra\012casa para edificar\nla ESTACIÓN.{DONE}",
  ["61:55af"] = "{PLAYER}: ¡Hola!\nMuchas gracias por\011el PASE de tren.\012{PLAYER}: ¿Perdona?\012{PLAYER}: ¿Tanto\nte divierte imitar\011todo lo que hago?{DONE}",
  ["61:560c"] = "COPIONA: ¿Apuestas\nalgo? ¡Es genial!{DONE}",
  ["61:562d"] = "DODRIO: ¡Dodrii!{DONE}",
  ["61:5640"] = "ESPEJITO, ESPEJITO\n¿QUIÉN ES EL MÁS\012GUAPO DE\nTODOS?{DONE}",
  ["61:567b"] = "¡Qué POKéMON\nmás raro!\012Es un muñeco…{DONE}",
  ["61:5702"] = "Muchas ciudades de\nJOHTO están llenas\012de historia. ¡Cómo\nme gustaría ir!{DONE}",
  ["61:5766"] = "Eres de JOHTO,\n¿verdad?\012¿Qué opinas de\nKANTO? Es bonito,\011¿no crees?{DONE}",
  ["61:57ff"] = "¡Aaaayy!\012Siento que una\nsiniestra sombra\012se cierne\nsobre ti.\012¡Toma esto para\nprotegerte!{DONE}",
  ["61:5851"] = "Corrías un peligro\nmortal, pero ahora\011estás protegido.{DONE}",
  ["61:5888"] = "A mi abuela le\ngusta protegerse\012contra supuestos\nmalos espíritus.\012Perdona si te\nha asustado.{DONE}",
  ["62:402c"] = "¡Se han quedado\nsin POKé BALL!\012¿Cuándo\nconseguirán más?{DONE}",
  ["62:406b"] = "¡Tengo POKé BALL\nde reserva! ¡Puedo\011atrapar POKéMON!{DONE}",
  ["62:4098"] = "Cuando iba por la\nhierba, un POKéMON\012bicho envenenó\na mis POKéMON.\012Yo seguí andando,\npero mi POKéMON\011se debilitó.\012Deberías llevar un\nANTÍDOTO contigo.{DONE}",
  ["62:4182"] = "¡Es genial! Puedo\nguardar a todos\012los POKéMON que\nquiera, ¡y gratis!{DONE}",
  ["62:41c0"] = "Ese PC puede ser\nusado por todo\011entrenador.{DONE}",
  ["62:41e9"] = "El CENTRO de\nCOMUNICACIONES de\012arriba está recién\nconstruido.\012Pero aún no está\nterminado.{DONE}",
  ["62:423e"] = "El CENTRO de\nCOMUNICACIONES de\012arriba está recién\nconstruido.\012¡Yo ya he cambiado\nPOKéMON en él!{DONE}",
  ["62:42e2"] = "¿Quieres saber lo\nbueno que eres\012como entrenador\nPOKéMON?\012Pues vete a los\nGIMNASIOS POKéMON\012de JOHTO y gana\nmuchas MEDALLAS.{DONE}",
  ["62:435d"] = "¡Cuando sea mayor,\nvoy a ser un LÍDER\011de GIMNASIO!\012¡Hago luchar a mis\nPOKéMON con los\012de mi amigo para\nfortalecerlos!{DONE}",
  ["62:4405"] = "¡Cuando era niño,\nera un brillante\011entrenador!\012Éste es mi\nconsejo: ¡Atrapa\011muchos POKéMON!\012¡Y trátalos con\nmucho cariño!{DONE}",
  ["62:44bb"] = "Luchando, los\nPOKéMON ganan\012experiencia y se\ntransforman.{DONE}",
  ["62:44f4"] = "¿Se transforman?\012¡Alucinaría si\nlo viera!{DONE}",
  ["62:457a"] = "Los POKéMON\ncomen BAYAS.\012Mi POKéMON se\ncuró comiendo\011una BAYA.\012Toma. ¡Te daré\nuna!{DONE}",
  ["62:45e4"] = "Busca BAYAS\nen los árboles.\012Son muy fáciles\nde encontrar.{DONE}",
  ["62:4755"] = "¡Hola! Debes de\nser {PLAYER}.\012El PROF. ELM dijo\nque vendrías.{DONE}",
  ["62:4797"] = "Esto es lo que\nquiero que\012examine el\nPROF. ELM.{DONE}",
  ["62:47c1"] = "{PLAYER} recibió\nun HUEVO MIST.{DONE}",
  ["62:47da"] = "Conozco a una\npareja que tiene\012una GUARDERÍA\nPOKéMON.\012Ellos me dieron\nese HUEVO.\012Como me intrigaba,\nle mandé una carta\011al PROF. ELM.\012El PROF. ELM es la\nmáxima autoridad\012en evolución de\nlos POKéMON.{DONE}",
  ["62:4881"] = "Hasta el PROF. OAK\nlo reconoce.{DONE}",
  ["62:48a6"] = "Si tengo razón,\nel PROF. ELM lo\011sabrá.{DONE}",
  ["62:48dc"] = "¿Vas a ir a ver\nal PROF. ELM?\012Toma. Tus POKéMON\ndeberían descansar\011un poco.{DONE}",
  ["62:4923"] = "¡Confío\nen ti!{DONE}",
  ["62:4939"] = "¡La vida es\ngenial! ¡Siempre\012quedan cosas por\ndescubrir!{DONE}",
  ["62:4974"] = "OAK: ¡Así que tú\neres {PLAYER}!\012¡Yo soy OAK!\n¡Un científico\011POKéMON!\012Estaba visitando a\nmi viejo amigo el\011SR. POKéMON.\012Y como me dijo que\ntenías algo para\012el PROF. ELM,\ndecidí esperarte.\012¡Oh! ¿Qué es esto?\n¡Un POKéMON raro!\012Veamos…\012¡Mmm, ya veo!\012Ahora entiendo por\nqué el PROF. ELM\012te confió un\nPOKéMON.\012Para científicos\ncomo el PROF. ELM\012y yo, los POKéMON\nson amigos.\012Sabía que\ntratarías a tus\012POKéMON con\nmucho cariño.\012¡Ah!\012Pareces ser de\nconfianza.\012¿Te gustaría\nayudarme?\012Mira. Ésta es la\núltima versión de\011la POKéDEX.\012Registra los datos\nde los POKéMON\012que has atrapado\no que has visto.\012¡Es una moderna\nenciclopedia!{DONE}",
  ["62:4bbb"] = "¡{PLAYER} recibió\nla POKéDEX!{DONE}",
  ["62:4bcd"] = "Busca muchos\ntipos de POKéMON\012y completa esa\nPOKéDEX.\012Ahora tengo\nque irme.\012Me esperan en\nCIUDAD TRIGAL para\012presentar mi\nprograma de radio.\012¡{PLAYER}, cuento\ncontigo!{DONE}",
  ["62:4c65"] = "¿Mmm? ¡Esa ESCAMA!\n¿De qué es? ¿De\011un GYARADOS rojo?\012¡Es muy rara!\nQuiero tenerla…\012{PLAYER}, ¿quieres\nintercambiarla?\012Yo te ofrezco\nREPARTIR EXP.\012Me lo dio\nel PROF. OAK.{DONE}",
  ["62:4cfc"] = "Es una pena.\nEs realmente\011raro.{DONE}",
  ["62:4d32"] = "Lleno de revistas\nextranjeras.\012Ni siquiera puedo\nleer los títulos.{DONE}",
  ["62:4d73"] = "Es un ordenador\nenorme. ¡Mmm!\011Está estropeado.{DONE}",
  ["62:4d9b"] = "¡Un montón de\nmonedas extrañas!\012Quizá sean de\notro país…{DONE}",
  ["62:4e29"] = "¡Hola, chico!\n¿Has visitado la\011TORRE BELLSPROUT?{DONE}",
  ["62:4e4f"] = "Estoy demasiado\nlejos. ¡Mejor que\011llame a casa!{DONE}",
  ["64:558e"] = "Soy el ENCARGADO\nde la GUARDERÍA.\012¿Quieres que\ncuide un POKéMON?{DONE}",
  ["64:55bd"] = "Soy el ENCARGADO\nde la GUARDERÍA.\012¿Sabes algo sobre\nlos HUEVOS?\012Mi mujer y yo\nestábamos cuidando\011unos POKéMON.\012¡Y de pronto\nvimos un HUEVO!\012¿No te parece\nincreíble?\012¿Quieres que te\ncuide un POKéMON?{DONE}",
  ["64:566a"] = "Soy la ENCARGADA\nde la GUARDERÍA.\012¿Quieres que te\ncuide un POKéMON?{DONE}",
  ["64:56a0"] = "Soy la ENCARGADA\nde la GUARDERÍA.\012¿Sabes algo sobre\nlos HUEVOS?\012Mi marido y yo\nestábamos cuidando\011unos POKéMON.\012¡Y de pronto\nvimos un HUEVO!\012¿No te parece\nincreíble?\012¿Quieres que te\ncuide un POKéMON?{DONE}",
  ["64:575e"] = "¿Cuál quieres\nque cuide?{PROMPT}",
  ["64:577c"] = "¿Oh? Pero sólo\ntienes un POKéMON.{PROMPT}",
  ["64:579d"] = "Perdona, pero no\nacepto HUEVOS.{PROMPT}",
  ["64:57bf"] = "Quita la CARTA y\nvuelve a verme.{PROMPT}",
  ["64:57e4"] = "Si me lo das,\n¿con quién vas\011a combatir?{PROMPT}",
  ["64:5815"] = "Vale. Cuidaré de\ntu {STRBUF}.{PROMPT}",
  ["64:5830"] = "Vuelve a por él\nmás tarde.{DONE}",
  ["64:5849"] = "¿Somos geniales o\nno? ¿Quieres ver a\011tu {STRBUF}?{DONE}",
  ["64:587b"] = "Tu {STRBUF}\nha crecido mucho.\012En cuanto a nivel,\nha subido {NUM}.\012Recuperar a tu\nPOKéMON te\011costará {NUM}¥.{DONE}",
  ["64:58e9"] = "¡Perfecto! ¡Aquí\nestá tu POKéMON!{PROMPT}",
  ["64:5904"] = "{PLAYER} recogió\na {STRBUF}.{PROMPT}",
  ["64:5917"] = "¿Ya de vuelta?\nTu {STRBUF}\012debería pasar más\ntiempo aquí. Pero\012recoger ahora\na tu POKéMON, te\011costará 100¥.{DONE}",
  ["64:5987"] = "¡No tienes sitio\npara él!{PROMPT}",
  ["64:59a1"] = "No tienes bastante\ndinero.{PROMPT}",
  ["64:59be"] = "No hay problema.{PROMPT}",
  ["64:59ce"] = "Vuelve cuando\nquieras.{DONE}",
  ["64:59db"] = "Aún no…{DONE}",
  ["64:59e5"] = "¡Ah, eres tú!\012Estábamos cuidando\nde tus POKéMON y\012¡menuda sorpresa\nnos hemos llevado!\012¡Tus POKéMON han\ntenido un HUEVO!\012No sabemos cómo ha\nllegado ahí, pero\012es de tus POKéMON.\n¿Lo quieres?{DONE}",
  ["64:5a8a"] = "¡{PLAYER} recibió\nel HUEVO!{DONE}",
  ["64:5a9f"] = "Cuídalo\nbien.{DONE}",
  ["64:5ab6"] = "Cuidaré de él.\n¡Gracias!{DONE}",
  ["64:5ad7"] = "No tienes sitio en\ntu equipo. Vuelve\011en otro momento.{DONE}",
  ["65:4751"] = "¿Qué?\012",
  ["65:475b"] = "¡{STRBUF}\nsalió del\011HUEVO!",
  ["65:4778"] = "¿Quieres darle\nun mote a\011{STRBUF}?{DONE}",
  ["65:4793"] = "Es el {STRBUF}\nque dejé con\012la ENCARGADA de\nla GUARDERÍA.{DONE}",
  ["65:47c4"] = "Es el {STRBUF}\nque dejé con el\012ENCARGADO de\nla GUARDERÍA.{DONE}",
  ["65:47f4"] = "Está rebosante\nde energía.{PROMPT}",
  ["65:480f"] = "No está interesado\nen {STRBUF}.{PROMPT}",
  ["65:482d"] = "Está interesado\nen {STRBUF}.{PROMPT}",
  ["65:484c"] = "Es agradable con\n{STRBUF}.{PROMPT}",
  ["65:4866"] = "Muestra interés\npor {STRBUF}.{PROMPT}",
  ["65:4883"] = "Aquí no hay\nninguna CARTA.{PROMPT}",
  ["65:4899"] = "La CARTA fue\nenviada.{PROMPT}",
  ["65:48b9"] = "¡MOCHILA llena!{PROMPT}",
  ["65:48cc"] = "Perderás el\nmensaje de\011la CARTA. ¿Vale?{DONE}",
  ["65:48f1"] = "Ya lleva\nun objeto.{PROMPT}",
  ["65:4911"] = "Un HUEVO no puede\nllevar CARTAS.{PROMPT}",
  ["65:492d"] = "La CARTA fue\nsacada del BUZÓN.{PROMPT}",
  ["65:4993"] = "Hay un POKéMON que\nlleva una CARTA.\012Por favor, quita\nla CARTA.{PROMPT}",
  ["65:544a"] = "Primero quita\nla CARTA.{PROMPT}",
  ["65:54fd"] = "¿O prefieres\nborrar el mensaje?{DONE}",
  ["65:5522"] = "Quitada CARTA de\n{STRBUF}.{PROMPT}",
  ["65:553d"] = "No hay bastante\nespacio para\011quitar la CARTA.{PROMPT}",
  ["65:5561"] = "¿Enviar la\nCARTA a tu PC?{DONE}",
  ["65:5584"] = "El BUZÓN de tu\nPC está lleno.{PROMPT}",
  ["65:559f"] = "La CARTA fue\nenviada a tu PC.{PROMPT}",
  ["65:5c61"] = "¿Cuántos?{DONE}",
  ["65:5c6c"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.{DONE}",
  ["65:5c8c"] = "Hola, hijo.\012Vendo hierbas\nmedicinales.\012Son buenas, pero\nun poco amargas.\012Quizá tus POKéMON\nno las quieran.\012¡Je, je, je…!{DONE}",
  ["65:5d07"] = "¿Cuánto quieres?{DONE}",
  ["65:5d12"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.{DONE}",
  ["65:5d32"] = "Gracias, hijo.\n¡Je, je, je…!{DONE}",
  ["65:5d4e"] = "¡Oh! Tu MOCHILA\nestá llena, hijo.{DONE}",
  ["65:5d6c"] = "¡Je, je…! No\ntienes ese dinero.{DONE}",
  ["65:5d8e"] = "Vuelve otra vez.\n¡Je, je, je…!{DONE}",
  ["65:5dab"] = "¡Oye! ¿Quieres ver\nunas gangas?\012Vendo objetos que\nnadie posee, pero\012sólo un objeto de\ncada tipo.{DONE}",
  ["65:5e14"] = "{STRBUF}\ncuesta {NUM}¥.\011¿Lo quieres?{DONE}",
  ["65:5e31"] = "Gracias.{DONE}",
  ["65:5e3a"] = "¡Oh! Tu MOCHILA\nestá a tope.{DONE}",
  ["65:5e5b"] = "Eso ya lo has\ncomprado. No me\011quedan más.{DONE}",
  ["65:5e8c"] = "¡Oh! No tienes\nsuficiente dinero.{DONE}",
  ["65:5eaa"] = "Vuelve en otra\nocasión.{DONE}",
  ["65:5ec3"] = "¿Qué quieres?\n¿Alguna medicina?{DONE}",
  ["65:5ee2"] = "¿Cuántas?{DONE}",
  ["65:5eed"] = "{NUM} unidad/es\nde {STRBUF}\011serán {NUM}¥.{DONE}",
  ["65:5f0f"] = "¡Muchas gracias!{DONE}",
  ["65:5f1d"] = "No te queda\nsitio.{DONE}",
  ["65:5f3c"] = "¿Eh? No tienes\nbastante dinero.{DONE}",
  ["65:5f5a"] = "De acuerdo.\nHasta luego.{DONE}",
  ["65:5f76"] = "No tienes nada\npara vender.{PROMPT}",
  ["65:5f97"] = "¿Cuántos?{DONE}",
  ["65:5fa2"] = "Puedo pagarte\n{NUM}¥.\012¿Te parece bien?{DONE}",
  ["65:5fc6"] = "¡Bienvenido!\n¿Qué deseas?{DONE}",
  ["65:5fe4"] = "Aquí tienes.\n¡Gracias!{DONE}",
  ["65:5ffe"] = "No tienes\nsuficiente dinero.{DONE}",
  ["65:601b"] = "No puedes llevar\nmás objetos.{DONE}",
  ["65:603b"] = "Lo siento. No te\npuedo comprar eso.{DONE}",
  ["65:605d"] = "¡Vuelve cuando\nquieras!{DONE}",
  ["65:6071"] = "¿Puedo ayudarte\nen algo más?{DONE}",
  ["65:6092"] = "Recibiste {NUM} ¥\npor {STRBUF}.{DONE}",
}
